} end)()
t.guides["forever/alliance/07-thousand-needles"] = (function() return {
		["Back to {area:42}"] = "De volta a {area:42}",
		["Below ground"] = "No subterrâneo",
		["Fly to {area:150}"] = "Voe para {area:150}",
		["For {npc:1212} in {zone:1453}, in the next guide"] = "Para {npc:1212}, em {zone:1453}, no próximo guia",
		["For {npc:482} in {zone:1453}, in the next guide"] = "Para {npc:482}, em {zone:1453}, no próximo guia",
		["Head south-west from {area:42} to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it."] = "Siga para sudoeste, de {area:42}, até a Gruta de Vul'Gol. {object:119} fica no acampamento da entrada; ogros Punhalasca o guardam.",
		["Inside"] = "Lá dentro",
		["Nightbane Dark Runners"] = "Corretrevas Nocturnos",
		["Nightbane Shadow Weavers"] = "Tece-sombras Nocturnos",
		["Nightbane Vile Fangs and the {npc:511}"] = "Presas Torpes Nocturnos e {npc:511}",
		["Only if a {npc:272273} dropped {quest:96138}: right-click it"] = "Só se um {npc:272273} deixou cair {quest:96138}: clique com o botão direito nele",
		["The Dark Runners prowl the woods south of the road, west of {area:42}."] = "Os Corretrevas rondam a mata ao sul da estrada, a oeste de {area:42}.",
		["The Defias camp lies in the south-west of {zone:1431}, south of {area:94} near the {zone:1436} border. The strongbox stands among the tents."] = "O acampamento dos Défias fica no sudoeste de {zone:1431}, ao sul de {area:94}, perto da fronteira com {zone:1436}. A caixa-forte fica entre as barracas.",
		["The Plague Spreaders walk the northern half of the {area:492}. {npc:522}, an elite, wanders the graves: keep away from him.\nSkeletal Raiders, Healers and Warders hold the west part of the cemetery, just east of {npc:311}'s camp.\nCareful: The skeletons in the catacombs are packed close together, so you can easily pull extra mobs."] = "Os Vetores da Peste andam pela metade norte de {area:492}. {npc:522}, um elite, perambula entre os túmulos: fique longe dele.\nSaqueadores, Curandeiros e Guardadores Descarnados ocupam a parte oeste do cemitério, logo a leste do acampamento de {npc:311}.\nCuidado: os esqueletos das catacumbas ficam amontoados, então é fácil puxar monstro a mais.",
		["The grave stands among the skeletons at the cemetery's north-west corner, on the way to {npc:311}. Its quest and the next are talk-only, to {npc:268} and Commander Althea in {area:42}: level 35 from level 28, but no fight."] = "O túmulo fica entre os esqueletos, no canto noroeste do cemitério, no caminho para {npc:311}. A missão dele e a seguinte são só de conversa, com {npc:268} e a Comandante Aldora, em {area:42}: nível 35 a partir do nível 28, mas sem luta.",
		["The strongest worgen roam the woods south of {area:42}, west and south of the {area:121}. The {npc:511} hides in the small crypt by the cemetery.\nCareful: {spell:8282} lasts 10 minutes and adds 13 to each hit of physical damage you take.\nCareful: Some worgen outside the cave stand in groups, including one camp of four. To avoid adds, pull them one at a time from the raised ground next to the cave entrance."] = "Os worgens mais fortes andam pela mata ao sul de {area:42}, a oeste e ao sul de {area:121}. O {npc:511} se esconde na criptinha junto ao cemitério.\nCuidado: {spell:8282} dura 10 minutos e soma 13 a cada golpe de dano físico que você leva.\nCuidado: alguns worgens fora da caverna ficam em grupo, incluindo um acampamento de quatro. Para não puxar a mais, puxe um de cada vez do terreno alto ao lado da entrada da caverna.",
		["The worgen hold the woods of Brightwood, west of {area:42} and north of the road. Pull them one at a time."] = "Os worgens dominam a mata do Bosque Brilhante, a oeste de {area:42} e ao norte da estrada. Puxe um de cada vez.",
		["Wait a moment, then speak with her again"] = "Espere um momento e fale com ela de novo",
		["{area:42} flight master"] = "Mestre de voo de {area:42}",
		["{area:492}: kill these as you meet them"] = "{area:492}: vá matando estes pelo caminho",
		["{area:93}: kill these as you meet them"] = "{area:93}: vá matando estes pelo caminho",
		["{item:1946}; inside"] = "{item:1946}; lá dentro",
		["{item:5947}; inside"] = "{item:5947}; lá dentro",
		["{npc:263}, in the town hall"] = "{npc:263}, na prefeitura",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, na casa atrás da prefeitura",
		["{npc:276}'s house stands at the east end of town, on the way to the flight master."] = "A casa de {npc:276} fica na ponta leste da cidade, no caminho para o mestre de voo.",
		["{npc:276}, inside"] = "{npc:276}, lá dentro",
		["{npc:311}'s Camp"] = "Acampamento do {npc:311}",
		["{npc:661}, by {npc:633}'s house; inside"] = "{npc:661}, junto à casa de {npc:633}; lá dentro",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, Taberna Corvo Escarlate",
		["{npc:840} walks around {area:42}: look inside the circle on the map"] = "{npc:840} anda por {area:42}: procure dentro do círculo no mapa",
		["{npc:840}, at the north entrance of town; walks around {area:42}: look inside the circle on the map"] = "{npc:840}, na entrada norte da cidade; anda por {area:42}: procure dentro do círculo no mapa",
} end)()
t.guides["forever/alliance/30-40/01-hillsbrad-foothills"] = (function() return {
		["A report for {object:2117}; inside"] = "Um relatório para {object:2117}; lá dentro",
		["Back down the road to {area:205}: {npc:1075} wants the {object:147516} explosives under the far end of the span destroyed."] = "De volta pela estrada até {area:205}: {npc:1075} quer os explosivos de {object:147516} sob o extremo do vão destruídos.",
		["Back east along the road to the {area:1025}: {npc:270637} camps among the Fenrunners, just west of {npc:1244}. Then west again to Menethil for the boat."] = "De volta a leste pela estrada até {area:1025}: {npc:270637} acampa entre os Corre-charcos, logo a oeste de {npc:1244}. Depois, de novo a oeste até Menethil para pegar o barco.",
		["Back over the span and down the road through {area:205} on the way south."] = "De volta pelo vão e descendo a estrada por {area:205}, a caminho do sul.",
		["Back to the same murlocs; not every one drops a head."] = "Volte aos mesmos murlocs; nem todos soltam uma cabeça.",
		["Beat {npc:4961} and his thugs: they give up"] = "Derrote {npc:4961} e os capangas dele: eles desistem",
		["Below ground"] = "No subterrâneo",
		["Boat to {area:271}"] = "Barco para {area:271}",
		["Cathedral of Light"] = "Catedral da Luz",
		["Daggerspine naga"] = "Nagas Espinhadaga",
		["Druid training"] = "Treinamento de druida",
		["Farren"] = "Fárrio",
		["Fly to {area:1537}"] = "Voe para {area:1537}",
		["Fly to {zone:1453}"] = "Voe para {zone:1453}",
		["For King Magni in {zone:1455}, at the end of this guide"] = "Para o Rei Magni em {zone:1455}, no fim deste guia",
		["For {npc:2916} in {zone:1455}, at the end of this guide"] = "Para {npc:2916} em {zone:1455}, no fim deste guia",
		["Inside"] = "Lá dentro",
		["Level 30 and 32 spells"] = "Feitiços de nível 30 e 32",
		["Level 30.8"] = "Nível 30.8",
		["Maddened Rotclaws roam the {area:1025} around {npc:1244}; one of them drops the flesh. {npc:1244} takes the quest only with {quest:98283}'s head too."] = "Patapodres Enlouquecidos rondam {area:1025}, ao redor de {npc:1244}; um deles solta a carne. {npc:1244} só aceita a missão com a cabeça de {quest:98283} também.",
		["Murloc heads"] = "Cabeças de murloc",
		["North along the road to {area:205}. {npc:1071} and {npc:1075} stand together in the dwarves' camp on the east side of the road; the {object:147516} ruins west of it are full of elites."] = "Ao norte pela estrada até {area:205}. {npc:1071} e {npc:1075} ficam juntos no acampamento dos anões, no lado leste da estrada; as ruínas de {object:147516}, a oeste dele, estão cheias de elites.",
		["North-east to the {area:1038}: {npc:271338} stands at the gates (use the {item:279996})."] = "Para nordeste até {area:1038}: {npc:271338} fica nos portões (use a {item:279996}).",
		["Off the boat, walk up the pier into town: {npc:2711} and Lieutenant Farren stand by the inn, {npc:2430} upstairs, {npc:2382} east of it; the flight master is at the north end, {npc:2381} and {npc:2438} between her and the inn, Maleb in the town hall at the west side.\n{npc:2366} may not offer {quest:98463} on Forever: if she doesn't, skip it."] = "Ao descer do barco, suba o cais até a cidade: {npc:2711} e o Tenente Fárrio ficam junto à estalagem, {npc:2430} no andar de cima, {npc:2382} a leste dela; o mestre de voo fica na ponta norte, {npc:2381} e {npc:2438} entre ela e a estalagem, e Maleb na prefeitura, no lado oeste.\n{npc:2366} pode não oferecer {quest:98463} no Forever: se ela não oferecer, pule.",
		["On the top floor"] = "No último andar",
		["Over the {area:880}: the Dark Irons' cache of explosives sits by its Arathi end."] = "Atravesse {area:880}: o esconderijo de explosivos dos Ferro Negro fica junto ao extremo de Arathi.",
		["Razormaw nests"] = "Ninhos de Rasgaqueixo",
		["Skipped {quest:474} and short of 30.8? Kill the Bluegill murlocs on the coast south of Menethil until level 30.8. Or, with a group, run the {area:133} dungeon or the {area:796} dungeon (Graveyard) instead."] = "Pulou {quest:474} e está abaixo do nível 30.8? Mate os murlocs Guelrazul na costa ao sul de Menethil até o nível 30.8. Ou, com um grupo, faça a masmorra {area:133} ou a masmorra {area:796} (Cemitério).",
		["Snapjaws"] = "Mordeliscas",
		["South-east from Menethil to the Dragonmaw's {area:1036}: the first catapult stands on the way, and the {object:671518} lies in the camp."] = "Ao sudeste de Menethil até {area:1036}, dos Presa do Dragão: a primeira catapulta fica no caminho, e {object:671518} está no acampamento.",
		["South-west from the Syndicate camp to the {area:286} farms."] = "Ao sudoeste do acampamento da Camarilha, até as fazendas de {area:286}.",
		["Syndicate camp"] = "Acampamento da Camarilha",
		["The Perfect Razormaw Eggs for {quest:98246} lie in the raptors' nests in the hills around {quest:98283}."] = "Os Ovos de Rasgaqueixo Perfeitos para {quest:98246} ficam nos ninhos dos raptores nas colinas ao redor de {quest:98283}.",
		["The Snapjaw turtles bask along the river east of {area:271}, south of {area:272} (Horde)."] = "As tartarugas Mordeliscas tomam sol ao longo do rio a leste de {area:271}, ao sul de {area:272} (Horda).",
		["The Syndicate camp sits on the Alterac border in northern {area:287}, west of {area:272} (Horde); the documents lie in the camp, and its Footpads and Thieves are the Syndicate Maleb wants."] = "O acampamento da Camarilha fica na divisa com as Montanhas de Alterac, no norte de {area:287}, a oeste de {area:272} (Horda); os documentos estão no acampamento, e seus Gatunos e Ladrões são a Camarilha que Maleb quer.",
		["The Torn Fin murlocs crowd the {area:295}, south-west of {area:271}.\nCareful: One camp holds a tight cluster of Oracles that all aggro together."] = "Os murlocs Rancapina lotam {area:295}, a sudoeste de {area:271}.\nCuidado: um dos acampamentos tem um bolo de Oráculos bem juntos que vêm todos de uma vez.",
		["The Villards"] = "Os Villard",
		["The cheese shop in the {object:2096}."] = "A loja de queijos em {object:2096}.",
		["The naga hold the shore south-east of {area:271}."] = "As nagas ocupam a costa a sudeste de {area:271}.",
		["The whelps nest in the hills north-east of the {area:1036}; {quest:98283} prowls further north, and the Razormaw raptors hunt the highlands on the way north to {area:205}.\n{quest:98283} is elite: grouping up is advised."] = "Os dragonetes fazem ninho nas colinas a nordeste de {area:1036}; {quest:98283} ronda mais ao norte, e os raptores Rasgaqueixo caçam nas terras altas no caminho para o norte, até {area:205}.\n{quest:98283} é elite: recomenda-se ir em grupo.",
		["The yetis live in the cave in the hills north of {area:271}, on the way north to the Syndicate camp."] = "Os yetis vivem na caverna nas colinas ao norte de {area:271}, no caminho para o norte até o acampamento da Camarilha.",
		["The {object:2704}"] = "A {object:2704}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. The {npc:271481} is held at the far west end of the {object:147516} ruins, past level 27-30 elite dwarves, and {npc:1364} (34, elite) can be among them. Lead it east out of the ruins, then hand it in to {npc:1072} in the camp. Skip it if you are alone."] = "Estes são monstros elite: recomenda-se ir em grupo, procure gente para isso. {npc:271481} fica preso no extremo oeste das ruínas de {object:147516}, depois de anões elite de nível 27-30, e {npc:1364} (34, elite) pode estar entre eles. Leve-o para leste, para fora das ruínas, e entregue-o a {npc:1072} no acampamento. Pule se estiver sozinho.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2091} is a level 32 elite: most classes solo it at level 34, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Shadowcasters stand on either side of him, and at least one is linked to him, so it joins when he is pulled. Non-elite centurions and captains are spread around his ring of tents."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:2091} é elite de nível 32: a maioria das classes encara sozinha no nível 34, mas talvez você precise de ajuda. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.\nCuidado: há lança-sombras dos dois lados dele, e pelo menos um está ligado a ele, então entra junto quando ele é puxado. Centuriões e capitães não elite se espalham pelo círculo de tendas dele.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:271462}, {npc:271338}, {npc:271458} and {npc:271460} are level 32 elites, each called up by using the {item:279996} beside it. Skip them if you are alone. {npc:271462} stands in the south-eastern hills."] = "São monstros elite: junte um grupo, procure gente para ir com você. {npc:271462}, {npc:271338}, {npc:271458} e {npc:271460} são elites de nível 32, cada um invocado ao usar a {item:279996} que fica ao lado dele. Pule-os se estiver sozinho. {npc:271462} fica nas colinas do sudeste.",
		["To {area:2104}"] = "Para {area:2104}",
		["Torn Fin murlocs"] = "Murlocs Rancapina",
		["Underwater"] = "Debaixo d'água",
		["Use the {item:279386} at the {area:287} council."] = "Use {item:279386} no conselho de {area:287}.",
		["West along the road to Menethil."] = "Para o oeste pela estrada até o Porto de Menethil.",
		["With {quest:98283}'s head and the flesh"] = "Com a cabeça de {quest:98283} e a carne",
		["Yeti cave"] = "Caverna dos yetis",
		["for {npc:2700} at {area:320}, in 05-arathi-highlands"] = "para {npc:2700} em {area:320}, em 05-arathi-highlands",
		["grind on {npc:1418}"] = "mate {npc:1418} até subir",
		["the same corpse"] = "o mesmo cadáver",
		["{area:1038}: kill these as you meet them"] = "{area:1038}: vá matando estes pelo caminho",
		["{area:271} flight master"] = "Mestre de voo de {area:271}",
		["{area:287} council"] = "Conselho de {area:287}",
		["{item:3713}, from {npc:2381}"] = "{item:3713}, de {npc:2381}",
		["{npc:1075} again"] = "{npc:1075} de novo",
		["{npc:1356}, {npc:2916} and {npc:5637} stand in the {object:32356}, north-east of the flight master."] = "{npc:1356}, {npc:2916} e {npc:5637} ficam no {object:32356}, a nordeste do mestre de voo.",
		["{npc:2104} stands on the top floor of {area:2103}: go up inside, the arrow cannot tell the floors apart."] = "{npc:2104} fica no último andar de {area:2103}: suba por dentro, a seta não diferencia os andares.",
		["{npc:2104}: for {npc:270637}, back east along the road"] = "{npc:2104}: para {npc:270637}, de volta a leste pela estrada",
		["{npc:2228}, inside"] = "{npc:2228}, lá dentro",
		["{npc:2276}, inside"] = "{npc:2276}, lá dentro",
		["{npc:2366}, in the inn: for {area:35} (04-stranglethorn-vale)"] = "{npc:2366}, na estalagem: para {area:35} (04-stranglethorn-vale)",
		["{npc:2382}: the lions come later"] = "{npc:2382}: os leões ficam para depois",
		["{npc:2430}, upstairs"] = "{npc:2430}, no andar de cima",
		["{npc:2438} makes a yeti fur cloak for anyone who brings a {item:3719} ({skill:165}) and a {item:2997} ({skill:197}); no vendor sells either, so this step shows only when you carry both."] = "{npc:2438} faz uma capa de pelo de yeti para quem levar {item:3719} ({skill:165}) e {item:2997} ({skill:197}); nenhum vendedor vende nenhum dos dois, então este passo só aparece quando você leva os dois.",
		["{npc:2438}, between the flight master and the inn: he wants a {item:3719} and a {item:2997} too"] = "{npc:2438}, entre o mestre de voo e a estalagem: ele quer {item:3719} e {item:2997} também",
		["{npc:251493} stands north-west of the flight master, on the way north to the yeti cave.\n{quest:98059}: {npc:251493} hands you a {item:279386} for the {area:287} council, in the farms west of {area:271}; you deliver it after the Syndicate camp."] = "{npc:251493} fica a noroeste do mestre de voo, no caminho para o norte até a caverna dos yetis.\n{quest:98059}: {npc:251493} entrega {item:279386} para o conselho de {area:287}, nas fazendas a oeste de {area:271}; você entrega depois do acampamento da Camarilha.",
		["{npc:2695}: for King Magni, on the same {zone:1455} stop"] = "{npc:2695}: para o Rei Magni, na mesma parada em {zone:1455}",
		["{npc:2708} is in the {object:2164}; {npc:5081} south of the {object:2101}."] = "{npc:2708} fica em {object:2164}; {npc:5081}, ao sul do {object:2101}.",
		["{npc:2711}: his trail leads to Arathi"] = "{npc:2711}: a pista dele leva ao Planalto Arathi",
		["{npc:271458} stands in the hills between the {area:1038} and {area:205} (use the {item:279996})."] = "{npc:271458} fica nas colinas entre {area:1038} e {area:205} (use {item:279996}).",
		["{npc:271460} stands in the ruins of {area:205} (use the {item:279996})."] = "{npc:271460} fica nas ruínas de {area:205} (use {item:279996}).",
		["{npc:2784}, the {object:171709}"] = "{npc:2784}, {object:171709}",
		["{npc:4455}, by the keep's door: for {quest:1132} in Theramore, in the next guide"] = "{npc:4455}, junto à porta da fortaleza: para {quest:1132} em Theramore, no próximo guia",
		["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961} espera na Taberna do Javatusco Saltitante, em {object:2100}; ele e seus dois capangas lutam com você, mas param quando derrotados.",
		["{npc:5479} trains warriors in {object:2100}, beside the Pig and Whistle. {npc:6236} waits on {area:720} in the {zone:1413}, on the way to {area:392} much later (40-50/01)."] = "{npc:5479} treina guerreiros em {object:2100}, ao lado da Taberna do Javatusco Saltitante. {npc:6236} espera em {area:720}, em {zone:1413}, no caminho para {area:392}, bem mais tarde (40-50/01).",
		["{npc:5683} waits on the road north of {area:205}, towards the {area:880}; {npc:271322} a short walk further north-east, and Ebenezer Rustlocke's corpse lies under the span beside her. Rustlocke's parchment goes back to {npc:1075}.\n{npc:5683} may not offer {quest:87318} yet: if she doesn't, skip it.\nTwo elite Dark Iron Saboteurs stand by the corpse inside the span: pull them one at a time, or loot the corpse and run out."] = "{npc:5683} espera na estrada ao norte de {area:205}, em direção a {area:880}; {npc:271322}, um pouco mais ao nordeste, e o cadáver de Ebenezer Ferratranca fica sob o vão, ao lado dela. O pergaminho de Ferratranca volta para {npc:1075}.\n{npc:5683} pode ainda não oferecer {quest:87318}: se ela não oferecer, pule.\nDois Sabotadores Ferro Negro elite ficam junto ao cadáver, dentro do vão: puxe um de cada vez, ou saqueie o cadáver e saia correndo.",
		["{object:2652}, inside"] = "{object:2652}, lá dentro",
		["{object:671518}: for {npc:2104}"] = "{object:671518}: para {npc:2104}",
		["{quest:98246}: the eggs"] = "{quest:98246}: os ovos",
		["{zone:1455} flight master"] = "Mestre de voo de {zone:1455}",
		["{zone:1455} has no druid trainer: {npc:5504} stands in {zone:1453}, north-west of the {object:2101}."] = "{zone:1455} não tem instrutor de druida: {npc:5504} fica em {zone:1453}, a noroeste do {object:2101}.",
} end)()
t.guides["forever/alliance/30-40/02-desolace"] = (function() return {
		["Boat to {area:17203}"] = "Barco para {area:17203}",
		["Escort {npc:5644}"] = "Escolte {npc:5644}",
		["Fly to {area:442}"] = "Voe para {area:442}",
		["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "Siga a estrada para o oeste, passando por {area:460} (Horda), e para o sudoeste por {area:465} até {zone:1443}; {area:608} fica no alto do desfiladeiro.",
		["For {npc:5638}, at the end of this guide"] = "Para {npc:5638}, no fim deste guia",
		["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building. {npc:5642} wants four of each kind of cultist on the way."] = "O irmão dela, {npc:5643} (36), anda pela fortaleza com os sectários da Lâmina Ardente (30-33): puxe-o sozinho. {npc:13019} guarda o cetro no prédio principal da fortaleza. {npc:5642} quer quatro de cada tipo de sectário pelo caminho.",
		["Inside"] = "Lá dentro",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "Leve {npc:5644} para fora da fortaleza; ela vai embora quando vocês saírem. {npc:5642} recebe a entrega em {area:608}, no fim do guia.",
		["Malem chest"] = "Baú de Malem",
		["Out of Thunder Axe Fortress"] = "Para fora da Fortaleza Machado do Trovão",
		["The Hatefury satyrs hold the ruins of {area:603}, east of {area:608}.\nCareful: Hatefury Rogues spawn stealthed, and Hatefury Tricksters have a poison proc on their attacks."] = "Os sátiros Furiódio ocupam as ruínas de {area:603}, a leste de {area:608}.\nCuidado: os Errantes Furiódio surgem furtivos, e os Trapaceiros Furiódio podem envenenar a cada golpe.",
		["The Kolkar roam the plains around {area:609}; their ears are for {npc:5752}."] = "Os Kolkar vagam pelas planícies ao redor de {area:609}; as orelhas deles são para {npc:5752}.",
		["The chest lies in the ruins south-west of {area:608}."] = "O baú está nas ruínas a sudoeste de {area:608}.",
		["The wrecked ship lies just south-west of {npc:11863}'s tower; its chest sits beside {object:177787}."] = "O navio naufragado fica logo a sudoeste da torre de {npc:11863}; o baú dele está ao lado de {object:177787}.",
		["{area:608} flight master"] = "Mestre de voo de {area:608}",
		["{item:6767}; inside"] = "{item:6767}; lá dentro",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "O acampamento de {npc:11596} fica na estrada ao sul de {area:609}, perto de {area:596}.",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "A torre de {npc:11863} fica no morro a oeste de {area:599}: pegue a missão dele primeiro; o cetro que ele quer está na fortaleza.",
		["{npc:5638}: the satchel lies off the north-west coast, on the south loop at the end of 30-40 (06-badlands): keep it"] = "{npc:5638}: a bolsa fica ao largo da costa noroeste, no circuito sul no fim de 30-40 (06-badlands): guarde-a",
		["{npc:5638}: the wreck's chest lies below {npc:11863}'s tower, on the way to {area:599}"] = "{npc:5638}: o baú do naufrágio fica abaixo da torre de {npc:11863}, no caminho para {area:599}",
		["{npc:5642}: the Burning Blade in {area:599}, where her search leads"] = "{npc:5642}: a Lâmina Ardente em {area:599}, para onde a busca dela leva",
		["{npc:5643} and the Seer"] = "{npc:5643} e o Vidente",
		["{npc:5644} hides inside the Burning Blade's fortress south-west of {area:608}."] = "{npc:5644} se esconde na fortaleza da Lâmina Ardente, a sudoeste de {area:608}.",
		["{npc:5644}, inside"] = "{npc:5644}, lá dentro",
		["{quest:5741}; on the top floor"] = "{quest:5741}; no último andar",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Boat to {area:150}"] = "Navio para {area:150}",
		["Crystalized Scale, from the Saltstone Basilisks: eight for {npc:4078} in {zone:1453}"] = "Escamas Cristalizadas, dos Basiliscos Sal-gema: oito para {npc:4078} em {zone:1453}",
		["Down the {area:485} into {zone:1441}, then west to the wyverns' cliffs at {area:482}. Every wyvern there can drop a venom sac."] = "Desça por {area:485} até {zone:1441}, depois a oeste até os penhascos das serpes em {area:482}. Toda serpe de lá pode soltar uma glândula de veneno.",
		["East through the canyons. {area:484}, a Horde camp with guards, sits on the mesa here: keep to the canyon floor and give the foot of its lifts a wide berth."] = "Para o leste pelos cânions. {area:484}, um acampamento da Horda com guardas, fica no planalto aqui: mantenha-se no fundo do cânion e passe bem longe da base dos elevadores.",
		["Fly to Theramore"] = "Voe para a Ilha Theramore",
		["Fly to {area:150}"] = "Voe para {area:150}",
		["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Siga os cânions para o leste até as planícies de sal. Os goblins e gnomos de {area:2240} são neutros e dão missões às duas facções.",
		["Follow the road west out of Theramore to the burned inn on the road toward the {zone:1413}: the black shield lies in the ashes and the hoofprints are in the mud beside the inn."] = "Siga a estrada para oeste, saindo de Theramore, até a estalagem queimada na estrada rumo a {zone:1413}: o escudo negro está nas cinzas e as pegadas de casco estão na lama ao lado da estalagem.",
		["For {npc:1416} in {zone:1453}, after Stranglethorn"] = "Para {npc:1416} em {zone:1453}, depois da Selva do Espinhaço",
		["For {quest:1132} in Theramore's inn, where this guide's boat goes"] = "Para {quest:1132} na estalagem de Theramore, para onde vai o barco deste guia",
		["For {quest:5762} in Stranglethorn, later"] = "Para {quest:5762}, na Selva do Espinhaço, mais tarde",
		["From the raceway follow the road south out of the {area:439} into {zone:1446}."] = "Da pista de corrida, siga a estrada para o sul, saindo de {area:439}, até {zone:1446}.",
		["Inside"] = "Lá dentro",
		["Into {zone:1413}"] = "Rumo a {zone:1413}",
		["Into {zone:1446}"] = "Rumo a {zone:1446}",
		["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "Na estrada para o sul por {zone:1413}, {npc:6244} acampa a leste da estrada, a nordeste de {area:378}; chegue pelo leste e fique longe dos guardas da Horda.",
		["Tapoke Jahn (34) slips out of the tavern once you take {quest:1248}: stay close behind him. He turns on you outside, a friend joins him, and he gives up once badly hurt. If you lose him the quest fails: abandon it and take it again from {npc:4963}."] = "Tapoke Jahn (34) sai furtivamente da taverna assim que você aceita {quest:1248}: fique bem atrás dele. Ele se vira contra você do lado de fora, um amigo se junta a ele, e ele desiste quando está muito ferido. Se você o perder, a missão falha: abandone-a e pegue de novo com {npc:4963}.",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "Os murlocs Guelrazul na praia a sudoeste de Menethil carregam os lingotes.",
		["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "O mestre de voo fica junto ao portão de {area:514}; {npc:5083} e {npc:4964} estão dentro da cidadela.",
		["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "O navio naufragado está nas águas rasas ao sul da fortaleza.",
		["Theramore"] = "Theramore",
		["{area:2240}: kill these as you meet them"] = "{area:2240}: vá matando estes pelo caminho",
		["{area:976} flight master"] = "Mestre de voo de {area:976}",
		["{area:976} is a short walk down the road; keep to it. {npc:7823}, the Alliance flight master, stands inside the walls."] = "{area:976} fica a uma curta caminhada pela estrada; mantenha-se nela. {npc:7823}, o mestre de voo da Aliança, fica dentro das muralhas.",
		["{item:2702}; underwater"] = "{item:2702}; debaixo d'água",
		["{npc:1217} stands in the {area:2104}, south of the keep, where {npc:4963} and {npc:5082} wait too."] = "{npc:1217} fica em {area:2104}, ao sul da fortaleza, onde {npc:4963} e {npc:5082} também esperam.",
		["{npc:4454}: for Martek in the {zone:1418}, at the end of 30-40"] = "{npc:4454}: para Martek em {zone:1418}, no fim do 30-40",
		["{npc:4455} stands by {area:2103}'s door, just north of the flight master."] = "{npc:4455} fica junto à porta de {area:2103}, logo ao norte do mestre de voo.",
		["{npc:4456} is in the north of town, Captain Vimes in {area:514}; {npc:4941} stands in the town."] = "{npc:4456} fica no norte da cidade, o Capitão Vimes em {area:514}; {npc:4941} fica na cidade.",
		["{npc:4456}'s next errand goes to {area:415}, off this route: leave it."] = "A próxima tarefa de {npc:4456} vai para {area:415}, fora desta rota: deixe-a.",
		["{npc:4964}, on the top floor"] = "{npc:4964}, no último andar",
		["{npc:5083}, on the top floor"] = "{npc:5083}, no último andar",
		["{object:19868} lies all over the flats. Scorpid Reavers and Salt Flats Scavengers roam the north half, Sparkleshell Snappers (tortoises) the whole flats. Saltstone Basilisks and Crystalhides hold the middle; the Gazers (34-35) only the far south."] = "Os {object:19868} estão espalhados pela planície. Aniquiladores Escorpídeos e Catadores da Planície Salgada andam pela metade norte; Tartaliscas Quelobrilho (tartarugas), pela planície toda. Basiliscos Sal-gema e Cristaldermes Sal-gema dominam o meio; os Observadores (34-35) ficam só no extremo sul.",
		["{quest:1132}, inside the inn in the north of town"] = "{quest:1132}, dentro da estalagem no norte da cidade",
		["{quest:1132}: the wyverns are in {zone:1441}, later in this guide"] = "{quest:1132}: as serpes ficam em {zone:1441}, mais adiante neste guia",
		["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738}: em {zone:1440}, no caminho para {zone:1443}",
		["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602}: o íncubo, ao lado da súcubo; {item:190309} fica perto de {quest:1738}",
		["{zone:1453} flight master"] = "Mestre de voo de {zone:1453}",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back east to Nesingwary's camp on the way north to the {area:99}."] = "De volta a leste, até o acampamento de Rosarães, a caminho do norte, para {area:99}.",
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "De volta ao sul, passando Rosarães: Panteras e Raptores-do-espinhaço correm nas clareiras a oeste do acampamento, rumo à costa; os tigres anciões dominam as colinas a sudoeste.",
		["Both roam the grass around the camp and along the road north."] = "Os dois vagam pelo capim ao redor do acampamento e ao longo da estrada para o norte.",
		["Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "Cuidado: há acampamentos troll perto da área dos tigres, e os trolls podem entrar na briga se você puxar sem cuidado.\nCuidado: o ninho de raptores tem filhotes que entram na briga quando você ataca os adultos.",
		["Down to {area:35}"] = "Descendo até {area:35}",
		["Druid training"] = "Treinamento de druida",
		["Fly to {area:108}"] = "Voe para {area:108}",
		["Fly to {area:415}"] = "Voe para {area:415}",
		["Fly to {area:42}"] = "Voar para {area:42}",
		["Fly to {zone:1453}"] = "Voe para {zone:1453}",
		["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "Siga a estrada principal para o sul por toda a selva, passando o desvio para {object:3202}, até {area:35}, no cabo ao sul.",
		["From {area:108} the way leads south out of {zone:1436} into Stranglethorn's north-west, to the {area:310} near the coast; the Crystal Spine Basilisks around it drop the shards.\nThe haunted island lies just off the coast south-west of the mine: just reach it. The Bloodscalp trolls hold the ruins on the coast to the north."] = "De {area:108}, o caminho segue para o sul, saindo de {zone:1436}, até o noroeste da Selva do Espinhaço, até {area:310}, perto da costa; os Basiliscos da Serra dos Cristais em volta dela soltam os cristais.\nA ilha mal-assombrada fica logo ao largo da costa, a sudoeste da mina: basta chegar lá. Os trolls Sanguescalpo dominam as ruínas na costa, ao norte.",
		["From {area:415} head north-west into the hills: the {quest:1738} is a glowing tree north of the road to {area:413}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {area:413} (26.6,22.0). Then take the road west to Stonetalon."] = "De {area:415}, siga para noroeste, pelas colinas: {quest:1738} é uma árvore brilhante ao norte da estrada para {area:413}. Se você pegou {quest:65602}, {item:190309} está numa casa entre as árvores ao norte de {area:413} (26.6,22.0). Depois siga a estrada para oeste até a Cordilheira das Torres de Pedra.",
		["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "De {zone:1431}, pegue a estrada para o sul até a Selva do Espinhaço; as barracas dos caçadores ficam logo a oeste da estrada, depois do desvio para {area:99}.",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "Glubglub, um murloc raro na costa a oeste do acampamento, deixa cair {item:4614}: pegue se encontrá-lo",
		["Level 33.2"] = "Nível 33.2",
		["Level 33.6"] = "Nível 33.6",
		["Level 34"] = "Nível 34",
		["Panthers, raptors and elder tigers"] = "Panteras, raptores e tigres anciões",
		["River Crocolisks swim the river by the {area:99}."] = "Crocoliscos do Rio nadam no rio junto a {area:99}.",
		["River crocolisks"] = "Crocoliscos do Rio",
		["Short of 33.6? Keep on the Kurzen Jungle Fighters and Medicine Men around the compound's outer edge until level 33.6. Or, with a group, run the {area:796} dungeon (Library) instead."] = "Abaixo de 33.6? Continue nos Guerrilheiros da Selva e Curandeiros de Kurzen na borda externa do complexo até o nível 33.6. Ou, com um grupo, faça a masmorra {area:796} (Biblioteca).",
		["Stranglethorn Tigers"] = "Tigres-do-espinhaço",
		["Take the road north; the camp sits in the hills to the west.\n{npc:738} spends most of his time at the top of the {area:99}'s path, by the huts, and now and then walks down it to the road and back (about eight minutes). If he isn't at the arrow, look along that path."] = "Siga a estrada para o norte; o acampamento fica nas colinas a oeste.\n{npc:738} passa a maior parte do tempo no alto do caminho de {area:99}, junto às cabanas, e de vez em quando desce por ele até a estrada e volta (cerca de oito minutos). Se ele não estiver na seta, procure ao longo desse caminho.",
		["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents. {quest:200}'s records lie in a hut on the compound's west side."] = "Os rebeldes de Kurzen dominam o complexo a leste de {area:99}; trabalhe pela borda externa, onde ficam os Guerrilheiros da Selva e os Curandeiros, e saqueie os caixotes de suprimentos junto às barracas. Os registros de {quest:200} ficam numa cabana no lado oeste do complexo.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Os tigres adultos rondam as colinas logo ao sul e a oeste do acampamento.",
		["The elder tigers come later, on the way back from the {area:99}"] = "Os tigres anciões ficam para depois, na volta de {area:99}",
		["The haunted island"] = "A ilha assombrada",
		["The jungle's quests climb to 37 from here: short of 33.2? Keep on the Stranglethorn Tigers in the hills just south and west of the camp until level 33.2. Or, with a group, run the {area:796} dungeon (Library) instead."] = "As missões da selva sobem para 37 a partir daqui: abaixo de 33.2? Continue nos Tigres-do-espinhaço nas colinas logo ao sul e a oeste do acampamento até o nível 33.2. Ou, com um grupo, faça a masmorra {area:796} (Biblioteca).",
		["The quests from here on are 37: if you are short of 34, keep on the elder tigers in the hills south-west of Nesingwary's camp until level 34. Or, with a group, run the {area:796} dungeon (Library or Armory) instead."] = "As missões daqui em diante são de nível 37: se estiver abaixo do 34, continue nos tigres anciãos das colinas a sudoeste do acampamento de Nesingwary até o nível 34. Ou, com um grupo, faça a masmorra {area:796} (Biblioteca ou Arsenal).",
		["The strongbox is deeper in, by the cave: on the northern loop (04b)"] = "O cofre fica mais para dentro, junto à caverna: no circuito do norte (04b)",
		["Young tigers and panthers"] = "Tigres e panteras jovens",
		["grind on {npc:1085}"] = "mate {npc:1085} até subir",
		["grind on {npc:682}"] = "mate {npc:682} até subir",
		["grind on {npc:937}"] = "mate {npc:937} até subir",
		["{area:101}: kill these as you meet them"] = "{area:101}: vá matando estes pelo caminho",
		["{area:150} flight master"] = "Mestre de voo de {area:150}",
		["{area:301}: kill these as you meet them"] = "{area:301}: vá matando estes pelo caminho",
		["{area:35} flight master"] = "Mestre de voo de {area:35}",
		["{area:442} flight master"] = "Mestre de voo de {area:442}",
		["{item:190309}, north of {area:413}"] = "{item:190309}, ao norte de {area:413}",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, de um caixote de {object:263}",
		["{npc:2495}, by the bank; inside"] = "{npc:2495}, junto ao banco; lá dentro",
		["{npc:2495}, inside"] = "{npc:2495}, lá dentro",
		["{npc:2495}: the Snapjaw Crocolisks, on the northern loop"] = "{npc:2495}: os Crocolíscos Arapuca, no circuito do norte",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, no andar de cima da taberna",
		["{npc:2496}: the water elementals rise around the haunted island, on the northern loop"] = "{npc:2496}: os elementais da água surgem em volta da ilha assombrada, no circuito do norte",
		["{npc:2498}, inside"] = "{npc:2498}, lá dentro",
		["{npc:2832}, in the {object:56910}; upstairs"] = "{npc:2832}, na {object:56910}; no andar de cima",
		["{npc:4078} is in the {object:2164}, in the {object:2101}."] = "{npc:4078} fica em {object:2164}, em {object:2101}.",
		["{npc:469}, in the hut"] = "{npc:469}, na cabana",
		["{npc:469}: {quest:200}'s records lie at the edge of {area:101}, next"] = "{npc:469}: os registros de {quest:200} ficam na beira de {area:101}, a seguir",
		["{npc:5504}, the druid trainer, stands in {zone:1453}, north-west of the {object:2101}."] = "{npc:5504}, a instrutora de druida, fica em {zone:1453}, a noroeste do {object:2101}.",
		["{npc:6807}, {object:56910}; upstairs"] = "{npc:6807}, {object:56910}; no andar de cima",
		["{npc:715}, from {zone:1441}"] = "{npc:715}, de {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} coleciona {item:2755}: as páginas caem de quase todo humanoide da selva. Transforme as páginas em capítulos pelo caminho.",
		["{npc:729} and the Lashtail raptors"] = "{npc:729} e os raptores Batecauda",
		["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "{npc:729}, o grande tigre, tem seu covil no alto da colina a sudoeste do acampamento; Raptores Batecauda correm ao sul dele, no caminho para {area:35}.",
		["{npc:737}, in the tavern"] = "{npc:737}, na taberna",
		["{npc:737}, upstairs"] = "{npc:737}, no andar de cima",
		["{npc:737}: the Tumbled Crystals, on the northern loop"] = "{npc:737}: os Cristais Rolados, no circuito do norte",
		["{npc:738} spends most of his time at the top of the {area:99}'s path, by the huts, and now and then walks down it to the road and back (about eight minutes). If he isn't at the arrow, look along that path."] = "{npc:738} passa a maior parte do tempo no alto do caminho de {area:99}, junto às cabanas, e de vez em quando desce por ele até a estrada e volta (cerca de oito minutos). Se ele não estiver na seta, procure ao longo desse caminho.",
		["{npc:770}: for {npc:773} in {area:35}, later in this guide"] = "{npc:770}: para {npc:773} em {area:35}, mais adiante neste guia",
		["{npc:773}, from {npc:770}"] = "{npc:773}, de {npc:770}",
		["{npc:773}, in the tavern; upstairs"] = "{npc:773}, na taberna; no andar de cima",
		["{npc:773}, upstairs"] = "{npc:773}, no andar de cima",
		["{object:287}, in the hut"] = "{object:287}, na cabana",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: basta olhar em volta do acampamento dos caçadores",
		["{zone:1434}: kill these as you meet them"] = "{zone:1434}: vá matando estes pelo caminho",
} end)()
t.guides["forever/alliance/30-40/04b-stranglethorn-vale"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "MacKinley \"Lobo do Mar\", no último andar",
		["East to the {area:99}, on the way back to Nesingwary's camp."] = "Para o leste até {area:99}, no caminho de volta ao acampamento do Rosarães.",
		["East to {area:101}: Herod's records lie in a hut on its west side."] = "Para o leste até {area:101}: os registros de Herodes ficam numa cabana no lado oeste.",
		["Fly to {area:42}"] = "Voar para {area:42}",
		["For Archmage Ansirem in {zone:1416}"] = "Para o Arquimago Ansirem, em {zone:1416}",
		["From {zone:1431} take the road south; the camp sits in the hills west of the road."] = "De {zone:1431}, siga a estrada para o sul; o acampamento fica nas colinas a oeste da estrada.",
		["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave, and Herod's strongbox sits by the cave mouth. Pick up Green Hills pages as they drop.\nCareful: Kurzen Commandos are level 34-35, not elite, and often spawn stealthed; near death they use {spell:7964}."] = "Encolhedores de Cabeças ficam mais fundo no complexo; as Tropas de Choque ficam à espreita, furtivas, em volta dele e na caverna, e o cofre de Herodes fica na boca da caverna. Pegue as páginas de Grande Espinhaço: Veredas conforme caírem.\nCuidado: as Tropas de Choque de Kurzen são de nível 34-35, não elite, e costumam aparecer furtivas; perto da morte, elas usam {spell:7964}.",
		["In the {object:2164}, if you still carry it"] = "Em {object:2164}, se você ainda estiver com isso",
		["Into {zone:1434}"] = "Rumo a {zone:1434}",
		["Level 36"] = "Nível 36",
		["North along the coast to the ruins on the hill: the last two tablets lie there. Pick up Green Hills pages as they drop."] = "Para o norte pela costa até as ruínas na colina: as duas últimas tabuletas ficam lá. Pegue as páginas de Grande Espinhaço: Veredas conforme caírem.",
		["Skullsplitter trolls"] = "Trolls Rachacrânio",
		["Snapjaw Crocolisks"] = "Crocoliscos Arapuca",
		["Snapjaw Crocolisks bask along the river in the middle of the jungle, on the way south to the Skullsplitter ruins."] = "Crocolíscos Arapuca tomam sol ao longo do rio no meio da selva, no caminho para o sul até as ruínas Rachacrânio.",
		["South along the road: the hunters' tents stand just west of it."] = "Para o sul pela estrada: as barracas dos caçadores ficam logo a oeste dela.",
		["South from the compound to {area:37}: the Venture Co. Geologists in the camps on its shore carry the Tumbled Crystals, and the Shadowmaw Panthers prowl stealthed in the jungle south and east of it."] = "Do complexo, siga para o sul até {area:37}: os Geólogos da Empreendimentos S.A. nos acampamentos da margem carregam os Cristais Rolados, e as Panteras Umbragorja rondam furtivas na selva ao sul e a leste dele.",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "Os trolls Rachacrânio dominam as ruínas a leste da estrada, entre Rosarães e {object:3202}.",
		["The haunted island lies just off the shore west of the second tablet: the Lesser Water Elementals rise from the water around it."] = "A ilha assombrada fica logo ao largo da costa, a oeste da segunda tabuleta: os Elementais Inferiores da Água surgem da água em volta dela.",
		["The jungle ruins"] = "As ruínas da selva",
		["The {area:102}"] = "{area:102}",
		["West across the jungle to the troll ruins: each holds one stone tablet of the troll legends, the first two in the ruins south-west of Nesingwary's camp, the last two on the hill in the north-west."] = "Para o oeste pela selva até as ruínas trolls: cada uma guarda uma tabuleta de pedra das lendas trolls, as duas primeiras nas ruínas a sudoeste do acampamento do Rosarães, as duas últimas na colina a noroeste.",
		["grind on {npc:1152}"] = "mate {npc:1152} até subir",
		["{item:2006}: {object:58}; underwater"] = "{item:2006}: {object:58}; debaixo d'água",
		["{npc:2495}, inside"] = "{npc:2495}, lá dentro",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, no andar de cima da taberna",
		["{npc:2498}, inside"] = "{npc:2498}, lá dentro",
		["{npc:718}: the Shadowmaw Panthers prowl around {area:37}, after {area:101}"] = "{npc:718}: as Panteras Umbragorja rondam {area:37}, depois de {area:101}",
		["{npc:733}: the Commandos and Headshrinkers fell in the compound"] = "{npc:733}: as Tropas de Choque e os Encolhedores de Cabeças são abatidos no complexo",
		["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}: para {npc:773}, em {area:35}",
		["{npc:773}, upstairs"] = "{npc:773}, no andar de cima",
		["{npc:773}: the ore drops from Drywhisker kobolds in {zone:1417}, next"] = "{npc:773}: o minério cai dos kobolds Bigodesseco em {zone:1417}, a seguir",
		["{npc:941}, below ground"] = "{npc:941}, no subterrâneo",
		["{object:287}, upstairs"] = "{object:287}, no andar de cima",
		["{object:288}, below ground"] = "{object:288}, no subterrâneo",
		["{quest:205}'s Skullsplitter trolls are 39-42. Below 36? Keep killing the Snapjaw Crocolisks along the river until level 36. Or, with a group, run the {area:796} dungeon (Armory) or the {area:1316} dungeon instead."] = "Os trolls Rachacrânio de {quest:205} são de nível 39-42. Abaixo do 36? Continue matando os Crocoliscos Arapuca ao longo do rio até o nível 36. Ou, com um grupo, faça a masmorra {area:796} (Arsenal) ou a masmorra {area:1316}.",
		["{zone:1453} flight master"] = "Mestre de voo de {zone:1453}",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A {npc:2434} lurks unseen on the edge of {area:271}; kill him and read the contract he carries."] = "Um {npc:2434} espreita invisível na borda de {area:271}; mate-o e leia o contrato que ele carrega.",
		["Back west through {zone:1430} to {area:42}."] = "De volta para oeste por {zone:1430} até {area:42}.",
		["Below ground"] = "No subterrâneo",
		["Careful: Syndicate Spies and Assassins can be stealthed. Assassins also poison you.\nCareful: About three stealthed Syndicate mobs are inside {npc:2320}'s house. {npc:2320} does not join when they are pulled, and a ranged attack through the doorway brings him out by himself."] = "Cuidado: Espiões e Assassinos da Camarilha podem estar furtivos. Os Assassinos ainda envenenam você.\nCuidado: há uns três da Camarilha furtivos dentro da casa de {npc:2320}. {npc:2320} não entra quando eles são puxados, e um ataque à distância pela porta traz só ele para fora.",
		["Crushridge ogres"] = "Ogros Massacristas",
		["Each key lies at one of the Highlands' standing-stone circles: east of the shards, near {area:320} and in the west. The {object:2702} stands west of {area:320}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "Cada chave fica num dos círculos de monólitos do Planalto: a leste dos estilhaços, perto de {area:320} e no oeste. A {object:2702} fica a oeste de {area:320}.\nCuidado: cada pedra central é guardada por uns três elementais perto do nível 39, que atacam juntos se você clicar na pedra sem limpá-los antes: Exilados em Chamas no Oeste, Exilados Trovejantes no Externo, Exilados Vagalhantes no Leste.",
		["East along the road to the {area:76}. {npc:256028} mobs drop the crystals; Noboru walks the ruins and drops his cudgel."] = "Para leste pela estrada até o {area:76}. Os {npc:256028} deixam cair os cristais; Noboru anda pelas ruínas e deixa cair sua borduna.",
		["East from {area:327} through the southern hills: {npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley."] = "A leste de {area:327}, pelas colinas do sul: {npc:2793}, um ogro mago, ocupa a caverna no extremo sul do vale Cascasseca.",
		["East from {quest:681} across the north of the Highlands; the shards glitter on the hill by the {area:333}, north of {area:314}."] = "Para leste a partir de {quest:681}, atravessando o norte do Planalto; os estilhaços brilham na colina junto ao {area:333}, ao norte de {area:314}.",
		["Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming."] = "Escolte o professor morro acima até a caverna acima da enseada e proteja-o enquanto ele trabalha. Dois elementais da água de nível 40 o emboscam ali, e eles são imunes a gelo. Segure-os na boca da caverna, longe dele: se a luta for dentro da caverna, ele entra na briga em vez de trabalhar e continuam aparecendo mais elementais.",
		["Fly to {area:271}"] = "Voar para {area:271}",
		["Fly to {area:42}"] = "Voar para {area:42}",
		["Fly to {zone:1453}"] = "Voar para {zone:1453}",
		["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "Siga a estrada para leste saindo de {area:287}, passando a {area:1057}, até o {area:320}.",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings. {npc:2306} (40) turns up in one spot at a time: the cellar of {area:280}'s inn, or one of the Syndicate tent camps in the uplands north and north-west of the village."] = "Siga a estrada para o norte saindo de {area:271} até as montanhas. Leões da montanha vagam pelas encostas; a Camarilha em {area:280} usa os anéis de sinete. {npc:2306} (40) aparece em um lugar de cada vez: no porão da estalagem de {area:280} ou em um dos acampamentos de tendas da Camarilha nas terras altas ao norte e a noroeste do vilarejo.",
		["Follow the road north to the draenei of the {area:657}."] = "Siga a estrada para o norte até os draeneis do {area:657}.",
		["For {npc:1440} in {zone:1453}: keep it"] = "Para {npc:1440} em {zone:1453}: guarde-o",
		["For {npc:2487} in {area:35}: keep it"] = "Para {npc:2487} em {area:35}: guarde-o",
		["For {npc:2542} in {area:35}: keep it"] = "Para {npc:2542} em {area:35}: guarde-o",
		["For {npc:2711} in {area:271}"] = "Para {npc:2711} em {area:271}",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "De {zone:1455}, pegue o túnel para leste por {zone:1426} até {zone:1432} e siga a estrada até {area:144}.",
		["Hay Weevils crawl about the north end of {quest:681}'s farm: catch one with the tool from {npc:217412}'s Entomology Starter Kit."] = "Gorgulhos do Feno rastejam pela ponta norte da fazenda de {quest:681}: pegue um com a ferramenta do kit de entomologia de {npc:217412}.",
		["Inside"] = "Lá dentro",
		["North-west out of the Witherbark valley; {npc:2712} and {npc:2713} camp in the hills just north of {area:314}."] = "Para noroeste, saindo do vale Cascasseca; {npc:2712} e {npc:2713} acampam nas colinas logo ao norte de {area:314}.",
		["Off the flight, straight to the {area:271} inn."] = "Ao descer do voo, direto para a estalagem de {area:271}.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Só se Glubglub lhe deu o pingente no Espinhaço",
		["Phizzlethorpe"] = "Bruzundanga",
		["South along the west coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "Siga para o sul pela costa oeste até a enseada dos goblins; Lolo vigia das pedras acima dela.",
		["South down the road to {npc:5476}, on the way west out of the swamp."] = "Ao sul pela estrada até {npc:5476}, no caminho para oeste, saindo do pântano.",
		["South from the {object:2691}, past {area:314}, to {area:317} in the hills: the Witch Doctors stand among the huts and the Shadow Hunters guard the far end of the valley. Every troll can drop a tusk."] = "Para o sul a partir da {object:2691}, passando a {area:314}, até {area:317} nas colinas: os Mandingueiros ficam entre as cabanas e os Caçadores Sombrios guardam o fundo do vale. Todo troll pode soltar uma presa.",
		["South-east along the loch to the dig site."] = "Para sudeste ao longo do lago até o sítio de escavação.",
		["South-west from {npc:2793}'s cave to the {area:880}: {npc:2696} stands on a broken section of the bridge; jump down to him from its north end. {quest:647} must reach {npc:2705} in {area:271} within 15 minutes: go straight back to {area:320} and fly to {area:271}."] = "Ao sudoeste da caverna de {npc:2793} até {area:880}: {npc:2696} fica num trecho quebrado da ponte; pule até ele pelo extremo norte. {quest:647} precisa chegar a {npc:2705} em {area:271} em 15 minutos: volte direto a {area:320} e voe até {area:271}.",
		["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "Para sudoeste até o acampamento do Kirin Tor na margem do lago a oeste de {area:279}, logo depois da divisa com {zone:1421}: a {npc:269127} fica lá. O Arquimago Ansirem fica a sudeste dela, junto à cúpula.",
		["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way.\nCareful: Orcs that drop to low health run away. {npc:2713} follows them and can pull more mobs, so kill or slow runners fast."] = "Fique com {npc:2713} enquanto ela se esgueira até {area:314} e volta; orcs da Horda pulam em vocês no caminho.\nCuidado: orcs com pouca vida fogem. {npc:2713} vai atrás deles e pode puxar mais monstros, então mate ou deixe lentos os fujões rapidinho.",
		["The Crushridge ogres hold the hills north of {area:280}. Farther north, a worn wooden chest holds the {item:3706}; {npc:2320} of the {quest:537} stands right by it.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and drop the knucklebones too: pull one at a time, or group up."] = "Os ogros Massacrista dominam as colinas ao norte de {area:280}. Mais ao norte, um baú de madeira gasto guarda {item:3706}; {npc:2320}, de {quest:537}, fica bem ao lado dele.\nOs Espancadores, Magos, Impositores e Fomentadores da Guerra Massacrista (36-39) são elite; os Ogros e Brutamontes Massacrista (34-35) não são e também soltam os Nós dos Dedos Sujos: puxe um de cada vez, ou forme grupo.",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop both the motes and Krazek's ore.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "Os kobolds Bigodesseco cavam no desfiladeiro a leste de {area:321} (Horda); contorne a cidade pelo norte. Eles deixam cair tanto as partículas quanto o minério do Krazek.\nCuidado: todo tipo de kobold sai correndo atrás de ajuda com pouca vida (Kobolds com 30%, Topógrafos e Escavadores com 15%), o que pode trazer mais deles.",
		["The Syndicate hold the farm north-west of {area:320}.\nCareful: Syndicate Highwaymen are level 30-31 and can cast Sneak while out of combat, so they are often stealthed and hard to spot."] = "A Camarilha ocupa a fazenda a noroeste de {area:320}.\nCuidado: os Bandoleiros da Camarilha são de nível 30-31 e ficam furtivos fora de combate, então costumam estar escondidos e difíceis de ver.",
		["The courier walks the road from {area:314} west across the Highlands, as far as about 24,45, and back, with two guards: the arrow follows the road west until you meet him. Pull them off the road."] = "O mensageiro anda pela estrada de {area:314} para oeste, atravessando o Planalto até mais ou menos 24,45, e volta, com dois guardas: a seta segue a estrada para oeste até você encontrá-lo. Atraia-os para fora da estrada.",
		["The shards lie at the far end of {area:318}."] = "Os estilhaços estão no fundo do {area:318}.",
		["The tomes lie in the ruined keep west of {area:280}; Argus Shadow Mages hold the ruins.\nCareful: Crushridge Warmongers call nearby allies within 15 yd once they fall below half health.\nThe Crushridge Maulers, Mages, Enforcers and Warmongers (36-39) are elite; the Crushridge Ogres and Brutes (34-35) are not and carry the tomes too: pull one at a time, or group up."] = "Os tomos estão na fortaleza em ruínas a oeste de {area:280}; Magos das Sombras Argus dominam as ruínas.\nCuidado: Fomentadores da Guerra Massacrista chamam aliados próximos a até 15 metros quando ficam abaixo de metade da vida.\nOs Espancadores, Magos, Impositores e Fomentadores da Guerra Massacrista (36-39) são elite; os Ogros e Brutamontes Massacrista (34-35) não são e também carregam os tomos: puxe um de cada vez, ou forme grupo.",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "Os dois naufrágios ficam na baía a oeste da enseada. As cartas náuticas e os diários estão dentro deles; as gemas estão no fundo do mar em volta. Nagas Espinhadaga nadam pela baía inteira.",
		["The western swamp"] = "O pântano oeste",
		["The wrecked caravan's chest lies at the north end of the {area:76}, beside {npc:5391}'s cage.\nCareful: The camp is full of Lost Ones around level 38. They stand in linked groups of 2-3, many are casters, and they respawn quickly."] = "O baú da caravana destruída fica no extremo norte de {area:76}, ao lado da jaula de {npc:5391}.\nCuidado: o acampamento está cheio de Perdidos de nível 38 ou perto disso. Eles ficam em grupos ligados de 2-3, muitos são conjuradores, e renascem rápido.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:2417} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:2417} walks from the arrow north-east through the ruins to about 40,47 and back: if he isn't at the arrow, follow his path."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:2417} é elite de nível 40: a maioria das classes encara sozinha no nível 42, mas talvez você precise de ajuda. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.\n{npc:2417} anda da seta para nordeste pelas ruínas até mais ou menos 40,47 e volta: se ele não estiver na seta, siga o caminho dele.",
		["Tram to {zone:1455}"] = "Metrô para {zone:1455}",
		["West along the road from {npc:5391}'s strongbox to the {area:657}."] = "Para oeste pela estrada, do cofre de {npc:5391} até {area:657}.",
		["West along the road to {area:320}, on the way to the {object:2689}."] = "Para oeste pela estrada até {area:320}, a caminho de {object:2689}.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Crocoliscos jovens, Tece-mágoas e Jaguares do Pântano vagam pelo pântano em volta da estrada.",
		["{area:280}: kill these as you meet them"] = "{area:280}: vá matando estes pelo caminho",
		["{area:281}: kill these as you meet them"] = "{area:281}: vá matando estes pelo caminho",
		["{area:318}: kill these as you meet them"] = "{area:318}: vá matando estes pelo caminho",
		["{area:320} flight master"] = "Mestre de voo de {area:320}",
		["{area:328}: kill these as you meet them"] = "{area:328}: vá matando estes pelo caminho",
		["{area:35} flight master"] = "Mestre de voo de {area:35}",
		["{item:2321}, from {npc:2381}"] = "{item:2321}, de {npc:2381}",
		["{item:3658}: Crushridge ogres"] = "{item:3658}: ogros Massacrista",
		["{item:3659}: the {object:1760}; inside"] = "{item:3659}: a {object:1760}; lá dentro",
		["{item:4435} from {npc:2572}, {npc:2573} and {npc:2574}, by this stop"] = "{item:4435} de {npc:2572}, {npc:2573} e {npc:2574}, perto desta parada",
		["{item:4492}; underwater"] = "{item:4492}; debaixo d'água",
		["{item:4525}; below ground"] = "{item:4525}; no subterrâneo",
		["{item:5040}; below ground"] = "{item:5040}; no subterrâneo",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, na estrada do {area:17203}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, Catedral da Luz",
		["{npc:1356}, {object:32356}: for {npc:1344} in {zone:1432}, next"] = "{npc:1356}, {object:32356}: para {npc:1344} em {zone:1432}, em seguida",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, na Biblioteca Real da fortaleza",
		["{npc:1470}, below ground"] = "{npc:1470}, no subterrâneo",
		["{npc:1776}: Noboru's cudgel"] = "{npc:1776}: a borduna de Noboru",
		["{npc:185335}, at the same circle"] = "{npc:185335}, no mesmo círculo",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: três bichinhos para capturar em Arathi, {zone:1443} e no Espinhaço",
		["{npc:2276}, inside"] = "{npc:2276}, lá dentro",
		["{npc:2277}: the parchment"] = "{npc:2277}: o pergaminho",
		["{npc:2438} stands between the flight master and the inn; {npc:2381} beside him sells {item:2321} if you have none."] = "{npc:2438} fica entre o mestre de voo e a estalagem; {npc:2381}, ao lado dele, vende {item:2321}, se você não tiver.",
		["{npc:2595}, underwater"] = "{npc:2595}, debaixo d'água",
		["{npc:2596}, underwater"] = "{npc:2596}, debaixo d'água",
		["{npc:2700}: {npc:1075}'s plea, from 01-hillsbrad-foothills"] = "{npc:2700}: o apelo de {npc:1075}, de 01-hillsbrad-foothills",
		["{npc:2705}, below ground"] = "{npc:2705}, no subterrâneo",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} e {npc:2713}",
		["{npc:2713}'s errand"] = "A tarefa de {npc:2713}",
		["{npc:2789}: {npc:2793}'s cave comes after {area:327}"] = "{npc:2789}: a caverna de {npc:2793} vem depois de {area:327}",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391} está preso numa jaula no extremo norte do santuário. Liberte-o e mantenha-o vivo na saída; o cofre dele aparece depois junto à estrada.",
		["{npc:5476} guards the road junction in the west of the swamp. {npc:217412} stands a short way north of him.\n{npc:217412} may not be here on Forever: if {npc:217412} doesn't offer {quest:93176}, skip it."] = "{npc:5476} guarda o cruzamento de estradas no oeste do pântano. {npc:217412} fica um pouco ao norte dele.\n{npc:217412} pode não estar aqui no Forever: se {npc:217412} não oferecer {quest:93176}, pule.",
		["{npc:5677}, at the summoning circle"] = "{npc:5677}, no círculo de evocação",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} vincula o íncubo a você",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} espera no porão do {object:2164}, no {object:2101}. Use o {item:6913} no círculo de evocação de lá e derrote a súcubo que ele chama. Se você pegou {quest:65602}, entregue também a {item:190309} a ele, coloque-a no mesmo círculo e derrote o íncubo.",
		["{object:2707}; underwater"] = "{object:2707}; debaixo d'água",
		["{object:2708}; underwater"] = "{object:2708}; debaixo d'água",
		["{object:2709}; underwater"] = "{object:2709}; debaixo d'água",
		["{object:2710}; underwater"] = "{object:2710}; debaixo d'água",
		["{quest:65602}, if you took it"] = "{quest:65602}, se você a pegou",
		["{zone:1455} flight master"] = "Mestre de voo de {zone:1455}",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["A {npc:217590} crawls about the {area:596}: catch one with the tool from {npc:217412}'s Entomology Starter Kit."] = "Um {npc:217590} rasteja por {area:596}: capture um com a ferramenta do kit de entomologia de {npc:217412}.",
		["Fly to Theramore"] = "Voe para a Ilha Theramore",
		["Fly to {area:150}"] = "Voe para {area:150}",
		["Follow the road north to {area:608}: {npc:5396} stands at its south end, {npc:5638} in the middle, {npc:1182} to the north."] = "Siga a estrada para o norte até {area:608}: {npc:5396} fica na ponta sul, {npc:5638} no meio e {npc:1182} ao norte.",
		["Follow the road south to {area:2407}."] = "Siga a estrada para o sul até {area:2407}.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "Siga a estrada para o oeste pelo norte de {zone:1443} até as ruínas de {area:2405}. A torre de {npc:11863} fica no morro dali, a caminho do naufrágio.",
		["For {npc:4454} at the {area:2240}: the {zone:1446} guide passes him at 45, keep it"] = "Para {npc:4454} em {area:2240}: o guia de {zone:1446} passa por ele no nível 45, guarde-o",
		["Head back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "Volte para oeste até a estrada e siga por ela para o sul, saindo de {zone:1432} pela passagem até {zone:1418}. {npc:2910} e {npc:2860} acampam lado a lado na escavação.",
		["Head north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "Siga para nordeste até a escavação abandonada; o caixote de suprimentos está lá, no meio dos ogros Arrota-pó.",
		["Head north-east to the dwarven ruins in the north of the {zone:1418}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "Siga para nordeste até as ruínas anãs no norte de {zone:1418}; o baú fica no meio dos anões de Umbraforja. {npc:2745}, ali perto, é elite: dê distância.",
		["Head south down the road: {npc:4618} and {npc:2817} camp in the {area:1877}, on the way to {area:345}."] = "Siga para o sul pela estrada: {npc:4618} e {npc:2817} acampam em {area:1877}, no caminho para {area:345}.",
		["Head south to {area:345}."] = "Siga para o sul até {area:345}.",
		["Head west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "Siga para oeste até {area:1878}; {npc:2921} trabalha junto às máquinas dele, bem no meio.",
		["Into {zone:1418}"] = "Rumo a {zone:1418}",
		["Lesser Rock Elementals"] = "Elementais Inferiores da Rocha",
		["Maraudine centaurs"] = "Centauros Maraudinos",
		["Off the boat, walk up the pier to Baldruc, the flight master by the gate of {area:514}."] = "Ao descer do barco, suba o cais até Baldruc, o mestre de voo junto ao portão de {area:514}.",
		["Rackmore's chest lies just south-east of the {object:177673}."] = "O baú de Rackmore fica logo a sudeste do {object:177673}.",
		["Rock Elementals"] = "Elementais da Rocha",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "A próxima tarefa de Ryedol é em {area:1517}: pule.",
		["South-west into the gulches: only the Greater Rock Elementals there drop the bracers."] = "Ao sudoeste, nas ravinas: só os Elementais Maiores da Rocha de lá soltam os braceletes.",
		["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east.\nThe battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers.\nCareful: Dustbelcher Lords are level 44-45. They use {spell:5242} and {spell:1160}, and below 50% health they call for help from allies within 15 yd. Seven of them stand about 750 yd south of {area:340}."] = "Os ogros Arrota-pó acampam logo ao sul do vale; qualquer um deles solta sucata. Urubus voam em círculos pela planície a leste.\nO esqueleto surrado fica na beira do acampamento de troggs da Abóbada de Pedra; {quest:739}, o assassino de Agmond, anda entre os Quebraossos.\nCuidado: os Grandes Arrota-pó são de nível 44-45. Eles usam {spell:5242} e {spell:1160}, e abaixo de 50% de vida chamam aliados a até 15 metros. Sete deles ficam a cerca de 750 metros ao sul de {area:340}.",
		["The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}; every rock elemental can drop {npc:1470}'s Rock Elemental Shards."] = "Os Elementais Inferiores da Rocha vagam por {area:1878}, a oeste de {npc:2921}; todo elemental da rocha pode soltar os Estilhaços de Elemental da Rocha de {npc:1470}.",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "Os centauros Maraudinos ocupam {area:607}, a oeste do cemitério; todos os tipos soltam os totens.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "Os Elementais da Rocha vagam a sudeste de {npc:2921}; Urubus Gigantes e Coiotes Anciões do Rochedo dividem a planície a oeste deles.",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "Os anões de Umbraforja acampam logo ao norte da escavação; o Mapa Amassado está entre as barracas. Escavadores e Tecetrevas carregam a picareta de Ryedol. Coiotes do Rochedo vagam pelas encostas ao redor.",
		["The Slitherblade naga hold the north-west coast north of {npc:11863}'s tower; Karnitol's satchel lies on the sea floor off it, and any naga can drop Rackmore's golden key. Swim out to {area:2406} off the far northern tip and use the {item:15766} on the {object:177673}: {npc:12369} (38) rises; kill him for the {quest:6027}."] = "Os nagas Lâmina Sinuosa dominam a costa noroeste, ao norte da torre de {npc:11863}; a bolsa de Karnitol está no fundo do mar diante dela, e qualquer naga pode soltar a chave dourada de Rackmore. Nade até {area:2406}, na ponta extrema norte, e use o {item:15766} no {object:177673}: {npc:12369} (38) surge; mate-o para obter {quest:6027}.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "O esqueleto danificado fica logo a leste dos ogros, na beira do acampamento dos troggs da Abóbada de Pedra; os Quebraossos e Xamãs ao redor soltam as lascas. Theldurin está sentado junto ao acampamento em ruínas, mais ao sul.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Os mariscos ficam no litoral noroeste da Selva do Espinhaço, no próximo guia: guarde-a",
		["The demons gather at the {area:602} in southern {zone:1443}: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit.\nCareful: Most of the mobs here walk patrol routes, so you can easily pull extra mobs."] = "Os demônios se juntam em {area:602}, no sul de {zone:1443}: canisvis (Manávoros, Caça-magos e Caçadores do Meridiano), Donzelas e Irmãs do Éter, e Capitães dos Guardiões da Ruína em volta do fosso.\nCuidado: a maioria dos monstros daqui faz patrulha, então é fácil puxar monstro a mais.",
		["The excavation crate"] = "O caixote da escavação",
		["The next guide starts in Theramore."] = "O próximo guia começa na Ilha Theramore.",
		["The wrecked ship's chest lies just south-west of {npc:11863}'s tower."] = "O baú do navio naufragado fica logo a sudoeste da torre de {npc:11863}.",
		["The {area:2657}"] = "{area:2657}",
		["The {object:126260}"] = "{object:126260}",
		["Theramore flight master"] = "Mestre de voo de Theramore",
		["To {area:2101}"] = "Para {area:2101}",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "Assoladores Mortos-vivos vagam pelos campos de ossos ao sul da Aldeia Magram, a leste das Ruínas de Mannoroc; no extremo sudeste, use o {item:15848} para atrair os Espectros Magrami.",
		["Underwater"] = "Debaixo d'água",
		["escort {npc:12277} back toward the graveyard"] = "escolte {npc:12277} de volta ao cemitério",
		["for {npc:2786} in {zone:1455}: keep it"] = "para {npc:2786} em {zone:1455}: guarde-a",
		["for {npc:3980} in {area:271}: keep it"] = "para {npc:3980} em {area:271}: guarde-a",
		["for {npc:5637} in {zone:1455}: keep it"] = "para {npc:5637} em {zone:1455}: guarde-a",
		["{area:144} flight master"] = "Mestre de voo de {area:144}",
		["{area:345}: kill these as you meet them"] = "{area:345}: vá matando estes pelo caminho",
		["{area:346}: kill these as you meet them"] = "{area:346}: vá matando estes pelo caminho",
		["{area:598}: kill these as you meet them"] = "{area:598}: vá matando estes pelo caminho",
		["{item:15766}, on the {object:177673}"] = "{item:15766}, no {object:177673}",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, dos nagas Lâmina Sinuosa",
		["{item:4631}; below ground"] = "{item:4631}; no subterrâneo",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277} está presa no acampamento dos centauros a oeste do cemitério. Liberte-a e mantenha-a viva na saída; ela para junto ao cemitério.\nCuidado: os grupos da escolta vêm juntos e só aparecem durante ela, então não dá para limpar antes nem puxar um de cada vez. Limpar os centauros comuns do caminho antes de começar ajuda.",
		["{npc:1470}, in the inn; below ground"] = "{npc:1470}, na estalagem; no subterrâneo",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}, ao lado de {npc:2921}",
		["{npc:2920}, beside {npc:2921}, trades for {item:2868}, a blacksmith's craft: this step shows only when you carry a pair."] = "{npc:2920}, ao lado de {npc:2921}, troca por {item:2868}, uma criação de ferreiro: este passo só aparece quando você leva um par.",
		["{npc:2921}'s last test is optional: five {item:4628}, which only the Greater Rock Elementals (42-44) in the south-western gulches drop, about one kill in five, well above your level. Take it only if you can handle them one at a time; otherwise hand in the slabs and move on."] = "O último teste de {npc:2921} é opcional: cinco {item:4628}, que só os Elementais Maiores da Rocha (42-44) das ravinas do sudoeste soltam, mais ou menos uma morte em cinco, bem acima do seu nível. Só faça se der conta deles um de cada vez; senão, entregue as lajes e siga em frente.",
		["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618} e {npc:2817} acampam juntos em {area:1877}, no meio de {zone:1418}.",
		["{npc:5638}, if 30-40/02 didn't take it: the wreck lies below {npc:11863}'s tower"] = "{npc:5638}, se o 30-40/02 não a pegou: o naufrágio fica abaixo da torre de {npc:11863}",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons."] = "{npc:6019} fica na beira de {area:596}, a sudoeste de {area:2407}; {object:176751} estão entre os esqueletos.",
		["{object:177787} lies beside {object:35251}. His silver key drops from the Drysnap crabs around the wreck; the golden one comes from the Slitherblade naga on the north-west coast, next."] = "{object:177787} fica ao lado de {object:35251}. A chave de prata dele cai dos caranguejos Estala-seca ao redor do naufrágio; a dourada vem dos nagas Lâmina Sinuosa na costa noroeste, a seguir.",
		["{quest:739} himself (42) walks among the Bonesnappers: leave him for the later {zone:1418} guide at 43, and kill the Bonesnappers for this quest now."] = "O próprio {quest:739} (42) anda entre os Quebraossos: deixe-o para o guia posterior de {zone:1418} no nível 43, e mate agora os Quebraossos para esta missão.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "MacKinley \"Lobo do Mar\", no último andar",
		["\"Stinky\" Ignatz"] = "Inácio \"Cascão\"",
		["Alone, you skip Nesingwary's three elite hunts: take their experience from the Skullsplitter trolls of Zul'Mamwe instead, just east of the mine, so every kill also counts for {npc:737}'s tusks. Or, with a group, run the {area:1517} dungeon instead."] = "Sozinho, você pula as três caçadas de elite de Rosarães: tire a experiência dos trolls Rachacrânio de Zul'Mamwe, logo a leste da mina, de modo que cada morte também conte para as presas de {npc:737}. Ou, com um grupo, faça a masmorra {area:1517}.",
		["An {npc:217588} crawls in the jungle south-east of Nesingwary's camp, on the way to the {area:99}: catch one with the tool from {npc:217412}'s Entomology Starter Kit."] = "{npc:217588} rasteja na selva a sudeste do acampamento de Rosarães, a caminho de {area:99}: pegue um exemplar com a ferramenta do kit de entomologia de {npc:217412}.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. Skyborne learn it from {npc:265756}, the stablemaster and riding trainer at the {area:17684} in {area:16638} on Zephras Isle, who also sells the Galestriders: the skyboat to the isle leaves the north side of {area:279} about every five minutes. Collectibles, Mounts · Level 40 lists the Galestriders."] = "No nível 40, por 100 ouros, você aprende Equitação e já ganha uma montaria. Celonatos aprendem com {npc:265756}, o cavalariço e instrutor de equitação de {area:17684}, em {area:16638}, na Ilha de Zefras, que também vende os Vagaventos: o barco celeste para a ilha sai do lado norte de {area:279} mais ou menos a cada cinco minutos. Colecionáveis, Montarias · Nível 40 lista os Vagaventos.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "No nível 40, com 100 de ouro, você pode aprender a montar, e aprender lhe dá uma montaria. {npc:4732} ensina Humanos em {area:88}, no leste de {zone:1429}, ao lado dos cavalos de {npc:384}. O Forever talvez deixe qualquer raça aprender com qualquer instrutor de montaria (não confirmado). Colecionáveis, Montarias · Nível 40 lista todas as cores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "No nível 40, com 100 de ouro, você pode aprender a montar, e aprender lhe dá uma montaria. {npc:4753} ensina Elfos Noturnos em {zone:1457}, ao lado dos sabres de {npc:4730}: o barco de {area:17203} para {area:442}, depois o voo até {area:702}. O Forever talvez deixe qualquer raça aprender com qualquer instrutor de montaria (não confirmado), como {npc:4732}, em {area:88}, {zone:1429}. Colecionáveis, Montarias · Nível 40 lista todas as cores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "No nível 40, com 100 de ouro, você pode aprender a montar, e aprender lhe dá uma montaria. {npc:4772} ensina Anões em {area:803}, a leste de {area:131}, na estrada para {zone:1432}, ao lado dos carneiros de {npc:1261}. O Forever talvez deixe qualquer raça aprender com qualquer instrutor de montaria (não confirmado). Colecionáveis, Montarias · Nível 40 lista todas as cores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "No nível 40, com 100 de ouro, você pode aprender a montar, e aprender lhe dá uma montaria. {npc:7954} ensina Gnomos em {area:189}, logo a leste de {area:131}, ao lado dos mecanostriders de {npc:7955}. O Forever talvez deixe qualquer raça aprender com qualquer instrutor de montaria (não confirmado). Colecionáveis, Montarias · Nível 40 lista todas as cores.",
		["Bloodsail camp"] = "Acampamento da Vela Sangrenta",
		["Boat to {area:150}"] = "Navio para {area:150}",
		["Boat to {area:17203}"] = "Barco para {area:17203}",
		["Boat to {area:35}"] = "Barco para {area:35}",
		["Cortello's scroll"] = "Pergaminho de Cortello",
		["Defeat the challengers and {npc:6238}"] = "Derrote os desafiantes e {npc:6238}",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "Todo pirata da Vela Sangrenta deixa cair Rapé, e um deles leva o olho de {npc:2493}; os Espadachins andam pela praia logo ao norte da cidade. As cartas náuticas e as ordens estão no acampamento pirata em {area:43}, ao sul de {area:35}.",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Qualquer seguidor de Zanzil pode deixar cair o preparado; {npc:2537} anda pelo sul do acampamento.",
		["Fly to {area:144}"] = "Voe para {area:144}",
		["Fly to {area:35}"] = "Voe até {area:35}",
		["Fly to {area:42}"] = "Voar para {area:42}",
		["Fly to {area:442}"] = "Voe para {area:442}",
		["Fly to {area:702}"] = "Voe para {area:702}",
		["Fly to {zone:1453}"] = "Voe para {zone:1453}",
		["Follow the road east back to Theramore. The officers are in {area:514}."] = "Siga a estrada para o leste de volta a Theramore. Os oficiais estão em {area:514}.",
		["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it.\n{npc:4967} waits at the foot of the tower: once you have looked around, hand the quest in to him there, not in Theramore."] = "Siga a estrada para noroeste, saindo de Theramore, até a torre de vigia em {area:503}. Toqueiras Pedralama vagam pelo brejo ao redor.\n{npc:4967} espera ao pé da torre: depois de dar uma olhada, entregue a missão a ele ali mesmo, não em Theramore.",
		["Gorilla hills"] = "Colinas dos gorilas",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "Entregue as presas e fique: vêm três ondas de gorilas, {npc:1514} por último. Lute com a vida cheia.",
		["If you skipped {quest:543}, grind here to level 42.46 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "Se você pulou {quest:543}, mate monstros aqui até o nível 42.46 para seguir o plano da rota. Ou, com um grupo, faça a masmorra {area:1517}.",
		["Inside"] = "Lá dentro",
		["Jungle Stalkers"] = "Espreitadores da Selva",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks."] = "Saia da cidade pelo túnel e siga a costa para o norte; a carta está no acampamento da Vela Sangrenta, na praia, onde anda Duncan \"Bonitão\".",
		["Level 42.16"] = "Nível 42.16",
		["Level 42.16 at Zul'Mamwe"] = "Nível 42.16 em Zul'Mamwe",
		["Level 42.46"] = "Nível 42.46",
		["MacKinley's next task sends you after elite ogres: skip it."] = "A próxima tarefa de MacKinley manda você atrás de ogros elite: pule-a.",
		["Mirefin murlocs"] = "Murlocs Lamapina",
		["Naga Explorers"] = "Exploradores Nagas",
		["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "No caminho para o norte até {area:392}, {area:720} fica perto de {area:391}, ao sul da cidade: atravesse a pé o banco de areia. {npc:6236} manda quatro desafiantes e depois {npc:6238} (nível 33) contra você, um de cada vez.",
		["On the top floor"] = "No último andar",
		["Optional: Cortello's scroll lies inside one of the three Bloodsail ships anchored off the coast just south of {area:35}, on a middle or lower deck, and is not always on the same ship. Their crews are 42-45 pirates: clear your way from the edge, one at a time, and leave the captains (45-48), whom the route comes back for at 48."] = "Opcional: o pergaminho de Cortello fica dentro de um dos três navios dos Velame Sangrento ancorados na costa logo ao sul de {area:35}, em um convés do meio ou inferior, e nem sempre no mesmo navio. As tripulações são piratas de nível 42-45: abra caminho a partir da borda, um de cada vez, e deixe os capitães (45-48), que a rota volta para pegar no 48.",
		["Paladin: {quest:1661}"] = "Paladino: {quest:1661}",
		["Ride back down to town; Shaky stands at the tunnel mouth."] = "Volte para a cidade; Sacode fica na entrada do túnel.",
		["Ride east out of {zone:1426} through the tunnel into {zone:1432} and on along the road to {area:144}."] = "Cavalgue para leste, saindo de {zone:1426}, pelo túnel até {zone:1432} e siga a estrada até {area:144}.",
		["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "Siga para o leste; os Horrores Emaranhados no caminho também deixam cair os ensaios. Procure na borda de {area:74}, onde as ruínas do templo saem da água.",
		["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "Siga para o interior até as colinas dos gorilas do Vale da Névoa. Gorilas Anciões do Vale da Névoa deixam cair os miúdos; {npc:1449} fica entre eles.",
		["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "Siga para o norte até as colinas a oeste da estrada. {npc:2535} e {npc:2536} ficam juntos, logo ao norte da aldeia de Zanzil.",
		["Ride north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale."] = "Cavalgue para nordeste, passando pelo acampamento de Rosarães, e siga a estrada para o norte até o acampamento no alto do vale.",
		["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "Siga para noroeste a partir da mina até a baía na costa noroeste. Os Mariscos Gigantes ficam no fundo dela e guardam as pérolas; {npc:2624} nada entre eles e deixa cair {item:4034}.",
		["Ride south down the road to {area:35}."] = "Siga para o sul pela estrada até {area:35}.",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Cavalgue para o sul, saindo de {zone:1432} pelo desfiladeiro até {zone:1418}; {npc:2860} acampa na escavação.",
		["Ride south to the giant's hut in the middle of the marsh."] = "Siga para o sul até a cabana do gigante, no meio do pântano.",
		["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "Montaria e Vagaventos: {npc:265756}, em {area:17684}, {area:16638}, na Ilha de Zefras.",
		["Riding at 40"] = "Montaria no nível 40",
		["Seahorn now offers {quest:604}: leave it. Its three captains are level 45-48 with crews around them, and the route brings you back to Seahorn at 48 for it."] = "Chifre do Mar agora oferece {quest:604}: deixe-a. Os três capitães dela são de nível 45-48, com tripulações ao redor, e a rota traz você de volta a Chifre do Mar no nível 48 para ela.",
		["Seahorn's next errand goes back to Arathi: skip it."] = "A próxima tarefa de Chifre do Mar volta para Arathi: pule-a.",
		["Skyboat to Zephras Isle: the north side of {area:279}, about every five minutes."] = "Barco celeste para a Ilha de Zefras: lado norte de {area:279}, mais ou menos a cada cinco minutos.",
		["Still short of level 42.16 after the hunts you did? Make up the rest on the Cold Eye Basilisks by the {area:310}, on your way south to {area:35}. Or, with a group, run the {area:1517} dungeon instead."] = "Ainda abaixo do nível 42.16 depois das caçadas que fez? Complete o resto nos Basiliscos Olho Frio perto de {area:310}, no caminho para o sul até {area:35}. Ou, com um grupo, faça a masmorra {area:1517}.",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "Cascão espera a oeste do casarão, no brejo abaixo de {area:504}. Leve-o até as folhas de trevo aquático e afaste as criaturas do pântano dele.",
		["Stormwind City"] = "Ventobravo",
		["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house. Jarl wants three {quest:1218}: if you passed {npc:4897}, buy them from her in Theramore first."] = "Siga a estrada para o norte até a mansão em ruínas; Zé mora no casebre ao lado dela e a terra solta fica no canto da casa. Zé quer três {quest:1218}: se você passou por {npc:4897}, compre-as dela em Theramore antes.",
		["The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "As aranhas Névoa Negra fazem ninho em volta da caverna no noroeste do pântano; toda aranha deixa cair olhos.\nCuidado: as Tocaieiras Névoa Negra andam furtivas e usam veneno no combate. As aranhas ficam bem juntas, então é comum vir monstro a mais; puxar um alvo de cada vez pela borda ajuda.",
		["The Jungle Stalkers roam the slopes west of the mine."] = "Os Espreitadores da Selva vagam pelas encostas a oeste da mina.",
		["The Mirefin murlocs crowd the north coast past {area:497}."] = "Os murlocs Lamapina lotam a costa norte depois de {area:497}.",
		["The Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do.\nFollow the road north-east to the Venture Co. camp at the {area:310}; the miners, surveyors and foremen drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "Os trolls Rachacrânio ocupam as ruínas logo a leste da mina; qualquer um pode deixar cair presas, e as panteras deles sempre deixam.\nSiga a estrada para nordeste até o acampamento da Empreendimentos S.A. em {area:310}; os mineradores, topógrafos e encarregados deixam cair os cristais.\nCuidado: Panteras Umbragorja furtivas e Tigresas-do-espinhaço andam em volta do acampamento.",
		["The boat leaves from Theramore: report to {npc:4944} on the top floor of {area:514} on the way to the docks."] = "O barco sai de Theramore: apresente-se a {npc:4944} no último andar de {area:514}, no caminho até as docas.",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes."] = "A estalagem queimada fica na estrada para o oeste, rumo a {zone:1413}; a insígnia do guarda está nas cinzas.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "Os desertores acampam ao sul da estrada, a oeste da cabana de {npc:4503}.",
		["The driftwood washes up along the eastern shore."] = "A madeira flutuante chega à praia ao longo da margem leste.",
		["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "Os nagas vasculham as praias ao norte do acampamento da Vela Sangrenta; eles deixam cair os juncos.",
		["The north-west coast"] = "A costa noroeste",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "O pergaminho fica no brejo ao norte de Biggs. Os Errantes do Pântano ao norte dele podem deixar cair os ensaios de Hadggar.",
		["The sunken temple"] = "O templo submerso",
		["Theramore"] = "Theramore",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:728} é elite de nível 40: a maioria das classes encara sozinha no nível 42, mas talvez você precise de ajuda. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:730} é elite de nível 43: a maioria das classes encara sozinha no nível 45, mas talvez você precise de ajuda. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:731} é elite de nível 43: a maioria das classes encara sozinha no nível 45, mas talvez você precise de ajuda. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.\nCuidado: tigres e panteras umbragorja furtivas andam perto dele. Limpe tudo antes de puxá-lo. Quando é puxado, {npc:731} chama ajuda de qualquer bicho num raio de 20 metros.",
		["Tram to {zone:1455}"] = "Metrô para {zone:1455}",
		["Unbagwa's ritual"] = "O ritual de Unbagwa",
		["Upstairs"] = "No andar de cima",
		["Warlock: {quest:3631}"] = "Bruxo: {quest:3631}",
		["Zanzil's village"] = "Aldeia de Zanzil",
