		["{area:702} flight master"] = "Mestre de voo de {area:702}",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, para Zé \"Olho de Lama\"",
		["{item:4611}; underwater"] = "{item:4611}; debaixo d'água",
		["{item:5938}, from the Silt Crawlers on the same shore"] = "{item:5938}, dos Guajás do Lodo na mesma praia",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141} cozinha em {object:2169}; {npc:5384} fica em {object:28027}.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: outras cores, 20g",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}, na Biblioteca Real, em {object:2117}",
		["{npc:1449}, inside {area:1742}"] = "{npc:1449}, dentro de {area:1742}",
		["{npc:1470} is below ground in {area:144}, by the inn. His mushrooms grow in the {area:1517} dig in the {zone:1418}; the next guide takes you there and back through {area:144}."] = "{npc:1470} fica no subterrâneo em {area:144}, junto à estalagem. Os cogumelos dele crescem na escavação de {area:1517}, em {zone:1418}; o próximo guia leva você até lá e de volta por {area:144}.",
		["{npc:1470}, below ground"] = "{npc:1470}, no subterrâneo",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}: {quest:93176}, de 30-40/05-arathi-highlands",
		["{npc:2487}, top floor"] = "{npc:2487}, último andar",
		["{npc:2488}, on the top floor"] = "{npc:2488}, no último andar",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "A próxima tarefa de {npc:2498} sobre Zanzil começa em {zone:1441}: pule-a.",
		["{npc:2535} and {npc:2536}"] = "{npc:2535} e {npc:2536}",
		["{npc:2542}, upstairs"] = "{npc:2542}, no andar de cima",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624} nada perto da costa noroeste, no circuito norte",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888} acampa sozinho em {area:1898}, a sudeste da escavação.",
		["{npc:384}: other colours, 20g"] = "{npc:384}: outras cores, 20g",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}, em {object:2164}: {npc:6251}, em {area:392}, recebe no fim do próximo guia",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: outras cores, 20g",
		["{npc:4794}, inside"] = "{npc:4794}, lá dentro",
		["{npc:4794}: the crawlers are on the {zone:1435} shore, keep it"] = "{npc:4794}: os caranguejos ficam na costa de {zone:1435}, guarde-o",
		["{npc:4944}, on the top floor"] = "{npc:4944}, no último andar",
		["{npc:4948}, on the top floor"] = "{npc:4948}, no último andar",
		["{npc:4964}, on the top floor of {area:514}"] = "{npc:4964}, no último andar de {area:514}",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields.\nCareful: Hendel has two guards who join the fight when he turns hostile. The guards flee once he surrenders.\n{npc:4967} and {npc:4968} wait beside the tower: once he yields, hand in to both on the spot."] = "{npc:4966} ocupa a torre com alguns desertores. Ele se vira contra você: bata até ele se render.\nCuidado: o Remos tem dois guardas que entram na briga quando ele fica hostil. Os guardas fogem quando ele se rende.\n{npc:4967} e {npc:4968} esperam ao lado da torre: quando ele se render, entregue aos dois ali mesmo.",
		["{npc:4967}, at the tower"] = "{npc:4967}, na torre",
		["{npc:4968}, on the top floor"] = "{npc:4968}, no último andar",
		["{npc:5464}, by the flight master"] = "{npc:5464}, junto ao mestre de voo",
		["{npc:5476} stands by the road junction in the west of the swamp."] = "{npc:5476} fica junto ao entroncamento no oeste do pântano.",
		["{npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:2786} in the {object:32383}."] = "{npc:5637} fica no salão da Recuperação Ilimitada, junto ao {object:32356}, e {npc:2786}, na {object:32383}.",
		["{npc:5694}: for {npc:5464} in {area:42}, on the way to the swamp"] = "{npc:5694}: para {npc:5464} em {area:42}, no caminho para o pântano",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}, na Catedral da Luz",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "Em seguida, {npc:6236} oferece O vigia dos ventos (1791): a série da arma de Redemoinho, com um elite no fim, está no guia de classe de Guerreiro Arma do redemoinho.",
		["{npc:737}, upstairs"] = "{npc:737}, no andar de cima",
		["{npc:737}, upstairs: the Skullsplitter trolls, on the northern loop"] = "{npc:737}, no andar de cima: os trolls Rachacrânio, no circuito do norte",
		["{npc:773}, upstairs"] = "{npc:773}, no andar de cima",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: para {quest:2864}, em {zone:1446}, guarde",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: outras cores, 20g",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260} fica perto da estalagem; {npc:4897}, um fornecedor de comércio alguns passos ao sul, vende os temperos que Zé quer.",
		["{quest:1260}, inside"] = "{quest:1260}, lá dentro",
		["{zone:1453} flight master"] = "Mestre de voo de {zone:1453}",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} não tem instrutor de xamã",
		["{zone:1455} flight master"] = "Mestre de voo de {zone:1455}",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Back through the pass: the Stonevault troggs dig outside {area:1517} at the {zone:1418}' northern edge. The carved urns and the magenta mushroom clusters sit in their caves and tunnels, outside the dungeon itself."] = "De volta pelo desfiladeiro: os Troggs da Abóbada de Pedra escavam fora de {area:1517}, na borda norte de {zone:1418}. As urnas entalhadas e os aglomerados de cogumelos magenta ficam nas cavernas e túneis deles, fora da masmorra.",
		["Back to {zone:1432}"] = "De volta a {zone:1432}",
		["Fly to {area:150}"] = "Voe para {area:150}",
		["Fly to {area:271}"] = "Voar para {area:271}",
		["From Theramore, ride north into the {zone:1413} to {area:392}, or fly if you know its flight path. {npc:6251} teaches in the house by the bank."] = "De Theramore, siga para o norte por {zone:1413} até {area:392}, ou voe, se você conhece a rota de voo de lá. {npc:6251} ensina na casa ao lado do banco.",
		["Inside {area:498}"] = "Dentro de {area:498}",
		["Into {zone:1418}"] = "Rumo a {zone:1418}",
		["Into {zone:1432}"] = "Rumo a {zone:1432}",
		["Raleigh's next errand is in the {area:796}: skip it."] = "A próxima tarefa de Raul é em {area:796}: pule.",
		["Ride back east to {area:1898}."] = "Volte a leste até {area:1898}.",
		["Ride back north to Ironband's camp."] = "Cavalgue de volta para o norte até o acampamento de Bandaferro.",
		["Ride north through the pass into {zone:1432} and east along the south shore to Ironband's camp."] = "Cavalgue para o norte pelo desfiladeiro até {zone:1432} e para leste pela margem sul até o acampamento de Bandaferro.",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "Saia de {area:271} para o nordeste pela estrada até as {zone:1425}; {area:348} fica logo depois da divisa. {npc:5635} recebe a corte no alto, {quest:1450} cuida do aviário e {npc:7884} fica junto à estalagem.",
		["Ride west along the loch to {area:144}."] = "Cavalgue para oeste ao longo do lago até {area:144}.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "A próxima tarefa de Garra-de-acha fica para um guia posterior das {zone:1425}.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Os Dragonetes Escaldantes fazem ninho na ravina a leste de {npc:2888}; deixe os Guardiões Flâmeos (elite) em paz. {item:4612} cai raramente: pegue se aparecer enquanto você farma.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "As duas primeiras jaulas ficam juntas na aldeia Cascasseca ao sul de {npc:5634}; a terceira está na aldeia seguinte, a leste. Qualquer troll Cascasseca pode soltar um colar.",
		["The {area:1517} dig"] = "A escavação de {area:1517}",
		["Theramore"] = "Ilha Theramore",
		["Theramore flight master"] = "Mestre de voo de Theramore",
		["Warlock: {quest:3631}"] = "Bruxo: {quest:3631}",
		["Witherbark villages"] = "Aldeias Cascasseca",
		["{area:144} flight master"] = "Mestre de voo de {area:144}",
		["{area:348} flight master"] = "Mestre de voo de {area:348}",
		["{item:8047}; below ground"] = "{item:8047}; no subterrâneo",
		["{npc:1470}, below ground"] = "{npc:1470}, no subterrâneo",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} fica nas docas onde o barco atraca.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "A próxima missão de {npc:2817} não dá experiência: pule.",
		["{npc:2817}: Blue Pearls from Stranglethorn"] = "{npc:2817}: Pérolas Azuis da Selva do Espinhaço",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "A próxima tarefa de {npc:2888} é uma caçada elite: pule.",
		["{npc:2944} does not stay at {area:342}: he walks a long loop around the {zone:1418} with his guards, from the camp in the west along the south of the zone to about 61,69, north to about 49,49 and back west to the camp. The arrow follows his loop west from here until you meet him."] = "{npc:2944} não fica em {area:342}: ele percorre um longo circuito por {zone:1418} com seus guardas, do acampamento no oeste ao longo do sul da zona até mais ou menos 61,69, depois para o norte até mais ou menos 49,49 e de volta para o oeste até o acampamento. A seta segue o circuito dele para o oeste a partir daqui até você encontrá-lo.",
		["{npc:3980} preaches by the inn."] = "{npc:3980} prega junto à estalagem.",
		["{npc:3980}, upstairs"] = "{npc:3980}, no andar de cima",
		["{npc:4794}, inside"] = "{npc:4794}, lá dentro",
		["{npc:4944}, on the top floor"] = "{npc:4944}, no último andar",
		["{npc:4968}, on the top floor"] = "{npc:4968}, no último andar",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634} acampa na estrada a leste de {area:348}.",
		["{npc:5636}, beside the flight master at the top; inside"] = "{npc:5636}, ao lado do mestre de voo, lá no topo; lá dentro",
		["{npc:7744}; below ground"] = "{npc:7744}; no subsolo",
		["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884} continua pagando pelos colares: entregue os que sobrarem",
		["{npc:7884}, inside"] = "{npc:7884}, lá dentro",
		["{object:2743}; below ground"] = "{object:2743}; no subterrâneo",
		["{quest:1450}, inside"] = "{quest:1450}, lá dentro",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "Volte a {area:1117}. Todo naga Cristafúria de lá pode deixar cair escamas.",
		["Boat to {area:1108}"] = "Barco para {area:1108}",
		["Boat to {area:1116}"] = "Barco para {area:1116}",
		["Coming from the south: {npc:7877} and {npc:7878} first, then {npc:7900} beside {npc:7880}'s building, then the stairs. {npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. {npc:7852} is by the flight master, on the way out."] = "Vindo do sul: primeiro {npc:7877} e {npc:7878}, depois {npc:7900}, ao lado do prédio de {npc:7880}, e então a escada. {npc:7880} fica no andar de cima do prédio dele: suba por dentro, a seta não diferencia os andares. {npc:7852} fica junto ao mestre de voo, na saída.",
		["Feathermoon flight master"] = "Mestre de voo de Plumaluna",
		["Fly to {area:489}"] = "Voe para {area:489}",
		["From {area:489} ride west along the road to the Grimtotem camp north of it. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "De {area:489}, siga para oeste pela estrada até o acampamento Temível Totem ao norte dela. {npc:7956} espera do lado de fora; liberte os Dardejantes do cercado no meio e mantenha {npc:7956} e pelo menos seis deles vivos.",
		["Gordunni ogres"] = "Ogros Gordunni",
		["Grimtotem camp"] = "Acampamento Temível Totem",
		["Grimtotem tauren"] = "Taurens Temível Totem",
		["Grind to 45"] = "Farme até o 45",
		["Hatecrest naga"] = "Nagas Cristafúria",
		["Into {zone:1413}"] = "Rumo a {zone:1413}",
		["No {quest:7735} yet? Keep killing the Rage Scar yetis until one drops, then right-click it."] = "Ainda sem {quest:7735}? Continue matando os yetis Cortifúria até um soltar, depois clique nele com o botão direito.",
		["Ride back to the {area:1108}; the goblin stands by the dock."] = "Volte cavalgando para {area:1108}; o goblin fica junto à doca.",
		["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide, and about one in thirty a {quest:7735}, which {npc:7852} pays for too.\n{npc:14637}'s quests on the coast need level 45: grind the yetis here until level 44.5, so the kills also bring {npc:7852}'s hides. Or, with a group, run the {area:978} dungeon instead."] = "Cavalgue de volta para oeste pela estrada e depois para o norte, pelas colinas Cortifúria. Todo yeti daqui pode soltar um pelego, e cerca de um em trinta, {quest:7735}, que {npc:7852} também paga.\nAs missões de {npc:14637} na costa exigem nível 45: mate os yetis daqui até o nível 44.5, para que as mortes também rendam os pelegos de {npc:7852}. Ou, com um grupo, faça a masmorra {area:978}.",
		["Ride east into {area:1105}. {npc:14637}'s quests on the coast need level 45. Or, with a group, run the {area:978} dungeon or the {area:1517} dungeon instead."] = "Siga para leste até {area:1105}. As missões de {npc:14637} na costa precisam de nível 45. Ou, com um grupo, faça a masmorra {area:978} ou a masmorra {area:1517}.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Cavalgue para leste até o acampamento Gordunni nas colinas a sudeste do vale dos yetis: Bruxos Gordunni e Xamãs Gordunni ocupam o acampamento, Brutamontes Gordunni vagam pelas encostas ao redor e mais ao norte.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Cavalgue para o norte até o vale dos yetis. Todo Yeti Abominável pode deixar cair um couro grosso; {npc:5346} (nível 48) ronda o meio.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Cavalgue para nordeste até o posto avançado dos elfos noturnos na fronteira de {zone:1441}.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Cavalgue para sudeste até os gnolls Patábua; as mochilas do mensageiro estão no acampamento sul deles, e um pacote dentro delas inicia uma entrega para {area:489}. A colmeia Zukk'ash fica logo ao sul: lute até o casulo que prende Patiphe, o Mensageiro, liberte-o e mantenha-o vivo na saída.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Costívagos, Fundívagos e Ondarilhos (gigantes elite) andam pela costa ao norte da doca: atinja um com {item:18904} e mate o gigante encolhido. Elementais do Mar e Borrifos do Mar flutuam na mesma rebentação.",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "Pegue o barco para {area:1108} e siga a costa para o sul até a Canoa Destruída na praia.",
		["The courier's boat"] = "O barco do mensageiro",
		["The {area:1121} is the island just south of {area:1120}: swim over. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "{area:1121} é a ilha logo ao sul de {area:1120}: vá nadando. Serpentes Guarda e Feiticeiras Cristafúria ocupam a ilha; {npc:8136} (nível 47) espera na caverna da ponta sul. Puxe os guardas dele primeiro.",
		["The {zone:1446} guide starts with the trip east, past {area:489}."] = "O guia de {zone:1446} começa com a viagem para leste, passando por {area:489}.",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Caminhe para o sul pela ilha até as ruínas dos nagas; o mirante fica entre elas.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "para Tyrande Murmuréolo em {zone:1457}: a rota leva você lá no 47",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "farme {npc:5292} em {area:1105}, {zone:1444}",
		["grind on {npc:5296}"] = "mate {npc:5296} até subir",
		["{area:1108}: kill these as you meet them"] = "{area:1108}: vá matando estes pelo caminho",
		["{area:1116} stands on {area:1120}, off the {area:1108}: the boat from the coast's dock crosses to it. {npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{area:1116} fica em {area:1120}, ao largo de {area:1108}: o barco do cais da costa faz a travessia. {npc:7880} fica no andar de cima do prédio dele: suba por dentro, a seta não diferencia os andares.",
		["{area:1136}: kill these as you meet them"] = "{area:1136}: vá matando estes pelo caminho",
		["{area:489} flight master"] = "Mestre de voo de {area:489}",
		["{item:11463}, from the backpacks"] = "{item:11463}, das mochilas",
		["{item:9248}; below ground"] = "{item:9248}; no subterrâneo",
		["{npc:14637}'s refills are level 55: skip them."] = "As recargas de {npc:14637} são de nível 55: pule-as.",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "{npc:3936} então pede que você leve notícias a {zone:1457}: pule, {area:976} manda você lá em vez disso.",
		["{npc:3936}, beside him"] = "{npc:3936}, ao lado dele",
		["{npc:4048} walks around {area:489}: look inside the circle on the map"] = "{npc:4048} anda por {area:489}: procure dentro do círculo no mapa",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}: a resposta dele espera em {area:702}, mais tarde",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, no alto do bastião",
		["{npc:7879}, upstairs"] = "{npc:7879}, no andar de cima",
		["{npc:7880} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:7880} fica no andar de cima do prédio dele: suba por dentro, a seta não diferencia os andares.",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} fica para o fim do circuito no continente.",
		["{object:164954}, inside"] = "{object:164954}, lá dentro",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["\"Sea Wolf\" MacKinley in {area:35}: the route takes you there at the end of the {zone:1425} guide, keep it"] = "MacKinley “Lobo do Mar” em {area:35}: a rota leva você até ele no fim do guia de {zone:1425}; mantenha a missão",
		["Boat to {area:150}"] = "Navio para {area:150}",
		["Careful: Thieves cast Disarm. Rogues stay hidden with Sneak. Assassins use Execute when your health is at 20% or lower."] = "Cuidado: os Ladrões desarmam você. Os Ladinos ficam escondidos, furtivos. Os Assassinos usam Executar quando sua vida está em 20% ou menos.",
		["Fly to Theramore"] = "Voe para a Ilha Theramore",
		["Fly to {area:348}"] = "Voe para {area:348}",
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "Siga a costa para o sul até a enseada dos piratas. Os piratas dos Mares do Sul lotam a praia e os barcos: vá pela borda e puxe um de cada vez. {npc:7883} fica do outro lado; a carga roubada de {npc:7881} está no acampamento.\nCuidado: dois ou três piratas ficam com {npc:7883}, e muitos outros piratas da vila entram na briga assim que ela começa.",
		["Gives the {item:8585}"] = "Dá o {item:8585}",
		["He runs off to keep Rizzle busy"] = "Ele sai correndo para distrair o Rebu",
		["Pool by {area:979}"] = "Lagoa junto a {area:979}",
		["Ride back west to {area:976}: {npc:11758} stands on the east side of town, where you come in."] = "Cavalgue de volta para oeste até {area:976}: {npc:11758} fica no lado leste da cidade, por onde você entra.",
		["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "Volte cavalgando para oeste rumo a {area:976}. Os bandidos e ladrões Errantes ocupam as dunas no caminho; qualquer um pode carregar um cantil.\nCuidado: os Ladinos Errantes (nível 43-44) andam furtivos, então podem chegar sem ser vistos.",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Cavalgue para o leste pelas dunas até o porto goblin na costa nordeste.",
		["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts.\nCareful: Centipaar Swarmers cast {npc:4196} both in and out of combat, which brings small adds that interrupt you."] = "Cavalgue para noroeste até a colmeia Centiparte nas dunas. Qualquer Centiparte pode deixar cair pedaços de inseto.\nCuidado: os Enxameadores Centiparte soltam {npc:4196} dentro e fora de combate, o que traz bichinhos que interrompem você.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "Cavalgue para o noroeste até o acampamento dos trolls Zangareia em {area:979}. Use o {item:8584} na beira da lagoa; os trolls ficam perto, então puxe o mais próximo primeiro.",
		["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time.\nCareful: The other thistleshrub mobs in the area are level 49-50 and wander a lot, so you can easily pull extra mobs."] = "Cavalgue para o sul até {quest:3362}. Os Coletores de Orvalho deixam cair as glândulas; só algumas vêm cheias, então guarde a carregada. Moitagulhas Rotos e Fazraízes dividem o vale. Os Moitagulhas são nível 48-50, acima de você: puxe um de cada vez.\nCuidado: os outros Moitagulhas da área são nível 49-50 e andam muito, então é fácil puxar monstro a mais.",
		["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside.\nCareful: One bug guards the gear. Many bugs patrol the tunnels, some of them level 50, so fights often pull extra adds."] = "Cavalgue para o sul, passando por {area:1938}, até {area:981}, os túneis dos Hazzali; o aparelho do Anilhacido está lá no fundo.\nCuidado: um inseto guarda o aparelho. Muitos insetos patrulham os túneis, alguns de nível 50, então as lutas costumam trazer bicho a mais.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Cavalgue para o sul até o acampamento de escavação em {area:1938}. {npc:7771} lhe entrega um elmo detector: use-o para ver os montes de {quest:3161}, espalhados pela areia ao redor do acampamento e a sudoeste, rumo aos ogros.",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "Saia de {area:439} para o sudeste, rumo a {zone:1446}. {area:976} fica logo depois da fronteira.",
		["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "Cavalgue para sudeste até {area:985}. {npc:7847} fica no meio do acampamento Errante do sul: limpe em volta dele antes.\nCuidado: dois Ladinos Errantes furtivos acompanham o Califa aonde ele for. No acampamento onde ele surge, dois magos das sombras e seus lacaios estão perto o bastante para entrar na luta. Lá perto das torres dá para enfrentá-lo sem eles.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Cavalgue para o sudoeste até o complexo dos ogros. Brutamontes Dunamalho e Impositores Dunamalho (46-48) o enchem; {npc:12046} (49) fica no meio, cercado de guardas: elimine-os primeiro.",
		["The Wanted poster beside him"] = "O cartaz de Procurado ao lado dele",
		["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "A tartaruguinha {npc:5955} se esconde no extremo norte do vale. Leve-o para casa, até a esposa {npc:6015}, junto à água logo a leste de {area:977}: ele anda devagar e as feras do deserto vão atrás dele, então mantenha-o vivo.",
		["The pool by {area:979}"] = "A lagoa junto a {area:979}",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "O mesmo cartaz: {npc:7847} vem bem mais tarde, depois de {area:976}",
		["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp."] = "Os ladinos, magos das sombras e assassinos Errantes mais fortes acampam a sudeste de {area:976}, ao sul dos bandidos. Deixe {npc:7847}, no meio do acampamento do sul, para depois.\nCuidado: os Ladinos Errantes ficam furtivos fora de combate, então ladinos escondidos podem entrar numa briga que você começar num acampamento.",
		["The {area:1938}"] = "{area:1938}",
		["The {area:2240} lies on the {area:439} in south-east {zone:1441}: {npc:4454} is in the gnomes' camp beside the track, {npc:4709} by the goblin camp."] = "{area:2240} fica em {area:439}, no sudeste de {zone:1441}: {npc:4454} está no acampamento dos gnomos, ao lado da pista, e {npc:4709}, junto ao acampamento dos goblins.",
		["Underwater"] = "Debaixo d'água",
		["for {zone:1457}: the route takes you there at 47"] = "para {zone:1457}: a rota leva você lá no nível 47",
		["grind on {npc:5474}"] = "mate {npc:5474} até subir",
		["{area:1336}: kill these as you meet them"] = "{area:1336}: vá matando estes pelo caminho",
		["{area:150} flight master"] = "Mestre de voo de {area:150}",
		["{area:1937}: kill these as you meet them"] = "{area:1937}: vá matando estes pelo caminho",
		["{area:976} flight master"] = "Mestre de voo de {area:976}",
		["{item:8593}; below ground"] = "{item:8593}; no subterrâneo",
		["{npc:12046}, below ground"] = "{npc:12046}, no subterrâneo",
		["{npc:4454}: {quest:1137}, from Martek in the {zone:1418}"] = "{npc:4454}: {quest:1137}, de Martek em {zone:1418}",
		["{npc:5594}, inside"] = "{npc:5594}, lá dentro",
		["{npc:5636}, beside the flight master"] = "{npc:5636}, ao lado do mestre de voo",
		["{npc:5955}'s escort"] = "Escolta de {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, junto à torre d'água",
		["{npc:7408}, next to him"] = "{npc:7408}, ao lado dele",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}: o caixote dele vai para {area:702}, depois",
		["{npc:7881}, in the port's tavern; inside"] = "{npc:7881}, na taberna do porto; lá dentro",
		["{npc:7881}, inside"] = "{npc:7881}, lá dentro",
		["{npc:7882}, inside"] = "{npc:7882}, lá dentro",
		["{npc:7884}, inside"] = "{npc:7884}, lá dentro",
		["{quest:2864}, north side of town"] = "{quest:2864}, no lado norte da cidade",
		["{quest:2873}; upstairs"] = "{quest:2873}; no andar de cima",
		["{quest:3362}: kill these as you meet them"] = "{quest:3362}: vá matando estes pelo caminho",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "MacKinley \"Lobo do Mar\", no último andar",
		["Boat to {area:17203}"] = "Barco para {area:17203}",
		["Class trainer"] = "Instrutor de classe",
		["Fly to {area:144}"] = "Voe para {area:144}",
		["Fly to {area:150}"] = "Voe para {area:150}",
		["Fly to {area:1537}"] = "Voe para {area:1537}",
		["Fly to {area:35}"] = "Voe até {area:35}",
		["Fly to {area:42}"] = "Voar para {area:42}",
		["Fly to {area:442}"] = "Voe para {area:442}",
		["Fly to {area:69}"] = "Voe para {area:69}",
		["Inside"] = "Lá dentro",
		["Portal to {zone:1438}"] = "Portal para {zone:1438}",
		["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it.\nCareful: Panthers move around the area in stealth."] = "Cavalgue para o norte até {area:351}, no meio de {zone:1425}. Lodos Verdes e Gosmas Jade rastejam em toda a volta.\nCuidado: panteras andam furtivas pela área.",
		["Ride on east along the road to the keep first: the {item:6091} expires an hour after {area:42}, and the bloodmages' beasts take longer than that."] = "Siga primeiro pela estrada para o leste até a fortaleza: o {item:6091} expira uma hora depois de {area:42}, e as feras dos Magos Sangrentos levam mais tempo que isso.",
		["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down.\nCareful: Elite trolls guard the top platform, including {npc:7996} and {npc:8636}, along with several Vilebranch Soothsayers. The soothsayers cast spells and are linked to the rest of the group."] = "Cavalgue para sudeste até {area:355}, o templo em degraus dos Ramatorpe no sul de {zone:1425}, e suba até o topo. Qiaga e {npc:8636} (elite, 50) ficam lá em cima: encoste no topo e desça na hora.\nCuidado: trolls elite guardam a plataforma do topo, entre eles {npc:7996} e {npc:8636}, junto com vários Adivinhos Ramatorpe. Os adivinhos lançam feitiços e estão ligados ao resto do grupo.",
		["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time.\nAshmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52.\nCareful: Scorpok Stingers use {spell:5416}; {npc:8301} adds Knockdown."] = "Cavalgue para oeste: as Rasgarrindos Famintas andam pelas colinas secas logo ao sul do acampamento dos magos sangrentos; os Aguilhantes Escorpóde (nível 50) correm pelo meio do norte. Abutres {npc:5982} rondam por cima de tudo. Puxe um de cada vez.\nJavalis Jubacinza e Basiliscos Itarrubra dividem as encostas a sudoeste da fortaleza. Passe longe dos Javiltuscos mais ao sul: são nível 52.\nCuidado: os Aguilhantes Escorpóde usam {spell:5416}; {npc:8301} ainda derruba você.",
		["Set your hearth here: the {zone:1427} guide starts from {area:144}."] = "Defina sua Pedra de Regresso aqui: o guia de {zone:1427} começa em {area:144}.",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "Atravesse o portal para {zone:1457}. O Templo da Lua fica no sul da cidade.",
		["Temple of the Moon"] = "Templo da Lua",
		["The Bloodsail captains"] = "Os capitães da Vela Sangrenta",
		["The bloodmages"] = "Os Magos Sangrentos",
		["The bloodmages' camp is the first stop beside the road into the {zone:1419}, north-west of {area:1438}."] = "O acampamento dos magos sangrentos é a primeira parada ao lado da estrada que entra em {zone:1419}, a noroeste de {area:1438}.",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "A segunda etapa dos Magos Sangrentos paga pelas mesmas partes com um item de bônus e sem experiência: pule.",
		["The three Bloodsail ships lie at anchor off the coast just south of {area:35}: {npc:2550} (45) and {npc:2548} (46) on the nearer decks, {npc:2546} (48) on the flagship, each with a crew of 42-45 pirates. Swim out, clear each deck from the edge and pull one at a time."] = "Os três navios da Vela Sangrenta estão ancorados ao largo da costa, logo ao sul de {area:35}: {npc:2550} (45) e {npc:2548} (46) nos conveses mais próximos, {npc:2546} (48) na nau capitânia, cada um com uma tripulação de 42-45 piratas. Nade até lá, limpe cada convés a partir da borda e puxe um de cada vez.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1494} (level 52 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:1494} (elite nível 52) pede um grupo de 2. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:8552} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {quest:8552} pede um grupo de 2. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["Tram to {zone:1453}"] = "Metrô para {zone:1453}",
		["for {quest:2990} at {area:1438}, later"] = "para {quest:2990} em {area:1438}, depois",
		["the book on her table"] = "o livro na mesa dela",
		["the soil comes from {zone:1449}, later"] = "o solo vem de {zone:1449}, depois",
		["{area:1438} flight master"] = "Mestre de voo de {area:1438}",
		["{area:144} flight master"] = "Mestre de voo de {area:144}",
		["{area:2418} flight master"] = "Mestre de voo de {area:2418}",
		["{area:348} flight master"] = "Mestre de voo de {area:348}",
		["{area:702} flight master"] = "Mestre de voo de {area:702}",
		["{npc:2487}, top floor"] = "{npc:2487}, último andar",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, no alto da árvore",
		["{npc:5385}, upstairs"] = "{npc:5385}, no andar de cima",
		["{npc:5636}, inside"] = "{npc:5636}, lá dentro",
		["{npc:7740}, beside her"] = "{npc:7740}, ao lado dela",
		["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907} fica no andar de cima, acima de {npc:7916}: suba por dentro, a seta não diferencia os andares.",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "A próxima tarefa de {npc:7907} vai para {zone:1446}: pule.",
		["{npc:7916}: keep it, the feathers come at the end of the {zone:1428} guide"] = "{npc:7916}: guarde-a; as penas vêm no fim do guia de {zone:1428}",
		["{npc:8022}' next task, {item:9471}, is a {area:978} quest: skip it."] = "A próxima tarefa de {npc:8022}, {item:9471}, é uma missão de {area:978}: pule.",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, no alto da fortaleza",
		["{zone:1419}: kill these as you meet them"] = "{zone:1419}: vá matando estes pelo caminho",
		["{zone:1453} flight master"] = "Mestre de voo de {zone:1453}",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["Below ground"] = "No subterrâneo",
		["Carry the {object:149047} south along the rim of the Cauldron and light the four Sentry Braziers, from the south-west round to the south-east."] = "Leve {object:149047} para o sul pela borda de O Caldeirão e acenda os quatro Braseiros Sentinela, do sudoeste até o sudeste.",
		["Class trainer"] = "Instrutor de classe",
		["Dorius stands by the road beside the {area:247}. Escort him north-east to {area:1959} and keep him alive; when it is over, read the {object:175704} he leaves on the road."] = "Dório fica junto à estrada, ao lado de {area:247}. Escolte-o para nordeste até {area:1959} e mantenha-o vivo; quando acabar, leia {object:175704}, que ele deixa na estrada.",
		["Fly to {area:1537}"] = "Voe para {area:1537}",
		["For {npc:8256} in {zone:1455}, at the end of this guide"] = "Para {npc:8256} em {zone:1455}, no fim deste guia",
		["Four rune rubbings in {zone:1447}: keep it"] = "Quatro decalques de runas em {zone:1447}: guarde",
		["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {zone:1427}: the {area:247} is just inside, in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one."] = "De {area:144}, siga para o sul até {zone:1418}, depois a oeste, passando pela cidade da Horda de {area:340} (dê espaço a ela), e suba a trilha até {zone:1427}: {area:247} fica logo na entrada, no sudeste. O prisioneiro na casinha de madeira quer 15 {item:4306} e oito Geólogos Ferro Negro mortos do sítio de escavação em volta. A casinha também abre com a chave, se você encontrou uma.",
		["Golems and elementals"] = "Golems e elementais",
		["Greater Lava Spiders"] = "Aranhas de Lava Abrasadoras",
		["Heavy War Golems patrol the floor of the Cauldron below {npc:8479}; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "Golens de Guerra Pesados patrulham o fundo de O Caldeirão, abaixo de {npc:8479}; Elementais de Magma vagam entre eles. Golens e elementais deixam cair o óleo; os elementais, os corações.",
		["If you skipped The {item:3985} or Facing Negolash, grind here to level 48.27 to stay on the route's plan. Or, with a group, run the {area:2100} dungeon or the {area:978} dungeon instead."] = "Se você pulou {item:3985} ou Confrontando Negolash, mate monstros aqui até o nível 48.27 para seguir o plano da rota. Ou, com um grupo, faça a masmorra {area:2100} ou a masmorra {area:978}.",
		["If you skipped {quest:3452}, grind here to level 48.98 to stay on the route's plan. Or, with a group, run the {area:2100} dungeon or the {area:978} dungeon instead."] = "Se você pulou {quest:3452}, mate monstros aqui até o nível 48.98 para seguir o plano da rota. Ou, com um grupo, faça a masmorra {area:2100} ou a masmorra {area:978}.",
		["If you skipped {quest:7701}, grind here to level 48.66 to stay on the route's plan. Or, with a group, run the {area:2100} dungeon or the {area:978} dungeon instead."] = "Se você pulou {quest:7701}, mate monstros aqui até o nível 48.66 para seguir o plano da rota. Ou, com um grupo, faça a masmorra {area:2100} ou a masmorra {area:978}.",
		["Into {zone:1427}"] = "Rumo a {zone:1427}",
		["Level 48.27"] = "Nível 48.27",
		["Level 48.66"] = "Nível 48.66",
		["Level 48.98"] = "Nível 48.98",
		["Listen to {npc:8479}'s story once more."] = "Ouça a história de {npc:8479} mais uma vez.",
		["Ride west along the north of the Gorge to {area:1446}, the scaffolded camp on the north-west rim."] = "Cavalgue para oeste pelo norte da Garganta até {area:1446}, o acampamento de andaimes na borda noroeste.",
		["Sentry Braziers"] = "Braseiros Sentinela",
		["Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it.\nCareful: Dark Iron Slavers (level 45-46) call for help from allies within 15 yd when pulled, cast Net from up to 15 yd, and use Rend in melee."] = "Capatazes e Feitores comandam os escravos por todo o Caldeirão, e qualquer um deles pode carregar {item:10551}. Os Vaporistas trabalham nas fornalhas do meio ({item:18959}), os Atalaias ficam nas cristas do sul (a Luneta). Qualquer {object:147516} pode soltar {item:11818}: guarde-o.\nCuidado: Feitores Ferro Negro (nível 45-46) chamam aliados a até 15 metros quando são puxados, lançam Rede a até 15 metros e usam Rasgar em combate corpo a corpo.",
		["The Grimesilt outhouse"] = "A casinha de Pedrassuja",
		["The night elf stands alone west of {area:1446}. Hear his story."] = "O elfo noturno está sozinho a oeste de {area:1446}. Ouça a história dele.",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "A próxima tarefa do prisioneiro, Livro-Caixa de {zone:1446}, manda você para {zone:1435} e {zone:1445}: pule.",
		["The spiders roam the plateaus and lava pools south of {npc:8436}, on the way to {npc:8479}."] = "As aranhas rondam os platôs e as poças de lava ao sul de {npc:8436}, no caminho até {npc:8479}.",
		["The {object:149502} it gives holds a {item:10575}: keep it for {npc:9459} in the {zone:1428}"] = "{object:149502} que ele dá contém {item:10575}: guarde para {npc:9459} em {zone:1428}",
		["The {object:179827} board"] = "O quadro {object:179827}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:14621} is a level 50 elite: most classes solo it at level 52, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:14621} é elite de nível 50: a maioria das classes encara sozinha no nível 52, mas talvez você precise de ajuda. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:5860} (level 50 elite) needs a group of 3. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:5860} (elite nível 50) pede um grupo de 3. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {quest:3181} needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {quest:3181} pede um grupo de 2. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["To {area:2101}"] = "Para {area:2101}",
		["Xiggs waits in the {object:32359}."] = "Xiggs espera na Ala Militar ({object:32359}).",
		["grind on {npc:5839}"] = "mate {npc:5839} até subir",
		["grind on {npc:5844}"] = "mate {npc:5844} até subir",
		["grind on {npc:9318}"] = "mate {npc:9318} até subir",
		["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443} se abre no norte de O Caldeirão. As Instruções Secretas: Fluxo Ígneo ficam na saliência superior; Incendossauros nadam nas poças de lava mais adentro, então puxe-os até a borda. Fique longe de {npc:14621} e de seus guardas de elite lá no fundo.",
		["{area:1446} flight master"] = "Mestre de voo de {area:1446}",
		["{item:18922}; below ground"] = "{item:18922}; no subterrâneo",
		["{npc:8479} stands on the rim of the Cauldron, south of {area:1446}. Listen to his story."] = "{npc:8479} fica na borda de O Caldeirão, ao sul de {area:1446}. Ouça a história dele.",
		["{npc:8509} and the dragonflight's hoard are beside {npc:8479}, on the rim south of {area:1446}."] = "{npc:8509} e o tesouro da revoada estão ao lado de {npc:8479}, na borda ao sul de {area:1446}.",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}: os limos estão em {zone:1448}, guarde",
		["{object:147516} dwarves: kill these as you meet them"] = "Anões {object:147516}: vá matando estes pelo caminho",
		["{quest:3453} lies on the ground at {npc:8479}'s feet; {quest:3462} stands beside him."] = "{quest:3453} está no chão aos pés de {npc:8479}; {quest:3462} está ao lado dele.",
		["{quest:3462}: hand it in on the way back to {area:1446}"] = "{quest:3462}: entregue no caminho de volta a {area:1446}",
		["{zone:1427}: kill these as you meet them"] = "{zone:1427}: vá matando estes pelo caminho",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Below ground"] = "No subterrâneo",
		["Bones and equipment"] = "Ossos e equipamentos",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "Ossos de Dinossauro ficam no chão no sudoeste, entre os estegodons: eles são elite, pegue os ossos ao redor deles e consiga o resto com os Dimetrodontes. O {item:11112} da expedição fica na selva sudoeste.",
		["Eastern Pylon"] = "Torre de Cristal Leste",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Termina com {npc:9298}, em {zone:1452}: guarde",
		["Fly to {area:150}"] = "Voe para {area:150}",
		["Fly to {area:1537}"] = "Voe para {area:1537}",
		["Fly to {area:415}"] = "Voe para {area:415}",
		["Fly to {area:976}"] = "Voar para {area:976}",
		["For {npc:7775} in {zone:1444}: keep it"] = "Para {npc:7775}, em {zone:1444}: guarde",
		["Lar'korwi Mates and the raft"] = "Lar'korwi Fêmeas e a jangada",
		["Level 49.51"] = "Nível 49.51",
		["Level 50.4"] = "Nível 50.4",
		["Northern Pylon"] = "Torre de Cristal Norte",
		["Pterrordax"] = "Pterrordax",
		["Ride east to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "Siga para o leste até {area:1943}, onde o robô fica entre os gorilas. Não entre na caverna funda dali.",
		["Ride north along the western jungle back to the refuge."] = "Siga para o norte pela selva oeste de volta ao refúgio.",
		["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales. The crate sits at the abandoned camp in the eastern jungle."] = "Desça para o sul pelo lado leste. Dimetrodontes Jovens pastam na selva leste e {npc:9165} voam perto dos penhascos leste; os dois soltam as escamas de {npc:9998}. O caixote fica no acampamento abandonado na selva leste.",
		["Ride south to {area:537} in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around {area:537}: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's {item:11113} sits at an abandoned camp in the eastern jungle."] = "Siga para o sul até {area:537}, no meio da cratera, e depois para o leste, até a selva leste. Há agrupamentos de cristais por toda a cratera, muitos ao redor de {area:537}: pegue alguns a mais de cada cor. Açoitadeiras Pétala Sangrenta e Látegas Pétala Sangrenta deixam cair as pétalas; o {item:11113} da expedição está num acampamento abandonado na selva leste.",
		["Ride south-west past {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; Pterrordax nest on the southern cliffs if you still need kills.\nCareful: Gorishi silithids are level 51-54 and cast {spell:8137} or {spell:14120} in melee; Gorishi Workers have a 50% chance to call for help within 25 yd once they fall below 45% health."] = "Siga para sudoeste, passando por {npc:9619}: a colmeia dos silitídeos ocupa o sul da cratera. Use o Scraping Vial em um chocadouro, uma câmara com larvas penduradas. Vespas e Trabalhadoras Gorishi soltam {quest:3764}; Pterrordaxes fazem ninho nos penhascos do sul, se você ainda precisar de mortes.\nCuidado: os silitídeos Gorishi são de nível 51-54 e lançam {spell:8137} ou {spell:14120} em combate corpo a corpo; as Trabalhadoras Gorishi têm 50% de chance de chamar ajuda a até 25 metros quando ficam abaixo de 45% de vida.",
		["Ride west back to the refuge.\nGive the elite devilsaurs and stegodons a wide berth. Pick up every Power Crystal and {object:157936} you pass from here on."] = "Volte cavalgando para oeste até o refúgio.\nPasse bem longe dos Demossauros e Estegodons elite. Daqui em diante, pegue todo Cristal de Poder e {object:157936} que encontrar.",
		["Ride west out of {area:976} to the long ramp down into {zone:1449}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "Siga para o oeste, saindo de {area:976}, até a longa rampa que desce para {zone:1449}. {npc:9619} acampa ao pé da rampa, no canto sudeste da cratera.",
		["The Gorishi hive"] = "A colmeia Gorishi",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "As Lar'korwi Fêmeas rondam a selva a oeste de {npc:9619}. A jangada destruída fica na margem do lago ali; a mochila pequena está na água ao lado. Guarde a bússola, o mapa e a chave para {npc:8737}. Qualquer fera da cratera pode deixar cair {item:11116}: clique com o botão direito nele.",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "O Manguadonte morto fica junto à água, ao norte de {npc:9619}.",
		["The flight from Theramore lands in {area:976}."] = "O voo de Theramore pousa em {area:976}.",
		["The gorillas on {area:1943} carry the pelts: keep it for the second Un'Goro visit, around 56"] = "Os gorilas de {area:1943} carregam as peles: guarde para a segunda visita a Un'Goro, por volta do nível 56",
		["The pylon stands on the eastern cliffs."] = "A torre fica nos penhascos leste.",
		["The pylon stands on the slope east of the refuge. Pterrordax circle the slopes around it: they count for Spraggle and drop {npc:9998}'s scales."] = "O pilão fica na encosta a leste do refúgio. Pterrordaxes rondam as encostas em volta: contam para a Espraga e deixam cair as escamas de {npc:9998}.",
		["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "A torre fica nos penhascos oeste. {npc:9167} voam por todo o lado oeste.",
		["The {zone:1455} quests were taken at the end of the {zone:1427} guide: fly straight on to {zone:1440} for {zone:1447}."] = "As missões de {zone:1455} foram pegas no final do guia de {zone:1427}: voe direto para {zone:1440} para ir a {zone:1447}.",
		["Theramore flight master"] = "Mestre de voo de Theramore",
		["To {area:2101}"] = "Para {area:2101}",
		["Top up here to level 49.51 before the hand-ins at {area:541}: they take you to level 50. Or, with a group, run the {area:2100} dungeon instead."] = "Complete aqui até o nível 49.51 antes das entregas em {area:541}: elas levam você ao nível 50. Ou, com um grupo, faça a masmorra {area:2100}.",
		["Top up here to level 50.4 before the hand-ins at {area:3137}: they take you to level 51. Or, with a group, run the {area:2100} dungeon or the {area:1417} dungeon instead."] = "Complete aqui até o nível 50.4 antes das entregas em {area:3137}: elas levam você ao nível 51. Ou, com um grupo, faça a masmorra {area:2100} ou a masmorra {area:1417}.",
		["Western Pylon"] = "Torre de Cristal Oeste",
		["grind on Pterrordax"] = "mate Pterrordaxes até subir",
		["grind on {npc:6116}"] = "mate {npc:6116} até subir",
		["grind on {npc:9164}"] = "mate {npc:9164} até subir",
		["grind on {npc:9167}"] = "mate {npc:9167} até subir",
		["{area:144} flight master"] = "Mestre de voo de {area:144}",
		["{area:442} flight master"] = "Mestre de voo de {area:442}",
		["{area:537} and the eastern jungle"] = "{area:537} e a selva leste",
		["{area:541} flight master"] = "Mestre de voo de {area:541}",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}: para Ogtinc, em {zone:1447}, guarde",
		["{npc:7312}, the mage trainer: for {npc:8395} in {zone:1447}, keep it"] = "{npc:7312}, o instrutor de magos: para {npc:8395} em {zone:1447}, mantenha a missão",
		["{npc:7564}, once he has brewed the elixir: a few seconds"] = "{npc:7564}, quando terminar de preparar o elixir: alguns segundos",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}, no fundo do refúgio",
		["{npc:9117}, at the back of the cave; below ground"] = "{npc:9117}, no fundo da caverna; no subterrâneo",
		["{npc:9117}, below ground"] = "{npc:9117}, no subterrâneo",
		["{npc:9618} stands just outside the refuge."] = "{npc:9618} fica logo fora do refúgio.",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, na entrada do refúgio",
		["{npc:9998}, at the refuge's entrance"] = "{npc:9998}, na entrada do refúgio",
		["{object:161504}, underwater"] = "{object:161504}, debaixo d'água",
		["{zone:1455} flight master"] = "Mestre de voo de {zone:1455}",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Arquefilis fica ao lado do Rei Magni, em {object:171709}.",
		["Archesonus stands beside King Magni in the {object:171709}: the relics you read in the Steppes are his."] = "Arquefilis fica ao lado do Rei Magni, em {object:171709}: as relíquias que você leu nas Estepes são dele.",
		["Ardalan is inside {area:1438}."] = "Ardalan fica dentro de {area:1438}.",
		["Back up through {npc:8395}'s teleport."] = "De volta ao alto pelo teletransporte de {npc:8395}.",
		["Below ground"] = "No subterrâneo",
		["Climb to the top of {area:249} and plant the head in the soft dirt mound."] = "Suba até o topo de {area:249} e finque a cabeça no monte de terra fofa.",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "Termina com {quest:4808} em {area:2255}, {zone:1452}: guarde-a",
		["Fly to {area:1438}"] = "Voe para {area:1438}",
		["Fly to {area:150}"] = "Voe para {area:150}",
		["Fly to {area:1537}"] = "Voe para {area:1537}",
		["Fly to {area:2418}"] = "Voe para {area:2418}",
		["Fly to {area:271}"] = "Voar para {area:271}",
		["Fly to {area:348}"] = "Voe para {area:348}",
		["Fly to {area:702}"] = "Voe para {area:702}",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "Siga a estrada para o oeste e depois suba para o norte até o acampamento goblin em {area:251}.",
		["For {zone:1453}: keep it"] = "Para {zone:1453}: guarde",
		["Get off your mount before you talk to {npc:8395}: he teleports you up to {npc:8379}'s tower on the cliff above his camp."] = "Desmonte antes de falar com {npc:8395}: ele teletransporta você até a torre de {npc:8379}, no penhasco acima do acampamento dele.",
		["If you skipped {quest:4022}, grind here to level 52.08 to stay on the route's plan. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "Se você pulou {quest:4022}, mate monstros aqui até o nível 52.08 para seguir o plano da rota. Ou, com um grupo, faça a masmorra {area:1417} ou a masmorra {area:2100}.",
		["Kum'isha waits at the {area:2517}, the hill south-west of the keep. The {zone:1419} mobs on the way drop the Imperfect Draenethyst Fragments; bring her what you have.\nCareful: Felcular, {npc:7664} and Ilifar are all level 60 elites. Razelikh casts {spell:2691}, {spell:8255} and Decimate, and as its health drops it adds {object:141891}, {spell:10854} and then Enrage at 15%."] = "Kum'isha espera em {area:2517}, o morro a sudoeste da fortaleza. Os monstros de {zone:1419} no caminho deixam cair os Fragmentos Imperfeitos de Draenetista; leve o que tiver.\nCuidado: Vilcular, {npc:7664} e Ilifar são todos elite de nível 60. Razelikh usa {spell:2691}, {spell:8255} e Dizimar e, conforme a vida cai, acrescenta {object:141891}, {spell:10854} e por fim Enfurecer com 15%.",
		["Level 52"] = "Nível 52",
		["Level 52.08"] = "Nível 52.08",
		["Listen to his tale, then ride back south to Kum'isha."] = "Ouça a história dele e depois volte para o sul até Kum'isha.",
		["Mosshoof Coursers"] = "Ginetes Cascomusgo",
		["Open the {item:10569} from {zone:1427} for its {item:10575}, then tell {npc:9459} you bring proof of your deeds: no drake to fight."] = "Abra o {item:10569} de {zone:1427} para pegar o {item:10575} e depois diga a {npc:9459} que você traz a prova dos seus feitos: não há draco para enfrentar.",
		["Portal to {zone:1438}"] = "Portal para {zone:1438}",
		["Ride back east along the road to the Vigil."] = "Volte para o leste pela estrada até a Vigia de Morgan.",
		["Ride back south to the camp."] = "Cavalgue de volta para o sul até o acampamento.",
		["Ride back west to {npc:8395}'s camp and get off your mount: he teleports you up to Xylem again."] = "Cavalgue de volta para oeste até o acampamento de {npc:8395} e desmonte: ele teletransporta você de novo até Tauriel.",
		["Ride north from {area:271} up the road through Alterac to {area:3197}."] = "Siga para o norte, de {area:271}, pela estrada por Alterac até {area:3197}.",
		["Ride north out of the {zone:1419} into the {zone:1435}: the {npc:10996} stands by the road from the {zone:1419}. Keep clear of {area:75}, the Horde town to the north-east."] = "Siga para o norte saindo de {zone:1419} e entrando em {zone:1435}: o {npc:10996} fica junto à estrada que vem de {zone:1419}. Mantenha distância de {area:75}, a cidade da Horda a nordeste.",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "Siga para o nordeste a partir do santuário: {npc:8405} acampa em {area:1224}, nas colinas acima da estrada.",
		["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones.\nCareful: These undead notice you from far away, and other undead nearby join the fight when one is pulled.\nCareful: The {npc:10411} (3 spawns, 15 min respawn) turns invisible when out of combat and calls in Rockwing Gargoyles once a fight starts."] = "Esfoladores Descarnados e Carniçais Salivantes andam pelos campos ao norte do acampamento; todo o Flagelo daqui deixa cair Pedras do Flagelo.\nCuidado: esses mortos-vivos percebem você de longe, e outros por perto entram na briga quando um é puxado.\nCuidado: o {npc:10411} (3 no mapa, renascem em 15 min) fica invisível fora de combate e chama Gárgulas Petrasas quando a luta começa.",
		["Swim to the small island off the southern tip of {zone:1447}. If {npc:8392} isn't there, fire your {item:10444} to signal him, and wait for him to land."] = "Nade até a pequena ilha na ponta sul de {zone:1447}. Se {npc:8392} não estiver lá, dispare sua {item:10444} para sinalizar a ele e espere que ele pouse.",
		["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side."] = "Os ogros Pirobucho ocupam a grande rocha ao norte da Vigia de Morgan, com os Brutamontes no lado leste.",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it."] = "Os fantasmas Altaneiros assombram as ruínas ao redor do santuário; os sátiros Haldarr ocupam o acampamento logo ao norte dele.",
		["The Spitelash Sirens wander the ruins and the beach around the {area:1223}, just south of {npc:8395}. Only the Sirens carry the coral, not the Screamers."] = "As Sirenas Iralisca vagam pelas ruínas e pela praia ao redor de {area:1223}, logo ao sul de {npc:8395}. Só as Sirenas carregam o coral, não os Urradores.",
		["The Spitelash naga of the {area:1221} carry {item:13815}. {npc:8507}'s four runes stand among the ruins: use his {item:10445} on each."] = "Os nagas Iralisca de {area:1221} carregam {item:13815}. As quatro runas de {npc:8507} ficam entre as ruínas: use o {item:10445} dele em cada uma.",
		["The Wildkin Feathers lie on the ground across the {zone:1425}, south and east of {area:348}, where the owlbeasts roam; the mobs here are well below you now."] = "As Penas de Coruscante estão no chão por {zone:1425}, ao sul e a leste de {area:348}, onde as ferujas andam; os monstros daqui agora estão bem abaixo de você.",
		["The apprentice at the top of the tower sends you back down."] = "O aprendiz no alto da torre manda você de volta para baixo.",
		["The blood elves are at the {area:1220}, on the way to {npc:8420}"] = "Os elfos sangrentos estão em {area:1220}, no caminho para {npc:8420}",
		["The nearest Mosshoof Coursers graze the hills north-east of the {area:1224}, toward the {area:1219}; a larger herd roams the open ground to the south."] = "Os Ginetes Cascomusgo mais próximos pastam nas colinas a nordeste de {area:1224}, em direção a {area:1219}; um rebanho maior vagueia pelo campo aberto ao sul.",
		["The portal in {area:702} leads up to {zone:1457}: {npc:9047} waits in the {area:1658}, in the north of the city."] = "O portal em {area:702} leva para cima até {zone:1457}: {npc:9047} espera em {area:1658}, no norte da cidade.",
		["The relics are in the {zone:1428}: keep it"] = "As relíquias estão em {zone:1428}: guarde",
		["The relics are the carved stones scattered through the {area:250} around {area:251}: click them until the information is recovered.\nRead the tablet in the {object:147516} camp among the ruins, south-west of {area:251}, to copy the transcript.\nUse the {item:12284} on a {npc:7047} on the slopes east of {area:251} just before it dies, then loot the essence it leaves."] = "As relíquias são as pedras esculpidas espalhadas por {area:250}, em volta de {area:251}: clique nelas até recuperar a informação.\nLeia a tábua no acampamento de {object:147516} entre as ruínas, a sudoeste de {area:251}, para copiar a transcrição.\nUse {item:12284} em um {npc:7047} nas encostas a leste de {area:251}, logo antes de ele morrer, e depois saqueie a essência que ele deixa.",
		["The shrine lies in the south-west corner of {zone:1447}, south of {area:3137}."] = "O santuário fica no canto sudoeste de {zone:1447}, ao sul de {area:3137}.",
		["The wildkin are in {zone:1452}: keep it"] = "Os coruscantes estão em {zone:1452}: guarde-a",
		["The {area:1221}"] = "{area:1221}",
		["The {area:1223}"] = "{area:1223}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} (level 48 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the {zone:1425} shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:7977} (elite nível 48) pede um grupo de 2. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.\n{npc:7977} anda pela costa de {zone:1425} abaixo de {area:307}, da seta para o sul até cerca de 75,66 e para o norte até cerca de 82,52: se ela não estiver na seta, siga a costa.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:9461} is a level 54 elite: most classes solo it at level 56, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:9461} é elite de nível 54: a maioria das classes encara sozinha no nível 56, mas talvez você precise de ajuda. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["To {area:2101}"] = "Para {area:2101}",
		["Top up here to level 52 on the ogres of {area:249}, on the way to {area:251}: the hand-ins there take you to level 53. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "Complete aqui até o nível 52 nos ogros de {area:249}, no caminho para {area:251}: as entregas de lá levam você ao nível 53. Ou, com um grupo, faça a masmorra {area:1417} ou a masmorra {area:2100}.",
		["Upstairs"] = "No andar de cima",
		["Wildkin feathers"] = "Penas de Coruscante",
		["Xylem's last task, Destroy Morphaz, is in the {area:1417}: skip it."] = "A última tarefa de Tauriel, A destruição de Morphaz, fica em {area:1417}: pule-a.",
		["grind on {npc:6196}"] = "mate {npc:6196} até subir",
		["grind on {npc:6375}"] = "mate {npc:6375} até subir",
		["grind on {npc:7033}: {npc:9177} gives {quest:4283} from level 51"] = "mate {npc:7033}: {npc:9177} dá {quest:4283} a partir do nível 51",
		["grind on {npc:7034}"] = "mate {npc:7034} até subir",
		["grind on {npc:9690}"] = "mate {npc:9690} até subir",
		["{area:144} flight master"] = "Mestre de voo de {area:144}",
		["{area:197}: kill these as you meet them"] = "{area:197}: vá matando estes pelo caminho",
		["{area:199} cauldron"] = "Caldeirão de {area:199}",
		["{area:2418} flight master"] = "Mestre de voo de {area:2418}",
		["{area:2418} sits in the south-east of the Steppes, at the top of the pass up from Redridge."] = "{area:2418} fica no sudeste das Estepes, no alto da passagem que sobe de Cristarrubra.",
		["{area:250}: kill these as you meet them"] = "{area:250}: vá matando estes pelo caminho",
		["{area:3197} flight master"] = "Mestre de voo de {area:3197}",
		["{area:348} flight master"] = "Mestre de voo de {area:348}",
		["{area:442} flight master"] = "Mestre de voo de {area:442}",
		["{item:10575}, from the hoard"] = "{item:10575}, do tesouro",
		["{item:11467}; inside"] = "{item:11467}; lá dentro",
		["{item:20028}, from the blood elf surveyors and reclaimers"] = "{item:20028}, dos agrimensores e recuperadores elfos sangrentos",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}: {npc:7864}, cerca de 10%",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of {area:200}; her parcel lies inside."] = "O fantasma de {npc:10778} vaga junto à casa da fazenda de {area:199}, a oeste de {area:200}; o embrulho dela está lá dentro.",
		["{npc:10838} stands in the middle of the camp."] = "{npc:10838} fica no meio do acampamento.",
		["{npc:11075} guards the cauldron in {area:199}, west of Andorhal."] = "{npc:11075} guarda o caldeirão em {area:199}, a oeste de Andorhal.",
		["{npc:7034}, below ground"] = "{npc:7034}, no subterrâneo",
		["{npc:7363} walks around here: look inside the circle on the map"] = "{npc:7363} anda por aqui: procure dentro do círculo no mapa",
		["{npc:7907} stands upstairs, above {npc:7916}: go up inside, the arrow cannot tell the floors apart."] = "{npc:7907} fica no andar de cima, acima de {npc:7916}: suba por dentro, a seta não diferencia os andares.",
		["{npc:8395} wants two Undamaged Hippogryph Feathers from the Thunderhead hippogryphs around his camp, the ones you top up on here: about one in three carries one."] = "{npc:8395} quer duas Penas Intactas de Hipogrifo dos hipogrifos Cabeça-de-trovão ao redor do acampamento dele, os mesmos em que você completa o nível aqui: cerca de um em cada três carrega uma.",
		["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him."] = "{npc:8420} acampa em {area:1219}, no norte; o equipamento dele está espalhado por {area:1220}, logo a sudeste dele.",
		["{npc:9047}, in the {area:1658}"] = "{npc:9047}, em {area:1658}",
		["{npc:9176} and the Blackrock orcs hold the camps and the stronghold at the foot of {area:254}, west of {area:251}. Pull them one at a time; every orc and worg may drop a medallion, so kill them until you have fifty.\nCareful: {npc:9176} has a guard linked to him that joins the fight, and a second soldier patrols close by; clear the patrol before pulling."] = "{npc:9176} e os orcs Rocha Negra ocupam os acampamentos e a fortaleza no pé de {area:254}, a oeste de {area:251}. Puxe um de cada vez; todo orc e todo worg pode deixar cair um medalhão, então mate até ter cinquenta.\nCuidado: {npc:9176} tem um guarda ligado a ele que entra na briga, e um segundo soldado patrulha ali perto; limpe a patrulha antes de puxar.",
		["{npc:9177}: the Blackrock orcs drop the medallions, keep it open all through the Steppes"] = "{npc:9177}: os orcs Rocha Negra deixam cair os medalhões, mantenha-a aberta por toda a região",
		["{object:175894}, inside"] = "{object:175894}, lá dentro",
		["{zone:1447}: kill these as you meet them"] = "{zone:1447}: vá matando estes pelo caminho",
		["{zone:1455} flight master"] = "Mestre de voo de {zone:1455}",
		["{zone:1455} has no druid trainer"] = "{zone:1455} não tem instrutor de druida",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Below ground"] = "No subterrâneo",
		["Ends in the {zone:1413}: keep it"] = "Termina em {zone:1413}: guarde-a",
		["First crater"] = "Primeira cratera",
		["Five feathers buy a little Timbermaw reputation"] = "Cinco penas rendem um pouco de reputação com os Presamatos",
		["Fly to {area:415}"] = "Voe para {area:415}",
		["Follow the road north to the cave mouth of {area:1769}; {npc:15395} guards it."] = "Siga a estrada para o norte até a entrada da caverna de {area:1769}; {npc:15395} a guarda.",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them."] = "Siga a estrada para o norte até o vale de crateras e vá até cada cratera, matando as Feras Entrópicas e os Horrores entre elas.",
		["If you skipped The Horn of the Beast or The {item:9328}, grind here to level 52.58 to stay on the route's plan. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "Se você pulou O chifre da fera ou {item:9328}, mate monstros aqui até o nível 52.58 para seguir o plano da rota. Ou, com um grupo, faça a masmorra {area:1417} ou a masmorra {area:2100}.",
		["Level 52.58"] = "Nível 52.58",
		["Level 52.69"] = "Nível 52.69",
		["Level 52.9"] = "Nível 52.9",
		["Ride north out of {area:415} into {zone:1448} to the {area:2479}, the druids' camp by the road."] = "Siga para o norte, saindo de {area:415}, até {zone:1448}, até {area:2479}, o acampamento dos druidas junto à estrada.",
		["Ride south-east from {area:1763} to the {area:2479}, the druids' camp by the road in southern {zone:1448}."] = "Siga para sudeste, de {area:1763} até {area:2479}, o acampamento dos druidas junto à estrada, no sul de {zone:1448}.",
		["Salfa stands at the {zone:1452} end of the tunnel: keep it"] = "Salfa fica na saída do túnel para {zone:1452}: guarde-a",
		["Second crater"] = "Segunda cratera",
		["Step into the cave: {npc:11558} stands just inside."] = "Entre na caverna: {npc:11558} fica logo na entrada.",
		["The Deadwood furbolgs live in the village just south-west of {npc:11554}; keep the Deadwood Headdress Feathers they drop."] = "Os furbolgs de Lenha Morta vivem na aldeia logo a sudoeste de {npc:11554}; guarde as Penas do Cocar de Lenha Morta que eles deixam cair.",
		["The Deadwood furbolgs of {area:1762} fill the hills west of the cave. Keep killing them until one drops a {quest:8470}, about one kill in thirty, then right-click it: {npc:11558} in {area:1769} takes it once the Timbermaw are Neutral to you, now if they already are, or when the last guide passes the cave again at 58.\nCareful: Den Watchers are level 53-54; they call nearby allies within 25 yd once below 50% health and run off for help below 15%."] = "Os furbolgs de Lenha Morta de {area:1762} ocupam as colinas a oeste da caverna. Continue matando-os até um soltar {quest:8470}, cerca de uma morte em trinta, e então clique nele com o botão direito: {npc:11558}, em {area:1769}, aceita-o quando os Presamatos estiverem Neutros com você, agora, se já estiverem, ou quando o último guia passar pela caverna de novo no nível 58.\nCuidado: os Vigias do Covil são de nível 53-54; chamam aliados próximos a até 25 metros quando ficam abaixo de 50% de vida e fogem para pedir ajuda abaixo de 15%.",
		["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back.\nCareful: Jadefire Shadowstalkers (level 51-52) use Sneak and {spell:7992} and are stealthed, so they often join fights uninvited.\nCursed Oozes slide about the glen's streams: kill them and use Laris's Empty Ooze Jar on their remains."] = "Os sátiros Flamejade dominam o vale a oeste da estrada, com {npc:9454} nos fundos.\nCuidado: os Assombrantes Flamejade (nível 51-52) usam Furtividade e {spell:7992} e ficam furtivos, então costumam entrar nas lutas sem serem chamados.\nGosmas Amaldiçoadas deslizam pelos riachos do vale: mate-as e use o Laris's Empty Ooze Jar nos restos delas.",
		["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "Os arvorosos Lenhatorta de {area:1767}, a leste de {area:2618}, carregam {item:11503}.",
		["The vial is filled in {zone:1457}: keep it; inside"] = "O frasco se enche em {zone:1457}: guarde; lá dentro",
		["The {area:2479}"] = "{area:2479}",
		["Third crater"] = "Terceira cratera",
		["Top up here to level 52.69 before the hand-ins at {area:1763}: they take you to level 53. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "Complete aqui até o nível 52.69 antes das entregas em {area:1763}: elas levam você ao nível 53. Ou, com um grupo, faça a masmorra {area:1417} ou a masmorra {area:2100}.",
		["Top up here to level 52.9 before the hand-ins at {area:2479}: they take you to level 53. Or, with a group, run the {area:1417} dungeon or the {area:2100} dungeon instead."] = "Complete aqui até o nível 52.9 antes das entregas em {area:2479}: elas levam você ao nível 53. Ou, com um grupo, faça a masmorra {area:1417} ou a masmorra {area:2100}.",
		["Use the {item:12922} at the corrupted moonwell in the middle of {area:1763}."] = "Use {item:12922} no poço lunar corrompido no meio de {area:1763}.",
		["grind on {npc:7109}"] = "mate {npc:7109} até subir",
		["grind on {npc:7125}"] = "mate {npc:7125} até subir",
		["grind on {npc:7153}"] = "mate {npc:7153} até subir",
		["grind on {npc:7155}"] = "mate {npc:7155} até subir",
		["{area:1763} again"] = "{area:1763} de novo",
		["{area:1763} is the ruined temple north of the glen."] = "{area:1763} é o templo em ruínas ao norte do vale.",
		["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}."] = "{area:2618} é o vale dos sátiros no noroeste, com {npc:10648} no fundo. Ele deixa cair {quest:939}; todo sátiro Flamejade pode deixar cair {item:11674}.",
		["{area:2618}: kill these as you meet them"] = "{area:2618}: vá matando estes pelo caminho",
		["{area:702} flight master"] = "Mestre de voo de {area:702}",
		["{item:11949}: Tainted Oozes slide about {area:1763}'s fel pools"] = "{item:11949}: Gosmas Maculadas deslizam pelas poças vis de {area:1763}",
		["{npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "{npc:11554}, o furbolg, fica junto à estrada, logo ao sul de {area:2479}.",
		["{npc:11558}: the Timbermaw speak to you only from Neutral; walks around here: look inside the circle on the map"] = "{npc:11558}: os Presamatos só falam com você a partir de Neutro; anda por aqui: procure dentro do círculo no mapa",
		["{npc:15395} waits at the north end of {zone:1448}"] = "{npc:15395} espera no extremo norte de {zone:1448}",
		["{npc:9116}, inside"] = "{npc:9116}, lá dentro",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528}, nas ruínas logo a leste de {npc:11554}",
} end)()
t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Any Winterfall furbolg can drop the totem, about one kill in thirty: if the top-up did not bring one, keep killing them here until it drops, then right-click it."] = "Qualquer furbolg Invernoso pode soltar o totem, cerca de uma morte em trinta: se a rodada para completar o nível não trouxe um, continue matando-os aqui até soltar, depois clique nele com o botão direito.",
		["Back to the hills: only the Ice Thistle Matriarchs and Patriarchs carry the horns."] = "De volta às colinas: só as Matriarcas e os Patriarcas Cardo de Gelo carregam os chifres.",
		["Boat to {area:150}"] = "Navio para {area:150}",
		["Fly to Theramore"] = "Voe para a Ilha Theramore",
		["Fly to {area:3197}"] = "Voe para o {area:3197}",
		["Follow the road east across the zone to the chapel."] = "Siga a estrada para leste atravessando a zona até a capela.",
		["Follow the road west to {npc:9298}'s camp beside the hot springs."] = "Siga a estrada para oeste até o acampamento de {npc:9298}, ao lado das fontes termais.",
		["Follow the southern road east into the {zone:1423}; the ruins of {area:2262} lie south of it. {npc:10926}'s ghost plays by the ruined house at the south end."] = "Siga a estrada do sul para leste até as {zone:1423}; as ruínas de {area:2262} ficam ao sul dela. O fantasma de {npc:10926} brinca junto à casa em ruínas no extremo sul.",
		["For Kernda in {area:1769}: keep it"] = "Para Kernda em {area:1769}: guarde-o",
		["Free Darrowshire Spirits: talk to them"] = "Liberte os Espíritos da Vila das Flechas: fale com eles",
		["Ice Thistle yetis live in the hills south of {area:2244}, Chillwind Chimaeras in the valley toward {area:2255}."] = "Yetis Cardo de Gelo vivem nas colinas ao sul da {area:2244}, Quimeras Ventogelantes no vale rumo a {area:2255}.",
		["Inside"] = "Lá dentro",
		["Into {zone:1423}"] = "Rumo a {zone:1423}",
		["Into {zone:1452}"] = "Rumo a {zone:1452}",
		["Keep it: Gregan in {zone:1444} brews the elixir later"] = "Guarde-o: Gregan em {zone:1444} prepara o elixir mais tarde",
		["Level 55.05"] = "Nível 55.05",
		["On {npc:10978}, by the inn"] = "Em {npc:10978}, perto da estalagem",
		["Pristine Yeti Horns"] = "Chifres Impolutos de Yeti",
		["Pureheart, Dumah, Valorfist and MacDonnell stand around the middle of the camp, by the flight master."] = "Purocoração, Dumah, Punho Valente e MacDonnell ficam no meio do acampamento, perto do mestre de voo.",
		["Scare {npc:10978} with {item:12928}"] = "Assuste {npc:10978} com {item:12928}",
		["The Deadwood cauldron in {zone:1448}: keep it"] = "O caldeirão Lenha Morta em {zone:1448}: guarde-o",
		["The Scourge around {area:2264}, west of the chapel, drop both kinds of Scourgestone; Darrowshire Spirits rise from them: talk to each one to free it.\nCareful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "O Flagelo ao redor de {area:2264}, a oeste da capela, solta os dois tipos de Pedra do Flagelo; Espíritos da Vila das Flechas surgem delas: fale com cada um para libertá-lo.\nCuidado: {npc:10411} fica invisível fora de combate e chama Gárgulas Petrasa assim que a luta começa. Existem apenas 3, e elas reaparecem a cada 15 min.",
		["The Winterfall furbolg village lies east of {area:2255}: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. {npc:10738} in the cave at the back is elite: stay out."] = "A aldeia dos furbolgs Invernosos fica a leste de {area:2255}: Xamãs (56-57), Vigias do Covil (55-56) e Ursinos (57-58), todos acima de você. Mate os Xamãs primeiro, eles curam, e atraia pelas bordas. {npc:10738}, na caverna dos fundos, é elite: fique longe.",
		["The next guide starts here and flies to {area:3197}."] = "O próximo guia começa aqui e voa para o {area:3197}.",
		["The ruins lie around the frozen lake south of {area:2253}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "As ruínas ficam em volta do lago congelado ao sul de {area:2253}. Pegue os quatro fragmentos de relíquia caídos nas ruínas e as Penas Lunamarca no chão onde os plumacuns vagam.",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "As três partes da boneca estão nas casas em ruínas de {area:2262}; pegar uma pode chamar fantasmas. Junte-as na boneca.",
		["The western Winterfall camp sits in the hills between {npc:11556} and {npc:9298}. Any furbolg here can drop an {item:12771} (about one in ten: it comes within the kills these quests need) and a {quest:8471} (about one in thirty: it comes within the top-ups): right-click whichever drops. Keep the {item:14047} the furbolgs drop for Meilosh.\nThe rest of {zone:1452}'s work is level 55-58: stay on this camp until level 54, so your first kills also count for {npc:9298} and {npc:11556}. Or, with a group, run the {area:1584} dungeon instead."] = "O acampamento oeste dos Invernosos fica nas colinas entre {npc:11556} e {npc:9298}. Qualquer furbolg daqui pode soltar {item:12771} (cerca de um em dez: vem dentro das mortes que essas missões exigem) e {quest:8471} (cerca de um em trinta: vem dentro das mortes para completar o nível): clique com o botão direito no que cair. Guarde {item:14047} que os furbolgs soltam para Meilosh.\nO resto do trabalho de {zone:1452} é de nível 55-58: fique neste acampamento até o nível 54, para que suas primeiras mortes também contem para {npc:9298} e {npc:11556}. Ou, com um grupo, faça a masmorra {area:1584}.",
		["To {area:2101}"] = "Para {area:2101}",
		["Top up here to level 55.05 before the hand-ins at {area:2255}: they take you to level 56. Grind the Winterfall furbolgs camped by {area:2246} (Pathfinders, Totemics, Den Watchers): killing them raises your Timbermaw reputation, which the quests here and the walk through {area:1769} need, one of them drops the {quest:8471}, and they fill your bags with the thirty Runecloth Meilosh asks for. Or, with a group, run the {area:1584} dungeon or the {area:1583} dungeon (Lower) instead."] = "Complete aqui até o nível 55.05 antes das entregas em {area:2255}: elas levam você ao nível 56. Mate os furbolgs Invernosos acampados perto de {area:2246} (Desbravadores, Totêmicos, Vigias do Covil): matá-los aumenta sua reputação com o Domínio dos Presamatos, que as missões daqui e a travessia de {area:1769} exigem, um deles solta {quest:8471} e eles enchem suas bolsas com as trinta Runatramas que Meilosh pede. Ou, com um grupo, faça a masmorra {area:1584} ou a masmorra {area:1583} (Inferior).",
		["Your Hearthstone is not set at {area:144} (the {zone:1425} guide binds there at 47, and this guide leaves {zone:1452} through it): bind at {area:2255} instead, for the trips back to town."] = "Sua Pedra de Regresso não está vinculada a {area:144} (o guia de {zone:1425} vincula você lá no nível 47, e este guia sai de {zone:1452} por ela): vincule-a a {area:2255}, para as viagens de volta à cidade.",
		["Your Hearthstone is still set at {area:144}: from there the gryphon to {area:3197} is about ten minutes quicker than {area:2255}'s flight to Theramore and the boat."] = "Sua Pedra de Regresso ainda está vinculada a {area:144}: de lá, o grifo para o {area:3197} é cerca de dez minutos mais rápido que o voo de {area:2255} para a Ilha Theramore e o navio.",
		["Zaeldarr is elite: grouping up is advised. He waits at the bottom of the {area:2261}, the crypt in the south-west of the zone."] = "Zaeldarr é elite: melhor ir em grupo. Ele espera no fundo de {area:2261}, a cripta no sudoeste da zona.",
		["grind on {npc:7442}"] = "mate {npc:7442} até subir",
		["{area:144} flight master"] = "Mestre de voo de {area:144}",
		["{area:150} flight master"] = "Mestre de voo de {area:150}",
		["{area:2246}: kill these as you meet them"] = "{area:2246}: vá matando estes pelo caminho",
		["{area:2247}: kill these as you meet them"] = "{area:2247}: vá matando estes pelo caminho",
		["{area:2255} flight master"] = "Mestre de voo de {area:2255}",
		["{area:2255}'s inn"] = "Estalagem de {area:2255}",
		["{item:12383}, 110 yd north"] = "{item:12383}, 110 metros ao norte",
		["{item:12886}; inside"] = "{item:12886}; lá dentro",
		["{item:12888}; inside"] = "{item:12888}; lá dentro",
		["{item:15785}; below ground"] = "{item:15785}; no subterrâneo",
		["{npc:10431}: keep both for the Plaguelands; inside"] = "{npc:10431}: guarde as duas para as Terras Pestilentas; lá dentro",
		["{npc:10739} stands by the farm at the {area:202}, on the road east to the {zone:1423}."] = "{npc:10739} fica junto à fazenda em {area:202}, na estrada para leste até {zone:1423}.",
		["{npc:10838}: the watchtowers are in Andorhal, keep it"] = "{npc:10838}: as torres de vigia ficam em Andorhal, guarde",
		["{npc:10926}'s doll"] = "A boneca de {npc:10926}",
		["{npc:10978}: {npc:7583} and {npc:10977} come later"] = "{npc:10978}: {npc:7583} e {npc:10977} vêm depois",
		["{npc:11038}: Zaeldarr is a level 54 elite"] = "{npc:11038}: Zaeldarr é elite de nível 54",
		["{npc:11053}: the cauldron is at {area:200}, keep it"] = "{npc:11053}: o caldeirão fica em {area:200}, guarde-o",
		["{npc:11556} stands right at the {zone:1452} exit of {area:1769}'s tunnel, where you come out."] = "{npc:11556} fica bem na saída de {zone:1452} do túnel de {area:1769}, por onde você sai.",
		["{npc:11616}: the termites come later, in {area:2627}"] = "{npc:11616}: os cupins vêm depois, em {area:2627}",
		["{npc:11629}: keep it for {area:2262}; inside"] = "{npc:11629}: guarde para {area:2262}; lá dentro",
		["{npc:11754} walks around {area:2255}: look inside the circle on the map"] = "{npc:11754} anda por {area:2255}: procure dentro do círculo no mapa",
		["{quest:5152}, in the {zone:1422}: keep it"] = "{quest:5152}, nas {zone:1422}: guarde-a",
} end)()
t.guides["forever/alliance/50-60/04-western-plaguelands"] = (function() return {
		["Andorhal"] = "Andorhal",
		["Back to {npc:7775}'s camp, just south-east of {npc:7765}: the {item:11242} buys three Videre Elixirs. Keep them: {npc:9298} takes one, and {npc:9299} in {area:976} shows himself only to someone who has drunk one."] = "Volte ao acampamento de {npc:7775}, logo a sudeste de {npc:7765}: o {item:11242} rende três Elixires de Videre. Guarde-os: {npc:9298} fica com um, e {npc:9299} em {area:976} só aparece para quem tiver bebido um.",
		["Below ground"] = "No subterrâneo",
		["Boat to {area:1108}"] = "Barco para {area:1108}",
		["Climb the hill west of {area:190} to look down on the town.\nCareful: Sentinels posted at the gate can detect stealthed players. Additional sentinels are found within the town, and an elite walks a patrol route nearby."] = "Suba o morro a oeste de {area:190} para olhar a cidade lá de cima.\nCuidado: as sentinelas do portão detectam jogadores furtivos. Há mais sentinelas dentro da cidade, e um elite faz patrulha ali perto.",
		["Coming in from {zone:1451}, {area:543} is just inside the crater: {npc:10302} the goblin sits by the water."] = "Vindo de {zone:1451}, {area:543} fica logo dentro da cratera: {npc:10302}, o goblin, fica junto à água.",
		["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "Atravesse o rio para o leste até a {area:2261}, a cripta no sudoeste da zona. O {object:177667} está lá dentro: a chave está com {npc:12248}, no extremo nordeste, no próximo guia.",
		["Cross the river west to {npc:1855}'s hut."] = "Atravesse o rio para o oeste até a cabana de {npc:1855}.",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "Atravesse o sul da cratera até {npc:9619}, junto à rampa.",
		["Diseased Grizzlies"] = "Ursos-cinzentos Doentes",
		["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "Os Dragasmagas cavam mais a oeste; Tenazes Petraçoite, Esfoladores Petraçoite e Espreitadoras de Rocha caçam nas mesmas areias.",
		["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "Os Dragatacas cavam nas dunas a noroeste do forte; Escorpídeos Petraçoite e Rastejantes da Areia vagueiam por toda parte.",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Termina com {npc:9298}, em {zone:1452}: guarde",
		["Escort {npc:9999}"] = "Escolte {npc:9999}",
		["Fly from {area:976} to {area:541}. {npc:8737} stands at the back of the refuge; {npc:9117} is in the cave behind him.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "Voe de {area:976} para {area:541}. {npc:8737} fica nos fundos do refúgio; {npc:9117} está na caverna atrás dele.\nO amigo de {npc:9997}, {npc:9999}, desapareceu.",
		["Fly to Theramore"] = "Voe para a Ilha Theramore",
		["Fly to {area:2255}"] = "Voe para {area:2255}",
		["Fly to {area:2268}"] = "Voe para a {area:2268}",
		["Fly to {area:271}"] = "Voar para {area:271}",
		["Fly to {area:541}"] = "Voe para {area:541}",
		["Fly to {area:702}"] = "Voe para {area:702}",
		["Fly to {area:976}"] = "Voar para {area:976}",
		["For the druids of {zone:1457}: keep it"] = "Para os druidas de {zone:1457}: guarde",
		["For {area:3197}: keep it"] = "Para {area:3197}: guarde-a",
		["For {zone:1448}: keep it"] = "Para {zone:1448}: guarde",
		["For {zone:1451}: keep it"] = "Para {zone:1451}: guarde",
		["From Theramore, ride west into the {zone:1413} and north up the coast to {area:392}."] = "De Theramore, siga para oeste até {zone:1413} e para o norte pela costa até {area:392}.",
		["From {area:702}, fly to {area:1116}."] = "De {area:702}, voe para {area:1116}.",
		["Horgus' skull lies at {area:2624} and Marduk's sword in the {area:2623}, each where ghosts fight; grown Plaguehounds hunt the plains between."] = "O Crânio de Horgus está em {area:2624} e a espada de Marduque em {area:2623}, ambos onde fantasmas lutam; Cães Pestilentos adultos caçam nas planícies entre eles.",
		["If you skipped The {item:9328}, grind here to level 56.89 to stay on the route's plan. Or, with a group, run the {area:1584} dungeon or the {area:1583} dungeon (Lower) instead."] = "Se você pulou {item:9328}, mate monstros aqui até o nível 56.89 para seguir o plano da rota. Ou, com um grupo, faça a masmorra {area:1584} ou a masmorra {area:1583} (Inferior).",
		["Inside"] = "Lá dentro",
		["Into {zone:1451}"] = "Rumo a {zone:1451}",
		["Lead {npc:7774} back to {npc:7765} at walking pace: she wanders off, so ring the bell to call her back (not in combat), and clear the harpies on the way before she reaches them."] = "Leve {npc:7774} de volta até {npc:7765} em ritmo de caminhada: ela se afasta, então toque o sino para chamá-la de volta (fora de combate) e limpe as harpias do caminho antes que ela chegue a elas.",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "Leve {npc:9999} para o norte até {area:541}. Quando ele desmaiar, use {item:11804} nele para acordá-lo.",
		["Level 56.89"] = "Nível 56.89",
		["Listen to his story"] = "Ouça a história dele",
		["Mark {npc:10902} with the {item:12815}"] = "Marque a {npc:10902} com a {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Marque a {npc:10903} com a {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Marque a {npc:10904} com a {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Marque a {npc:10905} com a {item:12815}",
		["More watches"] = "Mais relógios",
		["No {quest:5401} yet ({spell:437801} gives it on the {zone:1452} guide's way through)? Pureheart gives you one here: the scourgestone quests need it."] = "Ainda sem {quest:5401} ({spell:437801} dá uma na passagem do guia de {zone:1452})? Cândida dá uma a você aqui: as missões da Pedra do Flagelo precisam disso.",
		["Northern Pylon"] = "Torre de Cristal Norte",
		["On {npc:7583}"] = "Em {npc:7583}",
		["Portal to {zone:1438}"] = "Portal para {zone:1438}",
		["Radley and Durgen"] = "Eiras e Durgen",
		["Ranshalla in {zone:1452}: keep it"] = "Ranshalla em {zone:1452}: guarde",
		["Ride back south to the camp."] = "Cavalgue de volta para o sul até o acampamento.",
		["Ride back south-west to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "Volte para o sudoeste até a torre de {area:2742} em {area:2738}; suba nela e mate os emboscadores que surgem pelo objeto incrustado.",
		["Ride back to {area:3425}. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Cavalgue de volta a {area:3425}. {npc:15189} fica no andar de cima do prédio dele: suba por dentro, a seta não diferencia os andares.",
		["Ride east to the border river: {npc:1855} lives in a small hut on the bank."] = "Cavalgue para o leste até o rio da fronteira: {npc:1855} mora numa pequena cabana na margem.",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "Siga para o leste até {area:537}, suba e use {npc:10541} nas aberturas de lava perto do topo.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Siga para o norte pelo lado leste até o planalto dos gorilas. {npc:9622}, um gorila de nível 55, fica na caverna mais funda: limpe os gorilas da entrada antes.",
		["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby."] = "Cavalgue para o norte até {area:2627}. {npc:12384} mora na cabana em ruínas, e o livro de recibos dele está na estalagem em ruínas ali perto.",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "Cavalgue para o norte pela estrada até a Madeireira Beiranorte; {npc:11610} se esconde na borda do acampamento.",
		["Ride north-west to the Dalson farm. The diary lies in the barn; a wandering skeleton carries the outhouse key, and {npc:10836} waits in the outhouse with the cabinet key."] = "Cavalgue para o noroeste até a fazenda dos Dalson. O diário está no celeiro; um esqueleto errante carrega a chave da casinha, e {npc:10836} espera na casinha com a chave do armário.",
		["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "Cavalgue para o noroeste até {area:2276}, na borda de {area:2277}.",
		["Ride on west to {area:3425}. {npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Siga adiante para oeste até {area:3425}. {npc:15189} fica no andar de cima do prédio dele: suba por dentro, a seta não diferencia os andares.",
		["Ride out of the crater's north-western pass into {zone:1451}: {npc:13220} stands at {area:3077}, where the pass comes out."] = "Cavalgue saindo pela passagem noroeste da cratera até {zone:1451}: {npc:13220} fica em {area:3077}, onde a passagem sai.",
		["Ride south to {area:201}, where {npc:11078} guards the cauldron."] = "Cavalgue para o sul até {area:201}, onde {npc:11078} guarda o caldeirão.",
		["Ride south-west to the camp."] = "Cavalgue para o sudoeste até o acampamento.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Siga para o sudoeste até o acampamento de {npc:7771} em {area:1938}.",
		["Ride west along the road to the hot springs."] = "Cavalgue para o oeste pela estrada até as fontes termais.",
		["Ride west into the Ravenwind Ruins: {npc:7774} hides in the small round building at the back. Open the chest beside her for {item:9189}: it lasts 15 minutes, like the quest."] = "Cavalgue para o oeste, até as Ruínas dos Ventos Corvejantes: {npc:7774} se esconde na pequena construção redonda dos fundos. Abra o baú ao lado dela para pegar {item:9189}: dura 15 minutos, como a missão.",
		["Ride west to {area:2627}. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the {item:15042} at the big termite mounds and kill the Frenzied Plaguehounds further north."] = "Cavalgue para o oeste até {area:2627}. Cães Pestilentos Miúdos, Quirópragos e Vermes Carniceiros vagam pelos bosques; encha a {item:15042} nos grandes cupinzeiros e mate os Cães Pestilentos Frenéticos mais ao norte.",
		["Scare {npc:7583} with {item:12928}"] = "Assuste {npc:7583} com {item:12928}",
		["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones.\nCareful: These undead notice you from far away, and other undead nearby join the fight when one is pulled.\nCareful: The {npc:10411} (3 spawns, 15 min respawn) turns invisible when out of combat and calls in Rockwing Gargoyles once a fight starts."] = "Esfoladores Descarnados e Carniçais Salivantes andam pelos campos ao norte do acampamento; todo o Flagelo daqui deixa cair Pedras do Flagelo.\nCuidado: esses mortos-vivos percebem você de longe, e outros por perto entram na briga quando um é puxado.\nCuidado: o {npc:10411} (3 no mapa, renascem em 15 min) fica invisível fora de combate e chama Gárgulas Petrasas quando a luta começa.",
		["Take the boat to the mainland and ride north-east to {npc:14637}'s camp by the {area:1119}."] = "Pegue o barco para o continente e cavalgue para o nordeste até o acampamento de {npc:14637}, junto a {area:1119}.",
		["Tar Beasts wallow in the {area:538}; the fire elementals of {area:537} in the middle carry the ash; the Gorishi wasps of the {area:540} in the south carry the gland. Every creature in the crater can drop {item:11018}.\nCareful: Gorishi Workers that drop below 45% health have a 50% chance to call for help from allies within 25 yd."] = "Monstros de Piche chafurdam em {area:538}; os elementais do fogo de {area:537}, no meio, carregam a cinza; as vespas Gorishi de {area:540}, no sul, carregam a glândula. Qualquer criatura da cratera pode deixar cair {item:11018}.\nCuidado: as Gorishi Trabalhadoras que caem abaixo de 45% de vida têm 50% de chance de chamar ajuda de aliados num raio de 25 m.",
		["Ten {item:11040} from the {item:11020}"] = "Dez {item:11040} da {item:11020}",
		["The Andorhal watchtowers"] = "As torres de vigia de Andorhal",
		["The Scarlet Crusade"] = "A Cruzada Escarlate",
		["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "Socorristas Escarlates, Caçadores Escarlates, Cavaleiros Escarlates e Magos Escarlates patrulham a madeireira e a estrada rumo a {area:190}.",
		["The Tar Beasts and Tar Lords wallow in the {area:538}, south of the refuge on the way down into the crater."] = "Os Monstros de Piche e os Senhores do Piche chafurdam em {area:538}, ao sul do refúgio, no caminho para dentro da cratera.",
		["The cauldron sits at the {area:202}, by {npc:10739}' farm."] = "O caldeirão fica em {area:202}, junto à fazenda de {npc:10739}.",
		["The cauldron sits at {area:200}, north-east of Felstone; its Cauldron Lord stands beside it."] = "O caldeirão fica em {area:200}, a nordeste do Campo Pedravil; o Mestre da Caldeira dele fica ao lado.",
		["The crater"] = "A cratera",
		["The giant {npc:7765} sits just north-west of {npc:7775}'s camp."] = "O gigante {npc:7765} fica logo a noroeste do acampamento de {npc:7775}.",
		["The gorillas live on {area:1943}, east of {area:541}. Keep their pelts for {npc:9619}. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "Os gorilas vivem em {area:1943}, a leste de {area:541}. Guarde os pelegos para {npc:9619}. Não entre na caverna mais funda: {npc:9622} é nível 55.\nCuidado: os Gorilas de Un'Goro (nível 50-51) chamam ajuda de aliados num raio de 20 m quando caem para 25% de vida. Tem uma caverna lotada de macacos na área, e lutar lá traz monstro a mais de montão.",
		["The gorillas live on {area:1943}, just east of the pylon: take the pelts for {npc:9619} now, while you are up here. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "Os gorilas vivem em {area:1943}, logo a leste da torre de cristal: pegue os pelegos para {npc:9619} agora, enquanto está aqui em cima. Não entre na caverna mais funda: {npc:9622} é nível 55.\nCuidado: os Gorilas de Un'Goro (nível 50-51) chamam ajuda de aliados num raio de 20 m quando caem para 25% de vida. Tem uma caverna lotada de macacos na área, e lutar lá traz monstro a mais de montão.",
		["The pelts come from the gorillas on {area:1943}"] = "As peles vêm dos gorilas em {area:1943}",
		["The shrunken giants roam the {area:1119}; the sea elementals wade along the coast to the west."] = "Os gigantes encolhidos vagam por {area:1119}; os Elementais do Mar andam pela costa a oeste.",
		["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "Os Druidas Torturados e as Sentinelas Torturadas assombram a aldeia em ruínas a sudoeste de {npc:13220}.",
		["The wooden sign beside {npc:9997}"] = "A placa de madeira ao lado de {npc:9997}",
		["The {area:2742} tower"] = "A torre de {area:2742}",
		["The {item:11242} grows inside a ruined building north of {npc:7765}: climb in through the break in its wall from the ledge beside it."] = "O {item:11242} cresce dentro de uma construção em ruínas ao norte de {npc:7765}: entre pela abertura na parede, a partir da saliência ao lado.",
		["Umber in {zone:1450}: keep it"] = "Umbero em {zone:1450}: guarde-a",
		["Upstairs"] = "No andar de cima",
		["Use the {item:12627} by the grain silos to draw out Temporal Parasites. {quest:5154} is one of the musty tomes in the town hall. Every skeleton in town drops {quest:5537}."] = "Use o {item:12627} junto aos silos de grãos para atrair Parasitas Temporais. {quest:5154} é um dos Tomos Mofados na prefeitura. Todo esqueleto da cidade deixa cair {quest:5537}.",
		["Use the {item:12815} at the foot of each of the four watchtowers around the edge of Andorhal, north of the camp."] = "Use a {item:12815} ao pé de cada uma das quatro torres de vigia na periferia de Andorhal, ao norte do acampamento.",
		["Walk into {area:1769} and take the {zone:1450} branch of the tunnel to {area:2361}."] = "Entre em {area:1769} e pegue o ramo do túnel para {zone:1450} até {area:2361}.",
		["grind on {npc:11740}"] = "mate {npc:11740} até subir",
		["{area:1108}: kill these as you meet them"] = "{area:1108}: vá matando estes pelo caminho",
		["{area:190} overlook"] = "Mirante de {area:190}",
		["{area:1942}: kill these as you meet them"] = "{area:1942}: vá matando estes pelo caminho",
		["{area:1943}: kill these as you meet them"] = "{area:1943}: vá matando estes pelo caminho",
		["{area:197}: kill these as you meet them"] = "{area:197}: vá matando estes pelo caminho",
		["{area:200} cauldron"] = "Caldeirão de {area:200}",
		["{area:201} cauldron"] = "Caldeirão de {area:201}",
		["{area:202} cauldron"] = "Caldeirão de {area:202}",
		["{area:202}: kill these as you meet them"] = "{area:202}: vá matando estes pelo caminho",
		["{area:2277}: kill these as you meet them"] = "{area:2277}: vá matando estes pelo caminho",
		["{area:3197} flight master"] = "Mestre de voo de {area:3197}",
		["{area:348} flight master"] = "Mestre de voo de {area:348}",
		["{area:392} flight master"] = "Mestre de voo de {area:392}",
		["{area:442} flight master"] = "Mestre de voo de {area:442}",
		["{area:489} flight master"] = "Mestre de voo de {area:489}",
		["{area:538}: kill these as you meet them"] = "{area:538}: vá matando estes pelo caminho",
		["{area:702} flight master"] = "Mestre de voo de {area:702}",
		["{area:976} flight master"] = "Mestre de voo de {area:976}",
		["{item:11478}; below ground"] = "{item:11478}; no subterrâneo",
		["{item:11479}; below ground"] = "{item:11479}; no subterrâneo",
		["{item:11480}; below ground"] = "{item:11480}; no subterrâneo",
		["{item:12894}, at the monument"] = "{item:12894}, no monumento",
		["{item:12954} lies in the town hall of {area:190}, west of {npc:1855}: the Scarlet guards stand close together."] = "{item:12954} está na prefeitura de {area:190}, a oeste de {npc:1855}: os guardas escarlates ficam bem juntos.",
		["{item:12954}; inside"] = "{item:12954}; lá dentro",
		["{item:12955} lies east of the barn at {area:201}."] = "{item:12955} está a leste do celeiro em {area:201}.",
		["{item:12956}; underwater"] = "{item:12956}; debaixo d'água",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal."] = "{npc:10667} espera na estalagem em ruínas no lado oeste de Andorhal.",
		["{npc:10878} and {npc:7740} stand by the Temple of the Moon; fill {item:11682} at the moonwell inside."] = "{npc:10878} e {npc:7740} ficam junto ao Templo da Lua; encha o {item:11682} no poço lunar lá dentro.",
		["{npc:10927}'s farmhouse stands on the hill east of the camp; {npc:10936}'s monument is just north of it."] = "A casa de fazenda de {npc:10927} fica na colina a leste do acampamento; o monumento de {npc:10936} fica logo ao norte dela.",
		["{npc:11613} walks the Northridge camp east of {npc:11610}; {npc:11611} guards the tower at {area:190}'s southern approach.\nCareful: Guards stand at the tower's base and one more circles it on patrol. Clear them before you engage Durgen so they don't join the fight."] = "{npc:11613} anda pelo acampamento de Beiranorte, a leste de {npc:11610}; {npc:11611} guarda a torre na entrada sul de {area:190}.\nCuidado: há guardas na base da torre e mais um patrulhando em volta dela. Limpe-os antes de encarar o Durgen, para eles não entrarem na briga.",
		["{npc:11741} walks around here: look inside the circle on the map"] = "{npc:11741} anda por aqui: procure dentro do círculo no mapa",
		["{npc:11886} is elite: grouping up is advised"] = "{npc:11886} é elite: recomenda-se ir em grupo",
		["{npc:17082}, at the Alliance tents"] = "{npc:17082}, nas tendas da Aliança",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} é elite de nível 61",
		["{npc:1852} is elite: grouping up is advised. He guards his phylactery in the middle of Andorhal.\nSmall lockboxes lie in the rubble all over Andorhal; each holds a watch.\nCareful: Ghouls and skeletons usually stand next to the boxes and attack when you come close. Searing ghouls also hurt anyone nearby and will break stealth."] = "{npc:1852} é elite: melhor ir em grupo. Ele guarda a filactéria dele no meio de Andorhal.\nCaixinhas trancadas estão nos escombros por toda Andorhal; cada uma guarda um relógio.\nCuidado: carniçais e esqueletos costumam ficar ao lado das caixas e atacam quando você chega perto. Os Carniçais Ardentes também ferem quem estiver por perto e quebram a furtividade.",
		["{npc:5411} in {area:976}: keep it"] = "{npc:5411} em {area:976}: guarde",
		["{npc:5594}, inside"] = "{npc:5594}, lá dentro",
		["{npc:5901}, on the coast north of town"] = "{npc:5901}, na costa ao norte da cidade",
		["{npc:7740}: keep it for {area:976}"] = "{npc:7740}: guarde para {area:976}",
		["{npc:7775}'s camp lies north of the {area:1119}. He brews the {item:11243} from an {item:11242}: take his errand for one."] = "O acampamento de {npc:7775} fica ao norte de {area:1119}. Ele prepara o {item:11243} a partir de um {item:11242}: pegue a tarefa dele para conseguir um.",
		["{npc:7876}, north side of town: the tar is in Un'Goro, keep it"] = "{npc:7876}, no lado norte da cidade: o piche está em Un'Goro, guarde",
		["{npc:7900}: keep it for {zone:1446}"] = "{npc:7900}: guarde para {zone:1446}",
		["{npc:8496}: keep it for Un'Goro; inside"] = "{npc:8496}: guarde para Un'Goro; lá dentro",
		["{npc:8598}, 170 yd north-east"] = "{npc:8598}, 170 metros a nordeste",
		["{npc:9117}, below ground"] = "{npc:9117}, no subterrâneo",
		["{npc:9299} in {area:976}: keep it"] = "{npc:9299} em {area:976}: guarde",
		["{npc:9299} is a ghost at the graveyard just east of town: drink a {item:11243} there, which kills you, release your spirit and talk to him as a ghost. Then run back to your body to come back to life: the gravestone stands nearby."] = "{npc:9299} é um fantasma no cemitério logo a leste da cidade: beba um {item:11243} lá, o que mata você, libere o espírito e fale com ele como fantasma. Depois corra de volta ao seu corpo para reviver: a lápide fica ali perto.",
		["{npc:9619} camps at the foot of the ramp into the crater."] = "{npc:9619} acampa ao pé da rampa que leva à cratera.",
		["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "O covil de {npc:9684} fica na selva ao norte de {npc:9619}, abaixo dos penhascos leste: use {item:11568} ali. {npc:9684} é nível 56: comece com a vida cheia.",
		["{npc:9999} sits on the south-east slope of {area:537}, in the middle of the crater."] = "{npc:9999} está sentado na encosta sudeste de {area:537}, no meio da cratera.",
		["{object:175924}, in the farmhouse; inside"] = "{object:175924}, na casa da fazenda; lá dentro",
		["{object:177667}, below ground"] = "{object:177667}, no subterrâneo",
		["{quest:3444} is in {area:392}"] = "{quest:3444} fica em {area:392}",
		["{quest:5058}, inside"] = "{quest:5058}, lá dentro",
		["{quest:5210}, at {area:2268}: keep it"] = "{quest:5210}, em {area:2268}: guarde",
		["{quest:6762} in {zone:1450}: keep it"] = "{quest:6762} em {zone:1450}: guarde",
		["{zone:1423}: kill these as you meet them"] = "{zone:1423}: vá matando estes pelo caminho",
		["{zone:1449}: kill these as you meet them"] = "{zone:1449}: vá matando estes pelo caminho",
		["{zone:1451}: kill these as you meet them"] = "{zone:1451}: vá matando estes pelo caminho",
		["{zone:1455}, where the next guide trains, has no druid trainer"] = "{zone:1455}, onde o próximo guia treina, não tem instrutor de druida",
} end)()
t.guides["forever/alliance/50-60/05-silithus"] = (function() return {
		["Boat to {area:35}"] = "Barco para {area:35}",
		["Chromie in Andorhal: keep it"] = "Crona nas Ruínas de Andorhal: guarde-a",
		["Fly from {area:541} to {area:392}."] = "Voe de {area:541} para {area:392}.",
		["Fly to {area:2268}"] = "Voe para a {area:2268}",
		["Fly to {zone:1453}"] = "Voe para {zone:1453}",
		["For {npc:10778}: keep it"] = "Para {npc:10778}: guarde-a",
		["Its jars are filled on the next Un'Goro visit"] = "As jarras dela são enchidas na próxima visita à Cratera Un'Goro",
		["Ride north to the {area:2277}'s north-eastern edge.\nCareful: The trolls along the path to {area:2273} are level 57-59. They run away at low health and call for help, so they often bring adds with them."] = "Cavalgue para o norte até a borda nordeste de {area:2277}.\nCuidado: os trolls do caminho até {area:2273} são nível 57-59. Fogem com pouca vida e chamam ajuda, então costumam trazer reforço.",
		["Ride south-west to the {area:2261}. The mound of dirt lies inside. {npc:11886} is elite: grouping up is advised.\nCareful: About four non-elite adds come with Mercutio. They walk to the grave instead of appearing on the spot."] = "Cavalgue para sudoeste até {area:2261}. O monturo de terra fica lá dentro. {npc:11886} é elite: melhor ir em grupo.\nCuidado: uns quatro capangas não elite vêm com o Mercutio. Eles caminham até o túmulo em vez de aparecer ali na hora.",
		["Scourge Champions"] = "Campeões do Flagelo",
		["Scourge Champions (59) roam the {area:2270}, north of {area:2268}. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants. Pull them one at a time."] = "Os Campeões do Flagelo (59) vagueiam por {area:2270}, ao norte de {area:2268}. Passe o {item:13156} de {npc:11063} sobre cada um que você matar: os crânios que ressoam são os que ele quer. Puxe-os um de cada vez.",
		["Take the boat from {area:392} to {area:35} and fly to {zone:1453}."] = "Pegue o barco de {area:392} para {area:35} e voe para {zone:1453}.",
		["Tram to {zone:1455}"] = "Metrô para {zone:1455}",
		["{area:35} flight master"] = "Mestre de voo de {area:35}",
		["{item:13155}, from the Scourge Champions"] = "{item:13155}, dos Campeões do Flagelo",
		["{item:14613}, from {npc:11886}"] = "{item:14613}, de {npc:11886}",
		["{npc:11038}, by the graves south of the chapel: Egan is in {area:2627}, keep it"] = "{npc:11038}, junto aos túmulos ao sul da capela: Egan está em {area:2627}, guarde-o",
		["{npc:14724}, by the tram"] = "{npc:14724}, perto do metrô",
		["{npc:332}, in SI:7"] = "{npc:332}, na AVIN",
		["{npc:3520}, who walks the canals"] = "{npc:3520}, que anda pelos canais",
		["{npc:8496}, inside"] = "{npc:8496}, lá dentro",
		["{quest:6184} at {area:3197}: keep it"] = "{quest:6184} em {area:3197}: guarde-a",
		["{zone:1455} flight master"] = "Mestre de voo de {zone:1455}",
} end)()
t.guides["forever/alliance/50-60/06-silithus"] = (function() return {
		["Andorhal"] = "Ruínas de Andorhal",
		["Angerclaw bears and Felpaw wolves"] = "Ursos Garraivosos e Lobos Patavil",
		["Araj is elite: grouping up is advised."] = "Araj, o Evocador, é elite: recomenda-se formar um grupo.",
		["Back into {area:1770}: {npc:9861} and {npc:9860} guard {npc:9517} in its deepest chamber. The succubus {npc:9518} waits on the way, with Trey Lightforge's remains beside her.\nCareful: The three bosses fight as a group. Kill the nearby mobs first so you don't pull extra enemies."] = "De volta a {area:1770}: {npc:9861} e {npc:9860} guardam {npc:9517} na câmara mais funda. A súcubo {npc:9518} espera no caminho, com os restos mortais de Trey Forjaleve ao lado dela.\nCuidado: os três chefes lutam juntos. Mate os monstros por perto antes para não puxar inimigo a mais.",
		["Below ground"] = "No subterrâneo",
		["Boat to {area:150}"] = "Navio para {area:150}",
		["Bronzebeard's Encampment"] = "Acampamento Barbabronze",
		["Climb {area:537} in the middle of the crater and use the {item:14644} by the lava lake at the top, with two Thorium Bars in your bags. Fill {npc:9616}'s Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge."] = "Suba {area:537}, no meio da cratera, e use o {item:14644} junto ao lago de lava no topo, com duas Barras de Tório nas bolsas. Encha as Jarras de Amostra Pura Vazias de {npc:9616} nas Gosmas Primevas das poças ao redor da serra.",
		["Cross the river east of {npc:1855} into {area:2627}. The Terrordale Spirits haunt the woods there. Top up here to level 59.93 before the hand-ins at {area:3197}: they take you to level 60. Or, with a group, run the {area:2057} dungeon or the {area:2279} dungeon instead."] = "Atravesse o rio a leste de {npc:1855} até {area:2627}. Os Espíritos da Várzea do Medo assombram a mata ali. Complete aqui até o nível 59.93 antes das entregas em {area:3197}: elas levam você ao nível 60. Ou, com um grupo, faça a masmorra {area:2057} ou a masmorra {area:2279}.",
		["Cross the river east of {npc:1855}'s hut into {area:2627}: {npc:11140} stands by Augustus' ruined hut."] = "Atravesse o rio a leste da cabana de {npc:1855} até {area:2627}: {npc:11140} fica junto à cabana em ruínas de Augustus.",
		["Flint's next task goes to {zone:1453}: you are level 60 now, skip it."] = "A próxima tarefa de Flint vai para {zone:1453}: você já está no nível 60, pule-a.",
		["Fly to {area:2255}"] = "Voe para {area:2255}",
		["Fly to {area:271}"] = "Voar para {area:271}",
		["Fly to {area:3137}"] = "Voe para {area:3137}",
		["Fly to {area:3137} in {zone:1447} and ride west along the road to {area:2358}, just over the {zone:1440} border."] = "Voe para {area:3137} em {zone:1447} e siga para o oeste pela estrada até {area:2358}, logo depois da fronteira de {zone:1440}.",
		["Fly to {area:3425}"] = "Voe para {area:3425}",
		["Fly to {area:442}"] = "Voe para {area:442}",
		["Fly to {area:702}"] = "Voe para {area:702}",
		["Fly to {area:976}"] = "Voar para {area:976}",
		["Fly to {area:976}."] = "Voe para {area:976}.",
		["Fly to {area:976}. Buy two Thorium Bars at the Auction House here for {quest:5801}."] = "Voe para {area:976}. Compre duas Barras de Tório na Casa de Leilões daqui para {quest:5801}.",
		["Fly to {zone:1453}"] = "Voe para {zone:1453}",
		["Follow the road north to {area:1767}. The Irontree Stompers carry the heart; finish the claws on the Angerclaw Grizzlies and Felpaw Ravagers of the north."] = "Siga a estrada para o norte até {area:1767}. Os Pisoteadores de Ferrárbol carregam o coração; termine as garras nos Ursos-cinzentos Garraivosos e nos Assoladores Patavil do norte.",
		["Follow {npc:9298}'s directions to the mouth of {area:2256}, past the Frostmaul giants: pass them one at a time."] = "Siga as instruções de {npc:9298} até a entrada do {area:2256}, passando pelos gigantes Friomalho: passe por eles um de cada vez.",
		["From {area:3137} ride into {zone:1448}: the {area:2479} is the druids' camp on the road just past the {zone:1440} border."] = "De {area:3137}, siga para {zone:1448}: {area:2479} é o acampamento dos druidas na estrada, logo depois da divisa com {zone:1440}.",
		["Hand him the ten texts you kept"] = "Entregue a ele os dez textos que você guardou",
		["Havunth's camp sits just west of {area:3425}."] = "O acampamento do Guardião do Crepúsculo Havunth fica logo a oeste de {area:3425}.",
		["Inside"] = "Lá dentro",
		["Irontree Stompers"] = "Pisoteadores de Ferrárbol",
		["Keep the {item:11169}, the claws and the heart he hands back"] = "Guarde o {item:11169}, as garras e o coração que ele devolve",
		["Lead her out of {area:1770} and keep her alive until she is outside the cave: clear the way back first."] = "Leve-a para fora de {area:1770} e mantenha-a viva até ela estar fora da caverna: limpe antes o caminho de volta.",
		["Learn the flight path in {area:2361}."] = "Aprenda a rota de voo em {area:2361}.",
		["Level 59.93"] = "Nível 59.93",
		["Pick up the supplies around the wagon and take {npc:10301}'s amulet back from the owlbeasts nearby."] = "Pegue os suprimentos em volta da carroça e tome de volta o amuleto de {npc:10301} dos corujursos próximos.",
		["Portal to {zone:1438}"] = "Portal para {zone:1438}",
		["Ride back east past {area:2255} and south-east down the valley to {npc:10301}'s damaged crate in the snow at {area:2245}, with his wrecked wagon just east of it."] = "Volte para leste, passando por {area:2255}, e desça o vale para sudeste até o caixote danificado de {npc:10301} na neve, em {area:2245}, com a carroça destruída dele logo a leste.",
		["Ride back south along the road to the Sanctuary."] = "Volte para o sul pela estrada até o Santuário.",
		["Ride back south-east to the hermit."] = "Volte para o sudeste até o eremita.",
		["Ride back south-west to {area:3197}."] = "Volte para o sudoeste até {area:3197}.",
		["Ride east into the hills. Use the {item:11169} to summon {quest:4005}, then defeat him for the totem."] = "Siga para o leste até as colinas. Use o {item:11169} para invocar {quest:4005} e derrote-o para obter o totem.",
		["Ride east to the ruins of {area:2738}. The {object:179565} lies among the ruined buildings, watched by Tortured Sentinels."] = "Siga para o leste até as ruínas de {area:2738}. {object:179565} está entre os edifícios em ruínas, vigiado por Sentinelas Torturadas.",
		["Ride north along the west side to Mayna's small camp."] = "Siga para o norte pelo lado oeste até o pequeno acampamento da Tutora do Crepúsculo Mayna.",
		["Ride north to the Deadwood furbolgs' village by the {area:1769} cave mouth."] = "Siga para o norte até a aldeia dos furbolgs de Lenha Morta, perto da entrada da caverna de {area:1769}.",
		["Ride north to {area:541}. Use {npc:10980} beside {npc:10977}."] = "Siga para o norte até {area:541}. Use {npc:10980} ao lado de {npc:10977}.",
		["Ride north up the road to the lumber mill and set the termite barrel down in the middle of it."] = "Siga a estrada para o norte até a serraria e coloque o barril de cupins no meio dela.",
		["Ride north up the valley, past {area:2255}, to {area:2253}."] = "Siga para o norte pelo vale, passando por {area:2255}, até {area:2253}.",
		["Ride north-west up the road to {area:2253}."] = "Siga para noroeste pela estrada até {area:2253}.",
		["Ride south to the {area:2260}, the farm north-west of {area:2262}. The three agents' remains are bone outlines on the ground: one by the road south of the farm, one on the hill east of the house, one on the mound in front of it. Coming close enough to see the Blightcaller in front of the house completes the scouting.\nCareful: {npc:11878} (level 62 elite) and his elite hounds stand in front of the house: take the remains on the mound from the side and do not pull him. You don't have to fight him."] = "Cavalgue para o sul até {area:2260}, a fazenda a noroeste de {area:2262}. Os restos dos três agentes são contornos de ossos no chão: um junto à estrada ao sul da fazenda, um na colina a leste da casa, um no montículo na frente dela. Chegar perto o bastante para ver o Arauto da Praga na frente da casa completa o reconhecimento.\nCuidado: {npc:11878} (elite de nível 62) e seus cães de elite ficam na frente da casa: pegue os restos do montículo pelo lado e não o puxe. Você não precisa lutar contra ele.",
		["Ride south-west to the dwarves' camp near the southern mountains and question {npc:15171} and {npc:15170}. {npc:15190}'s satchel lies in the sand just south-east of the camp."] = "Siga para o sudoeste até o acampamento dos anões perto das montanhas do sul e interrogue {npc:15171} e {npc:15170}. A Algibeira do {npc:15190} está na areia, logo a sudeste do acampamento.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Siga para o sudoeste até o acampamento de {npc:7771} em {area:1938}.",
		["Running {area:2057} ({area:2298}, south-east {zone:1422}) or {area:2279} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "Fazer {area:2057} ({area:2298}, sudeste de {zone:1422}) ou {area:2279} em vez de farmar leva você lá mais rápido em grupo. Pule esta etapa para farmar sozinho.",
		["Running {area:2577} in {zone:1444} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "Fazer {area:2577} em {zone:1444} em vez de farmar leva você lá mais rápido em grupo. Pule esta etapa para farmar sozinho.",
		["Take the portal up to {zone:1457}."] = "Pegue o portal para subir até {zone:1457}.",
		["Take the road west down into the crater and ride to the {area:540}, the silithid cave in the south. The {npc:10041} waits in its deepest chamber."] = "Pegue a estrada para o oeste, desça até a cratera e siga até a {area:540}, a caverna dos silitídeos no sul. {npc:10041} espera na câmara mais profunda.",
		["Take the {area:1769} tunnel from its {zone:1452} mouth, west of {npc:9298}, and follow the {area:493} branch to {area:2361}. {npc:11939} studies by the lake shore."] = "Pegue o túnel de {area:1769} pela entrada de {zone:1452}, a oeste de {npc:9298}, e siga o ramal de {area:493} até {area:2361}. {npc:11939} estuda à beira do lago.",
		["Take the {area:2257} to {zone:1455}. {npc:14724} and {npc:14723} each take sixty Wool, sixty Silk and sixty Mageweave, then sixty {item:14047}: hand in what you carry (or buy at the Auction House), skip the rest."] = "Pegue o {area:2257} até {zone:1455}. {npc:14724} e {npc:14723} aceitam sessenta de Lã, sessenta de Seda e sessenta de Magitrama cada, depois sessenta {item:14047}: entregue o que você carrega (ou compre na Casa de Leilões) e pule o resto.",
		["Ten more for {quest:8323}"] = "Mais dez para {quest:8323}",
		["The Deadwood totem from {area:1762}, if {npc:11558} didn't take it then."] = "O totem de Lenha Morta de {area:1762}, se {npc:11558} não o aceitou antes.",
		["The Twilight's Hammer dig fills the north-west corner: tablet fragments lie on the ground and the Dust Stormers and Desert Rumblers carry them too. Every cultist can drop an {item:20404}: keep twenty, ten for {npc:15306} and ten for {npc:15194} later."] = "A escavação do Martelo do Crepúsculo ocupa o canto noroeste: há fragmentos de tábua no chão, e as Tempestades de Poeira e os Estrondores do Deserto também os carregam. Todo sectário pode deixar cair um {item:20404}: guarde vinte, dez para {npc:15306} e dez para {npc:15194} depois.",
		["The flight lands in {area:702}. {npc:7916} stands a short walk north-west of the flight master."] = "O voo pousa em {area:702}. {npc:7916} fica a uma curta caminhada a noroeste do mestre de voo.",
		["The hermit hides among the rocks south-east of {area:2738}."] = "O eremita se esconde entre as rochas a sudeste de {area:2738}.",
		["The western Winterfall furbolgs drop the beads.\nCareful: Turning in spawns three or four level 56-57 Winterfall ambushers that attack you; you can escape them while mounted, in stealth or with {spell:5384}, and they then gather by the lake so you can take the next quest."] = "Os furbolgs Invernosos do oeste deixam cair as contas.\nCuidado: a entrega faz surgir três ou quatro emboscadores Invernosos de nível 56-57 que atacam você; dá para escapar montado, furtivo ou com {spell:5384}, e depois eles se juntam perto do lago, liberando a próxima missão.",
		["The {area:2479}"] = "{area:2479}",
		["The {area:3098}"] = "{area:3098}",
		["To {area:392}"] = "Para {area:392}",
		["Tram to {zone:1455}"] = "Metrô para {zone:1455}",
		["Twilight Tablet Fragments"] = "Fragmentos de Tabuleta do Crepúsculo",
		["Twilight's Hammer cultists"] = "Sectários do Martelo do Crepúsculo",
		["Underwater"] = "Debaixo d'água",
		["Upstairs"] = "No andar de cima",
		["Use the jars on slain oozes"] = "Use as jarras nas gosmas mortas",
		["Wait a moment for {npc:9116}"] = "Espere um pouco por {npc:9116}",
		["grind on {npc:14564} at {area:2627}, {zone:1423}"] = "farme {npc:14564} em {area:2627}, {zone:1423}",
		["{area:150} flight master"] = "Mestre de voo de {area:150}",
		["{area:1770} braziers"] = "Braseiros de {area:1770}",
		["{area:1770} is the cave at the back of {area:1763}, west of the road. Use the {item:12906} on the four braziers inside. Kill the Angerclaw bears and Felpaw wolves you pass for the {item:11172}.\nCareful: Shadow Council mobs of level 53-55 fill the cave and often come in large linked groups, many with stuns. A group of 2-3 players is recommended.\nThe Jaedenar Darkweavers, Warlocks and Enforcers in here drop a {item:13140}, about one kill in thirty: keep killing them until it drops. It opens the cell of {npc:11018}, the night elf held in the cave."] = "{area:1770} é a caverna no fundo de {area:1763}, a oeste da estrada. Use {item:12906} nos quatro braseiros lá dentro. Mate os ursos Garraivosos e os lobos Patavil que encontrar pelo caminho para pegar {item:11172}.\nCuidado: monstros do Conselho das Sombras de nível 53-55 enchem a caverna e costumam vir em grandes grupos ligados, muitos com atordoamentos. Recomenda-se um grupo de 2-3 jogadores.\nOs Tecetrevas, Bruxos e Impositores de Jaedenar daqui soltam {item:13140}, cerca de uma morte em trinta: continue matando-os até soltar. Ela abre a cela de {npc:11018}, o elfo da noite preso na caverna.",
		["{area:2057} (optional)"] = "{area:2057} (opcional)",
		["{area:2057} fits levels 58 to 60; {quest:5505} is handed in at {area:3197} below."] = "{area:2057} é para os níveis 58 a 60; {quest:5505} é entregue em {area:3197}, abaixo.",
		["{area:2577} (optional)"] = "{area:2577} (opcional)",
		["{area:2577} fits levels 55 to 60; alone, the {area:2627} grind at the end of this guide gets you to 60."] = "{area:2577} serve para os níveis 55 a 60; sozinho, matar monstros em {area:2627} no fim deste guia leva você ao nível 60.",
		["{area:2742}: kill these as you meet them"] = "{area:2742}: vá matando estes pelo caminho",
		["{area:3137} flight master"] = "Mestre de voo de {area:3137}",
		["{area:392} flight master"] = "Mestre de voo de {area:392}",
		["{area:541} flight master"] = "Mestre de voo de {area:541}",
		["{area:702} flight master"] = "Mestre de voo de {area:702}",
		["{item:14047}, from your bags"] = "{item:14047}, das suas bolsas",
		["{item:2592}, from your bags"] = "{item:2592}, das suas bolsas",
		["{item:4306}, from your bags"] = "{item:4306}, das suas bolsas",
		["{item:4338}, from your bags"] = "{item:4338}, das suas bolsas",
		["{npc:10300} waits at {area:2250}, south of {area:2255}.\nProtect {npc:10300} while she lights the torches on the way to the {object:177404}."] = "{npc:10300} espera em {area:2250}, ao sul de {area:2255}.\nProteja {npc:10300} enquanto ela acende as tochas no caminho até {object:177404}.",
		["{npc:10301}'s camp"] = "Acampamento de {npc:10301}",
		["{npc:10301}'s supplies"] = "Suprimentos de {npc:10301}",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal, the ruined city north of the camp. {npc:1852} guards his phylactery in the middle of the town."] = "{npc:10667} espera na estalagem em ruínas no lado oeste das Ruínas de Andorhal, a cidade em ruínas ao norte do acampamento. {npc:1852} protege o filactério dele no meio da cidade.",
		["{npc:10667}, upstairs"] = "{npc:10667}, no andar de cima",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of Andorhal. The Jabbering Ghouls in the field carry the other half of the charm: combine the two halves."] = "O fantasma de {npc:10778} vagueia perto da casa da fazenda de {area:199}, a oeste das Ruínas de Andorhal. Os Carniçais Grasnantes do campo carregam a outra metade do amuleto: junte as duas metades.",
		["{npc:11016}, in her cell; below ground"] = "{npc:11016}, na cela dela; no subterrâneo",
		["{npc:11020}, below ground"] = "{npc:11020}, no subterrâneo",
		["{npc:11557}, just inside the cave beside {npc:11558}, takes thirty {quest:6031} from Friendly with the Timbermaw: the {zone:1452} top-up on the Winterfall furbolgs gets you both."] = "{npc:11557}, logo dentro da caverna, ao lado de {npc:11558}, recebe trinta {quest:6031} a partir de Amigável com os Presamatos: a rodada para completar o nível em {zone:1452}, nos furbolgs Invernosos, rende as duas coisas.",
		["{npc:11557}; below ground"] = "{npc:11557}; no subterrâneo",
		["{npc:11558} stands just inside the {area:1769} cave: she speaks to you from Neutral with the Timbermaw, which the Winterfall furbolgs you ground in {zone:1452} brought you to."] = "{npc:11558} fica logo dentro da caverna de {area:1769}: ela fala com você a partir de Neutro com os Presamatos, nível que os furbolgs Invernosos que você matou em {zone:1452} deram a você.",
		["{npc:11558}, just inside the cave: walks around here: look inside the circle on the map"] = "{npc:11558}, logo dentro da caverna: anda por aqui: procure dentro do círculo no mapa",
		["{npc:11558}: walks around here: look inside the circle on the map"] = "{npc:11558}: anda por aqui: procure dentro do círculo no mapa",
		["{npc:11801}'s house stands in {area:2361}, east of {npc:11939}."] = "A casa de {npc:11801} fica em {area:2361}, a leste de {npc:11939}.",
		["{npc:11803} holds the cultists' camp in the far south-west."] = "{npc:11803} comanda o acampamento dos sectários no extremo sudoeste.",
		["{npc:11939} walks around {area:2361}: look inside the circle on the map"] = "{npc:11939} anda por {area:2361}: procure dentro do círculo no mapa",
		["{npc:14722} takes sixty Silk, sixty Mageweave and sixty {item:14047}: hand in what you carry (or buy at the Auction House), skip the rest."] = "{npc:14722} recebe sessenta Sedas, sessenta Magitramas e sessenta {item:14047}: entregue o que estiver carregando (ou compre na Casa de Leilões) e pule o resto.",
		["{npc:14722}, in the {object:2096}"] = "{npc:14722}, em {object:2096}",
		["{npc:15189} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15189} fica no andar de cima do prédio dele: suba por dentro, a seta não diferencia os andares.",
		["{npc:15190} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:15190} fica no andar de cima do prédio dele: suba por dentro, a seta não diferencia os andares.",
		["{npc:15190}, upstairs beside {npc:15189}"] = "{npc:15190}, no andar de cima, ao lado de {npc:15189}",
		["{npc:17080} camps outside {area:2743}, the western hive. Pick up a Silithyst at one of the red geysers nearby and carry it to the Alliance extractor at his camp.\nCareful: You lose the Silithyst if you mount, stealth, use {spell:642}, {spell:5384} or Vanish. Blink and {spell:17} do not drop it."] = "{npc:17080} acampa do lado de fora de {area:2743}, a colmeia do oeste. Pegue um Silitista num dos gêiseres vermelhos ali perto e leve até o extrator da Aliança no acampamento dele.\nCuidado: você perde o Silitista se montar, ficar furtivo, usar {spell:642}, {spell:5384} ou Sumir. Lampejo e {spell:17} não derrubam.",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} é um elite de nível 61",
		["{npc:1855} (optional)"] = "{npc:1855} (opcional)",
		["{npc:1855} lives in a small hut on the border river, north-east of the lumber camp. Hand in {quest:5781} if you finished it."] = "{npc:1855} Fordring vive numa pequena cabana à beira do rio da fronteira, a nordeste da madeireira. Entregue {quest:5781} se você a concluiu.",
		["{npc:3516}, atop the {area:1658}"] = "{npc:3516}, no alto de {area:1658}",
		["{npc:4155}, in the bank"] = "{npc:4155}, no banco",
		["{npc:5594}, inside"] = "{npc:5594}, lá dentro",
		["{npc:7740} in {zone:1457}: keep it"] = "{npc:7740} em {zone:1457}: guarde-a",
		["{npc:7740}, in the Temple of the Moon"] = "{npc:7740}, no Templo da Lua",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}, no fundo do refúgio",
		["{npc:9116}, inside"] = "{npc:9116}, lá dentro",
		["{npc:9117}, below ground"] = "{npc:9117}, no subterrâneo",
		["{npc:9517}; below ground"] = "{npc:9517}; no subterrâneo",
		["{npc:9518}, below ground"] = "{npc:9518}, no subterrâneo",
		["{npc:9598} waits in {area:1767}. Escort her out of the woods and keep her alive.\nCareful: Three {quest:5086} ambush you soon after the escort starts."] = "{npc:9598} espera em {area:1767}. Escolte-a para fora da mata e mantenha-a viva.\nCuidado: três {quest:5086} emboscam vocês logo depois que a escolta começa.",
		["{npc:9860}, below ground"] = "{npc:9860}, no subterrâneo",
		["{npc:9861}, below ground"] = "{npc:9861}, no subterrâneo",
		["{object:176158}, below ground"] = "{object:176158}, no subterrâneo",
		["{object:176159}, below ground"] = "{object:176159}, no subterrâneo",
		["{object:176160}, below ground"] = "{object:176160}, no subterrâneo",
		["{object:176161}, below ground"] = "{object:176161}, no subterrâneo",
		["{object:179565}; inside"] = "{object:179565}; lá dentro",
		["{quest:5085}: {npc:9298} in {zone:1452}, keep it"] = "{quest:5085}: {npc:9298} em {zone:1452}, guarde-a",
		["{quest:6184}: the agents' remains lie at the {area:2260} in the {zone:1423}"] = "{quest:6184}: os restos dos agentes ficam em {area:2260}, em {zone:1423}",
		["{zone:1451}, {zone:1448}, {zone:1452} & the Plaguelands"] = "{zone:1451}, {zone:1448}, {zone:1452} e as Terras Pestilentas",
		["{zone:1452}: kill these as you meet them"] = "{zone:1452}: vá matando estes pelo caminho",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} não tem instrutor de xamã",
		["{zone:1455} flight master"] = "Mestre de voo de {zone:1455}",
} end)()
t.guides["forever/alliance/dwarf/01-dun-morogh"] = (function() return {
		["Back east through {area:131}: the class quests here wait for level 10."] = "De volta para leste por {area:131}: as missões de classe daqui ficam para o nível 10.",
		["Back through the tunnel to {npc:257597}' cave above the farm."] = "Volte pelo túnel até a caverna de {npc:257597} acima da fazenda.",
		["Back to the tunnel post"] = "De volta ao posto do túnel",
		["Back to the {area:925}"] = "De volta a {area:925}",
		["Back to {area:77}"] = "De volta a {area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "De volta a {npc:257446} em {area:77}. Ele lhe dá a {item:6635}: pegue a trilha marcada por escombros que sobe para oeste a partir do sul do vale até a Pedra Espiritual na crista, beba a Sapta ao lado dela e fale com a {npc:5891}, depois leve o {item:6656} dela de volta a Teo.",
		["Back to {npc:257597}"] = "De volta a {npc:257597}",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {area:87} and east Elwynn are next, then {zone:1436}."] = "De volta a {npc:6122}. Use {item:6928} no círculo de evocação no porão de {object:2164} e derrote o emissário do caos que ele invocar. {area:87} e o leste de Elwynn vêm em seguida, depois {zone:1436}.",
		["Below ground"] = "No subterrâneo",
		["Crag Boars and Young Black Bears roam the fields from Rumbleshot's camp north-east to {area:131} and the depot: kill them on the walk back."] = "Rochetuscos e Ursos Pretos Jovens vagam pelos campos do acampamento de Rumbleshot, a nordeste, até {area:131} e o depósito: mate-os na caminhada de volta.",
		["Druid trainer"] = "Instrutor de druida",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "Cada missão de Grif Selvacuore lhe dá um {item:15908}: use-o na fera que ele indicar e depois leve o bastão de volta a ele na ferraria de {area:131}. Rochetuscos Grandes, Leopardos da Neve e Ursos Garra de Gelo vagam pelos campos logo ao sul e a leste de {area:131}.",
		["East along the hills to the mine at the north end of the loch: the Miners' League crates sit in its tunnels, among more Tunnel Rats."] = "Para o leste, pelas colinas, até a mina na ponta norte do lago: os caixotes da Liga dos Mineradores ficam nos túneis dela, entre mais Ratatúneis.",
		["East back into {object:171524}: the {area:2257} leaves from its east end. Ride it to {zone:1453}."] = "De volta a leste até {object:171524}: o {area:2257} parte do extremo leste dela. Pegue-o até {zone:1453}.",
		["East from the {object:32372} into {object:171524}: the {object:660964} lie by its mailbox. From here the guide goes once round the city: north to the {object:32383}, west to the {object:32362}, south through the Commons to the {object:171709}, east through the {object:32359} and back to {object:171524} for the tram."] = "A leste da {object:32372}, até {object:171524}: {object:660964} ficam junto à caixa de correio de lá. A partir daqui, o guia dá uma volta pela cidade: ao norte até {object:32383}, a oeste até {object:32362}, ao sul pelo Commons até {object:171709}, a leste por {object:32359} e de volta a {object:171524} para pegar o metrô.",
		["East through the South Gate tunnel into {zone:1432}. {npc:1089} and {npc:1092} stand at the dwarven post just past it."] = "Para leste, pelo túnel do Portão Sul, até {zone:1432}. {npc:1089} e {npc:1092} ficam no posto dos anões, logo depois dele.",
		["East to the {object:32359}: the warrior trainers and {npc:11865} in the {object:32390}, the hunter trainers beside it."] = "A leste, até {object:32359}: os instrutores de guerreiro e {npc:11865} em {object:32390}, os instrutores de caçador ao lado.",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Farsen acampa na crista que dá vista para a {area:134}, a oeste. Fale com ele para usar a vidência dele.",
		["Feather Charms, from the Frostmane Novices"] = "Patuás de Penas, dos Noviços Jubafria",
		["Firewood"] = "Lenha",
		["Flintfire's shipments lie on the cave floor, and {npc:278166} is missing somewhere inside.\nCareful: Wendigos stand close together inside the cave, so fights easily pull several at once; drawing them out one at a time with ranged attacks from outside avoids this."] = "Os carregamentos do Pederfogo estão no chão da caverna, e {npc:278166} sumiu em algum lugar lá dentro.\nCuidado: os wendigos ficam bem juntos dentro da caverna, então é fácil puxar vários de uma vez; atraia um de cada vez com ataques à distância lá de fora.",
		["Follow the road all the way east to the {area:806} at the {zone:1432} tunnel."] = "Siga a estrada até o fim, para leste, até {area:806}, no túnel de {zone:1432}.",
		["Follow the road east past the depot to {area:138}."] = "Siga a estrada para leste passando a garagem até o {area:138}.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "Siga a estrada para nordeste a partir de {area:131} até a garagem abaixo da estrada de {zone:1455}.",
		["Follow the road north-east from {area:131} to the depot: the whole east of {zone:1426} is one sweep from here."] = "Siga a estrada para nordeste de {area:131} até o depósito: daqui dá para varrer todo o leste de {zone:1426} de uma vez.",
		["Follow the road through the tunnel and north-east to {area:131}. Start outside: {npc:1252} and Eric's campfire are in front of the {area:2102}."] = "Siga a estrada pelo túnel e para nordeste até {area:131}. Comece do lado de fora: {npc:1252} e a fogueira do Ériic ficam em frente a {area:2102}.",
		["From the {object:28027} south-west to {object:2098}: {npc:1646}'s compass is in his old house in {zone:1436}, on the way. The flight master and the {object:2096} are south of the square."] = "Do {object:28027} para sudoeste até a {object:2098}: a bússola de {npc:1646} está na antiga casa dele em {zone:1436}, no caminho. O mestre de voo e o {object:2096} ficam ao sul da praça.",
		["From the {quest:2997} she gives you"] = "Do {quest:2997} que ela lhe dá",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Jovens Trolls Jubafria enchem as encostas ao sul e a leste do acampamento de {npc:786}.",
		["Go through the tunnel into {zone:1432}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "Atravesse o túnel até {zone:1432}. Logo depois, uma trilha marcada por pedras sobe as colinas à direita da estrada, para o norte, até o acampamento de {npc:257808}.",
		["Gretchen camps just outside the {area:136}, the wendigo cave south-west of {area:131}."] = "A Gretchen acampa logo do lado de fora de {area:136}, a caverna dos wendigos a sudoeste de {area:131}.",
		["Head back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "Saia de {zone:1455} e siga a estrada para leste até {area:212}. {npc:6177} está morto na margem: use o {item:6866} nele. Os Espiões Ferro Negro que se esgueiram pelo lago carregam a carta.",
		["Heal and fortify {npc:12427}"] = "Cure e fortaleça {npc:12427}",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Pingentes de Urso Garrálgido, dos Jovens Trolls Jubafria nas encostas acima do acampamento",
		["Inside {area:77}"] = "Dentro de {area:77}",
		["Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. Back in the distillery: {npc:1699} teaches {skill:185}, then the ribs go to {npc:1267}."] = "Mate os Rochetuscos no caminho: as costelas caem antes de você ter a missão de {npc:1267} e contam para ela. De volta à cervejaria: {npc:1699} ensina {skill:185}, depois as costelas vão para {npc:1267}.",
		["Last: some classes' trainers stand outside"] = "Por último: os instrutores de algumas classes ficam do lado de fora",
		["Leave {zone:1453} by the main gate and follow the road south to {area:87}: east Elwynn comes before {zone:1436}."] = "Saia de {zone:1453} pelo portão principal e siga a estrada para o sul até {area:87}: o leste de Elwynn vem antes de {zone:1436}.",
		["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Saia de {zone:1453} pelo portão principal, vá para o sul até {area:87} e para leste pela estrada até a {area:62}. {npc:881} (nível 9) fica junto à casa da fazenda.",
		["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "Gnomos Leprosos em volta da Aldeia da Cevada e da estrada de {area:133} levam as rodas dentadas e engrenagens. Ursos Garra de Gelo, Rochetuscos Anciões e Leopardos da Neve vagam pelas colinas em volta do lago.",
		["Level 4 spells, before Gozwin's camp"] = "Feitiços de nível 4, antes do acampamento de Gozwin",
		["North of the post, west of the road: the Stonesplinter troggs and scouts camp in the hills. Both drop the Trogg Stone Teeth."] = "Ao norte do posto, a oeste da estrada: os troggs e batedores Lascapedra acampam nas colinas. Ambos soltam os Dentes de Pedra de Trogg.",
		["North of the {object:32372}: {npc:258098}, the shaman trainer, stands at the south end of the {object:32383}, the rogue and warlock trainers and {npc:6120} just north of him."] = "Ao norte da {object:32372}: {npc:258098}, o instrutor de xamã, fica no extremo sul de {object:32383}, os instrutores de ladino e de bruxo e {npc:6120} logo ao norte dele.",
		["North through the hills west of the road to {npc:1343} at the {area:925}. The Tunnel Rat kobolds dig in the hills on the way; Elder Black Bears, Mountain Boars and Forest Lurkers roam the same ground."] = "Ao norte pelas colinas a oeste da estrada até {npc:1343}, em {area:925}. Os kobolds Ratatúnel cavam nas colinas no caminho; Ursos Pretos Anciões, Javalis Montanheses e Tocaieiras da Floresta vagam pelo mesmo terreno.",
		["North up the road to {area:144}. {npc:1340} walks the road through town, {npc:1963} stands outside the {area:2101}, {npc:1681} on the east side of town; {npc:1572} keeps the gryphons."] = "Ao norte pela estrada até {area:144}. {npc:1340} anda pela estrada que atravessa a cidade, {npc:1963} fica na frente de {area:2101}, {npc:1681} no lado leste da cidade; {npc:1572} cuida dos grifos.",
		["On the road back west to {zone:1455}."] = "Na estrada de volta para oeste, rumo a {zone:1455}.",
		["On the {zone:1455} platform of the {area:2257}, {npc:12997} asks for help with the rats: use his {item:17117} on the Deeprun Rats around the platform, hand them in, then take his letter to his brother {npc:13018} at the {zone:1453} end."] = "Na plataforma de {zone:1455} do {area:2257}, {npc:12997} pede ajuda com os ratos: use o {item:17117} dele nos Ratos Correfundo em volta da plataforma, entregue-os e depois leve a carta dele ao irmão dele, {npc:13018}, no extremo de {zone:1453}.",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "Lobos Jovens Rotos vagam pela neve logo ao sul de {area:77}.",
		["Ride the tram to {zone:1453}: {npc:13018} waits on the {zone:1453} platform. {npc:5413} stands in the {object:28027}, just outside the tram."] = "Pegue o metrô até {zone:1453}: {npc:13018} espera na plataforma de {zone:1453}. {npc:5413} fica no {object:28027}, logo fora do metrô.",
		["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}. Dark Iron Spies sneak around the lake shore east of the quarry; one of them drops the {item:274268}."] = "Emboscadores Pedraqueixo perto de {area:212}, ao norte da pedreira, e Quebradorsos Pedraqueixo mais a leste soltam {quest:95214}. Espiões Ferro Negro rondam a margem do lago a leste da pedreira; um deles solta {item:274268}.",
		["Rockjaw Skullthumpers, Bonesnappers and Ambushers share the quarry and the slopes north of it; the Ambushers drop the {item:268548}."] = "Batecrânios Pedraqueixo, Quebraossos e Emboscadores dividem a pedreira e as encostas ao norte dela; os Emboscadores soltam o {item:268548}.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "Troggs Pedraqueixo e Troggs Pedraqueixo Parrudos cavam por todo o fundo do vale ao sul de {area:77}.",
		["Sit by Eric's campfire (type /sit) and wait for the buff. With a profession learned, Eric also offers its Camping 101, which its trainer takes: blacksmithing with {npc:1241} and {skill:129} with {npc:2326} in {area:131}, mining and engineering at {area:189}."] = "Sente na fogueira do Ériic (digite /sit) e espere o bônus. Com uma profissão aprendida, o Eric também oferece a Introdução ao acampamento dela, que o instrutor da profissão recebe: ferraria com {npc:1241} e {skill:129} com {npc:2326} em {area:131}, mineração e engenharia em {area:189}.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Rochetuscos Pequenos pastam em volta do acampamento de {npc:714} e pelo lado oeste do vale.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Leopardos da Neve e javalis vagam pela neve entre o rancho e a pedreira. Ferreiros: Barras de Cobre vêm da fundição de {item:2770} ou dos mercadores de profissão.",
		["South down the road to {area:144}, finishing the ears, meat and ichor on the way. {npc:1340} walks the road through town."] = "Ao sul pela estrada até {area:144}, terminando as orelhas, a carne e o icor no caminho. {npc:1340} anda pela estrada que atravessa a cidade.",
		["South through the Commons: {npc:1274} stands in the {object:171709} with King Magni."] = "Para o sul pela área comum: {npc:1274} fica em {object:171709}, com o Rei Magni.",
		["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "Videntes Lascapedra (nível 13) ficam entre os troggs no sul do {area:923}, ao sul de {npc:257808}; Geomantes Ratatúnel (nível 12) trabalham na {area:149}, no extremo norte do lago. Os troggs vêm em bandos e alguns atacam à distância: atraia um de cada vez.",
		["Stonesplinter troggs"] = "Troggs Lascapedra",
		["Subdue the voidwalker"] = "Subjugue o emissário do caos",
		["The Fire Spirit Stone"] = "A Pedra do Espírito de Fogo",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "O Rabo-de-galo Escaldante dura cinco minutos: vá direto para o norte até {npc:836} dentro de {area:77}.",
		["The boars"] = "Os javalis",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "A lenha está na neve em volta do lago congelado junto ao refúgio.",
		["The gryphons land in the {object:32372}: {npc:4256} works at its north end, and {npc:1573} keeps the gryphons where you landed."] = "Os grifos pousam na {object:32372}: {npc:4256} trabalha no extremo norte dela, e {npc:1573} cuida dos grifos onde você pousou.",
		["The paladin, priest and mage trainers are in the {object:32386}, in the {object:32362}."] = "Os instrutores de paladino, sacerdote e mago estão em {object:32386}, em {object:32362}.",
		["The pilots stand at the depot; {npc:1269} is on the road back west, north of {area:131}."] = "Os pilotos ficam no depósito; {npc:1269} está na estrada de volta a oeste, ao norte de {area:131}.",
		["The quarry lies just east of Farsen's ridge."] = "A pedreira fica logo a leste da crista do Farsen.",
		["The quarry troggs"] = "Os troggs da pedreira",
		["The three rifles lie in the snow around the frozen lake by the refuge. Minor Ice Elementals drift around the lake and along the way: kill them as you go for {quest:99160}.\nFinish off the Minor Ice Elementals around the small lake just west of the refuge if you are still short."] = "Os três rifles estão na neve em volta do lago congelado perto do refúgio. Elementais de Gelo Menores vagam pelo lago e pelo caminho: mate-os pelo caminho para {quest:99160}.\nSe ainda faltar, termine os Elementais de Gelo Menores em volta do laguinho logo a oeste do refúgio.",
		["The troggs"] = "Os troggs",
		["The troll cave"] = "A caverna dos trolls",
		["The tunnel"] = "O túnel",
		["The tunnel post"] = "O posto do túnel",
		["The west hills and the {area:925}"] = "As colinas do oeste e {area:925}",
		["The {area:2257}"] = "O {area:2257}",
		["The {item:2676} grows in baskets up on {area:802}, the snowy slope north of the road between {area:131} and Brewnall: climb from the road west of {area:131}. The Frostmane Seers camped on the ridge drop it too."] = "A {item:2676} cresce em cestos lá em cima, em {area:802}, a encosta nevada ao norte da estrada entre {area:131} e Brewnall: suba pela estrada a oeste de {area:131}. Os Videntes Jubafria acampados na crista também deixam cair.",
		["The {object:176785} sits next to {npc:271546}, south of the {area:136}."] = "A {object:176785} fica ao lado de {npc:271546}, ao sul de {area:136}.",
		["The {object:269} in the basement"] = "O {object:269} no porão",
		["The {object:270} in the distillery; below ground"] = "O {object:270} na cervejaria; no subterrâneo",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:1388} is a level 12 elite: most classes solo it at level 14, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:1388} é elite de nível 12: a maioria das classes encara sozinha no nível 14, mas talvez você precise de ajuda. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["Tram to {zone:1453}"] = "Metrô para {zone:1453}",
		["Upstairs"] = "No andar de cima",
		["Use the {item:6866} on {npc:6177}"] = "Use o {item:6866} em {npc:6177}",
		["West from the {object:32383} into the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}, {npc:6179} and {npc:6178} on its upper floor: the stairs up start just north-east of {npc:5149}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {zone:1426} drop it, and the Auction House sells it."] = "A oeste de {object:32383}, até {object:32362}: {npc:5149}, {npc:6179} e {npc:6178} estão em {object:32386}, {npc:6179} e {npc:6178} no andar de cima: a escada começa logo a nordeste de {npc:5149}. {npc:6175}, um mendigo, vaga pela cidade. Ele pede dez {item:2589}: os troggs e trolls de {zone:1426} soltam, e a Casa de Leilões vende.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Já que está aqui: aprenda Cajados com {npc:11867} ({object:2096}, 10 pratas); a arma corpo a corpo do Caçador vale pelos atributos, e as de duas mãos são as que mais trazem.",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Já que está aqui: aprenda Cajados com {npc:11867} ({object:2096}, 10 pratas); enquanto você sobe de nível, um cajado traz mais atributos de feitiço que uma arma de uma mão.",
		["While you're here: learn Swords from {npc:11867} ({object:2096}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Já que está aqui: aprenda Espadas com {npc:11867} ({object:2096}, 10 pratas); espada na mão principal faz o Ladino subir de nível sem tropeço.",
		["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Paladin fastest."] = "Já que está aqui: aprenda {spell:197} com {npc:11865} ({object:32359}, 10 pratas); arma de duas mãos é o jeito mais rápido de upar Paladino.",
		["While you're here: learn {spell:197} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Já que está aqui: aprenda {spell:197} com {npc:11865} ({object:32359}, 10 pratas); arma de duas mãos é o jeito mais rápido de upar Guerreiro.",
		["While you're here: learn {spell:199} from {npc:11865} ({object:32359}, 10 silver); two-handers level a Warrior fastest."] = "Já que está aqui: aprenda {spell:199} com {npc:11865} ({object:32359}, 10 pratas); arma de duas mãos é o jeito mais rápido de upar Guerreiro.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Paladin fastest."] = "Já que está aqui: aprenda {spell:202} com {npc:11867} ({object:2096}, 10 pratas); arma de duas mãos é o jeito mais rápido de upar Paladino.",
		["While you're here: learn {spell:202} from {npc:11867} ({object:2096}, 10 silver); two-handers level a Warrior fastest."] = "Já que está aqui: aprenda {spell:202} com {npc:11867} ({object:2096}, 10 pratas); arma de duas mãos é o jeito mais rápido de upar Guerreiro.",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Você começa diante de {area:77}, o salão de pedra no extremo norte do vale. {npc:658} espera do lado de fora da porta.",
		["Young wolves"] = "Lobos jovens",
		["talk to the trainer"] = "fale com o instrutor",
		["{area:131} and the depot"] = "{area:131} e a garagem",
		["{area:132}: kill these as you meet them"] = "{area:132}: vá matando estes pelo caminho",
		["{area:133}: kill these as you meet them"] = "{area:133}: vá matando estes pelo caminho",
		["{area:135} is the troll cave in the hills south-west of {area:137}. Ice Claw Bears, Elder Crag Boars and Snow Leopards you kill on the way count for {npc:1374}. Kill Headhunters at its mouth and walk through to its far end."] = "{area:135} é a caverna dos trolls nas colinas a sudoeste de {area:137}. Os Ursos Garra de Gelo, Rochetuscos Anciãos e Leopardos da Neve que você matar no caminho contam para {npc:1374}. Mate os Caçadores de Cabeças da entrada e atravesse até o fundo.",
		["{area:137} sits on the lake west of {area:131}. {npc:8508}'s dock is the first stop; {npc:1374} and {npc:1375} are in the village beyond it."] = "{area:137} fica no lago a oeste de {area:131}. O cais de {npc:8508} é a primeira parada; {npc:1374} e {npc:1375} ficam na vila logo depois.",
		["{area:138}: kill these as you meet them"] = "{area:138}: vá matando estes pelo caminho",
		["{area:77} is on the way north from {npc:786}'s camp to the tunnel: {npc:837}, the priest trainer inside, sends priests of level 5 to {npc:1226} in {area:131}."] = "{area:77} fica no caminho para o norte, do acampamento de {npc:786} até o túnel: {npc:837}, o instrutor de sacerdote lá dentro, envia sacerdotes de nível 5 a {npc:1226} em {area:131}.",
		["{item:13850}: the {object:176785}"] = "{item:13850}: {object:176785}",
