		["{npc:1226}: heal {npc:12427} south of {area:131}"] = "{npc:1226}: cure {npc:12427} ao sul de {area:131}",
		["{npc:1226}: {npc:258785} in {zone:1455} takes it"] = "{npc:1226}: {npc:258785} em {zone:1455} a recebe",
