t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "\"Titia\" Berenice Campedra",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "De volta a {npc:6122}. Use o {item:6928} no círculo de evocação no porão de {object:2164} e derrote o emissário do caos que ele invocar.",
		["Back to {zone:1429}"] = "De volta a {zone:1429}",
		["Billy plays in the {area:64}, east of the mine."] = "Guinho brinca em {area:64}, a leste da mina.",
		["Chunks of Boar Meat"] = "Nacos de Carne de Javali",
		["Class trainer"] = "Instrutor de classe",
		["Crystal Kelp Fronds"] = "Folhas de Cristalga",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "Teurgos Proscritos Défias acampam nas margens de {area:86}; eles também soltam as Bandanas de Linho Vermelhas. {object:56} está na aldeia murloc da margem nordeste.",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "Capangas Défias acampam na clareira a leste da Abadia e ao longo do lado leste do vale.",
		["Druid trainer"] = "Instrutor de druida",
		["Follow the hills south to the tower, on the road west."] = "Siga pelas colinas para o sul até a torre, na estrada para o oeste.",
		["Follow the hills south to the tower."] = "Siga pelas colinas para o sul até a torre.",
		["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}."] = "Siga a trilha para o norte até a mina. Trabalhadores Kobold enxameiam do lado de fora; qualquer kobold do vale pode soltar {object:83763}.",
		["Follow the road east past the {area:91} to the bridge. Finish the Prowlers and Young Forest Bears around the river south of it."] = "Siga a estrada para leste, passando por {area:91}, até a ponte. Termine os Predadores e Jovens Ursos da Floresta em volta do rio, ao sul dela.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Siga a estrada para o norte, de {area:87} até {zone:1453}. {npc:5497} fica no Sacrário dos Teurgos, a torre de {object:2101}; ela lhe dá um frasco para a cachoeira de {quest:1861}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Siga a estrada para o norte, de {area:87} até {zone:1453}. {npc:6122} espera no porão de {object:2164}, em {object:2101}.",
		["Follow the road south out of the valley to {area:87}. {npc:240} stands outside the smithy on the west side of the road, {npc:241} by the road south of it, and {npc:295} and {npc:253} in the Lion's Pride Inn across the road."] = "Siga a estrada para o sul, saindo do vale, até {area:87}. {npc:240} fica na frente da ferraria, no lado oeste da estrada, {npc:241} junto à estrada ao sul dela, e {npc:295} e {npc:253} na Estalagem Orgulho do Leão, do outro lado da estrada.",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Siga a estrada para o sul, saindo de {area:87}, até {area:64}. {npc:251} espera junto à casa.",
		["Follow the road south to the {area:120}, on the way into {zone:1436}. {npc:963} stands outside the barracks; {npc:955} stands inside. He has {quest:91738} only while you carry the {item:247824}: talk to him and it goes straight to the hand-in."] = "Siga a estrada para o sul até {area:120}, no caminho para {zone:1436}. {npc:963} fica na frente do quartel; {npc:955} fica lá dentro. Ele só tem {quest:91738} enquanto você carrega {item:247824}: fale com ele e vai direto para a entrega.",
		["Follow the road west back to {area:87}; {npc:6306} stands on the lake shore before town. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "Siga a estrada de volta para oeste até {area:87}; {npc:6306} fica na margem do lago, antes da cidade. {npc:377} (sacerdotes), {npc:328} (magos) e {npc:917} (ladinos) ficam no andar de cima da estalagem: suba as escadas por dentro, a seta não diferencia os andares.",
		["Fun with Elementals: {npc:248464}"] = "Diversão com Elementais: {npc:248464}",
		["He stands by the river west of the farm."] = "Ele fica junto ao rio, a oeste da fazenda.",
		["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Volte por {area:87} e siga para leste pela estrada até {area:62}. {npc:881} (nível 9) fica perto da casa da fazenda.",
		["Head east out of {area:87} along the lake shore. {npc:383} stands on the shore north-east of town."] = "Saia de {area:87} para leste, pela margem do lago. {npc:383} fica na margem a nordeste da cidade.",
		["Heal and fortify {npc:12423}"] = "Cure e fortifique {npc:12423}",
		["If you skipped {quest:91740}, grind here to level 8.85 to stay on the route's plan."] = "Se você pulou {quest:91740}, mate monstros aqui até o nível 8.85 para seguir o plano da rota.",
		["If you skipped {quest:91752}, grind here to level 5.48 to stay on the route's plan."] = "Se você pulou {quest:91752}, mate monstros aqui até o nível 5.48 para seguir o plano da rota.",
		["If you skipped {quest:91752}, grind here to level 5.77 to stay on the route's plan."] = "Se você pulou {quest:91752}, mate monstros aqui até o nível 5.77 para seguir o plano da rota.",
		["If you skipped {quest:91775}, grind here to level 8.39 to stay on the route's plan."] = "Se você pulou {quest:91775}, mate monstros aqui até o nível 8.39 para seguir o plano da rota.",
		["Inside"] = "Lá dentro",
		["Inside {area:34}"] = "Dentro de {area:34}",
		["It lies by the river north-west of the logging camp."] = "Fica junto ao rio, a noroeste do acampamento madeireiro.",
		["Kobold Laborers work the tunnels inside the mine. {npc:248362} waits down the second turn on the right."] = "Operários Kobold trabalham nos túneis dentro da mina. {npc:248362} espera depois da segunda curva à direita.",
		["Large Candles"] = "Velas Grandes",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Saia de {zone:1453} pelo portão principal. A cachoeira de {quest:1861} fica a sudoeste dos portões, no caminho para o oeste rumo a {zone:1436}: encha {item:7207} na base dela.",
		["Level 5.48"] = "Nível 5.48",
		["Level 5.77"] = "Nível 5.77",
		["Level 8.39"] = "Nível 8.39",
		["Level 8.85"] = "Nível 8.85",
		["Lost Books: Kobold Miners and Tunnelers"] = "Livros Perdidos: Mineradores e Tuneleiros Kobold",
		["Mages: {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "Magos: {npc:198}, o instrutor de mago, fica no andar de cima da Abadia: suba a escada por dentro, a seta não diferencia os andares.",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp. Careful: the murlocs stand close together, so a fight easily pulls two or three at once: pull them one at a time from the edge of the camp, and don't chase one into the next group."] = "Murlocs e Murlocs Corredores ocupam a margem leste; as Pilhas de Sucata ficam no acampamento deles. Cuidado: os murlocs ficam bem juntos, então uma luta facilmente puxa dois ou três de uma vez: puxe-os um por vez a partir da beirada do acampamento e não persiga nenhum até o grupo seguinte.",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake."] = "A nordeste do acampamento madeireiro. Teurgos Proscritos Défias acampam nas margens do lago.",
		["Painted Gnoll Armbands"] = "Braçadeiras Pintadas dos Gnolls",
		["Red Burlap Bandanas"] = "Bandanas de Lona Vermelhas",
		["Red Linen Bandanas"] = "Bandanas de Linho Vermelhas",
		["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border."] = "Pata Molhada Miúdos e Vanguardeiros ocupam as colinas ao sul da guarnição, ao longo da divisa com {zone:1436}.",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Gnolls Pata Molhada acampam nas colinas a oeste de {area:86}; {quest:91725} estão nos acampamentos deles.",
		["Shaman trainer"] = "Instrutor de xamã",
		["She stands by her cart at the vineyard east of the Abbey."] = "Ela fica junto à carroça, no vinhedo a leste da Abadia.",
		["She stands outside the mine entrance. {npc:248362}, inside, is elite: grouping up is advised."] = "Ela fica do lado de fora da entrada da mina. {npc:248362}, lá dentro, é elite: recomenda-se formar um grupo.",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "Maçãs Vermelhas Brilhantes, de {npc:894}, para {quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "Sente-se (/sit) junto à fogueira dele até ganhar {spell:1229451}",
		["South down the road to the {area:64}."] = "Para o sul pela estrada até {area:64}.",
		["Subdue the voidwalker"] = "Subjugue o emissário do caos",
		["Tame {npc:1922}"] = "Dome {npc:1922}",
		["Tame {npc:524}"] = "Dome {npc:524}",
		["Tame {npc:822}"] = "Dome {npc:822}",
		["The Defias camp"] = "O acampamento Défias",
		["The Fishing Traps sit along the west shore of the lake."] = "As armadilhas ({object:694772}) ficam ao longo da margem oeste do lago.",
		["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house.\nShe sits inside the farmhouse."] = "A fazenda dos Campedra fica a oeste da mina. Mama e \"Titia\" Berenice ficam junto à casa.\nEla fica sentada dentro da casa da fazenda.",
		["The bridge"] = "A ponte",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "O acampamento fica a nordeste da ponte. Feixes de Lenha estão espalhados pelo acampamento e pelo bosque ao norte dele.",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "Os caixotes de uvas estão nos vinhedos, atrás dos Défias. {npc:103} espera junto à cabana no extremo leste do vale.",
		["The gnoll camps"] = "Os acampamentos gnolls",
		["The kobold camp"] = "O acampamento kobold",
		["The lake shore"] = "A margem do lago",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels."] = "A mina fica a sudoeste dos acampamentos gnolls. {item:247816} estão perto da entrada; Geomantes Kobold ocupam os túneis.",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "A mina fica a oeste dos vinhedos. Mineradores e Tuneleiros Kobold enchem os dois níveis; {npc:248464}, um kobold nomeado, guarda o livro ilustrado nos túneis inferiores. {npc:248464} é elite: recomenda-se formar um grupo.",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too."] = "Os murlocs da margem leste soltam a alga. Esfoladores: Lobos Cinza da Floresta vagam pelo bosque entre o lago e {area:91}; Predadores mais a leste também dão peles.",
		["The vineyards and {npc:103}"] = "Os vinhedos e {npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Prowlers and Young Forest Bears on the way. Careful: {npc:248278} is a level 11 elite on the murloc shore. Only go for his head with a group or once you're level 10; otherwise leave him: it's optional."] = "A {item:247813}, o Machado e a Caixa de Ferramentas estão no rio ao sul da ponte. {npc:330}, uma javalina graúda, fuça em {area:62}, a oeste do rio, com o {npc:390} dela: puxe os leitõezinhos para longe primeiro. Mate Predadores e Jovens Ursos da Floresta no caminho. Cuidado: {npc:248278} é elite de nível 11 na margem dos murlocs. Só vá atrás da cabeça dele em grupo ou depois do nível 10; senão deixe para lá: é opcional.",
		["The {quest:91736}"] = "{quest:91736}",
		["The {quest:91736} stands north of the {area:120}. Click it with four Shiny Red Apples in your bags: it takes them and gives you a {item:247824} on the spot (the quest never shows in your quest log). Keep the Applejack for {npc:955}: don't drink it."] = "O {quest:91736} fica ao norte de {area:120}. Clique nele com quatro Maçãs Vermelhas Brilhantes nas bolsas: ele pega as maçãs e entrega um {item:247824} na hora (a missão nunca aparece no Registro de Missões). Guarde o conhaque para {npc:955}: não beba.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248362} (level 3 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:248362} (elite nível 3) pede um grupo de 2. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:248464} (level 6 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:248464} (elite nível 6) pede um grupo de 2. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["Walk into the mine"] = "Entre na mina",
		["Walk through the mine"] = "Atravesse a mina",
		["While you're here: learn Staves from {npc:11867} ({object:2096}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Já que está aqui: aprenda Cajados com {npc:11867} ({object:2096}, 10 pratas); enquanto você sobe de nível, um cajado traz mais atributos de feitiço que uma arma de uma mão.",
		["Wolves"] = "Lobos",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "Você começa em frente à Abadia. {npc:823} fica ao pé da escadaria; {npc:197}, dentro do salão; {npc:951} e {npc:247229}, na biblioteca à direita; {npc:196}, do lado de fora, no canto noroeste.",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "Lobos Jovens e Lobos Silvestres vagam pelos campos bem ao redor da Abadia.",
		["grind on {npc:118}"] = "mate {npc:118} até subir",
		["grind on {npc:40}"] = "mate {npc:40} até subir",
		["grind on {npc:80}"] = "mate {npc:80} até subir",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "o rastreador de kobolds dele mostra os kobolds para clicar na estrada para {area:87}",
		["talk to the trainer"] = "fale com o instrutor",
		["{area:18}: kill these as you meet them"] = "{area:18}: vá matando estes pelo caminho",
		["{area:34}: kill these as you meet them"] = "{area:34}: vá matando estes pelo caminho",
		["{area:54}: kill these as you meet them"] = "{area:54}: vá matando estes pelo caminho",
		["{area:64}: kill these as you meet them"] = "{area:64}: vá matando estes pelo caminho",
		["{item:247824}, from the still"] = "{item:247824}, do alambique",
		["{item:286215}: Stonetusk Boars"] = "{item:286215}: Javalis Pedratusco",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}: {object:83763} no acampamento Défias",
		["{item:981}; below ground"] = "{item:981}; no subterrâneo",
		["{npc:12423} kneels wounded by a tree on the west shore of {area:18}, among the Fishing Traps. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count. He walks off once both land and is back in about 3 minutes."] = "{npc:12423} está ajoelhado e ferido junto a uma árvore na margem oeste de {area:18}, entre as armadilhas de pesca. Lance {spell:613} (Grau 2) nele e depois {spell:1243}: o Grau 1 de {spell:613} não conta. Ele vai embora quando os dois feitiços pegam e volta em cerca de 3 minutos.",
		["{npc:1430} cooks in the inn's kitchen. {npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:1430} cozinha na cozinha da estalagem. {npc:377} (sacerdotes), {npc:328} (magos) e {npc:917} (ladinos) ficam no andar de cima da estalagem: suba a escada por dentro, a seta não diferencia os andares.",
		["{npc:1430}: Camping 101 asks you to learn it; below ground"] = "{npc:1430}: Introdução ao acampamento pede que você aprenda; no subterrâneo",
		["{npc:1632}, beside {npc:6306}"] = "{npc:1632}, ao lado de {npc:6306}",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}: dome-o com o {item:15908}",
		["{npc:197}, inside"] = "{npc:197}, lá dentro",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}, o instrutor de magos, dentro da Abadia",
		["{npc:2329}, in the Lion's Pride Inn"] = "{npc:2329}, na Estalagem Orgulho do Leão",
		["{npc:240}, while William brews"] = "{npc:240}, enquanto o Guilherme prepara a poção",
		["{npc:247229}, in the library; inside"] = "{npc:247229}, na biblioteca; lá dentro",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242} e {npc:248248} ficam ao pé da torre.",
		["{npc:248278} is a level 11 elite on the murloc shore south of the bridge: grouping up is encouraged, look for people to do it with. {quest:91740} needs a group of 2. Skip it if you are alone: the route has you grind the XP back. Right-click the head for its quest."] = "{npc:248278} é um elite de nível 11 na margem dos murlocs ao sul da ponte: recomenda-se formar grupo, procure gente para fazer junto. {quest:91740} exige um grupo de 2. Pule se estiver sozinho: a rota faz você recuperar a experiência matando monstros. Clique com o botão direito na cabeça para pegar a missão.",
		["{npc:248415} stands behind the Abbey, by the stables. {npc:198}, the mage trainer, stands upstairs in the Abbey: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:248415} fica atrás da Abadia, junto aos estábulos. {npc:198}, o instrutor de mago, fica no andar de cima da Abadia: suba a escada por dentro, a seta não diferencia os andares.",
		["{npc:248415}, by the Abbey"] = "{npc:248415}, perto da Abadia",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507} fica com os instrutores de {area:87}. Cada missão dela lhe dá um {item:15908}: use-o na fera que ela indicar e traga o bastão de volta. Javalis Couropedra e Jovens Ursos da Floresta vagam pelas colinas ao sul de {area:64}; Lobos Cinza da Floresta, pelo bosque a leste de {area:18}.",
		["{npc:253}, back in the inn"] = "{npc:253}, de volta à estalagem",
		["{npc:253}, inside"] = "{npc:253}, lá dentro",
		["{npc:257446} in {zone:1426}; {area:87} has no shaman trainer"] = "{npc:257446} em {zone:1426}; {area:87} não tem instrutor de xamã",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, ao lado dela: {spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261} guarda a ponte na estrada para o leste; {npc:248265} fica logo do outro lado.",
		["{npc:263399} camps north-east of the inn. With a profession learned, he also offers its Camping 101, which its trainer takes: skinning, leatherworking and fishing on the lake shore, {skill:129} and blacksmithing in {area:87}."] = "{npc:263399} acampa a nordeste da estalagem. Com uma profissão aprendida, ele também oferece a Introdução ao acampamento dela, que o instrutor da profissão recebe: esfolamento, couraria e pesca na margem do lago; {skill:129} e ferraria em {area:87}.",
		["{npc:263399}: for {npc:1632} on the lake shore"] = "{npc:263399}: para {npc:1632}, na margem do lago",
		["{npc:263399}: for {npc:1651} on the lake shore"] = "{npc:263399}: para {npc:1651}, na margem do lago",
		["{npc:263399}: for {npc:2329} in the Lion's Pride Inn"] = "{npc:263399}: para {npc:2329}, na Estalagem Orgulho do Leão",
		["{npc:263399}: for {npc:514} at the {area:87} smithy"] = "{npc:263399}: para {npc:514}, na ferraria de {area:87}",
		["{npc:263399}: for {npc:6306} on the lake shore"] = "{npc:263399}: para {npc:6306}, na margem do lago",
		["{npc:278}, inside"] = "{npc:278}, lá dentro",
		["{npc:279} in {zone:1453} takes it (02-westfall)"] = "{npc:279} em {zone:1453} recebe (02-westfall)",
		["{npc:295}, inside"] = "{npc:295}, lá dentro",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}: {npc:5497} em {zone:1453} recebe",
		["{npc:375}, the priest trainer"] = "{npc:375}, a instrutora de sacerdotes",
		["{npc:375}, the priest trainer: {npc:377} in {area:87} takes it"] = "{npc:375}, a instrutora de sacerdotes: {npc:377} em {area:87} recebe",
		["{npc:377} (priests), {npc:328} (mages) and {npc:917} (rogues) stand upstairs in the inn: take the stairs inside, the arrow cannot tell the floors apart."] = "{npc:377} (sacerdotes), {npc:328} (magos) e {npc:917} (ladinos) ficam no andar de cima da estalagem: suba a escada por dentro, a seta não diferencia os andares.",
		["{npc:377}, upstairs"] = "{npc:377}, no andar de cima",
		["{npc:377}, upstairs: {item:16605}"] = "{npc:377}, no andar de cima: {item:16605}",
		["{npc:377}: heal {npc:12423} at {area:18}"] = "{npc:377}: cure {npc:12423} em {area:18}",
		["{npc:377}: {npc:376} in {zone:1453} takes it"] = "{npc:377}: quem recebe é {npc:376}, em {zone:1453}",
		["{npc:459}, outside the Abbey"] = "{npc:459}, do lado de fora da Abadia",
		["{npc:476} walks around {area:54}: look inside the circle on the map"] = "{npc:476} anda por {area:54}: procure dentro do círculo no mapa",
		["{npc:514}, at the smithy across the road"] = "{npc:514}, na ferraria do outro lado da estrada",
		["{npc:514}, at the smithy beside Dughan: {npc:1416} in {zone:1453} takes it (02-westfall)"] = "{npc:514}, na ferraria ao lado de Dughan: {npc:1416} em {zone:1453} recebe (02-westfall)",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524}: dome-o com o {item:15908}",
		["{npc:5504} in {zone:1453}; {area:87} has no druid trainer"] = "{npc:5504} em {zone:1453}; {area:87} não tem instrutor de druida",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}: {npc:6122} em {zone:1453} recebe",
		["{npc:6306}, inside"] = "{npc:6306}, lá dentro",
		["{npc:6306}, on the lake shore east of town; inside"] = "{npc:6306}, na margem do lago a leste da cidade; lá dentro",
		["{npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:6306}, {npc:383} e {npc:1651} ficam na margem de {area:18}, a leste da cidade.",
		["{npc:6306}: skinners only, the pelts are skinned; inside"] = "{npc:6306}: só para esfoladores, os pelegos saem da esfola; lá dentro",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}, perto dos estábulos ao sul da Abadia",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "{npc:6} cavam nos vinhedos a nordeste da Abadia. De vez em quando um solta um {quest:91741}: clique nele com o botão direito.",
		["{npc:80} walks around {area:34}: look inside the circle on the map"] = "{npc:80} anda por {area:34}: procure dentro do círculo no mapa",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822}: dome-o com o {item:15908}",
		["{npc:823}, at the Abbey steps"] = "{npc:823}, nos degraus da Abadia",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}, de volta à escadaria da Abadia",
		["{npc:894} sells the Shiny Red Apples for the {quest:91736}. Apples looted from kobolds and crates count too: the purchase ticks itself once you have four."] = "{npc:894} vende as Maçãs Vermelhas Brilhantes para o {quest:91736}. Maçãs saqueadas de kobolds e caixotes também contam: a compra se marca sozinha quando você tiver quatro.",
		["{npc:911}, the warrior trainer; inside"] = "{npc:911}, o instrutor de guerreiro; lá dentro",
		["{npc:915}, the rogue trainer"] = "{npc:915}, o instrutor de ladinos",
		["{npc:925}, the paladin trainer"] = "{npc:925}, o instrutor de paladinos",
		["{npc:952}, upstairs"] = "{npc:952}, no andar de cima",
		["{npc:955}: he wants your {item:247824}; inside"] = "{npc:955}: ele quer o seu {item:247824}; lá dentro",
		["{npc:963}: for {npc:234} at {area:108}"] = "{npc:963}: para {npc:234} em {area:108}",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood.\nStonetusk Boars graze between the vineyards and the farm."] = "A {object:694855} cresce nos campos em volta dos vinhedos e da fazenda dos Campedra; os Javalis Pedratusco ali em volta dão o sangue.\nJavalis Pedratusco pastam entre os vinhedos e a fazenda.",
		["{quest:76}'s entrance"] = "Entrada de {quest:76}",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it."] = "{quest:87} está dentro de {area:57}, não no morro acima dela: entre pela boca e mantenha-se à esquerda até o fundo do piso da mina; não suba as escadas. Bandidos Défias ao redor dos vinhedos soltam uma {item:1972} de vez em quando: clique nela com o botão direito.",
		["{quest:91733} and {npc:330}"] = "{quest:91733} e {npc:330}",
		["{zone:1429}: kill these as you meet them"] = "{zone:1429}: vá matando estes pelo caminho",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "Use /sentar junto à fogueira de {npc:265811} até receber {spell:1229451}",
		["Back at {area:256}"] = "De volta a {area:256}",
		["Back out of the city gate and east along the road: {quest:1683} stands south of it, by {area:736}. Bring his horn back to {quest:1684}."] = "Saia de novo pelo portão da cidade e siga a estrada para leste: {quest:1683} fica ao sul dela, perto de {area:736}. Leve o chifre dele de volta a {quest:1684}.",
		["Back to the moonwell."] = "De volta ao poço lunar.",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "De volta ao topo de {area:256}. {object:654846} está ao lado dele.",
		["Back upstairs to {npc:3567} with the webwoods done and {npc:272116}'s moss."] = "De volta ao andar de cima até {npc:3567}, com as lenhateias feitas e o musgo de {npc:272116}.",
		["Befouled Webwoods"] = "Lenhateias Conspurcadas",
		["Below ground"] = "No subterrâneo",
		["Bloodfeather harpies"] = "Harpias Plumassangue",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Then {npc:11800} in {area:2361} flies Druids straight to {area:702}, no flight path needed. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Lance {spell:18960}. {npc:11802} está em {area:2361}; {quest:5929} fica na mata ao noroeste. Depois {npc:11800}, em {area:2361}, leva Druidas direto para {area:702}, sem precisar de rota de voo. {npc:11802} fica no andar de cima do prédio dele: suba por dentro, a seta não diferencia os andares.",
		["Crawler Legs: the Tide Crawlers"] = "Patas de Rastejante: os Maretiscos",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Cada missão de Dazalar lhe dá um {item:15908}: use-o na fera indicada e depois leve o bastão de volta para ele em {area:186}. Tocaieiras Lenhateia rastejam ao redor da aldeia; Espreitadores Sabre-da-noite e Guinchadoras Estrígidas vagueiam pelo bosque ao sul dela.",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Escolte {npc:275744} para fora do túmulo; {npc:2081}, em {area:186}, recebe o relatório.",
		["Fandral in {zone:1457} takes it"] = "Fandral Guenelmo, em {zone:1457}, a recebe",
		["Fel Cones lie under the trees all around {area:186} and {npc:2150}: pick them up on the road east and hand them to {npc:2150} on the way to {npc:7234}."] = "Pinhas Vis estão embaixo das árvores em volta de {area:186} e de {npc:2150}: pegue na estrada para leste e entregue a {npc:2150} no caminho até {npc:7234}.",
		["Fishers only: {npc:10216} stands on the pier. His {item:12238} is fished from the pier itself."] = "Só para pescadores: {npc:10216} fica no cais. A {item:12238} dele é pescada do próprio cais.",
		["Fly back to {area:702} from {npc:3841}, hand {item:16263} to {npc:10118} on the dock, then fly back to {area:442}."] = "Voe de volta a {area:702} a partir de {npc:3841}, entregue {item:16263} a {npc:10118} no cais, depois voe de volta a {area:442}.",
		["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442}."] = "Voe para {area:702} mais uma vez e pegue o portal para subir até {npc:4217}; depois volte voando para {area:442}.",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Siga a estrada para o sudoeste, saindo de {area:188}. {npc:2150} fica junto a ela, logo a leste de {area:186}.",
		["Follow the road west into {zone:1457} and use the {item:279378} at the inn on the {area:1659} and at the tunnel mouth below {area:3425} for the last two owls. {npc:4241} stands on the {area:1659} just inside the city. {npc:3516} is in the {area:1658} at the north end of the city, {quest:922} just south of it; {npc:4092}, {npc:7999}, {npc:7313} and {npc:8396} are in the Temple of the Moon at the south end."] = "Siga a estrada para oeste até {zone:1457} e use {item:279378} na estalagem de {area:1659} e na boca do túnel abaixo de {area:3425}, para as duas últimas corujas. {npc:4241} fica em {area:1659}, logo na entrada da cidade. {npc:3516} está em {area:1658}, no extremo norte da cidade, {quest:922} logo ao sul dele; {npc:4092}, {npc:7999}, {npc:7313} e {npc:8396} estão no Templo da Lua, no extremo sul.",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "Emboscadores Masca-pinho se escondem ao longo da estrada a oeste de {area:258}.",
		["Gnarlpine Mystics and {npc:7234} camp north-east of {area:260}. {npc:7234} drops the {item:8049}: open it for the jewel.\nCareful: {npc:7234} waits near the camp fire with mystics around him, so pulling him without adds is hard."] = "Místicos Masca-pinho e {npc:7234} acampam a nordeste de {area:260}. {npc:7234} deixa cair o {item:8049}: abra para pegar a joia.\nCuidado: {npc:7234} fica perto da fogueira com místicos em volta, então é difícil puxá-lo sozinho.",
		["Gnarlpine Shamans"] = "Xamãs Masca-pinho",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Desça de volta até {area:702} e voe para {area:442}. {object:177525} fica nas colinas logo a leste da vila: use o {item:15208} ali, derrote Lunagarra e fale com {npc:12144}.",
		["Grells"] = "Capetas",
		["Heal and fortify {npc:12429}"] = "Cure e fortifique {npc:12429}",
		["Into the city through the gate. {quest:922} is just south of the {area:1658} at the north end, {npc:7316} in the west, {npc:7313} and {npc:8396} in the Temple of the Moon at the south end. On the way back out, use Dalia's {item:279378} at the bank and at the city gate; the other two owls wait for your last visit."] = "Entre na cidade pelo portão. {quest:922} fica logo ao sul de {area:1658}, no extremo norte, {npc:7316} no oeste, {npc:7313} e {npc:8396} no Templo da Lua, no extremo sul. Na saída, use {item:279378}, de Dalia, no banco e no portão da cidade; as outras duas corujas esperam a sua última visita.",
		["Into {zone:1457}"] = "Rumo a {zone:1457}",
		["Lead {quest:938} to the moonwell"] = "Leve {quest:938} até o poço lunar",
		["Learn the flight path from {npc:3841} where you land. {npc:4200}'s fish stall is just north of her, by the docks.\nThe boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "Aprenda a rota de voo com {npc:3841} onde você pousar. A barraca de peixe de {npc:4200} fica logo ao norte dela, junto ao cais.\nO barco atraca a oeste da vila. O mestre de voo fica no morro ao sul da estalagem; quem dá missões está espalhado pela rua principal.",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "Saia de {area:188} pela trilha a sudeste de {area:256}: {npc:6780} fica ao lado dela, onde ela desce em direção à estrada para {area:186}.",
		["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:1994} sits deep inside. {npc:8584} waits in the trees west of the cave mouth."] = "Sabres-da-noite Sarnentos e Javalis-espinho vagueiam ao norte de {area:256}, a caminho da caverna. {npc:1994} fica bem no fundo. {npc:8584} espera entre as árvores a oeste da entrada da caverna.",
		["Nightsabers"] = "Sabres-da-noite",
		["Nightsabers, Strigid Owls and Webwood Lurkers roam all around {area:186} and along the road east; the lurkers also drop the recipe's spider legs. The moonwell is at the west edge of {area:260}."] = "Sabres-da-noite, Corujas Estrígidas e Tocaieiras Lenhateia andam em volta de {area:186} e pela estrada para leste; as tocaieiras também deixam cair as patas de aranha da receita. O poço lunar fica na borda oeste de {area:260}.",
		["North to {area:257}"] = "Ao norte, para {area:257}",
		["North-east from Ursal's den, back to {area:186}."] = "Para o nordeste a partir do covil de Ursal, de volta a {area:186}.",
		["North-west of Dolanaar, on the way to the {area:264}, Befouled Webwoods creep through the woods; {npc:272116} prowls at their east edge and carries the {item:281023}.\n{npc:272116} is elite (level 12): grouping up is advised. Clear the webwoods around him first and pull him on his own."] = "A noroeste de Dolanaar, a caminho de {area:264}, Lenhateias Conspurcadas rastejam pelo bosque; {npc:272116} ronda a borda leste delas e carrega o {item:281023}.\n{npc:272116} é elite (nível 12): é recomendável formar um grupo. Limpe primeiro as lenhateias em volta dele e puxe-o sozinho.",
		["Portal to {quest:940}"] = "Portal para {quest:940}",
		["Sentinel Arynia again"] = "Sentinela Arynia de novo",
		["South from the glade toward Ursal: Shayla walks the road west of {area:186}, from where the path down from the glade meets it south-west to the bend at about 38,54 and back."] = "Ao sul da clareira, em direção a Ursal: Shayla percorre a estrada a oeste de {area:186}, desde onde a trilha que desce da clareira encontra a estrada, para o sudoeste até a curva em cerca de 38,54, e volta.",
		["South of the pools. The {object:6751} grows by the Hold; the furbolgs around it drop the rest of the fangs."] = "Ao sul das águas. A {object:6751} cresce junto ao Acampamento; os furbolgs em volta dela soltam o resto das presas.",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "A sudeste de Dolanaar, até {npc:2080}. Brotos de Açoitadeira vagueiam ao redor dele na margem.",
		["South-west of Starbreeze, south of {npc:2150}. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "A sudoeste de Starbreeze, ao sul de {npc:2150}. {npc:2080} cuida das mudas dele na margem; Brotos de Açoitadeira e Muscoides andam em volta dele, e os {quest:919} crescem no meio.",
		["South-west of the barrow. The moonwell sits by the pools."] = "A sudoeste do túmulo. O poço lunar fica junto aos lagos.",
		["Speak with the {quest:5929}"] = "Fale com {quest:5929}",
		["Take the antidote from {npc:8583} at the foot of {area:256} only now, on the way down: it lasts five minutes. {npc:8584} waits north-west, by the cave: go straight on to him."] = "Pegue o antídoto de {npc:8583}, ao pé de {area:256}, só agora, na descida: ele dura cinco minutos. {npc:8584} espera a noroeste, junto à caverna: vá direto até ele.",
		["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs. Once you have {quest:6342}, talk to {npc:3838} again and choose the flight to {area:442}: it is free and lands beside {npc:4200}. If the flight map opens instead, close it and talk to him again holding Shift."] = "Desça pelo portal até {area:702}. {npc:10118} fica no cais, {npc:3838} junto aos hipogrifos. Quando tiver {quest:6342}, fale de novo com {npc:3838} e escolha o voo para {area:442}: é de graça e pousa ao lado de {npc:4200}. Se abrir o mapa de voo, feche e fale com ele de novo segurando Shift.",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "Pegue de novo a estrada para o noroeste a partir de {area:186}; ela continua à beira da estrada, a caminho de {zone:1457}.",
		["The Bloodfeather harpies nest on the slopes west and north of the glade. {quest:938}, an injured sabercat, lies by the glade's west wall among them: lead her back to Sentinel Arynia at the moonwell before her time runs out.\nCareful: The harpies stand packed together, so extra ones often join a fight. Casters are mixed in among them."] = "As harpias Plumassangue fazem ninho nas encostas a oeste e ao norte da clareira. {quest:938}, uma gata-de-sabre ferida, está junto à parede oeste da clareira, no meio delas: leve-a de volta até a Sentinela Arynia Rasganimbus, no poço lunar, antes que o tempo dela acabe.\nCuidado: as harpias ficam amontoadas, então costuma vir harpia a mais. Há lançadoras de feitiço misturadas.",
		["The WANTED poster outside the inn"] = "O cartaz de PROCURA-SE em frente à estalagem",
		["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms. Its furbolgs drop Shayla's fangs."] = "O túmulo fica ao sul da estrada. {npc:275744} está presa lá dentro, {npc:7317} dorme nas profundezas, e os quatro baús de relíquias ficam nas salas inferiores. Os furbolgs de lá soltam as presas de Shayla.",
		["The moonwell"] = "O poço lunar",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "O poço lunar fica no meio da clareira. {object:6752} cresce no extremo norte dela.",
		["The moonwell sits north of {area:256}."] = "O poço lunar fica ao norte de {area:256}.",
		["The named harpies"] = "As harpias nomeadas",
		["The road to {zone:1457}"] = "A estrada para {zone:1457}",
		["The road west to the {area:264} runs through {area:186}: hand {npc:3567} the jewel on the way."] = "A estrada para oeste até {area:264} passa por {area:186}: entregue a joia a {npc:3567} no caminho.",
		["The trainers stand upstairs inside {area:256}, along the ramp that winds up the tree: {npc:3593} and {npc:3594} on the first level, {npc:3595} above them, {npc:3596} and {npc:3597} at the top. The arrow cannot tell the levels apart."] = "Os instrutores ficam no andar de cima, dentro de {area:256}, ao longo da rampa que sobe em espiral pela árvore: {npc:3593} e {npc:3594} no primeiro nível, {npc:3595} acima deles, {npc:3596} e {npc:3597} no topo. A seta não diferencia os níveis.",
		["The {area:265}"] = "{area:265}",
		["The {area:478}"] = "{area:478}",
		["The {object:177525}"] = "{object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "{object:4406} ficam no fundo de {area:257}: pegue o caminho central e vire à esquerda na bifurcação, até a saliência alta. Os Capetas deixam cair Cogumelos Jacinto; os Lírios Lunapétala crescem junto aos lagos ao norte de {area:256}.",
		["The {object:6752} grows at the glade's north end, on the way: then north of {npc:272046}, along the island's northern edge by {area:266}, {npc:7319}, a level 12 spider, lurks."] = "{object:6752} cresce no extremo norte da clareira, no caminho: depois, ao norte de {npc:272046}, ao longo da margem norte da ilha, junto a {area:266}, {npc:7319}, uma aranha de nível 12, espreita.",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Maretiscos correm pela costa abaixo do vilarejo; {quest:983} fica na praia logo ao sul das docas. Manguais da Costa Negra nadam nas águas rasas. A {object:175207} está na costa logo ao sul do vilarejo.",
		["Upstairs"] = "No andar de cima",
		["Use the {item:18152} at the moonwell"] = "Use o {item:18152} no poço lunar",
		["Use the {item:5185} at the moonwell"] = "Use o {item:5185} no poço lunar",
		["Use the {item:5619} at the moonwell"] = "Use o {item:5619} no poço lunar",
		["Use the {item:5621} at the moonwell"] = "Use o {item:5621} no poço lunar",
		["Walk Lynessa out and keep her alive"] = "Leve Lynessa para fora e mantenha-a viva",
		["Walk south along the west side of the island. Ursal prowls the far south, below the {area:478}.\nCareful: Gnarlpine of roughly level 9-12 crowd the camp and sit close together, so it is easy to pull several at once. Take them on singly before you engage Ursal."] = "Ande para o sul pelo lado oeste da ilha. Ursal ronda o extremo sul, abaixo de {area:478}.\nCuidado: Masca-pinhos de nível 9-12 lotam o acampamento e ficam bem juntos, então é fácil puxar vários de uma vez. Enfrente um de cada vez antes de encarar o Ursal.",
		["Webwood Lurkers"] = "Tocaieiras Lenhateia",
		["Webwood Spiders; below ground"] = "Aranhas Lenhateia; no subterrâneo",
		["West along the road toward the city. Shayla walks this stretch of road, from the arrow south-west to the bend at about 38,54 and back: if she isn't at the arrow, follow the road south-west. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and {area:261}'s all count."] = "A oeste pela estrada, em direção à cidade. Shayla percorre este trecho da estrada, da seta para o sudoeste até a curva em cerca de 38,54, e volta: se ela não estiver na seta, siga a estrada para o sudoeste. Todo furbolg Masca-pinho solta presas: os emboscadores desta estrada, os do túmulo e os de {area:261} contam todos.",
		["West from the webwoods to the {area:265}, then north along it to the glade: the timberlings along its banks drop the Mossy Tumors."] = "A oeste das lenhateias até {area:265}, depois para o norte ao longo dele até a clareira: os muscoides nas margens soltam os Tumores Musguentos.",
		["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Já que está aqui: aprenda Cajados com {npc:11866} ({area:1660}, 10 pratas); a arma corpo a corpo do Caçador vale pelos atributos, e as de duas mãos são as que mais trazem.",
		["While you're here: learn Staves from {npc:11866} ({area:1660}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Já que está aqui: aprenda Cajados com {npc:11866} ({area:1660}, 10 pratas); enquanto você sobe de nível, um cajado traz mais atributos de feitiço que uma arma de uma mão.",
		["With a profession learned, {npc:265811} also offers its Camping 101, which its trainer takes: alchemy and herbalism beside {npc:6286}, {skill:129} with {npc:6094} in the inn, skinning and leatherworking at the Maneweavers' camp on the road west."] = "Com uma profissão aprendida, {npc:265811} também oferece a Introdução ao acampamento dela, que o instrutor da profissão recebe: alquimia e herborismo ao lado de {npc:6286}, {skill:129} com {npc:6094} na estalagem, esfolamento e couraria no acampamento dos Tecejuba, na estrada para oeste.",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "Você começa ao pé de {area:256}, a grande árvore de {area:188}.",
		["Young Nightsabers and Young Thistle Boars roam around {area:256}. Grells carry {item:3297} in the woods west of the tree, where the Gnarlpine Totems stand."] = "Sabres-da-noite Jovens e Javalis-espinho Jovens vagueiam ao redor de {area:256}. Os Capetas carregam {item:3297} no bosque a oeste da árvore, onde ficam os Totens de Masca-pinho.",
		["talk to the trainer"] = "fale com o instrutor",
		["talk to {npc:3838} again: free with {quest:6342}"] = "fale de novo com {npc:3838}: de graça com {quest:6342}",
		["the city gate"] = "o portão da cidade",
		["the same {object:673378}: Fandral in {zone:1457} takes it"] = "o mesmo {object:673378}: Fandral, em {zone:1457}, o recebe",
		["the tunnel mouth below {area:3425}, on the way south"] = "a boca do túnel abaixo de {area:3425}, no caminho para o sul",
		["{area:186} again"] = "{area:186} de novo",
		["{area:188}: kill these as you meet them"] = "{area:188}: vá matando estes pelo caminho",
		["{area:258}'s mouth"] = "Entrada de {area:258}",
		["{area:262}'s entrance"] = "Entrada de {area:262}",
		["{area:736}, outside the barrow"] = "{area:736}, fora do túmulo",
		["{item:159} from {npc:6736}, for {npc:6094}"] = "{item:159} de {npc:6736}, para {npc:6094}",
		["{item:279378}: the bank, on the way out"] = "{item:279378}: o banco, na saída",
		["{item:279378}: the inn on the {area:1659}"] = "{item:279378}: a estalagem de {area:1659}",
		["{item:3371} from {npc:3614}, beside {npc:6094}"] = "{item:3371} de {npc:3614}, ao lado de {npc:6094}",
		["{item:5170}: timberlings"] = "{item:5170}: muscoides",
		["{item:5220}: any Gnarlpine furbolg"] = "{item:5220}: qualquer furbolg Masca-pinho",
		["{item:8049}, from {npc:7234}"] = "{item:8049}, de {npc:7234}",
		["{npc:10118} stands on the Rut'theran dock where you land. Then take the portal up to {npc:4217} in the {area:1658}."] = "{npc:10118} fica no cais de Rut'theran, onde você pousa. Depois suba pelo portal até {npc:4217}, em {area:1658}.",
		["{npc:10216}, on the pier"] = "{npc:10216}, no cais",
		["{npc:11401}, in the Temple of the Moon: Starshards"] = "{npc:11401}, no Templo da Lua: Fragmentos Estelares",
		["{npc:12429} kneels wounded on the rocks at the north edge of {area:259}, on the walk back to {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count. She runs off once both land and is back in about 5 minutes."] = "{npc:12429} está ajoelhada e ferida nas pedras da margem norte de {area:259}, no caminho de volta a {area:186}, sem marcador de missão sobre ela. Lance {spell:613} (Grau 2) nela e depois {spell:1243}: o Grau 1 de {spell:613} não conta. Ela sai correndo assim que os dois fazem efeito e volta em cerca de 5 minutos.",
		["{npc:1992}, south of the tree"] = "{npc:1992}, ao sul da árvore",
		["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}: dome-a com o {item:15908}",
		["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}: dome-a com o {item:15908}",
		["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038} espera dentro da caverna, no fundo ou em cima da saliência; mantenha-se à direita.",
		["{npc:2038}; below ground"] = "{npc:2038}; no subterrâneo",
		["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}: dome-o com o {item:15908}",
		["{npc:2077}, by the path"] = "{npc:2077}, junto à trilha",
		["{npc:2079}: a sigil for {npc:3596}"] = "{npc:2079}: um sigilo para {npc:3596}",
		["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}: {quest:922}, em {zone:1457}, a recebe",
		["{npc:2082}, on the tree's ramp"] = "{npc:2082}, na rampa da árvore",
		["{npc:2107} stands upstairs in a house in the village, east of the moonwell: go up inside, the arrow cannot tell the floors apart. {object:126158} is in the house on the hill at the east end of the village."] = "{npc:2107} fica no andar de cima de uma casa da vila, a leste do poço lunar: suba por dentro, a seta não diferencia os andares. {object:126158} fica na casa da colina, na ponta leste da vila.",
		["{npc:2150} sits by the road just east of {area:186}, between {area:186} and {area:260}."] = "{npc:2150} fica junto à estrada, logo a leste de {area:186}, entre {area:186} e {area:260}.",
		["{npc:2151} patrols the road west of the village: if she isn't at the arrow, follow the road until you meet her."] = "{npc:2151} patrulha a estrada a oeste da aldeia: se ela não estiver na seta, siga a estrada até encontrá-la.",
