t.guides["forever/class/priest/priest-robes-alliance"] = (function() return {
		["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "Uma veste incomum de graça no nível 5: cure e fortifique um guarda ferido perto da sua primeira cidade.",
		["At 5, {npc:3595}, the priest trainer on the second level of {area:256}, the great tree in {area:188}, sends you to {npc:3600} in {area:186}. Train {spell:613} (Rank 2) from her while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "No nível 5, {npc:3595}, a instrutora de sacerdote no segundo nível de {area:256}, a grande árvore de {area:188}, manda você até {npc:3600}, em {area:186}. Aprenda {spell:613} (Grau 2) com ela enquanto está aqui: abre no nível 4 por 1 prata, e a próxima missão pede exatamente esse grau.",
		["At 5, {npc:375}, the priest trainer inside {area:24}, sends you to {npc:377} in {area:87}. Train {spell:613} (Rank 2) from Anetta while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "No nível 5, {npc:375}, o instrutor de sacerdote dentro de {area:24}, manda você até {npc:377}, em {area:87}. Aprenda {spell:613} (Grau 2) com Anetta enquanto está aqui: ele abre no nível 4 por 1 prata, e a próxima missão pede exatamente esse grau.",
		["At 5, {npc:837}, the priest trainer inside {area:77} in {area:132}, sends you to {npc:1226} in {area:131}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "No nível 5, {npc:837}, o instrutor de sacerdote dentro de {area:77}, em {area:132}, manda você até {npc:1226}, em {area:131}. Aprenda {spell:613} (Grau 2) com ele enquanto está aqui: abre no nível 4 por 1 prata, e a próxima missão pede exatamente esse grau.",
		["Back at the north edge of {area:186}: {npc:3600} gives you the {item:16604}."] = "De volta à borda norte de {area:186}: {npc:3600} entrega {item:16604} a você.",
		["Back inside the {area:2102}: {npc:1226} gives you {item:16605}."] = "De volta à {area:2102}: {npc:1226} entrega {item:16605} a você.",
		["Back upstairs in the Lion's Pride Inn: Josetta gives you {item:16605}."] = "De volta ao andar de cima da Lion's Pride Inn: Joselita entrega {item:16605} a você.",
		["Follow the road south out of {area:9} to {area:87}. {npc:377} is upstairs in the Lion's Pride Inn."] = "Siga a estrada para o sul saindo de {area:9} até {area:87}. {npc:377} está no andar de cima da Estalagem Orgulho do Leão.",
		["Heal and fortify {npc:12423}"] = "Cure e fortifique {npc:12423}",
		["Heal and fortify {npc:12427}"] = "Cure e fortifique {npc:12427}",
		["Heal and fortify {npc:12429}"] = "Cure e fortifique {npc:12429}",
		["Leave {area:188} by the ramp and follow the road south-west to {area:186}. {npc:3600} is in the building at the north edge of the village."] = "Saia de {area:188} pela rampa e siga a estrada para sudoeste até {area:186}. {npc:3600} está no prédio da borda norte da vila.",
		["Priest Robes at 5 (Alliance)"] = "Vestes de Sacerdote no nível 5 (Aliança)",
		["Take the tunnel north-east out of {area:132} and follow the road east to {area:131}. {npc:1226} is inside the {area:2102}."] = "Pegue o túnel a nordeste saindo de {area:132} e siga a estrada para leste até {area:131}. {npc:1226} está dentro da {area:2102}.",
		["{npc:12423} kneels by a tree on the lake shore east of {area:87}, off the road: walk along the shore, the minimap misses him from the road. Cast {spell:613} (Rank 2) on him first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook (or cast both from the spellbook if an action bar addon gets in the way). He walks off once both land and is back in about 3 minutes."] = "{npc:12423} fica ajoelhado ao lado de uma árvore na margem do lago, a leste de {area:87}, fora da estrada: ande pela margem, o minimapa não o mostra de quem está na estrada. Lance {spell:613} (Grau 2) nele primeiro, depois {spell:1243}. O Grau 1 de {spell:613} não vale; arraste o Grau 2 do grimório para a sua barra (ou lance os dois pelo grimório, se um addon de barra de ação atrapalhar). Ele vai embora quando os dois pegam e volta em cerca de 3 minutos.",
		["{npc:12427} kneels on a ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer: if the road starts going downhill, you have passed him. Cast {spell:613} (Rank 2) on him first, then {spell:1243}; he speaks after each spell. Rank 1 of {spell:613} does not count."] = "{npc:12427} fica ajoelhado numa elevação entre dois muros baixos, logo ao sul de {area:131}, do outro lado da estrada em relação ao instrutor de mascotes de caçador: se a estrada começar a descer, você passou dele. Lance {spell:613} (Grau 2) nele primeiro, depois {spell:1243}; ele fala depois de cada magia. O Grau 1 de {spell:613} não vale.",
		["{npc:12429} kneels on the rocks at the edge of {area:259}, about 100 yards south of {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her first, then {spell:1243}; she runs off toward the lake once both land and is back in about 5 minutes. Rank 1 of {spell:613} does not count."] = "{npc:12429} fica ajoelhada nas pedras da beira de {area:259}, uns 100 metros ao sul de {area:186}, sem marca de missão sobre ela. Lance {spell:613} (Grau 2) nela primeiro, depois {spell:1243}; ela corre para o lago quando os dois pegam e volta em cerca de 5 minutos. O Grau 1 de {spell:613} não vale.",
		["{spell:613} (Rank 2), if Anetta did not teach it yet"] = "{spell:613} (Grau 2), se Anetta ainda não ensinou",
		["{spell:613} (Rank 2), if {npc:3595} did not teach it yet"] = "{spell:613} (Grau 2), se {npc:3595} ainda não ensinou",
		["{spell:613} (Rank 2), if {npc:837} did not teach it yet"] = "{spell:613} (Grau 2), se {npc:837} ainda não ensinou",
} end)()
t.guides["forever/class/priest/priest-robes-horde"] = (function() return {
		["A free uncommon robe at 5: heal and fortify a wounded guard near your first town."] = "Uma veste incomum de graça no nível 5: cure e fortifique um guarda ferido perto da sua primeira cidade.",
		["At 5, {npc:2123}, the priest trainer in the chapel of {area:154}, sends you to {npc:2129} in {area:159}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "No nível 5, {npc:2123}, o instrutor de sacerdote na capela de {area:154}, manda você até {npc:2129}, em {area:159}. Aprenda {spell:613} (Grau 2) com ele enquanto está aqui: abre no nível 4 por 1 prata, e a próxima missão pede exatamente esse grau.",
		["At 5, {npc:3707}, the priest trainer in the Den in the middle of the {area:363}, sends you to {npc:3706} in {area:362}. Train {spell:613} (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank."] = "No nível 5, {npc:3707}, o instrutor de sacerdote na Toca, no meio de {area:363}, manda você até {npc:3706}, em {area:362}. Aprenda {spell:613} (Grau 2) com ele enquanto está aqui: abre no nível 4 por 1 prata, e a próxima missão pede exatamente esse grau.",
		["Back in the {area:362} barracks: {npc:3706} gives you the {item:16606}."] = "De volta ao quartel de {area:362}: {npc:3706} entrega {item:16606} a você.",
		["Back upstairs in the {area:159} inn: Beryl gives you the {item:16607}."] = "De volta ao andar de cima da estalagem de {area:159}: Beryl entrega {item:16607} a você.",
		["Follow the road east out of {area:154} to {area:159}. {npc:2129} is upstairs in the inn, {area:2119}."] = "Siga a estrada para leste saindo de {area:154} até {area:159}. {npc:2129} está no andar de cima da estalagem, {area:2119}.",
		["Follow the road out of the {area:363} north-east to {area:362}. {npc:3706} is inside the barracks, the first building on the right as you come into town."] = "Siga a estrada para nordeste saindo de {area:363} até {area:362}. {npc:3706} está dentro do quartel, o primeiro prédio à direita de quem chega à cidade.",
		["Heal and fortify {npc:12428}"] = "Cure e fortifique {npc:12428}",
		["Heal and fortify {npc:12430}"] = "Cure e fortifique {npc:12430}",
		["Priest Robes at 5 (Horde)"] = "Vestes de Sacerdote no nível 5 (Horda)",
		["{npc:12428} kneels, half-dead, beside the north gate of {area:159}'s graveyard, a short walk north of the inn. Cast {spell:613} (Rank 2) on him first, then {spell:1243}: Fortitude first does not count, nor does Rank 1 of {spell:613}. If an addon gets in the way, cast both from the spellbook."] = "{npc:12428} fica ajoelhado, meio morto, ao lado do portão norte do cemitério de {area:159}, uma caminhada curta ao norte da estalagem. Lance {spell:613} (Grau 2) nele primeiro, depois {spell:1243}: Fortitude primeiro não vale, nem o Grau 1 de {spell:613}. Se um addon atrapalhar, lance os dois pelo grimório.",
		["{npc:12430} kneels behind a group of rocks just off the road, a short walk south of {area:362}. Cast {spell:613} (Rank 2) on her first, then {spell:1243}. Rank 1 of {spell:613} does not count; drag Rank 2 onto your bar from the spellbook. She leaves once both land and is back in about 5 minutes."] = "{npc:12430} fica ajoelhada atrás de um grupo de pedras ao lado da estrada, uma caminhada curta ao sul de {area:362}. Lance {spell:613} (Grau 2) nela primeiro, depois {spell:1243}. O Grau 1 de {spell:613} não vale; arraste o Grau 2 do grimório para a sua barra. Ela vai embora quando os dois pegam e volta em cerca de 5 minutos.",
		["{spell:613} (Rank 2), if Duesten did not teach it yet"] = "{spell:613} (Grau 2), se Duesten ainda não ensinou",
		["{spell:613} (Rank 2), if {npc:3707} did not teach it yet"] = "{spell:613} (Grau 2), se {npc:3707} ainda não ensinou",
} end)()
t.guides["forever/class/priest/starshards-and-elunes-grace"] = (function() return {
		["At 10 in {zone:1426}, {npc:1226}, the priest trainer inside the {area:2102} in {area:131}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "No nível 10, em {zone:1426}, {npc:1226}, o instrutor de sacerdote dentro da {area:2102}, em {area:131}, entrega {quest:5628}, uma carta para {npc:11401}, em {zone:1457}.",
		["At 10 in {zone:1429}, {npc:377}, upstairs in the Lion's Pride Inn in {area:87}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "No nível 10, na {zone:1429}, {npc:377}, no andar de cima da Estalagem Orgulho do Leão, em {area:87}, entrega {quest:5628}, uma carta para {npc:11401}, em {zone:1457}.",
		["At 10 in {zone:1453}, {npc:5489} at the altar of the Cathedral of Light hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "No nível 10, em {zone:1453}, {npc:5489}, no altar da Catedral da Luz, entrega {quest:5628}, uma carta para {npc:11401}, em {zone:1457}. {npc:11397}, no Parque, tem a mesma carta.",
		["At 10 in {zone:1455}, {npc:5142} in the {object:32386} ({object:32362}) hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}."] = "No nível 10, em {zone:1455}, {npc:5142}, no {object:32386} ({object:32362}), entrega {quest:5628}, uma carta para {npc:11401} em {zone:1457}.",
		["At 10, go to {npc:11401} on the upper balcony of the Temple of the Moon, at the south end of {zone:1457}: take the ramp up from the temple floor; she stands beside {npc:7999}. {quest:5627} is given and taken back at once and teaches {spell:10797}. No letter needed. Forever made {spell:10797} hit much harder, on a 30-second cooldown."] = "No nível 10, vá até {npc:11401}, na sacada de cima do Templo da Lua, no extremo sul de {zone:1457}: suba a rampa a partir do chão do templo; ela fica ao lado de {npc:7999}. {quest:5627} é dada e recolhida de volta na hora, e ensina {spell:10797}. Não precisa de carta. O Forever fez {spell:10797} bater bem mais forte, com recarga de 30 segundos.",
		["At 10, {npc:3600}, the priest trainer in the building at the north edge of {area:186}, hands you {quest:5628}, a letter for {npc:11401} in {zone:1457}. {area:186} is on the road west to {zone:1457}."] = "No nível 10, {npc:3600}, o instrutor de sacerdote no prédio da borda norte de {area:186}, entrega {quest:5628}, uma carta para {npc:11401}, em {zone:1457}. {area:186} fica na estrada para oeste, rumo a {zone:1457}.",
		["At 20 in {zone:1453}, {npc:376} at the altar of the Cathedral of Light hands you an {spell:2651} letter for {npc:11401} in {zone:1457}. {npc:11397} in the Park has the same letter."] = "No nível 20, em {zone:1453}, {npc:376}, no altar da Catedral da Luz, entrega uma carta de {spell:2651} para {npc:11401}, em {zone:1457}. {npc:11397}, no Parque, tem a mesma carta.",
		["At 20 in {zone:1455}, {npc:11406} in the {object:32386} ({object:32362}) hands you an {spell:2651} letter for {npc:11401} in {zone:1457}."] = "No nível 20, em {zone:1455}, {npc:11406}, no {object:32386} ({object:32362}), entrega uma carta de {spell:2651} para {npc:11401} em {zone:1457}.",
		["At 20, {npc:11401} on the upper balcony of the Temple of the Moon, beside {npc:7999}, teaches {quest:5672} with a quest she gives and takes back at once. In Forever, {quest:5672} halves the chance for melee and ranged attacks to hit you for 15 seconds or until three attacks miss."] = "No nível 20, {npc:11401}, na sacada de cima do Templo da Lua, ao lado de {npc:7999}, ensina {quest:5672} com uma missão que ela dá e recolhe de volta na hora. No Forever, {quest:5672} reduz pela metade a chance de ataques corpo a corpo e à distância acertarem você por 15 segundos, ou até três ataques errarem.",
		["Hand Laurena's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Entregue a carta de Laurena a {npc:11401}, na sacada de cima do Templo da Lua, em {zone:1457}, ao lado de {npc:7999}: o barco de {area:17203} (ou de {area:150}) até {area:442}, o barco seguinte até {area:702} e depois o portal que sobe para {zone:1457}.",
		["Hand Nara's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Entregue a carta de Nara a {npc:11401}, na sacada de cima do Templo da Lua, em {zone:1457}, ao lado de {npc:7999}: o barco de {area:17203} (ou de {area:150}) até {area:442}, o barco seguinte até {area:702} e depois o portal que sobe para {zone:1457}.",
		["Hand Rohan's letter to {npc:11401}, on the upper balcony of the Temple of the Moon in {zone:1457}, beside {npc:7999}: the boat from {area:17203} (or {area:150}) to {area:442}, the boat on to {area:702}, then the portal up into {zone:1457}."] = "Entregue a carta de Rohan a {npc:11401}, na sacada de cima do Templo da Lua, em {zone:1457}, ao lado de {npc:7999}: o barco de {area:17203} (ou de {area:150}) até {area:442}, o barco seguinte até {area:702} e depois o portal que sobe para {zone:1457}.",
		["Take the road west from {area:186} into {zone:1457} and go up to the upper balcony of the Temple of the Moon, beside {npc:7999}: {npc:11401} takes {quest:5629} and teaches {spell:10797}."] = "Siga a estrada para oeste saindo de {area:186} até {zone:1457} e suba até a sacada de cima do Templo da Lua, ao lado de {npc:7999}: {npc:11401} recebe {quest:5629} e ensina {spell:10797}.",
		["The Night Elf priest spells: {spell:10797} at 10, {spell:2651} at 20. Free, no objectives."] = "As magias do sacerdote elfo noturno: {spell:10797} no nível 10, {spell:2651} no 20. De graça, sem objetivos.",
		["{npc:11406}: take his {spell:2651} letter"] = "{npc:11406}: pegue a carta de {spell:2651} dele",
