t.guides["forever/class/priest/touch-of-weakness-and-dark-sacrifice"] = (function() return {
		["At 10 in {zone:1411}, {npc:3706}, the priest trainer inside the barracks of {area:362}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "No nível 10, em {zone:1411}, {npc:3706}, o instrutor de sacerdote dentro do quartel de {area:362}, entrega uma carta de {spell:2652} para {npc:4606}, na {zone:1458}.",
		["At 10 in {zone:1412}, {npc:11407}, just south-west of {area:222}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "No nível 10, em {zone:1412}, {npc:11407}, logo a sudoeste de {area:222}, entrega uma carta de {spell:2652} para {npc:4606}, na {zone:1458}.",
		["At 10 in {zone:1454}, {npc:6018} in the {object:172961} hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}. The zeppelin to {zone:1420} leaves from the tower outside {zone:1454}'s front gate."] = "No nível 10, em {zone:1454}, {npc:6018}, no {object:172961}, entrega uma carta de {spell:2652} para {npc:4606}, na {zone:1458}. O zepelim para {zone:1420} sai da torre fora do portão da frente de {zone:1454}.",
		["At 10 in {zone:1456}, {npc:3044}, the priest trainer in the cave under {area:1640}, hands you a {spell:2652} letter for {npc:4606} in the {zone:1458}."] = "No nível 10, em {zone:1456}, {npc:3044}, o instrutor de sacerdote na caverna embaixo de {area:1640}, entrega uma carta de {spell:2652} para {npc:4606}, na {zone:1458}.",
		["At 10, go to {npc:4606}, the priest trainer in the {zone:1458}'s {object:36070}: she gives {quest:5658} and takes it back at once. No letter needed. From {area:159}, follow the road south to the ruined city of Lordaeron; the {zone:1458}'s lifts are at the back of the throne room. {quest:5658} strikes the next melee attacker for Shadow damage and lowers its melee attack power for 2 minutes."] = "No nível 10, vá até {npc:4606}, a instrutora de sacerdote no {object:36070} da {zone:1458}: ela dá {quest:5658} e pega de volta na hora. Não precisa de carta. De {area:159}, siga a estrada para o sul até a cidade em ruínas de Lordaeron; os elevadores da {zone:1458} ficam no fundo do salão do trono. {quest:5658} atinge o próximo atacante corpo a corpo com dano de Sombra e reduz o poder de ataque corpo a corpo dele por 2 minutos.",
		["At 20 in {zone:1454}, {npc:6018} in the {object:172961} hands you a {quest:5644} letter for {npc:4606} in the {zone:1458}."] = "No nível 20, em {zone:1454}, {npc:6018}, no {object:172961}, entrega uma carta de {quest:5644} para {npc:4606}, na {zone:1458}.",
		["At 20 in {zone:1456}, {npc:3044} in the cave under {area:1640} hands you a {quest:5644} letter for {npc:4606} in the {zone:1458}."] = "No nível 20, em {zone:1456}, {npc:3044}, na caverna embaixo de {area:1640}, entrega uma carta de {quest:5644} para {npc:4606}, na {zone:1458}.",
		["At 20, {npc:4606} in the {object:36070} teaches {quest:5644} with a quest she gives and takes back at once (its text still speaks of {spell:2944}, which every priest now learns from the trainer)."] = "No nível 20, {npc:4606}, no {object:36070}, ensina {quest:5644} com uma missão que ela dá e pega de volta na hora (o texto dela ainda fala de {spell:2944}, que todo sacerdote agora aprende com o instrutor).",
		["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: the zeppelin from the tower outside {zone:1454} lands in {zone:1420}, a short walk from the {zone:1458}."] = "Entregue a carta a {npc:4606} no {object:36070} da {zone:1458}: o zepelim da torre fora de {zone:1454} pousa em {zone:1420}, a uma curta caminhada da {zone:1458}.",
		["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: the zeppelin from the tower outside {zone:1454} lands in {zone:1420}."] = "Entregue a carta a {npc:4606} no {object:36070} da {zone:1458}: o zepelim da torre fora de {zone:1454} pousa em {zone:1420}.",
		["Hand the letter to {npc:4606} in the {zone:1458}'s {object:36070}: travel to {zone:1454} and take the zeppelin to {zone:1420}."] = "Entregue a carta a {npc:4606} no {object:36070} da {zone:1458}: vá até {zone:1454} e pegue o zepelim para {zone:1420}.",
		["The Undead priest spells: {spell:2652} at 10, {quest:5644} (new in Forever) at 20. Free, no objectives."] = "As magias do sacerdote morto-vivo: {spell:2652} no nível 10, {quest:5644} (nova no Forever) no 20. De graça, sem objetivos.",
		["{npc:11407}: take the {spell:2652} letter"] = "{npc:11407}: pegue a carta de {spell:2652}",
		["{npc:3044}: take his {quest:5644} letter"] = "{npc:3044}: pegue a carta de {quest:5644} dele",
		["{npc:3044}: take his {spell:2652} letter"] = "{npc:3044}: pegue a carta de {spell:2652} dele",
		["{npc:3706}: take his {spell:2652} letter"] = "{npc:3706}: pegue a carta de {spell:2652} dele",
		["{npc:6018}: take his {quest:5644} letter"] = "{npc:6018}: pegue a carta de {quest:5644} dele",
		["{npc:6018}: take his {spell:2652} letter"] = "{npc:6018}: pegue a carta de {spell:2652} dele",
		["{quest:5644}: {npc:3044}'s letter"] = "{quest:5644}: a carta de {npc:3044}",
		["{quest:5646}: {npc:6018}'s letter"] = "{quest:5646}: a carta de {npc:6018}",
		["{quest:5660}: {npc:3706}'s letter"] = "{quest:5660}: a carta de {npc:3706}",
		["{quest:5661}: {npc:11407}'s letter"] = "{quest:5661}: a carta de {npc:11407}",
		["{quest:5662}: {npc:6018}'s letter"] = "{quest:5662}: a carta de {npc:6018}",
		["{quest:5663}: {npc:3044}'s letter"] = "{quest:5663}: a carta de {npc:3044}",
		["{spell:2652} and {quest:5644}"] = "{spell:2652} e {quest:5644}",
} end)()
t.guides["forever/class/rogue/blade-of-cunning-alliance"] = (function() return {
		["A dagger at 10 from your home town's rogue quests."] = "Uma adaga no nível 10, das missões de ladino da sua cidade natal.",
		["At 10 {npc:1234}, the rogue trainer in the {area:2102} in {area:131}, sends you to {npc:5165} in {zone:1455}."] = "No nível 10, {npc:1234}, o instrutor de ladinos na {area:2102} em {area:131}, manda você até {npc:5165} em {zone:1455}.",
		["At 10 {npc:3599}, the rogue trainer in the {area:186} inn, gives you a rose for {npc:4163} in {zone:1457}. If you lose the rose, abandon the quest and take it again."] = "No nível 10, {npc:3599}, o instrutor de ladino na estalagem de {area:186}, entrega a você uma rosa para {npc:4163}, em {zone:1457}. Se perder a rosa, abandone a missão e pegue de novo.",
		["At 10 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, gives you a package for {npc:332} in {zone:1453}. Train {spell:921} if you lack it: this chain needs it."] = "No nível 10, {npc:917}, o instrutor de ladino no andar de cima da Estalagem Orgulho do Leão, em {area:87}, entrega a você um pacote para {npc:332}, em {zone:1453}. Aprenda {spell:921} se não tiver: esta cadeia exige.",
		["Back to Mathias Shaw"] = "De volta ao Mestre Mathias Shaw",
		["Back to {npc:4163}"] = "De volta a {npc:4163}",
		["Back to {npc:5165}"] = "De volta a {npc:5165}",
		["Head north to {zone:1453}. Shaw stands upstairs in the SI:7 building in {object:2100} (the quest says the Barracks; it means SI:7)."] = "Vá para o norte, até {zone:1453}. Shaw fica no andar de cima do prédio da SI:7, em {object:2100} (a missão diz Quartel; ela quer dizer SI:7).",
		["Head west to {area:133}. Beside the road to its entrance stands a wooden spiral tower: {npc:6886} waits stealthed on the top platform, next to a level 10 {npc:1211}, so you only see him up close."] = "Vá para o oeste, até {area:133}. Ao lado da estrada para a entrada fica uma torre de madeira em espiral: {npc:6886} espera em furtividade na plataforma de cima, ao lado de um {npc:1211} de nível 10, então você só o vê de perto.",
		["Head west to {zone:1457}. {npc:4163} is below ground in the {area:1658}: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground."] = "Vá para o oeste, até {zone:1457}. {npc:4163} fica no subterrâneo, em {area:1658}: a entrada é a abertura ao pé da árvore rachada, à esquerda da árvore do Arquidruida, perto do instrutor de sabres-da-noite. O marcador dela no mapa aparece acima do chão.",
		["Pick Pocket Sethir the Ancient for {item:7737}"] = "{item:7737}: bata a carteira de Sethir, o Antigo",
		["The {npc:6846} (level 10, a goblin) works in the dock house at {area:797}, on the river at Elwynn's southern edge, south of {area:87}. Stealth in and {spell:921} him from behind: the schedule never drops from his corpse. Do not open with {spell:2070} or a fight: he calls in three waves of bodyguards. Keep away from the fireplaces in the house; they burn you out of stealth. He is back 2 to 5 minutes after a death."] = "O {npc:6846} (nível 10, um goblin) trabalha na casa da doca de {area:797}, no rio, na ponta sul de Elwynn, ao sul de {area:87}. Entre em furtividade e use {spell:921} nele pelas costas: o cronograma nunca cai do corpo dele. Não comece com {spell:2070} nem com uma luta: ele chama três levas de guarda-costas. Fique longe das lareiras da casa; elas queimam você para fora da furtividade. Ele volta de 2 a 5 minutos depois de morrer.",
		["{item:7298} (Alliance)"] = "{item:7298} (Aliança)",
		["{npc:332}, SI:7"] = "{npc:332}, AVIN",
		["{npc:5165} is in the {object:32383}, the rogue quarter in the north of {zone:1455}: go into the building with a shady dealer outside and down the stairs."] = "{npc:5165} fica na {object:32383}, o bairro dos ladinos no norte de {zone:1455}: entre no prédio com um negociante suspeito do lado de fora e desça as escadas.",
		["{npc:6909} (level 12 satyr) lives out on a great branch north of the {area:264}: go through the V-shaped gap in the wall north of the glade and out along the branch. Pick his pocket for the journal; killing him does not give it, and a fight brings out three Minions of Sethir. He walks between the main branch and a side branch: wait stealthed at the far end of the main branch and pick him from behind when he comes back. Then {spell:2983} away. He is back 8 1/2 minutes after a death."] = "{npc:6909} (sátiro de nível 12) fica num grande galho ao norte de {area:264}: passe pela abertura em V na parede ao norte da clareira e siga pelo galho. Bata a carteira dele para pegar o diário; matá-lo não dá o diário, e uma luta faz aparecer três Lacaios de Sethir. Ele anda entre o galho principal e um galho lateral: espere em furtividade na ponta do galho principal e bata a carteira dele pelas costas quando ele voltar. Depois use {spell:2983} para sair. Ele volta 8 minutos e meio depois de morrer.",
		["{spell:921} the {npc:6846} for the {item:7675}"] = "Use {spell:921} no {npc:6846} para pegar o {item:7675}",
} end)()
t.guides["forever/class/rogue/blade-of-cunning-horde"] = (function() return {
		["A dagger at 10 from your home town's rogue quests."] = "Uma adaga no nível 10, das missões de ladino da sua cidade natal.",
		["At 10 {npc:2130}, the rogue trainer upstairs in the {area:2119} in {area:159}, sends you to {quest:1885} in the {zone:1458}."] = "No nível 10, {npc:2130}, o instrutor de ladino no andar de cima da {area:2119}, em {area:159}, manda você para {quest:1885}, na {zone:1458}.",
		["At 10 {npc:3170}, the rogue trainer in {area:362}, sends you to {quest:1859} in {zone:1454}. It is only a pointer: an Orc already in {zone:1454} can skip it and take {quest:1963} from {quest:1859} straight away."] = "No nível 10, {npc:3170}, o instrutor de ladino em {area:362}, manda você para {quest:1859}, em {zone:1454}. É só uma indicação: um orc que já está em {zone:1454} pode pular essa parte e pegar {quest:1963} direto com {quest:1859}.",
		["Back to {npc:6446}"] = "Volte a {npc:6446}",
		["Back to {npc:6467}"] = "Volte a {npc:6467}",
		["Pick Pocket Gamon for {item:7208}"] = "{item:7208}: bata a carteira de Gamon",
		["The {object:36073}"] = "{object:36073}",
		["{item:7209}, once you have the key"] = "{item:7209}, depois de ter a chave",
		["{item:7295}, from the satchel"] = "{item:7295}, da algibeira",
		["{item:7298} (Horde)"] = "{item:7298} (Horda)",
		["{npc:6446}'s reward"] = "Recompensa de {npc:6446}",
		["{npc:6467} and {npc:2425}"] = "{npc:6467} e {npc:2425}",
		["{npc:6467} sends the ledger on to {npc:2425}, the big demon in the middle of the Hall of the Dark Lady in the {object:36126}, past its elite guards; the way in is the passage off the Apothecarium. If you lose the ledger, take another from {npc:6522}'s bookshelf."] = "{npc:6467} manda o livro-razão a {npc:2425}, o demônio grande no meio do Salão da Dama Sombria, no {object:36126}, passando por seus guardas elite; o caminho é a passagem que sai do Apothecarium. Se perder o livro-razão, pegue outro na estante de {npc:6522}.",
		["{npc:6494} (level 13, not elite) is a troll pirate on the {area:391} south of {area:392}: he walks the fenced hill path between the lower pirate camp by the beached ship and the upper camp by a big tree. Fight him at the foot of the hill, away from the camps. He always drops his satchel and is back 4 1/2 minutes after a death; one satchel per kill, so two rogues need two kills. Hand the satchel in unopened: picking its lock now destroys it and you must kill him again."] = "{npc:6494} (nível 13, não elite) é um pirata troll na {area:391}, ao sul de {area:392}: ele anda pela trilha cercada do morro entre o acampamento pirata de baixo, perto do navio encalhado, e o de cima, perto de uma árvore grande. Lute com ele ao pé do morro, longe dos acampamentos. Ele sempre solta a sacola e volta 4 minutos e meio depois de morrer; uma sacola por morte, então dois ladinos precisam de duas mortes. Entregue a sacola fechada: arrombar a fechadura agora a destrói, e você teria de matá-lo de novo.",
		["{npc:6497} (level 13) walks the road between the {area:228} and the {zone:1458}, north of the {area:228}. He looks like a friendly traveller with no quest mark. Talk to him and pick both of his answers: he turns hostile. Kill him for the letter (it always drops). Fight him away from guards, who can take the kill and leave no loot; only one rogue per kill gets the letter. He is back 5 minutes after a death."] = "{npc:6497} (nível 13) anda pela estrada entre a {area:228} e a {zone:1458}, ao norte da {area:228}. Ele parece um viajante amigável, sem marca de missão. Fale com ele e escolha as duas respostas dele: ele fica hostil. Mate-o para pegar a carta (ela sempre cai). Lute com ele longe dos guardas, que podem roubar a morte e deixar sem saque; só um ladino por morte recebe a carta. Ele volta 5 minutos depois de morrer.",
		["{npc:6522} is in the Apothecarium, in its biggest room, where two huge guards watch a small bridge. His ledger is on the bookshelf in the back room behind him, not the shelf on the wall next to him."] = "{npc:6522} fica no Apothecarium, na maior sala, onde dois guardas enormes vigiam uma ponte pequena. O livro-caixa dele está na estante do quarto dos fundos, atrás dele, não na estante da parede ao lado dele.",
		["{quest:1859} hands the satchel back: now open it. {npc:6466} (level 12) kneels by the innkeeper in the inn in the {object:172982}; stealth up and pick his pocket for {item:7208} (do not kill him: the key almost never drops). Players often kill him, so you may wait up to 5 minutes for him. Then use the key on {item:7209} in your bags. If you have trained {spell:1804}, you can pick the satchel's lock instead."] = "{quest:1859} devolve a sacola: agora abra-a. {npc:6466} (nível 12) fica ajoelhado junto ao estalajadeiro, na estalagem do {object:172982}; fique furtivo e bata a carteira dele para pegar {item:7208} (não o mate: a chave quase nunca cai). Jogadores costumam matá-lo, então você pode esperar até 5 minutos por ele. Depois use a chave em {item:7209} nas bolsas. Se você treinou {spell:1804}, pode abrir a fechadura da sacola com ela.",
		["{quest:1859} stands in the {object:172960}, the canyon under the {object:172982}. Trolls: take {quest:1963} from him at 10."] = "{quest:1859} fica na {object:172960}, o cânion sob o {object:172982}. Trolls: peguem {quest:1963} com ele no nível 10.",
		["{quest:1885} stands in the {object:36073}."] = "{quest:1885} fica no {object:36073}.",
} end)()
t.guides["forever/class/rogue/certificate-of-thievery"] = (function() return {
		["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165} in {zone:1455}'s {object:32383}."] = "No nível 16, {npc:1234}, na {area:2102}, em {area:131}, manda você para {npc:5165}, na {object:32383} de {zone:1455}.",
		["At 16 {npc:3599} in the {area:186} inn sends you to {quest:2259} in {zone:1457}."] = "No nível 16, {npc:3599}, na estalagem de {area:186}, manda você para {quest:2259}, em {zone:1457}.",
		["At 16 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}. Taking it shuts out the other towns' breadcrumbs."] = "No nível 16, {npc:917}, o instrutor de ladino no andar de cima da Estalagem Orgulho do Leão, em {area:87}, manda você para {npc:6946}, em {zone:1453}. Pegar esta fecha as indicações das outras cidades.",
		["Back to {npc:6966}"] = "De volta a {npc:6966}",
		["Head east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} stands on a crate on one of the {area:69} docks, south of town; he gives you {item:5060} with the job ({npc:3090} in {area:69} sells more). {spell:1804} does not work without the tools in your bags."] = "Vá para o leste, atravessando {zone:1429}, até Cristarrubra, ou voe para {area:69}. {npc:6966} fica em cima de um caixote numa das docas de {area:69}, ao sul da cidade; ele entrega {item:5060} junto com o trabalho ({npc:3090}, em {area:69}, vende mais). {spell:1804} não funciona sem as ferramentas nas suas bolsas.",
		["Your first lockpicking job at 16: {npc:6966}'s lockbox at {quest:2282}, for {quest:2300}."] = "Seu primeiro serviço de arrombamento no nível 16: o cofre de {npc:6966} em {quest:2282}, para a {quest:2300}.",
		["{npc:4214} stands in the {area:1658}. Then the boat from {area:702} to {area:442}, and the boat from {area:442} to {area:17203}."] = "{npc:4214} fica em {area:1658}. Depois pegue o barco de {area:702} até {area:442} e o barco de {area:442} até {area:17203}.",
		["{npc:5165} is in the house with a shady dealer outside, in the {object:32383}, down the stairs. Then fly or take the {area:2257} to {zone:1453}."] = "{npc:5165} fica na casa com um negociante suspeito do lado de fora, na {object:32383}, descendo as escadas. Depois voe ou pegue o {area:2257} até {zone:1453}.",
		["{npc:6946} stands upstairs in the {quest:2300} building in {object:2100}, behind the rogue trainers. Before you leave: if you lack {spell:1804}, {npc:13283} in the {quest:2300} building teaches it; Lockpicking is the test of the next quest."] = "{npc:6946} fica no andar de cima do prédio de {quest:2300}, em {object:2100}, atrás dos instrutores de ladino. Antes de sair: se você não tem {spell:1804}, {npc:13283}, no prédio de {quest:2300}, ensina; Arrombamento é o teste da próxima missão.",
		["{quest:2282} stands east of {area:69}, up off the road; Blackrock orcs roam near it. Inside, the Practice Lockboxes come back almost at once: pick them until {object:121264} opens for you (about 25 Lockpicking). Your Lockpicking cap rises 5 per level, so a low character may stall. Some boxes are trapped (a frost trap, for one); the skill still goes up. On Forever level 20 spiders wander near the boxes: clear them first or bring a friend. The lockbox always holds the token and is back two seconds after use. Practise on while it still gives skill: the next class quest needs about 75."] = "{quest:2282} fica a leste de {area:69}, subindo a partir da estrada; orcs da Rocha Negra rondam por perto. Lá dentro, os Cofres de Treino voltam quase na hora: arrombe-os até {object:121264} abrir para você (cerca de 25 de Arrombamento). O teto do seu Arrombamento sobe 5 por nível, então um personagem de nível baixo pode travar. Alguns cofres têm armadilha (uma armadilha de gelo, por exemplo); a habilidade sobe do mesmo jeito. No Forever, aranhas de nível 20 andam perto dos cofres: limpe-as primeiro ou leve um amigo. O cofre sempre guarda a ficha e volta dois segundos depois de usado. Continue treinando enquanto ainda der perícia: a próxima missão de classe pede cerca de 75.",
} end)()
t.guides["forever/class/rogue/plundering-the-plunderers"] = (function() return {
		["At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}."] = "No nível 16, {npc:3170}, o instrutor de ladinos em {area:362}, manda você até {npc:3401} em {zone:1454}.",
		["At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide."] = "No nível 16, {npc:6467} no {object:36073} manda você até {npc:3401} em {zone:1454}. Pegue também {quest:1998} com ele; ela é feita em {zone:1421} no fim deste guia.",
		["Back to {npc:6467}"] = "De volta a {npc:6467}",
		["Back to {npc:7161}"] = "De volta a {npc:7161}",
		["Fly or walk to {area:392} on the {zone:1413} coast. {npc:7161} stands in a small shed near the bank, up the hill to the left before the docks. His Gizmotronic Apparatus beside him hands out what the job needs: take an {item:7970} and {item:5060} ({spell:1804} does not work without the tools in your bags)."] = "Voe ou ande até {area:392}, na costa de {zone:1413}. {npc:7161} fica num galpão pequeno perto do banco, subindo o morro à esquerda antes das docas. O Aparato Gizmotrônico ao lado dele entrega o que o trabalho precisa: pegue {item:7970} e {item:5060} ({spell:1804} não funciona sem as ferramentas nas suas bolsas).",
		["Follow the coast south from {area:392} to the first beached pirate ship, the Tide Razor, and climb aboard up its bow. On the middle deck the Buccaneer's Strongboxes come back fast: pick them until your Lockpicking is about 30 (a few are trapped with a frost nova or turn you into a rat; picking still works as a rat). Keep picking while they still give skill: the poisons job at 20 ends at a lockbox that needs about 75, and these boxes are the closest practice. Then go down to the bottom hold and pick the lock of {object:123462}: it is empty, but opening it calls a giant level 50 {npc:7168} into the next room. Stay stealthed, put the {item:7970} on your action bar, target {npc:7168} and use it: the parrot shrinks to level 18. Kill it for the {item:7968}."] = "Siga a costa para o sul de {area:392} até o primeiro navio pirata encalhado, o Tide Razor, e suba a bordo pela proa. No convés do meio, as Caixas-fortes dos Bucaneiros voltam rápido: abra-as até o seu Arrombamento chegar a cerca de 30 (algumas têm armadilha de Nova de Gelo ou transformam você em rato; arrombar ainda funciona como rato). Continue abrindo enquanto elas ainda dão habilidade: o serviço dos venenos no nível 20 termina numa caixa trancada que exige cerca de 75, e estas caixas são o treino mais próximo. Depois desça até o porão e arrombe a fechadura de {object:123462}: está vazio, mas abri-lo chama um {npc:7168} gigante de nível 50 para a sala ao lado. Fique furtivo, ponha o {item:7970} na sua barra de ação, selecione {npc:7168} e use-o: o papagaio encolhe para o nível 18. Mate-o para pegar o {item:7968}.",
		["If you have no {item:5060} left, ask {npc:6566}, the outfitter in the {object:36073}."] = "Se você não tiver mais {item:5060}, peça a {npc:6566}, a fornecedora no {object:36073}.",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and head south into Silverpine. {quest:1998} (level 16) stands alone on the old ferry dock on {area:1338}, north-east of the {area:228}. His Uppercut knocks you back, so do not fight him at the dock's edge. He always drops his head and is back 4 1/2 minutes after a death."] = "Pegue o zepelim de {zone:1454} até a {zone:1458} e siga para o sul, rumo a Pinhaprata. {quest:1998} (nível 16) fica sozinho na velha doca da balsa em {area:1338}, a nordeste da {area:228}. O Golpe Ascendente dele empurra você para trás, então não lute com ele na beira da doca. Ele sempre solta a cabeça e volta 4 minutos e meio depois de morrer.",
		["Ten {item:7676}, the rogue energy drink, from the Horde lockpicking jobs at 16."] = "Dez {item:7676}, a bebida de energia dos ladinos, dos trabalhos de arrombamento da Horda no nível 16.",
		["The Kirin Tor keep their reports in walled {area:233}, in south-east Silverpine. Facing the town hall, take the building on the right: the {object:103815} is in a corner room upstairs (any Lockpicking opens it; the {item:5060} must be in your bags). Three casters of level 19-20 guard that floor and see through stealth, one walking in and out of the strongbox room: time it or fight them one at a time."] = "O Kirin Tor guarda os relatórios em {area:233}, cercada de muros, no sudeste de Pinhaprata. De frente para a prefeitura, entre no prédio da direita: {object:103815} fica num quarto de canto no andar de cima (qualquer Arrombamento abre; {item:5060} precisa estar nas suas bolsas). Três conjuradores de nível 19-20 guardam aquele andar e enxergam através da furtividade, e um deles entra e sai da sala do cofre: marque o tempo ou lute com eles um de cada vez.",
		["Undead take the zeppelin from the towers outside the {zone:1458} to {zone:1411}. {npc:3401} and {quest:2379} stand in the {object:172960}, the canyon under the {object:172982}. Train {spell:1804} from {npc:3401} (or any rogue trainer) now if you lack it: this job is a lockpicking test."] = "Mortos-vivos pegam o zepelim das torres fora da {zone:1458} até {zone:1411}. {npc:3401} e {quest:2379} ficam na {object:172960}, o cânion sob o {object:172982}. Aprenda {spell:1804} com {npc:3401} (ou qualquer instrutor de ladino) agora, se não tiver: este serviço é um teste de arrombamento.",
		["{item:7968}: {npc:7168}, after the {item:7970}"] = "{item:7968}: {npc:7168}, depois de {item:7970}",
		["{npc:3401} and {quest:2379}"] = "{npc:3401} e {quest:2379}",
		["{npc:7161}: ten {item:7676}"] = "{npc:7161}: dez {item:7676}",
} end)()
t.guides["forever/class/rogue/poisons-alliance"] = (function() return {
		["/lay with the Doc targeted"] = "/lay com o Doutor selecionado",
		["All four are in {zone:1453}. {item:3421}: Bernard or {npc:1303}'s flower shop by the {object:2096} canal. A {item:3372}: many general goods and alchemy vendors ({npc:1257}, {npc:1325} and others). A {item:4371}: the Auction House in the {object:2096}; the engineering suppliers keep only one and are nearly always sold out, and an engineer can make one. The {item:8431} lies on the floor beside the left end of the counter in {object:2177}, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an {item:6452} ({skill:129}) or a druid's {spell:526} also clears the {spell:9810}."] = "Todos os quatro estão em {zone:1453}. {item:3421}: Bernardo ou a floricultura de {npc:1303}, perto do canal do {object:2096}. Um {item:3372}: muitos vendedores de bens gerais e de alquimia ({npc:1257}, {npc:1325} e outros). Um {item:4371}: a Casa de Leilões no {object:2096}; os fornecedores de engenharia só mantêm um e quase sempre estão sem estoque, e um engenheiro pode fazer um. O {item:8431} fica no chão ao lado da ponta esquerda do balcão em {object:2177}, a alfaiataria nos canais; só dá para pegá-lo com esta missão. Se você pular a cura, um {item:6452} ({skill:129}) ou o {spell:526} de um druida também remove {spell:9810}.",
		["At 20 {npc:332}, upstairs in the SI:7 building in {object:2100}, sends you to {npc:7024} in {zone:1436}. This chain is how you learn Poisons on Forever, so do not skip it."] = "No nível 20, {npc:332}, no andar de cima do prédio da SI:7, em {object:2100}, manda você para {npc:7024}, em {zone:1436}. Esta cadeia é como se aprende Venenos no Forever, então não pule.",
		["Back to {npc:7207}"] = "De volta a {npc:7207}",
		["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "O Forever ensina Venenos por esta cadeia, não pelo instrutor; a receita de {item:7676} vem junto.",
		["Get the key first. The {npc:7051} (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and {spell:921} it from behind: it always has the key. It hits hard: if stealth breaks, {spell:2983} away. Watch for the pair of Defias Drones that also patrol."] = "Pegue a chave primeiro. O {npc:7051} (nível 23, não elite) começa na entrada da torre e dá uma volta por fora; é o de cabelo espetado, deixando um rastro de faíscas amarelas. Entre em furtividade e use {spell:921} nele pelas costas: ele sempre tem a chave. Ele bate forte: se a furtividade quebrar, use {spell:2983} para sair. Cuidado com o par de Parasitas Défias que também patrulha.",
		["Head north through Elwynn to {zone:1453}; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the {item:7676} recipe. Poisons are made, not bought: each batch of {item:6947} takes a {item:2928} and an {item:3371}, which {npc:1325} and {npc:1326} sell in {object:2100} next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon."] = "Vá para o norte por Elwynn até {zone:1453}; Mathias Shaw fica no andar de cima da SI:7. Ele ensina Venenos e entrega a receita de {item:7676}. Venenos são fabricados, não comprados: cada lote de {item:6947} leva {item:2928} e {item:3371}, que {npc:1325} e {npc:1326} vendem em {object:2100}, ao lado da SI:7. Compre uma pilha de cada, abra Venenos pelo grimório para fabricar e depois use um veneno na sua arma.",
		["Kearnen hides stealthed against the west side of a big tree with two small trees in front of it, just north of {npc:7053}'s Defias tower in the far east of {zone:1436}, by the {zone:1431} border. Read {item:8046} for the tower's layout if you like."] = "Kearnen se esconde em furtividade encostado no lado oeste de uma árvore grande com duas árvores pequenas na frente, logo ao norte da torre dos Défias de {npc:7053}, no extremo leste de {zone:1436}, na divisa com {zone:1431}. Leia {item:8046} para ver a planta da torre, se quiser.",
		["Klaven's journal"] = "O diário de Filipe Pinel",
		["Poisons (Alliance)"] = "Venenos (Aliança)",
		["Sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. {npc:7053}, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The {object:123214} beside his desk needs Lockpicking of about 70-75 (practise on the boxes at {area:97} in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the {spell:9810}, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out."] = "Suba a torre em silêncio. Patrulheiros da Torre Défias (23) e Sentinelas (24) guardam os andares; uma Emboscada com adaga mata na hora, se você preferir limpar. {npc:7053}, um elite de nível 26, espera no último andar: use Sap nele, ou leve um amigo. {object:123214}, ao lado da mesa dele, pede Arrombamento de uns 70-75 (treine antes nas caixas de {area:97}, em Cristarrubra). Um truque: enquanto as Sentinelas estão longe, pule da cadeira para o lampião e dele para a estante acima do baú, saia da furtividade e abra o baú de lá. Abri-lo envenena você com {spell:9810}, o que interrompe sua furtividade por um tempo e deixa o parasita ver você; é por isso que a chave vem primeiro. Depois saia.",
		["The cure's ingredients"] = "Os ingredientes da cura",
		["The {item:7923}"] = "{item:7923}",
		["{item:4371}: the Auction House"] = "{item:4371}: a Casa de Leilões",
		["{item:7908}: the {object:123214}, top floor"] = "{item:7908}: {object:123214}, último andar",
		["{npc:332}: Poisons"] = "{npc:332}: Venenos",
		["{quest:2607} still sits on you. {npc:7207} works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind {npc:1325}. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down."] = "{quest:2607} ainda está com você. {npc:7207} trabalha no porão do prédio da SI:7: a escada para baixo fica embaixo da escada para o andar de cima, atrás de {npc:1325}. Selecione-o como alvo e digite /lay (nada depois) para ser examinado, depois espere. Se ele não fizer nada, abandone a missão, pegue de novo e espere até ele pedir que você se deite.",
		["{spell:921} the {npc:7051} for the {item:7923}"] = "Use {spell:921} no {npc:7051} para pegar a {item:7923}",
} end)()
t.guides["forever/class/rogue/poisons-horde"] = (function() return {
		["/salute {npc:3401}"] = "/saudar {npc:3401}",
		["Back to {npc:3401}"] = "De volta a {npc:3401}",
		["Fly back to {zone:1454} ({area:392} or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep {item:8072} afterwards. Before you leave the {area:263}, buy {item:2928} and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of {item:6947} takes one of each."] = "Voe de volta a {zone:1454} ({area:392} ou a Encruzilhada; morrer na torre e voltar pelo curandeiro espiritual até a Encruzilhada é mais rápido). Fique com {item:8072} depois. Antes de sair de {area:263}, compre {item:2928} e Ampolas Vazias de Rekkol: quando Hinoto ensinar Venenos, cada lote de {item:6947} gasta um de cada.",
		["Fly to the Crossroads and head north to the Venture Co. tower above the {area:382}. Fizzule stands under a tree east of the tower, outside it, and is hostile until signalled. Target him from about 50 yards and fire the {item:8051} twice, then walk up in front of him and /salute. In any other order he attacks. Lost the {item:8051}? Abandon and retake from {npc:3401}."] = "Voe até a Encruzilhada e siga para o norte até a torre da Empreendimentos S.A. acima de {area:382}. Arruela fica sob uma árvore a leste da torre, do lado de fora, e é hostil até ser sinalizado. Selecione-o a cerca de 50 metros e dispare o {item:8051} duas vezes, depois ande até ficar na frente dele e use /saudar. Em qualquer outra ordem ele ataca. Perdeu o {item:8051}? Abandone e pegue de novo com {npc:3401}.",
		["Forever teaches Poisons through this chain, not the trainer; the {item:7676} recipe comes with it."] = "O Forever ensina Venenos por esta cadeia, não pelo instrutor; a receita de {item:7676} vem junto.",
		["Inside, floor by floor (everything comes back after 4 1/2 minutes): the Mutated Venture Co. Drones (level 25) on the ground floor die to one Ambush with a dagger; the Patrollers on the second floor take half their health from a one-point {spell:1943}; the Lookouts on the open third floor from a one-point {spell:2098}. {npc:7288} waits on the top floor: a level 23 elite, back 10 minutes after a kill. Open with Ambush (about half his health), then {spell:1776}, {spell:5277}, a healing potion and {item:7676}; a friend makes it easy. One head per kill. Then pick {object:129127} beside him for the cache: it poisons you with the {spell:9810}, which weakens your stealth and agility until {npc:2391} cures it."] = "Lá dentro, andar por andar (tudo volta depois de 4 minutos e meio): os Parasitas Mutantes da Empreendimentos S.A. (nível 25) do térreo morrem com uma Emboscada de adaga; os Patrulheiros do segundo andar perdem metade da vida com um {spell:1943} de um ponto; os Vigias do terceiro andar, aberto, com um {spell:2098} de um ponto. {npc:7288} espera no último andar: um elite de nível 23, que volta 10 minutos depois de morrer. Comece com Emboscada (cerca de metade da vida dele), depois {spell:1776}, {spell:5277}, uma poção de cura e {item:7676}; com um amigo, fica fácil. Uma cabeça por morte. Depois arrombe {object:129127}, ao lado dele, para pegar o esconderijo: ele envenena você com {spell:9810}, que enfraquece sua furtividade e sua agilidade até {npc:2391} curar.",
		["Keep {item:8066} in your bags and use it on him every time you come near, or he turns hostile. {npc:7287} (level 22) walks by the tower: hug the wall, stealth up behind him and {spell:921} the key. Killing him does not give it; if his pockets are empty, kill him and wait 4 1/2 minutes for him to come back."] = "Mantenha {item:8066} nas bolsas e use nele toda vez que chegar perto, senão ele fica hostil. {npc:7287} (nível 22) passa perto da torre: encoste na parede, entre em furtividade atrás dele e use {spell:921} para pegar a chave. Matá-lo não dá a chave; se os bolsos dele estiverem vazios, mate-o e espere 4 minutos e meio até ele voltar.",
		["Lockpicking about 75: pick the Buccaneer's Strongboxes on the Tide Razor"] = "Arrombamento de uns 75: arrombe as Caixas-fortes dos Bucaneiros no Tide Razor",
		["Lockpicking practice"] = "Treino de arrombamento",
		["Pick Pocket Foreman Silixiz for {item:8072}"] = "{item:8072}: bata a carteira do Capataz Biela",
		["Poisons (Horde)"] = "Venenos (Horda)",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and follow the road south through {zone:1421} into {area:287}, to {area:272}. {npc:2391} works in the building next to the flight path, beside {npc:2216}, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from {npc:3401}. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make {item:6947} from Rekkul's dust and vials, and use it on your weapon."] = "Pegue o zepelim de {zone:1454} até a {zone:1458} e siga a estrada para o sul, por {zone:1421}, rumo a {area:287}, até {area:272}. {npc:2391} trabalha no prédio ao lado do ponto de voo, ao lado de {npc:2216}, uma carroça lá fora. Se perdeu a Amostra do Preparado de Zanzil, abandone e pegue de novo com {npc:3401}. Fique ao lado dele por cerca de um minuto enquanto ele prepara a cura; se nunca terminar, abandone e pegue de novo com ele. Depois abra Venenos pelo grimório para fabricar {item:6947} com o pó e as ampolas de Rekkol, e use na sua arma.",
		["The Venture Co. tower"] = "A torre da Empreendimentos S.A.",
		["Tide Razor"] = "Tide Razor",
		["Wait for the cure"] = "Espere pela cura",
		["{item:8051}, twice, at Fizzule"] = "{item:8051}, duas vezes, em Arruela",
		["{item:8074}: {npc:7288} (elite)"] = "{item:8074}: {npc:7288} (elite)",
		["{item:8095}: clears the {spell:9810}"] = "{item:8095}: remove {spell:9810}",
		["{npc:2391}: Poisons"] = "{npc:2391}: Venenos",
		["{npc:3401} stands in the {object:172960}, the canyon under the {object:172982}. Take the quest and wait: he speaks three lines and salutes you. After his third line, target him and type /salute. If it does not count, abandon the quest and take it again. The tower job ahead is built around Ambush, which needs a dagger: if you have none, Kareth, the blade merchant in the {object:172960}, sells a Jambiya."] = "{npc:3401} fica na {object:172960}, o cânion sob o {object:172982}. Pegue a missão e espere: ele diz três falas e faz continência para você. Depois da terceira fala, selecione-o e digite /saudar. Se não contar, abandone a missão e pegue de novo. O serviço da torre adiante gira em torno de Emboscada, que exige uma adaga: se você não tiver nenhuma, Kareth, o vendedor de lâminas na {object:172960}, vende uma Jambiya.",
		["{object:129127} at the end of the tower job needs Lockpicking of about 70-75. Train {spell:1804} from Gest or {npc:3401} in the {object:172960} if you lack it, carry {item:5060}, and pick the Buccaneer's Strongboxes on the middle deck of the Tide Razor, the beached pirate ship south of {area:392}: they come back fast. Your cap rises 5 per level."] = "{object:129127}, no fim do serviço da torre, exige Arrombamento de cerca de 70-75. Aprenda {spell:1804} com Gest ou com {npc:3401} na {object:172960}, se não tiver, leve {item:5060} e abra as Caixas-fortes dos Bucaneiros no convés do meio do Tide Razor, o navio pirata encalhado ao sul de {area:392}: elas voltam rápido. Seu limite sobe 5 por nível.",
		["{quest:2458}: keep the {item:8051}"] = "{quest:2458}: guarde a {item:8051}",
} end)()
t.guides["forever/class/rogue/ravenholdt"] = (function() return {
		["At 24 any capital's rogue trainer ({npc:332} or {npc:918} in {zone:1453}, Gest or Ormok in {zone:1454}, and the others) has an {item:17126} from {npc:13936} for you: ask for it in their talk window. Open it: the quest gives you the {item:17125} for {npc:6707}. Learn {spell:1846} from your trainer first if you have not; the way in is a test of it."] = "No nível 24, o instrutor de ladino de qualquer capital ({npc:332} ou {npc:918}, em {zone:1453}, Gest ou Ormok, em {zone:1454}, e os demais) tem para você {item:17126}, de {npc:13936}: peça na janela de conversa. Abra: a missão entrega {item:17125} para {npc:6707}. Aprenda {spell:1846} com seu instrutor antes, se ainda não aprendeu; o caminho até lá é um teste dela.",
		["Back to {npc:13085}"] = "De volta a {npc:13085}",
		["Back to {npc:13085}; the report sends you after the Perenolde heirlooms. Two towers stand among the {area:281}, in the middle of the {zone:1416}, held by ogres: the shield lies in the northern tower, the sword in the southern one, which elite ogres ring and watch from far off. Stay stealthed; nothing guards the heirlooms inside."] = "De volta a {npc:13085}; o relatório manda você atrás das relíquias dos Perenolde. Duas torres ficam entre {area:281}, no meio de {zone:1416}, ocupadas por ogros: o escudo está na torre do norte, a espada na do sul, que é cercada de ogros elite e vigiada de longe. Fique em furtividade; nada guarda as relíquias lá dentro.",
		["Falconcrest's men make the handoff at the southern end of {area:1057}, the old wall between Arathi and {area:287}. Kill the two guarding the box and take the {item:275882}. Keep the {item:275706}: {npc:13085} wants it back with the shipment."] = "Os homens de Falcocrista fazem a entrega na ponta sul de {area:1057}, a velha muralha entre Arathi e {area:287}. Mate os dois que guardam a caixa e pegue {item:275882}. Guarde {item:275706}: {npc:13085} quer de volta, junto com a carga.",
		["Horde fly to {area:272}, Alliance to {area:271}. The trail to the manor is hard to see: it starts behind the plateau north of {area:275}, east of {area:272}, climbs into the hills and bends twice to a small tunnel. A chest sits in the tunnel: do not open it. Cast {spell:1846} near it and walk up close; that is the Rite of Cunning (it comes back after 5 minutes). Opening the chest calls Milton, an elite rogue of about level 32. Through the tunnel lies {area:3486}: {npc:6707} is upstairs inside. Do not attack anyone at the manor: it costs {npc:13936} reputation."] = "A Horda voa para {area:272}, a Aliança para {area:271}. A trilha até a mansão é difícil de ver: começa atrás do planalto ao norte de {area:275}, a leste de {area:272}, sobe pelas colinas e faz duas curvas até um túnel pequeno. Há um baú no túnel: não abra. Lance {spell:1846} perto dele e chegue bem perto; isso é o Rito da Astúcia (volta depois de 5 minutos). Abrir o baú chama Milton, um ladino elite de uns nível 32. Depois do túnel fica {area:3486}: {npc:6707} está lá dentro, no andar de cima. Não ataque ninguém na mansão: isso custa reputação com {npc:13936}.",
		["In your mid 30s {npc:13085} has two more jobs; take both. Barton leads a Syndicate scouting party at {area:280}, in the east of the {zone:1416}, inside one of the houses with stealthed Syndicate around him. Pick his pocket for the report and do not kill him: he does not drop it. If you are lower than him he sees through stealth; Master of Deception helps, or Distract him, Vanish and come in from behind. {spell:921} can miss several times in a row."] = "Perto do nível 35, {npc:13085} tem mais dois trabalhos; pegue os dois. Barton lidera um grupo de reconhecimento da Camarilha em {area:280}, no leste de {zone:1416}, dentro de uma das casas, com a Camarilha em furtividade ao redor dele. Bata a carteira dele para pegar o relatório e não o mate: ele não solta. Se você tem nível menor que o dele, ele enxerga através da furtividade; Mestre da Enganação ajuda, ou use Distração, Sumir e entre por trás. {spell:921} pode errar várias vezes seguidas.",
		["Opens {area:3486}, the hidden rogue house in the Alterac hills, and {npc:13085}'s jobs against the Syndicate."] = "Abre {area:3486}, a casa secreta dos ladinos nas colinas de Alterac, e os trabalhos de {npc:13085} contra a Camarilha.",
		["Pick Pocket Barton for {item:275482}"] = "{item:275482}: bata a carteira de Barton",
		["Pick Pocket Syndicate members for {quest:6701}"] = "{quest:6701}: bata a carteira de membros da Camarilha",
		["Rite of Cunning: {spell:1846} beside the tunnel chest"] = "Rito da Astúcia: {spell:1846} ao lado do baú do túnel",
		["She will not talk without something to bargain with. Her stash is upstairs in a house close to the keep: take the {item:275709}. If it is already open, wait for it to come back."] = "Ela não fala sem ter o que negociar. O esconderijo dela fica no andar de cima de uma casa perto da fortaleza: pegue {item:275709}. Se já estiver aberto, espere voltar.",
		["Stromgarde's Syndicate Prowlers and Conjurors are elite (level 35-36): a rogue of 36 can slip past them, but fighting one alone is hard, so stay hidden or bring a friend. Put on the {item:275706} ({quest:96784} hands it to you at the footlocker) to pass as one of them; stealth or suspicious acts can break it. If the footlocker gave you no uniform, Anastasia hands you one with {quest:96785}. {npc:266847} is not inside the keep: she stands on a ledge on the outside of the castle wall. Jump across to it from the roof of the house beside the ledge."] = "Os Predadores e Conjuradores da Camarilha de Stromgarde são elite (nível 35-36): um ladino de nível 36 consegue passar por eles, mas lutar com um sozinho é difícil, então fique escondido ou leve um amigo. Vista {item:275706} ({quest:96784} entrega no baú) para passar por um deles; furtividade ou atos suspeitos podem quebrar o disfarce. Se o baú não deu o uniforme, Anastácia entrega um com {quest:96785}. {npc:266847} não está dentro da fortaleza: ela fica numa saliência do lado de fora da muralha do castelo. Pule até ela a partir do telhado da casa ao lado da saliência.",
		["The {item:17126}"] = "A {item:17126}",
		["{area:324} in western Arathi is a Syndicate stronghold; to get in you need a uniform. {area:313}, in north-western Arathi, is held by Syndicate Highwaymen, Pathstalkers and Mercenaries (level 30-32): find the {object:656157} there and take the uniform; that ends {quest:96783}."] = "{area:324}, no oeste de Arathi, é uma fortaleza da Camarilha; para entrar, você precisa de um uniforme. {area:313}, no noroeste de Arathi, é ocupada por Bandoleiros, Tocaiantes e Mercenários da Camarilha (nível 30-32): ache {object:656157} ali e pegue o uniforme; isso encerra {quest:96783}.",
		["{item:275635}, in the southern tower"] = "{item:275635}, na torre do sul",
		["{item:275636}, in the northern tower"] = "{item:275636}, na torre do norte",
		["{item:275709}: Anastasia's Stash"] = "{item:275709}: o esconderijo de Anastácia",
		["{npc:13085}: 70 silver, 300 {npc:13936} reputation"] = "{npc:13085}: 70 pratas, 300 de reputação com {npc:13936}",
		["{npc:13936} reputation"] = "Reputação com {npc:13936}",
		["{npc:266216} is inside {area:275}, the Syndicate fortress south of the manor; he can stand in any of fifteen spots in the keep, so search. Quick and quiet, says {npc:13085}. Pick the pockets of the level 20-21 Syndicate Rogues, Shadow Mages and Watchmen on your way: they carry {quest:6701} for the guards' repeatable reputation quest."] = "{npc:266216} está dentro de {area:275}, a fortaleza da Camarilha ao sul da mansão; ele pode estar em qualquer um de quinze pontos da fortaleza, então procure. Rápido e em silêncio, diz {npc:13085}. Bata a carteira dos Ladinos da Camarilha, Magos das Sombras e Vigias de nível 20-21 pelo caminho: eles carregam {quest:6701}, para a missão repetível de reputação dos guardas.",
		["{npc:6766}: one emblem each time, 100 reputation"] = "{npc:6766}: um emblema por vez, 100 de reputação",
		["{npc:6766}: {quest:6701}, repeatable; take it now, the emblems are quest items"] = "{npc:6766}: {quest:6701}, repetível; pegue agora, os emblemas são itens de missão",
		["{quest:96784}: the {item:275706}"] = "{quest:96784}: {item:275706}",
} end)()
t.guides["forever/class/rogue/the-azure-key"] = (function() return {
		["Alliance fly to {area:3137}, Horde to {area:1237}. Only the level 50-51 Timbermaw Shamans in the furbolg hills of northern {zone:1447} carry the bag (the level 47-49 furbolgs further south do not): about one kill in thirty drops it. {spell:921} them instead and you lose no Timbermaw reputation; if you are Unfriendly or better with {area:1769}, mark them At War in your reputation panel first. They cast {spell:403} and {spell:6535}, heal each other and run at low health."] = "A Aliança voa para {area:3137}, a Horda para {area:1237}. Só os Xamãs Presamatos de nível 50-51, nas colinas dos furbolgs do norte de {zone:1447}, carregam a bolsa (os furbolgs de nível 47-49 mais ao sul, não): cerca de uma morte em trinta solta. Use {spell:921} neles em vez de matar e você não perde reputação com os Presamatos; se você é Inamistoso ou melhor com {area:1769}, marque-os como Em Guerra no painel de reputação antes. Eles lançam {spell:403} e {spell:6535}, curam uns aos outros e fogem com pouca vida.",
		["At 50 {npc:3328} in the {object:172960} has it; so does {npc:4583} in the {zone:1458}'s {object:36073}."] = "No nível 50, {npc:3328} na {object:172960} a tem; assim como {npc:4583} no {object:36073} de {zone:1458}.",
		["At 50 {npc:918} in {zone:1453}'s {object:2100} has it; so do Syurna in {zone:1457} and {npc:5165} in {zone:1455}."] = "No nível 50, {npc:918}, em {object:2100}, em {zone:1453}, tem esta; Syurna, em {zone:1457}, e {npc:5165}, em {zone:1455}, também.",
		["Back to Xylem"] = "De volta a Tauriel",
		["Look at the reward window before you hand in: Classic offered the {item:19982}, the {item:19984} or the {item:20255}, and Forever's notes say the choice may be gone."] = "Olhe a janela de recompensa antes de entregar: o Classic oferecia {item:19982}, {item:19984} ou {item:20255}, e as notas do Forever dizem que a escolha pode ter sumido.",
		["Lord Ravenholdt"] = "Lorde Ravenholdt",
		["Morphaz in the {area:1417}"] = "Morphaz no {area:1417}",
		["Morphaz, a level 52 elite green drake, lives deep in the {area:1417}: a group of five, level 50-54. The temple stands in the {area:74}; climb into the sunken building, swim down through it and follow the passage to the portal. Horde: fly to {area:75}; Alliance: fly to {area:1438} and ride on. He is not there when you arrive: first kill the six troll guardians (elites of 50-52) on the platforms around the upper ring, which opens the way down (the left-hand ramp from the entrance) to {npc:5710} in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe; when both are dead, Morphaz and Hazzas appear together and fight as a pair. Their {spell:12533} is nature damage: nature protection potions help; poisons and {spell:2094} do not work on them. The key always drops. Hunters, Priests and Mages of 50 need Morphaz too: one clear serves them all."] = "Morphaz, um dragão verde elite de nível 52, mora no fundo de {area:1417}: um grupo de cinco, nível 50-54. O templo fica em {area:74}; entre no prédio afundado, nade para baixo por ele e siga a passagem até o portal. Horda: voe para {area:75}; Aliança: voe para {area:1438} e continue cavalgando. Ele não está lá quando você chega: primeiro mate os seis guardiões trolls (elites de 50-52) nas plataformas do anel de cima, o que abre o caminho para baixo (a rampa da esquerda a partir da entrada) até {npc:5710}, no Fosso do Sacrifício. A morte de Jammal'an traz dois dragonetes, Tecelão e Darquimeros; quando os dois morrem, Morphaz e Hazzas aparecem juntos e lutam em dupla. O {spell:12533} deles é dano de natureza: poções de proteção contra a natureza ajudam; venenos e {spell:2094} não funcionam neles. A chave sempre cai. Caçadores, Sacerdotes e Magos de nível 50 também precisam de Morphaz: uma limpeza serve a todos.",
		["Ravenholdt reputation"] = "Reputação com Ravenholdt",
		["Ravenholdt reputation and experience at 50; Classic's item choice may be gone on Forever."] = "Reputação com Corvoforte e experiência no nível 50; a escolha de item do Classic pode ter sumido no Forever.",
		["The Forest Oozes (level 52-53, {spell:6907} up close) drop a fragment four times in five: the biggest group, seven of them, is in the {area:2497} hills of north-eastern {zone:1447}, four more south-east of {area:1237}. Pick their pockets before the kill for an extra fragment or two. Killing the Mistwing Ravagers and hippogryphs that share their spots makes more oozes appear."] = "As Gosmas Florestais (nível 52-53, {spell:6907} de perto) soltam um fragmento quatro vezes em cinco: o maior grupo, de sete, fica nas colinas de {area:2497}, no nordeste de {zone:1447}, e mais quatro ao sudeste de {area:1237}. Bata a carteira delas antes de matar para ganhar um fragmento ou dois a mais. Matar os Assoladores Alanévoa e os hipogrifos que dividem os mesmos pontos faz aparecer mais gosmas.",
		["{area:3486} hides in the hills east of {area:272}. Horde fly to {area:272}, Alliance to {area:271}. The trail starts behind the plateau north of {area:275}, climbs into the hills and runs through a small tunnel into the {zone:1416}; Lord Jorach is inside the manor. Do not attack anyone at the manor: lost Ravenholdt reputation makes him refuse to speak to you."] = "{area:3486} fica escondida nas colinas a leste de {area:272}. A Horda voa para {area:272}, a Aliança para {area:271}. A trilha começa atrás do planalto ao norte de {area:275}, sobe pelas colinas e passa por um túnel pequeno até {zone:1416}; Lord Jorach está dentro da mansão. Não ataque ninguém na mansão: perder reputação com Corvoforte faz com que ele se recuse a falar com você.",
		["{item:20022}: Morphaz, inside the temple"] = "{item:20022}: Morphaz, dentro do templo",
		["{npc:8395}, camped below the cliffs just east of {area:1237}, teleports you up (dismount first); a trail leads to Xylem's tower."] = "{npc:8395}, acampado embaixo dos penhascos, logo a leste de {area:1237}, teletransporta você para cima (desmonte antes); uma trilha leva à torre de Xylem.",
		["{quest:8233} (Alliance)"] = "{quest:8233} (Aliança)",
		["{quest:8233} (Horde)"] = "{quest:8233} (Horda)",
} end)()
t.guides["forever/class/rogue/the-eye-of-bhossca"] = (function() return {
		["Back to the dead drop"] = "De volta ao ponto de entrega",
		["C's dead drop"] = "O ponto de entrega de C",
		["C's next job comes by letter: once you are level 30 and have done the horn job, visit any capital city and C's letter arrives in the mailbox; only then does the {object:410369} near {area:204}, in southern Silverpine just south of {area:236}, offer it. The quest data lists a minimum of 25, but players get the letter, and the job, at 30."] = "A próxima missão de C vem por carta: quando você estiver no nível 30 e tiver feito a missão do chifre, visite qualquer capital e a carta de C chega na caixa de correio; só então {object:410369}, perto de {area:204}, no sul de Pinhaprata, logo ao sul de {area:236}, a oferece. Os dados da missão listam um mínimo de 25, mas os jogadores recebem a carta, e a missão, no 30.",
		["Place the eye in the {object:410369} near Pyrewood. Check a capital mailbox for C's payment letter on your next planned city visit, then return here for the reward quest. The payment may not be available immediately; do not repeat the infiltration just because the reward has not appeared."] = "Coloque o olho em {object:410369} perto de Lenhardente. Olhe a caixa de correio de uma capital, na sua próxima visita planejada à cidade, para ver a carta de pagamento de C, e volte aqui para a missão de recompensa. O pagamento pode não estar disponível na hora; não repita a infiltração só porque a recompensa ainda não apareceu.",
		["Solo route: Graveyard key, Library letter, Graveyard benches and coffer, then Library reliquary for the eye. Read the letter before the bench puzzle; check the disguise each time you change wings."] = "Rota solo: chave do Cemitério, carta da Biblioteca, bancos e cofre do Cemitério, depois o relicário da Biblioteca para pegar o olho. Leia a carta antes do enigma dos bancos; confira o disfarce a cada mudança de ala.",
		["The monastery stands in the far north-east of {zone:1420}. Go in alone, out of any group. Before entering, take the {spell:427592} from the Supply Locker in the stables behind the monastery and wear it; stealth and suspicious actions remove it, so put it back on after each wing change. In the Graveyard, in the Chamber of Atonement (the first big room), {spell:921} a {npc:4293} or Scarlet Crier for the {item:210963}. In the Library, open the Personal Letterbox in the Athenaeum with it and read the Confidential Message. It sends you back to sit on both benches between the two statues in the Graveyard. Watch for the mechanism's messages, then take the {item:210968} from the stone coffer: an elite stands by the coffer with a patrol behind it, but from beside the northern mausoleum you can turn the camera until the box shows and click it through the wall (an interact key works too). An elite ghost walks near the mausoleum; the broken piece at its edge keeps you out of its path. Then return to the Library for the locked reliquary and the eye. Avoid fighting through the instance."] = "O monastério fica no extremo nordeste de {zone:1420}. Entre sozinho, fora de qualquer grupo. Antes de entrar, pegue {spell:427592} no Armário de Suprimentos nos estábulos atrás do monastério e vista-o; furtividade e ações suspeitas o removem, então coloque de volta a cada mudança de ala. No Cemitério, na Câmara da Expiação (a primeira sala grande), use {spell:921} em um {npc:4293} ou Pregoeiro Escarlate para pegar {item:210963}. Na Biblioteca, abra a Caixa de Correio Pessoal no Ateneu com ela e leia a Mensagem Confidencial. Ela manda você de volta para sentar nos dois bancos entre as duas estátuas do Cemitério. Fique atento às mensagens do mecanismo e depois pegue {item:210968} do cofre de pedra: um elite fica ao lado do cofre, com uma patrulha atrás dele, mas, ao lado do mausoléu norte, dá para girar a câmera até a caixa aparecer e clicar nela através da parede (uma tecla de interagir também funciona). Um fantasma elite anda perto do mausoléu; a peça quebrada na borda dele mantém você fora do caminho. Depois volte à Biblioteca para o relicário trancado e o olho. Evite lutar para atravessar a instância.",
		["The {area:796}"] = "{area:796}",
		["The {item:277246}, C's payment for a solo job inside the {area:796}."] = "A {item:277246}, o pagamento de C por um serviço solo dentro do {area:796}.",
} end)()
t.guides["forever/class/rogue/the-horn-of-xelthos"] = (function() return {
		["Back to the dead drop"] = "Volte ao esconderijo",
		["C's dead drop"] = "O esconderijo de C",
		["Go in alone and use the {item:210186} at the courtyard gate. Players also report a freed prisoner opening the courtyard door for you: if you die while he is opening it, stay dead until it is open; it stays open once you release. If you know Vanish, bring {item:5140} and check its cooldown before entering; keep it ready for a failed approach. Pickpocket the sister in the dining hall for the {item:210213}, then the brother in the room reached by turning right at the top of the stairs for the {item:210212} (a level 20 rogue without Vanish may need ranks in Master of Deception to reach the second one unseen). Combine them somewhere safe: this breaks stealth. Free a bag slot first: opening the chest with full bags can use up the key without giving the horn. Return to the courtyard stables and use the combined key on the chest for the horn. Stay clear of the nearby elites; the minimum quest level does not guarantee a safe approach."] = "Vá sozinho e use {item:210186} no portão do pátio. Jogadores também relatam um prisioneiro libertado abrindo a porta do pátio para você: se você morrer enquanto ele abre, fique morto até ela abrir; ela continua aberta depois que você libera o espírito. Se você conhece Sumir, leve {item:5140} e confira o tempo de recarga antes de entrar; deixe pronto para uma aproximação que falhe. Bata a carteira da irmã no salão de jantar para pegar {item:210213}, depois a do irmão, no quarto que se alcança virando à direita no topo da escada, para pegar {item:210212} (um ladino de nível 20 sem Vanish pode precisar de graus em Mestre da Enganação para chegar ao segundo sem ser visto). Combine as duas num lugar seguro: isso quebra a furtividade. Libere um espaço na bolsa antes: abrir o baú com as bolsas cheias pode gastar a chave sem dar a trombeta. Volte aos estábulos do pátio e use a chave combinada no baú para pegar a trombeta. Fique longe dos elites próximos; o nível mínimo da missão não garante uma aproximação segura.",
		["Place the horn in the {object:410369} near Pyrewood. The payment may not appear immediately: check a capital mailbox for C's follow-up letter on your next planned city visit, then return to this chest for the reward quest. Do not repeat the dungeon just because the payment is not yet offered."] = "Coloque a trombeta em {object:410369} perto de Lenhardente. O pagamento pode não aparecer na hora: olhe a caixa de correio de uma capital, na sua próxima visita planejada à cidade, para ver a carta de acompanhamento de C, e volte a este baú para a missão de recompensa. Não repita a masmorra só porque o pagamento ainda não foi oferecido.",
		["The {item:277210}, C's payment for a solo job inside {area:236}."] = "O {item:277210}, o pagamento de C por um serviço solo dentro do {area:236}.",
		["The {object:410369} is a chest in a house just outside {area:204} in southern Silverpine, south of {area:236}. Open it and read C's note: the job has to be done alone, out of any group."] = "{object:410369} é um baú numa casa logo fora de {area:204}, no sul de Pinhaprata, ao sul de {area:236}. Abra e leia o bilhete de C: o trabalho precisa ser feito sozinho, fora de qualquer grupo.",
		["{item:210183}, inside {area:236}"] = "{item:210183}, dentro do {area:236}",
		["{npc:4086}, a goblin friendly to both factions, stands among the Venture Co. in the {area:461}, east Stonetalon, a short way north-east of {area:460}. Horde fly to {area:460}; Alliance to {area:467}. He wants a {item:210187} before he hands over explosives: the Venture Co. Loggers (level 18) working around him carry them in their pockets. Stealth up behind one and {spell:921} it; killing them does not give it."] = "{npc:4086}, um goblin amigo das duas facções, fica entre o pessoal da Empreendimentos S.A. em {area:461}, no leste da Cordilheira das Torres de Pedra, a uma curta distância a nordeste de {area:460}. A Horda voa para {area:460}; a Aliança, para {area:467}. Ele quer uma {item:210187} antes de entregar explosivos: os Madeireiros da Empreendimentos S.A. (nível 18) que trabalham em volta dele a carregam nos bolsos. Fique furtivo atrás de um e use {spell:921} nele; matá-los não dá o item.",
		["{spell:921} a {npc:3989} for a {item:210187}"] = "Use {spell:921} em um {npc:3989} para pegar uma {item:210187}",
} end)()
t.guides["forever/class/shaman/call-of-air-alliance"] = (function() return {
		["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} he gives."] = "No nível 30, {npc:258098}, o instrutor de xamã em {zone:1455}, manda você para {npc:259023}, em {zone:1417}. Seus totens de ar do nível 30 (Aterramento, {spell:10596}) precisam de {item:5178}, que ele entrega.",
		["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "Cinco Totens do Ar Deturpados. Os centauros Maraudine (nível 36-40) ao norte e nordeste de {area:2408}, no oeste de {zone:1443}, carregam; os Batedores soltam um quase a cada duas mortes. Os Domadores usam Rede e Desarmar, os Caçaventos curam e os Tempestuosos jogam {spell:9654}: puxe um de cada vez. Voltam em cerca de cinco minutos.",
		["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "Cinco Totens da Terra Deturpados. Os Perdidos (murlocs, nível 34-39) ao norte e nordeste de {area:75}, em {zone:1435}, carregam; a maioria corre atrás de ajuda quando ferida.",
		["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "Cinco Totens do Fogo Deturpados. Os trogues da Abóbada de Pedra (Batecrânios, Quebraossos e Xamãs, nível 37-41) ao sul de {area:338}, em {zone:1418}, carregam; os Xamãs soltam Totens de Nova de Fogo e {npc:3560}, e os Quebraossos correm atrás de ajuda quando feridos. Voltam em cerca de cinco minutos.",
		["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "Cinco Totens da Água Deturpados. Os murlocs Pântano Fino (nível 35-38) a nordeste de {area:496}, no norte de {zone:1445}, carregam.",
		["The steam pools"] = "As fontes de vapor",
		["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "O {item:5178} que permite pôr totens de ar, e depois uma arma à sua escolha no nível 40.",
		["Twisted Air Totems"] = "Totens do Ar Deturpados",
		["Twisted Earth Totems"] = "Totens da Terra Deturpados",
		["Twisted Fire Totems"] = "Totens do Fogo Deturpados",
		["Twisted Water Totems"] = "Totens da Água Deturpados",
		["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717} é uma masmorra para cinco jogadores no extremo sul de {zone:1413} (a seta aponta para a entrada); {npc:4421} (elite de nível 33) é o último chefe. Ela lança {spell:8292}, {spell:139} nos aliados e Pureza; {item:274463} cai só dela.",
		["{item:212792}, from the {npc:216474}"] = "{item:212792}, de {npc:216474}",
		["{item:274463}, from {npc:4421}"] = "{item:274463}, de {npc:4421}",
		["{npc:259023} camps in the hills just west of {area:321}, the Horde town in the north-east of Arathi: mind its guards. Fly to {area:320} and head north-east."] = "{npc:259023} acampa nas colinas logo a oeste de {area:321}, a cidade da Horda no nordeste de Arathi: cuidado com os guardas. Voe para {area:320} e siga para nordeste.",
		["{npc:259023} hands you the {item:268582}. {zone:1441} is far: the boat to Theramore and the road west, or fly to {area:489} on the {zone:1444} border and head east into the canyon. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "{npc:259023} entrega {item:268582} a você. {zone:1441} é longe: pegue o barco até Theramore e siga a estrada para oeste, ou voe até {area:489}, na divisa com {zone:1444}, e siga para leste, rumo ao desfiladeiro. Coloque {item:268582} nas poças de vapor a noroeste de {area:484} para chamar os elementais corrompidos e depois {npc:216474}; os quilboar Navalha se juntam à luta enquanto o ritual corre. Missão de grupo: leve pelo menos um ou dois amigos. {item:212792} cai quase a cada duas mortes, e todo membro do grupo pode saquear.",
		["{npc:259023}: your {item:5178}"] = "{npc:259023}: seu {item:5178}",
		["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}."] = "{npc:6176} acampa nas ruínas do leste de {zone:1416}: a partir de {area:272}, siga para o norte, pelas colinas, o rio a leste da cidade. Escolha sua arma: {item:280607}, {item:280605} ou {item:280604}.",
		["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176}: o {item:280696} e sua arma",
		["{quest:94789} and the Tempest's Weapons (Alliance)"] = "{quest:94789} e The Tempest's Weapons (Aliança)",
} end)()
t.guides["forever/class/shaman/call-of-air-horde"] = (function() return {
		["At 30 Skyborne shamans get their own {quest:96136}. {npc:259119} waits where the airship from Zephras Isle lands, in northern {zone:1412} beside {zone:1456}. Your level 30 air totems need the Air Totem Prate Cloudseer gives. If she has nothing for you, head up to {npc:5906} in {zone:1456} (next step): the trainers' {quest:96136} is open to Skyborne and gives the same totem."] = "No nível 30, os xamãs Celonatos recebem a própria {quest:96136}. {npc:259119} espera onde o barco celeste da Ilha de Zefras pousa, no norte de {zone:1412}, ao lado de {zone:1456}. Seus totens de ar do nível 30 precisam do Totem do Ar que Pradosa Fita Nuvens entrega. Se ela não tiver nada para você, suba até {npc:5906}, em {zone:1456} (próximo passo): a {quest:96136} dos instrutores está aberta aos Celonatos e dá o mesmo totem.",
		["At 30 {npc:5892} in the {object:172957} sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the {item:5178} she gives."] = "No nível 30, {npc:5892}, no {object:172957}, manda você a {npc:5905} em {zone:1441}. Seus totens de ar de nível 30 (Aterramento, {spell:10596}) precisam do {item:5178} que ela dá.",
		["At 30 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5905} in {zone:1441}. Your level 30 air totems (Grounding, {spell:10596}) need the Air Totem Prate gives. Already carry {npc:5892}'s {quest:1531} from {zone:1454}? It goes to {npc:5905} too: skip {npc:5906}."] = "No nível 30, {npc:5906}, instrutor de xamã em {area:1640}, em {zone:1456}, manda você para {npc:5905}, em {zone:1441}. Seus totens de ar do nível 30 (Aterramento, {spell:10596}) precisam do Totem do Ar que Pradosa entrega. Já tem {quest:1531} de {npc:5892}, de {zone:1454}? Ela vai para {npc:5905} também: pule {npc:5906}.",
		["Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of {area:2408} in western {zone:1443} carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw {spell:9654}: pull one at a time. Respawn about five minutes."] = "Cinco Totens do Ar Deturpados. Os centauros Maraudine (nível 36-40) ao norte e nordeste de {area:2408}, no oeste de {zone:1443}, carregam; os Batedores soltam um quase a cada duas mortes. Os Domadores usam Rede e Desarmar, os Caçaventos curam e os Tempestuosos jogam {spell:9654}: puxe um de cada vez. Voltam em cerca de cinco minutos.",
		["Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of {area:75} in the {zone:1435} carry them; most run for help when hurt."] = "Cinco Totens da Terra Deturpados. Os Perdidos (murlocs, nível 34-39) ao norte e nordeste de {area:75}, em {zone:1435}, carregam; a maioria corre atrás de ajuda quando ferida.",
		["Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of {area:338} in the {zone:1418} carry them; the Shamans drop Fire Nova Totems and a {npc:3560}, the Bonesnappers run for help when hurt. Respawn about five minutes."] = "Cinco Totens do Fogo Deturpados. Os trogues da Abóbada de Pedra (Batecrânios, Quebraossos e Xamãs, nível 37-41) ao sul de {area:338}, em {zone:1418}, carregam; os Xamãs soltam Totens de Nova de Fogo e {npc:3560}, e os Quebraossos correm atrás de ajuda quando feridos. Voltam em cerca de cinco minutos.",
		["Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of {area:496} in northern {zone:1445} carry them."] = "Cinco Totens da Água Deturpados. Os murlocs Pântano Fino (nível 35-38) a nordeste de {area:496}, no norte de {zone:1445}, carregam.",
		["Fly to {area:484}. {npc:5905} stands on a ledge above a cave mouth in the canyon wall north-east of the post, not inside the cave: climb the slope beside it. She also gives you an hour of faster attacks and running."] = "Voe para {area:484}. {npc:5905} fica numa saliência acima da boca de uma caverna na parede do desfiladeiro a nordeste do posto, não dentro da caverna: suba a encosta ao lado. Ela também dá uma hora de ataques e corrida mais rápidos.",
		["The steam pools"] = "As fontes de vapor",
		["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "O {item:5178}, que permite colocar totens de ar, e depois uma arma à sua escolha no nível 40.",
		["Twisted Air Totems"] = "Totens do Ar Deturpados",
		["Twisted Earth Totems"] = "Totens da Terra Deturpados",
		["Twisted Fire Totems"] = "Totens do Fogo Deturpados",
		["Twisted Water Totems"] = "Totens da Água Deturpados",
		["{area:1717} is a five-player dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} (level 33 elite) is its last boss. She casts {spell:8292}, {spell:139} on her allies and Purity; the {item:274463} drops only from her."] = "{area:1717} é uma masmorra para cinco jogadores no extremo sul de {zone:1413} (a seta aponta para a entrada); {npc:4421} (elite de nível 33) é o último chefe. Ela lança {spell:8292}, {spell:139} nos aliados e Pureza; {item:274463} cai só dela.",
		["{item:212792}, from the {npc:216474}"] = "{item:212792}, da {npc:216474}",
		["{item:274463}, from {npc:4421}"] = "{item:274463}, de {npc:4421}",
		["{npc:4722} stands at {area:484}."] = "{npc:4722} fica em {area:484}.",
		["{npc:5905} hands you the {item:268582}. Place the {item:268582} at the steam pools north-west of {area:484} to call the corrupted elementals and then the {npc:216474}; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The {item:212792} drops about every other kill, and every group member can loot it."] = "{npc:5905} entrega {item:268582} a você. Coloque {item:268582} nas poças de vapor a noroeste de {area:484} para chamar os elementais corrompidos e depois {npc:216474}; os quilboar Navalha se juntam à luta enquanto o ritual corre. Missão de grupo: leve pelo menos um ou dois amigos. {item:212792} cai quase a cada duas mortes, e todo membro do grupo pode saquear.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}: seu {item:5178}",
		["{npc:6176} camps in the ruins in the east of {zone:1416}: from {area:272} follow the river east of town north into the hills. Pick your weapon: {item:280607}, {item:280605} or {item:280604}; the {item:280696} shield comes with it."] = "{npc:6176} acampa nas ruínas do leste de {zone:1416}: a partir de {area:272}, siga para o norte, pelas colinas, o rio a leste da cidade. Escolha sua arma: {item:280607}, {item:280605} ou {item:280604}; o escudo {item:280696} vem junto.",
		["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176}: o {item:280696} e sua arma",
		["{quest:1531} and the Tempest's Weapons (Horde)"] = "{quest:1531} e The Tempest's Weapons (Horda)",
} end)()
t.guides["forever/class/shaman/call-of-earth-alliance"] = (function() return {
		["Back to Teo inside {area:77}. He hands you the {item:6635}: do not drink it yet."] = "De volta a Teo, dentro de {area:77}. Ele entrega {item:6635} a você: não beba ainda.",
		["Bring the {item:6656} back to Teo inside {area:77}. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Leve {item:6656} de volta a Teo, dentro de {area:77}. Guarde {item:5175} nas suas bolsas para sempre: todo totem de terra precisa dele.",
		["Iceclaw Bear Pendants"] = "Pingentes de Urso Garrálgido",
		["Lost the {quest:94472}?"] = "Perdeu {quest:94472}?",
		["Only if the {quest:94472} is gone from your bags (drunk away from the stone, or sold): Teo gives you another."] = "Só se {quest:94472} sumiu das suas bolsas (bebida longe da pedra, ou vendida): Teo entrega outra.",
		["Teo's {quest:94373} needs the {quest:98581} handed in first: {npc:658}, where you entered {area:132}, gives it to Dwarf shamans after his {quest:179}. Bring it up the road to {npc:257446} inside {area:77}."] = "{quest:94373}, do Teo, exige a entrega prévia de {quest:98581}: {npc:658}, onde você entrou em {area:132}, dá essa missão aos xamãs anões depois de {quest:179}. Leve a entrega pela estrada até {npc:257446}, dentro de {area:77}.",
		["The Frostmane Troll Whelps (level 3-4) hold the snowy slopes west and south-west of {area:77}, and the Frostmane Novices (level 3-4, they throw Frostbolts from range) camp south of it. Both carry the pendants; they respawn in about three minutes."] = "Os Filhotes de Troll Jubafria (nível 3-4) ocupam as encostas nevadas a oeste e sudoeste de {area:77}, e os Noviços Jubafria (nível 3-4, jogam Seta de Gelo à distância) acampam ao sul dela. Os dois carregam os pingentes; voltam em cerca de três minutos.",
		["The Spirit Stone"] = "A Pedra dos Espíritos",
		["The Spirit Stone stands on a snowy ridge north-west of {area:77}. The trail is easy to miss: it climbs the hill from the valley floor; at the small camp near the top turn left and the stone comes into view. Stand beside it, drink the {item:6635} and speak to the {npc:5891} before it fades."] = "A Pedra dos Espíritos fica numa crista nevada a noroeste de {area:77}. A trilha é fácil de perder: sobe o morro a partir do fundo do vale; no pequeno acampamento perto do topo, vire à esquerda e a pedra aparece. Fique ao lado dela, beba {item:6635} e fale com {npc:5891} antes que ele suma.",
		["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "Seu {item:5175}: sem ele, nenhum totem de terra pode ser lançado. {spell:8071} vem junto, no nível 4.",
		["it hands you the {item:6656}: keep it"] = "ele entrega {item:6656} a você: guarde",
		["the level 4 shaman spells"] = "as magias de xamã do nível 4",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}, ao lado da Pedra Espiritual",
		["{npc:257446} trains shamans inside {area:77}, the hall at the south end of {area:132}. The quest opens at level 4. Never took it and now 10 or more? {npc:258098} in {zone:1455} or {npc:258113} in {area:131} gives you {quest:94373}, a pointer back to Teo: take it for the experience on the way."] = "{npc:257446} ensina xamãs dentro de {area:77}, o salão no extremo sul de {area:132}. A missão abre no nível 4. Nunca pegou e agora está no 10 ou mais? {npc:258098}, em {zone:1455}, ou {npc:258113}, em {area:131}, entrega {quest:94373}, uma indicação de volta a Teo: pegue pela experiência no caminho.",
		["{npc:257446}: a new {quest:94472}"] = "{npc:257446}: uma nova {quest:94472}",
		["{npc:257446}: {spell:8071} and your {item:5175}"] = "{npc:257446}: {spell:8071} e seu {item:5175}",
		["{quest:94373} (Alliance)"] = "{quest:94373} (Aliança)",
} end)()
t.guides["forever/class/shaman/call-of-earth-horde"] = (function() return {
		["Any Al'Aketh cultist can carry the {item:251924}: the Converts (level 2-3) around the standing stones just east of the village, or the Brutes and Neophytes (level 4) in the camp beyond {npc:252095}, south-west of the village. Keep killing until one drops it."] = "Qualquer cultista de Al'Aketh pode carregar {item:251924}: os Convertidos (nível 2-3) em volta das pedras erguidas logo a leste da vila, ou os Brutamontes e Neófitos (nível 4) no acampamento depois de {npc:252095}, a sudoeste da vila. Continue matando até um soltar.",
		["Back to Boro in {area:16635}. He hands you the {quest:1462}: do not drink it yet."] = "De volta a Boro, em {area:16635}. Ele entrega {quest:1462} a você: não beba ainda.",
		["Back to the Seer in {area:221}. She hands you the {quest:1462}: do not drink it yet."] = "De volta à Vidente, em {area:221}. Ela entrega {quest:1462} a você: não beba ainda.",
		["Back to {npc:5887} outside the Den. She hands you the {quest:1462}: do not drink it yet."] = "De volta a {npc:5887}, fora da Toca. Ela entrega {quest:1462} a você: não beba ainda.",
		["Bring the {item:6656} back to Boro. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Leve {item:6656} de volta a Boro. Guarde {item:5175} nas suas bolsas para sempre: todo totem de terra precisa dele.",
		["Bring the {item:6656} back to the Seer. Keep the {item:5175} in your bags for good: every earth totem needs it."] = "Leve {item:6656} de volta à Vidente. Guarde {item:5175} nas suas bolsas para sempre: todo totem de terra precisa dele.",
		["Bring the {item:6656} back to {npc:5887} outside the Den. Keep the {item:5175} she gives you in your bags for good: every earth totem needs it."] = "Leve {item:6656} de volta a {npc:5887}, fora da Toca. Guarde para sempre nas suas bolsas {item:5175}, que ela entrega: todo totem de terra precisa dele.",
		["Felstalker Hooves"] = "Cascos de Espreitador Vil",
		["Felstalkers (level 3-4) prowl the slope below the {area:365}, the cave in the north of the valley, and just inside its mouth among the Vile Familiars. Nearly every {npc:3102} drops a hoof (four kills in five); they respawn in a little over three minutes."] = "Os Espreitadores Vis (nível 3-4) rondam a encosta embaixo de {area:365}, a caverna no norte do vale, e logo dentro da boca dela, entre os Familiares torpes. Quase todo {npc:3102} solta um casco (quatro mortes em cinco); voltam em pouco mais de três minutos.",
		["Lost the {quest:1462}?"] = "Perdeu {quest:1462}?",
		["Lost the {quest:1463}?"] = "Perdeu {quest:1463}?",
		["Only if the {quest:1462} is gone from your bags: the Seer gives you another."] = "Só se {quest:1462} sumiu das suas bolsas: a Vidente entrega outra.",
		["Only if the {quest:1463} is gone from your bags (drunk away from the rock, or sold): {npc:5887} gives you another."] = "Só se {quest:1463} sumiu das suas bolsas (bebida longe da pedra, ou vendida): {npc:5887} entrega outra.",
		["The Bristleback Shamans (level 3-4) stand among the quilboar huts of {area:358}, east of the camp, and throw the odd {spell:403}. Four kills in five drop a salve; they respawn in about four minutes."] = "Os Xamãs Costagulha (nível 3-4) ficam entre as cabanas dos quilboar de {area:358}, a leste do acampamento, e jogam um {spell:403} de vez em quando. Quatro mortes em cinco soltam um ungüento; voltam em cerca de quatro minutos.",
		["The {area:16988}"] = "{area:16988}",
		["The {area:16988} is the hilltop shrine north-east of Boro: the path up starts on the hill just above the clearing where the flies were. Drink the {item:6635} beside the shrine and speak to the {npc:251166} before it fades."] = "{area:16988} é o santuário no topo do morro a nordeste de Boro: a trilha para subir começa no morro, logo acima da clareira onde estavam as moscas. Beba {item:6635} ao lado do santuário e fale com {npc:251166} antes que ele suma.",
		["Your {item:5175}: without it no earth totem can be cast. {spell:8071} comes with it at level 4."] = "Seu {item:5175}: sem ele, nenhum totem de terra pode ser lançado. {spell:8071} vem junto, no nível 4.",
		["it hands you the {item:6656}: keep it"] = "ele entrega {item:6656} a você: guarde",
		["the level 4 shaman spells"] = "as magias de xamã do nível 4",
		["{area:637} is a small pillar on a low mound due east of {npc:2991}'s well, east of the camp; it only shows from about fifteen yards away, and hostile boars graze around it. Stand beside it and drink the {item:6635}, then speak to the {npc:5891} before it fades (drink again if it does)."] = "{area:637} é um pilar pequeno num montículo baixo, bem a leste do poço de {npc:2991}, a leste do acampamento; só aparece a uns quinze metros, e javalis hostis pastam em volta. Fique ao lado dele, beba {item:6635} e fale com {npc:5891} antes que ele suma (beba de novo se sumir).",
		["{area:639} sits on a ledge in the hills just south of the Den. The {area:638} up starts at the foot of the hills south-west of the Den, between two idle peons; it climbs south-west into the hills, then bends back east to the rock. Stand right beside the stone and drink the {item:6635}: the {npc:5891} appears for a short while, so speak to it at once (walk almost under it if it does not answer). Coming back, you can drop down the ledge towards the Den instead of walking the path."] = "{area:639} fica numa saliência nas colinas, logo ao sul da Toca. A {area:638} começa ao pé das colinas, a sudoeste da Toca, entre dois peões parados; sobe para sudoeste pelas colinas e depois dobra de volta para leste até a pedra. Fique bem ao lado da pedra e beba {item:6635}: {npc:5891} aparece por pouco tempo, então fale com ele na hora (ande quase para debaixo dele se não responder). Na volta, você pode descer pela saliência em direção à Toca em vez de seguir a trilha.",
		["{item:6635}, beside the shrine"] = "{item:6635}, ao lado do santuário",
		["{item:6635}, beside {area:637}"] = "{item:6635}, ao lado de {area:637}",
		["{item:6635}, beside {area:639}"] = "{item:6635}, ao lado de {area:639}",
		["{npc:251374}, the shaman trainer, stands in {area:16635}. The quest opens at level 3."] = "{npc:251374}, o instrutor de xamã, fica em {area:16635}. A missão abre no nível 3.",
		["{npc:251374}: {spell:8071} and your {item:5175}"] = "{npc:251374}: {spell:8071} e seu {item:5175}",
		["{npc:5887} stands just outside the Den, the cave in the middle of the {area:363}. The quest opens at level 4."] = "{npc:5887} fica logo fora da Toca, a caverna no meio de {area:363}. A missão abre no nível 4.",
		["{npc:5887}: a new {quest:1463}"] = "{npc:5887}: uma nova {quest:1463}",
		["{npc:5887}: {spell:8071} and your {item:5175}"] = "{npc:5887}: {spell:8071} e seu {item:5175}",
		["{npc:5888} stands in {area:221}. She may show no quest mark over her head: speak to her anyway. The quest opens at level 4."] = "{npc:5888} fica em {area:221}. Pode não ter marca de missão sobre a cabeça: fale com ela mesmo assim. A missão abre no nível 4.",
		["{npc:5888}: a new {quest:1462}"] = "{npc:5888}: uma nova {quest:1462}",
		["{npc:5888}: {spell:8071} and your {item:5175}"] = "{npc:5888}: {spell:8071} e seu {item:5175}",
		["{quest:1516} (Horde)"] = "{quest:1516} (Horda)",
} end)()
t.guides["forever/class/shaman/call-of-fire-alliance"] = (function() return {
		["At 10 {npc:258113}, the shaman trainer in {area:131}, or {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:257597}."] = "No nível 10, {npc:258113}, o instrutor de xamã em {area:131}, ou {npc:258098}, o instrutor de xamã em {zone:1455}, manda você para {npc:257597}.",
		["Back through the South Gate tunnel and up the trail to {npc:257597}' cave. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "De volta pelo túnel do Portão Sul e subindo a trilha até a caverna de {npc:257597}. Guarde {item:5176} nas suas bolsas para sempre: todo totem de fogo precisa dele.",
		["Back up the trail to {npc:257808}. He makes the {item:6636} from the tar and the pouch: keep it with the torch."] = "De volta pela trilha até {npc:257808}. Ele faz {item:6636} com o piche e a bolsinha: guarde junto com a tocha.",
		["Click the {object:61934} atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit {item:277329}."] = "Clique em {object:61934}, no alto do santuário, com a tocha nas suas bolsas, para colocar a brasa, e depois clique de novo para a próxima missão: {item:277329} acesa.",
		["Climb on past {npc:257808} to the peak. Drink the {item:6636} beside the rock statue there to see the {npc:5893} (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with {spell:8017} and {spell:8042}. Its {item:6655} drops every time."] = "Suba além de {npc:257808}, até o pico. Beba {item:6636} ao lado da estátua de pedra para ver {npc:5893} (nível 12): ela espera até você atacar, mas fica mais forte quanto mais tempo é deixada, e é imune a fogo. Abra de imediato com {spell:8017} e {spell:8042}. {item:6655} dela cai sempre.",
		["Follow the road east to the tunnel towards {area:806}. Out of the first tunnel, keep left past {npc:1959} and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to {npc:257597}' cave above the farm. He hands you the {item:6653}: keep it until the end of the chain."] = "Siga a estrada para leste até o túnel rumo a {area:806}. Ao sair do primeiro túnel, mantenha-se à esquerda, passando {npc:1959} e a torre: uma trilha estreita, difícil de ver mas marcada no minimapa, sobe a montanha até a caverna de {npc:257597}, acima da fazenda. Ele entrega {item:6653} a você: guarde até o fim da cadeia.",
		["From {npc:257597}' ledge you can drop carefully down the mountain into {zone:1432}, or walk back through the tunnel. {npc:257808} keeps the shrine on the peak just south of {area:144}: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak."] = "Da saliência de {npc:257597}, você pode descer com cuidado a montanha até {zone:1432}, ou voltar a pé pelo túnel. {npc:257808} cuida do santuário no pico logo ao sul de {area:144}: uma trilha escondida por uma saliência do penhasco, marcada por totens de pedra, sobe até ele a partir da estrada ao norte do pico.",
		["Lost the {quest:94473}?"] = "Perdeu {quest:94473}?",
		["Only if the {quest:94473} is gone from your bags: {npc:257808} gives you another."] = "Só se {quest:94473} sumiu das suas bolsas: {npc:257808} entrega outra.",
		["The Shrine of Eternal Flame"] = "O Santuário da Chama Eterna",
		["The Stonesplinter Seers (level 13-14) stand among the troggs of {area:923} in the south of the loch, and in the trogg camps north-east of {area:144}. They throw {spell:1245113} from 40 yards and run for help when hurt: pull one at a time. Respawn about five minutes."] = "Os Videntes Lascapedra (nível 13-14) ficam entre os trogues de {area:923}, no sul do lago, e nos acampamentos de trogues a nordeste de {area:144}. Eles jogam {spell:1245113} a 40 metros e correm atrás de ajuda quando feridos: puxe um de cada vez. Voltam em cerca de cinco minutos.",
		["The Tunnel Rat Geomancers (level 12-13) work only inside the {area:149} at the north end of the loch, past {area:144}. They cast {spell:2136} behind a {spell:134} and run for help at low health."] = "Os Geomantes Ratatúnel (nível 12-13) trabalham só dentro de {area:149}, no extremo norte do lago, depois de {area:144}. Eles lançam {spell:2136} atrás de {spell:134} e correm atrás de ajuda com pouca vida.",
		["The {object:61934}"] = "{object:61934}",
		["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "Seu {item:5176} para todo totem de fogo, {spell:3599} junto com ele, e {item:263412} do Forever.",
		["{item:6636}, beside the statue"] = "{item:6636}, ao lado da estátua",
		["{npc:257597}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:257597}: {spell:3599}, seu {item:5176} e {item:263412}",
		["{npc:257808}: a new {quest:94473}"] = "{npc:257808}: uma nova {quest:94473}",
		["{npc:258113}, {area:131}; or {npc:258098}, {zone:1455}"] = "{npc:258113}, {area:131}; ou {npc:258098}, {zone:1455}",
		["{quest:94449} (Alliance)"] = "{quest:94449} (Aliança)",
} end)()
t.guides["forever/class/shaman/call-of-fire-horde"] = (function() return {
		["At 10 {npc:252382}, the shaman trainer beside {npc:251968} in {area:16638}, hands you the {item:6653} ({npc:254082} offers the same quest). Already left the isle? A {quest:97243} sends you back to them: take the skycutter from the cliffs south of {area:17045}, north of {zone:1456}. Learn {spell:8050} from her now: {npc:268605}, later in the chain, only takes fire damage."] = "No nível 10, {npc:252382}, o instrutor de xamã ao lado de {npc:251968}, em {area:16638}, entrega {item:6653} a você ({npc:254082} oferece a mesma missão). Já saiu da ilha? {quest:97243} manda você de volta a eles: pegue o barco celeste nos penhascos ao sul de {area:17045}, ao norte de {zone:1456}. Aprenda {spell:8050} com ela agora: {npc:268605}, mais adiante na cadeia, só sofre dano de fogo.",
		["At 10 {npc:3066}, the shaman trainer in {area:222}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5906}'s letter from {zone:1456}? It goes to {npc:5907} too: skip Narm."] = "No nível 10, {npc:3066}, o instrutor de xamã em {area:222}, manda você para {npc:5907}, em {zone:1413}. Já tem a carta de {npc:5906}, de {zone:1456}? Ela vai para {npc:5907} também: pule Narm.",
		["At 10 {npc:3173}, the shaman trainer on the east side of {area:362}, sends you to {npc:5907} in the {zone:1413}. Already carry {npc:5892}'s letter from {zone:1454}? It goes to {npc:5907} too: skip {npc:3173}."] = "No nível 10, {npc:3173}, o instrutor de xamã no lado leste de {area:362}, manda você para {npc:5907}, em {zone:1413}. Já tem a carta de {npc:5892}, de {zone:1454}? Ela vai para {npc:5907} também: pule {npc:3173}.",
		["Back east over the bridge, then south along the {zone:1411} bank of the river to where the mountains meet the water. The trail up starts at the foot of the mountain beside a small dark stone carved with symbols, near the quilboar camp; it is narrow, and a slip costs fall damage. {npc:5900} keeps the shrine at the top."] = "De volta a leste pela ponte, depois para o sul, pela margem de {zone:1411} do rio, até onde as montanhas encontram a água. A trilha que sobe começa ao pé da montanha, ao lado de uma pequena pedra escura entalhada com símbolos, perto do acampamento dos quilboar; é estreita, e um escorregão causa dano de queda. {npc:5900} cuida do santuário no topo.",
		["Back to {npc:268592} at the Shrine of Flames."] = "De volta a {npc:268592}, no Shrine of Flames.",
		["Back to {npc:268592}. Accept the last quest, then wait by the {npc:268762} while he performs the ritual; when the fire spirits light the {object:148418}, hold the torch to it. From then you have six minutes: carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638}, with no detours or fights. Timer out? Abandon the quest and take it again from {npc:268592}."] = "De volta a {npc:268592}. Aceite a última missão e espere ao lado de {npc:268762} enquanto ele faz o ritual; quando os espíritos do fogo acenderem {object:148418}, encoste a tocha nele. A partir daí, você tem seis minutos: leve a chama direto até {npc:268679}, ao lado de {npc:252382}, em {area:16638}, sem desvios nem lutas. O tempo acabou? Abandone a missão e pegue de novo com {npc:268592}.",
		["Back up the trail to {npc:5900}. He makes the {quest:1464} from the tar and the pouch and hands it to you with the torch: keep both."] = "De volta pela trilha até {npc:5900}. Ele faz {quest:1464} com o piche e a bolsinha e entrega a você junto com a tocha: guarde os dois.",
		["Click the {object:61934} on the plateau with the torch in your bags to place the ember, then click it a second time: the next quest does not open by itself. It gives you the lit {item:277329}."] = "Clique em {object:61934}, no platô, com a tocha nas suas bolsas, para colocar a brasa, e depois clique uma segunda vez: a próxima missão não abre sozinha. Ela entrega {item:277329} acesa a você.",
		["Down the trail, back over the bridge to {npc:5907} by his tower. Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Desça a trilha, volte pela ponte até {npc:5907}, ao lado da torre dele. Guarde {item:5176} nas suas bolsas para sempre: todo totem de fogo precisa dele.",
		["Drink the {item:6636} beside the {object:63674}, the big grey stone just below the summit, then climb to the plateau. Of the fire elementals there only the one in the middle can be attacked: it is level 12, immune to fire and grows stronger the longer the fight lasts, so open at once with {spell:8017} and {spell:8042} and leave the others alone. Its {item:6655} drops every time."] = "Beba {item:6636} ao lado do {object:63674}, a grande pedra cinza logo abaixo do cume, depois suba até o platô. Dos elementais de fogo ali, só o do meio pode ser atacado: ele é de nível 12, imune a fogo e fica mais forte quanto mais a luta dura, então abra na hora com {spell:8017} e {spell:8042} e deixe os outros em paz. Dele sempre cai {item:6655}.",
		["Keep the {item:5176} in your bags for good: every fire totem needs it."] = "Guarde {item:5176} nas suas bolsas para sempre: todo totem de fogo precisa dele.",
		["Lost the {quest:1464}?"] = "Perdeu {quest:1464}?",
		["Only if the {quest:1464} is gone from your bags: {npc:5900} gives you another."] = "Só se {quest:1464} sumiu das suas bolsas: {npc:5900} entrega outra.",
		["The Burning Blade Cultists (level 10-11, they call imps and cast {spell:348}) live deep in {area:371} north of {area:362}: climb the ramp just north-east of town and stay on the high ground above the ravines. The orcs at the cave mouth are not cultists; the cultists are further in, off to the left. Three kills in four drop a pouch. {area:817} by {zone:1454} is the wrong cave."] = "Os Sectários da Lâmina Ardente (nível 10-11, chamam diabretes e lançam {spell:348}) vivem no fundo de {area:371}, ao norte de {area:362}: suba a rampa logo a nordeste da cidade e fique nas partes altas acima das ravinas. Os orcs na boca da caverna não são sectários; os sectários estão mais para dentro, à esquerda. Três mortes em quatro soltam uma bolsinha. {area:817}, perto de {zone:1454}, é a caverna errada.",
		["The Razormane casters north-east of the Crossroads drop the {item:5026} three times in four: Water Seekers and Thornweavers (level 10-11), Geomancers (level 12-13, they throw Fireballs and run for help when hurt) and Mystics (level 13-14, they heal themselves at low health). Pull them one at a time."] = "Os conjuradores Crinavalha a nordeste da Encruzilhada soltam {item:5026} três vezes em quatro: Rabdomantes e Tecespinhos (nível 10-11), Geomantes (nível 12-13, jogam Bolas de Fogo e correm atrás de ajuda quando feridos) e Místicos (nível 13-14, se curam com pouca vida). Puxe um de cada vez.",
		["The Shrine of Flames hides on the island's outer rim south-west of {area:16638}, just south-east of {area:16663}: {npc:268592} keeps it."] = "O Santuário das Chamas fica escondido na borda externa da ilha, a sudoeste de {area:16638}, logo a sudeste de {area:16663}: {npc:268592} cuida dele.",
		["The {npc:5893}"] = "{npc:5893}",
		["The {object:148418}"] = "{object:148418}",
		["The {object:61934}"] = "{object:61934}",
		["Your {item:5176} for every fire totem, {spell:3599} with it, and Forever's {item:263412}."] = "Seu {item:5176} para todo totem de fogo, {spell:3599} junto com ele, e {item:263412} do Forever.",
		["the ritual, then the {npc:268679} in {area:16638}"] = "o ritual, e depois {npc:268679}, em {area:16638}",
		["{item:6636}, beside the {object:63674}"] = "{item:6636}, ao lado do {object:63674}",
		["{npc:252382}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:252382}: {spell:3599}, seu {item:5176} e {item:263412}",
		["{npc:268602} (level 10, a turncoat Windshaper with a single spawn) holds the farm north-east past {area:16638}, just south of the {area:16629}, on the hill west of the falls north of the {area:17675}. Kill him and take his heart."] = "{npc:268602} (nível 10, um Moldavento traidor com um único ponto de aparição) ocupa a fazenda a nordeste, depois de {area:16638}, logo ao sul de {area:16629}, no morro a oeste da cachoeira ao norte de {area:17675}. Mate-o e pegue o coração dele.",
		["{npc:5900}: a new {quest:1464}"] = "{npc:5900}: uma nova {quest:1464}",
		["{npc:5907} hands you the {item:6653}: keep it until the end of the chain."] = "{npc:5907} entrega {item:6653} a você: guarde até o fim da cadeia.",
		["{npc:5907} is not in the Crossroads: take the road north from the Crossroads and fork east towards {zone:1411}; past {area:1704} he paces by a tall tower east of the road (from {zone:1411}: over the Southfury bridge, past {area:379}). If you reach {zone:1440} you went too far."] = "{npc:5907} não fica na Encruzilhada: siga a estrada para o norte a partir da Encruzilhada e pegue o desvio para leste rumo a {zone:1411}; depois de {area:1704}, ele anda ao lado de uma torre alta a leste da estrada (de {zone:1411}: pela ponte do Rio Furiaustral, depois de {area:379}). Se chegar a {zone:1440}, você foi longe demais.",
		["{npc:5907}: {npc:3066}'s letter"] = "{npc:5907}: a carta de {npc:3066}",
		["{npc:5907}: {npc:3173}'s letter"] = "{npc:5907}: a carta de {npc:3173}",
		["{npc:5907}: {npc:5892}'s letter"] = "{npc:5907}: a carta de {npc:5892}",
		["{npc:5907}: {npc:5906}'s letter"] = "{npc:5907}: a carta de {npc:5906}",
		["{npc:5907}: {spell:3599}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {spell:3599}, seu {item:5176} e {item:263412}",
		["{object:660848} is the twisted stump on the hilltop by the Shen'dar Highlands Anchor Pylon, west of {area:16638}, in the hills south of the Windsong Crawlers' lakes. Knock on it to call {npc:268605} (level 10). The spirit shrugs off most magic: only fire hurts it, so keep {spell:8050} on it. Take its wooden mask."] = "{object:660848} é o toco retorcido no topo da colina junto ao Shen'dar Highlands Anchor Pylon, a oeste de {area:16638}, nas colinas ao sul dos lagos dos Rastejantes Cantéolos. Bata nele para chamar {npc:268605} (nível 10). O espírito ignora a maior parte da magia: só o fogo o machuca, então mantenha {spell:8050} nele. Pegue a máscara de madeira dele.",
		["{object:660848}: knock on the bark"] = "{object:660848}: bata na casca",
		["{quest:1522} (Horde)"] = "{quest:1522} (Horda)",
} end)()
t.guides["forever/class/shaman/call-of-water-alliance"] = (function() return {
		["At 20 {npc:258098}, the shaman trainer in {zone:1455}'s {object:32362}, sends you to {npc:258043} in {zone:1432}."] = "No nível 20, {npc:258098}, o instrutor de xamãs na {object:32362} de {zone:1455}, envia você a {npc:258043} em {zone:1432}.",
		["Back to {npc:258043} by {area:146} with the {item:7810}. He hands you the {item:6637} and the {item:7811}: keep both for {zone:1436}."] = "De volta a {npc:258043}, perto de {area:146}, com {item:7810}. Ele entrega {item:6637} e {item:7811} a você: guarde os dois para {zone:1436}.",
		["Back to {npc:258043} with the {item:7813}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "De volta a {npc:258043}, com {item:7813}. Guarde {item:5177} nas suas bolsas para sempre: todo totem de água precisa dele.",
		["Fill the {item:265732} at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish. {object:147516} dwarves roam near the falls."] = "Encha o {item:265732} no pé das cachoeiras abaixo da caverna de {npc:258203}, onde a água doce encontra a salobra. Anões {object:147516} rondam perto das cachoeiras.",
		["Fly to {area:108} and head south to {area:20}: {area:919} and the {object:619896} lie just north of it. Drink the {item:6637} by the shrine to see the {npc:5894} (level 22, {spell:8056} and {spell:122}; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the {item:7811} on the {object:619896} (this, not {npc:258043}, ends the quest). Click the shrine again: the {npc:5895} rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the {item:7813}."] = "Voe para {area:108} e siga para o sul até {area:20}: {area:919} e {object:619896} ficam logo ao norte dela. Beba {item:6637} ao lado do santuário para ver {npc:5894} (nível 22, {spell:8056} e {spell:122}; um único ponto de aparição, volta três minutos depois de morrer), derrote-o para pegar as braçadeiras dele (sempre caem), e então coloque-as e {item:7811} em {object:619896} (isso, e não {npc:258043}, termina a missão). Clique no santuário de novo: {npc:5895} se ergue ao lado dele; fale com ele antes de sair andando (se tiver sumido, abandone e pegue a missão de novo no santuário). Ele entrega {item:7813} a você.",
		["Lost the {quest:94616}?"] = "Perdeu {quest:94616}?",
		["Only if the {quest:94616} is gone from your bags: {npc:258043} gives you another before you leave for {zone:1436}."] = "Só se {quest:94616} sumiu das suas bolsas: {npc:258043} entrega outra antes de você partir para {zone:1436}.",
		["Take the boat from {area:150} to {area:442} (it stops in {area:271} on the way), then fly or walk south through {zone:1439} to {area:415} in {zone:1440}. Fill the {item:265772} in the lake around the town, then the boat back to Menethil."] = "Pegue o barco de {area:150} até {area:442} (ele para em {area:271} no caminho), depois voe ou ande para o sul por {zone:1439} até {area:415}, em {zone:1440}. Encha {item:265772} no lago em volta da cidade, depois pegue o barco de volta a Menethil.",
		["The blue waterskin"] = "O odre azul",
		["The brown waterskin"] = "O odre marrom",
		["The red waterskin"] = "O odre vermelho",
		["The {item:5177} that lets you place water totems, and {spell:5394} with it."] = "O {item:5177}, que permite colocar totens de água, e {spell:5394} junto.",
		["the {item:7810}, for {npc:258043}"] = "o {item:7810}, para {npc:258043}",
		["{area:71} pour out of {area:68} at the east end of Redridge (fly from {zone:1455} to {area:69}). Fill the {item:265747} at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from {npc:258203} for a new one."] = "{area:71} jorram de {area:68}, no extremo leste de Cristarrubra (voe de {zone:1455} até {area:69}). Encha {item:265747} ao pé deles, onde se reúnem os Reptantes Murloc; tire os murlocs do ponto primeiro. Se o odre sumir sem contar, abandone a missão e pegue de novo com {npc:258203} para receber um novo.",
		["{npc:258043}'s burrow hut stands on the north-western shore of the loch, below {area:146}, north of {area:144}."] = "A cabana-toca de {npc:258043} fica na margem noroeste do lago, embaixo de {area:146}, ao norte de {area:144}.",
		["{npc:258043}: a new {quest:94616}"] = "{npc:258043}: uma nova {quest:94616}",
		["{npc:258043}: your {item:6637}"] = "{npc:258043}: sua {item:6637}",
		["{npc:258043}: {spell:5394} and your {item:5177}"] = "{npc:258043}: {spell:5394} e seu {item:5177}",
		["{npc:258203}'s family lives in a cave beneath the southern falls of the {zone:1437}, east of {area:836}: not in a town. Through the Algaz tunnel north of {zone:1432}, then east off the road."] = "A família de {npc:258203} mora numa caverna embaixo das quedas-d'água do sul de {zone:1437}, a leste de {area:836}: não numa cidade. Pelo túnel de Algaz, ao norte de {zone:1432}, e depois para leste, saindo da estrada.",
		["{npc:5895}, beside the shrine"] = "{npc:5895}, ao lado do santuário",
		["{quest:94494} (Alliance)"] = "{quest:94494} (Aliança)",
} end)()
t.guides["forever/class/shaman/call-of-water-horde"] = (function() return {
		["At 20 {npc:5892} in the {object:172957} sends you to {npc:5901} in the {zone:1413}. (Swart in {area:362} gives the same letter: carry either.)"] = "No nível 20, {npc:5892}, no {object:172957}, manda você a {npc:5901} em {zone:1413}. (Swart, em {area:362}, dá a mesma carta: leve qualquer uma.)",
		["At 20 {npc:5906}, a shaman trainer on {area:1640} in {zone:1456}, sends you to {npc:5901} in the {zone:1413}. ({npc:3066} in {area:222} gives the same letter: carry either.)"] = "No nível 20, {npc:5906}, instrutor de xamã em {area:1640}, em {zone:1456}, manda você para {npc:5901}, em {zone:1413}. ({npc:3066}, em {area:222}, entrega a mesma carta: leve qualquer uma.)",
		["Back to {npc:5899}. She gives you the {item:7810} for {npc:5901}."] = "De volta a {npc:5899}. Ela entrega {item:7810} a você, para {npc:5901}.",
		["Back to {npc:5901} south of {area:392}. Keep the {item:5177} in your bags for good: every water totem needs it."] = "De volta a {npc:5901}, ao sul de {area:392}. Guarde {item:5177} nas suas bolsas para sempre: todo totem de água precisa dele.",
		["Click the {object:113791} to place the bracers and the drops. A few seconds later the pure {npc:5895} rises on the stone in the middle of the pool: speak to it while the {spell:8202} lasts (drink again by the stone if it has worn off). It gives you the {item:7813} for {npc:5901}. Gone before you could speak to it? Back at {npc:5901} ask for {quest:63} (a fresh {quest:972} for {npc:7007}, who stands just west of the shrine): hand it to Tiev, stay close while he calls the spirit back, then speak to it."] = "Clique em {object:113791} para colocar as braçadeiras e os itens. Alguns segundos depois, {npc:5895} puro se ergue na pedra no meio da lagoa: fale com ele enquanto {spell:8202} durar (beba de novo ao lado da pedra se tiver passado). Ele entrega {item:7813} a você, para {npc:5901}. Sumiu antes de você falar com ele? De volta a {npc:5901}, peça {quest:63} (uma nova {quest:972} para {npc:7007}, que fica logo a oeste do santuário): entregue a Tiev, fique perto enquanto ele chama o espírito de volta e depois fale com ele.",
		["Fly to the {area:228}. The shrine lies in a hollow just south-west of it: go round the back of the crypt to the thick tree between the two hills, hop past it onto the rocks and drop west down the slope to the pool (each drop costs a little health). Drink the {item:6637} beside the tall standing stone by the pool: several water elementals appear, and only the corrupt one near the middle can be attacked (Tab picks it). The {npc:5894} is level 22 and casts {spell:8056} and {spell:122}; if someone just killed it, it is back in about three minutes. Its bracers always drop."] = "Voe para {area:228}. O santuário fica numa depressão logo a sudoeste dela: dê a volta por trás da cripta até a árvore grossa entre os dois morros, passe por ela pulando até as pedras e desça para oeste pela encosta até a lagoa (cada queda custa um pouco de vida). Beba {item:6637} ao lado da pedra alta erguida junto à lagoa: aparecem vários elementais da água, e só o corrompido perto do meio pode ser atacado (Tab escolhe). {npc:5894} é de nível 22 e lança {spell:8056} e {spell:122}; se alguém acabou de matá-lo, ele volta em cerca de três minutos. As braçadeiras dele sempre caem.",
		["Lost the {quest:972}?"] = "Perdeu {quest:972}?",
		["Only if the {quest:972} is gone from your bags: {npc:5901} gives you another."] = "Só se {quest:972} sumiu das suas bolsas: {npc:5901} entrega outra.",
		["The muddy pond below {npc:5899}'s hut. Step right into the puddle before you use the {item:7766} (too far away and it refuses). Filling it calls a hostile {npc:3456} (level 20): kill it, and watch for the quilboar hunter by the pond, who may start shooting afterwards."] = "A lagoa lamacenta embaixo da cabana de {npc:5899}. Entre direto na poça antes de usar {item:7766} (longe demais e ele recusa). Encher chama um {npc:3456} hostil (nível 20): mate-o, e fique de olho no caçador quilboar perto da lagoa, que pode começar a atirar depois.",
		["The right fountain stands in a ring of standing stones on the island of the small green lake south of {area:415}, west of Lake Mystral (not the island in Lake Mystral itself). From the {zone:1413} take the road north through the {area:1703} and on west. Water elementals and walking treants guard the lake and root you in place; an elite {npc:12836} roams {zone:1440} and can pass close by. Use the {item:7767} beside the fountain."] = "A fonte certa fica num círculo de pedras erguidas na ilha do pequeno lago verde ao sul de {area:415}, a oeste do Lago Mystral (não a ilha no próprio Lago Mystral). A partir de {zone:1413}, siga a estrada para o norte por {area:1703} e depois para oeste. Elementais da água e ents andantes guardam o lago e prendem você no lugar; um {npc:12836} elite ronda {zone:1440} e pode passar por perto. Use {item:7767} ao lado da fonte.",
		["The {item:5177} that lets you place water totems, and {spell:5394} with it."] = "O {item:5177}, que permite colocar totens de água, e com ele {spell:5394}.",
		["The {npc:5895}"] = "{npc:5895}",
		["The {object:107045}"] = "{object:107045}",
		["The {object:107045} stands in the middle of {area:272}, just outside the church. From the {zone:1413}: the zeppelin from {zone:1454} to {zone:1420}, then south past the {zone:1458} and through {zone:1421} (or fly once you have the {area:272} flight path). {area:287} is contested: Alliance players may attack. Stand beside the well and use the {item:7768}."] = "{object:107045} fica no meio de {area:272}, logo fora da igreja. De {zone:1413}: o zepelim de {zone:1454} até {zone:1420}, depois ao sul passando pela {zone:1458} e atravessando {zone:1421} (ou voe quando tiver a rota de voo de {area:272}). {area:287} é disputada: jogadores da Aliança podem atacar. Fique ao lado do poço e use o {item:7768}.",
		["The {object:107046}"] = "{object:107046}",
		["The {object:113791}"] = "{object:113791}",
		["the {item:7810}, for {npc:5901}"] = "a {item:7810}, para {npc:5901}",
		["{item:6637}, beside the standing stone"] = "{item:6637}, ao lado da pedra erguida",
		["{item:7766}, standing in the puddle"] = "{item:7766}, em pé na poça",
		["{item:7767}, beside the fountain"] = "{item:7767}, ao lado da fonte",
		["{item:7768}, beside the well"] = "{item:7768}, ao lado do poço",
		["{npc:5899} lives in the southern {zone:1413}, south of {area:378}: her hut sits on a hilltop of {area:1701} with a spinning windmill beside it, and the way up is the ridge by the lone tree. Quilboar camp all around the hill; Stormhides, thunderhawks and hyenas roam the plains on the way."] = "{npc:5899} mora no sul de {zone:1413}, ao sul de {area:378}: a cabana dela fica no topo de um morro de {area:1701}, com um moinho de vento girando ao lado, e o caminho para subir é a crista junto à árvore solitária. Javatuscos acampam em volta do morro; Borrascouros, falcões-trovão e hienas rondam as planícies no caminho.",
		["{npc:5901} hands you the {item:6637} and the {item:7811}: take everything she offers before you leave for Silverpine, or you will be back for more."] = "{npc:5901} entrega {item:6637} e {item:7811} a você: pegue tudo o que ela oferecer antes de partir para Pinhaprata, ou você vai ter de voltar para pegar mais.",
		["{npc:5901} is not in {area:392}: take the small coast road south from {area:392} past the pirate camp and over a low hill; her fishing hut, with a shark strung up outside, stands by the water before the pirate ship. If you reach the ship you went too far."] = "{npc:5901} não está em {area:392}: pegue a estradinha da costa para o sul saindo de {area:392}, passando o acampamento pirata e um morro baixo; a cabana de pesca dela, com um tubarão pendurado do lado de fora, fica junto à água antes do navio pirata. Se chegar ao navio, foi longe demais.",
		["{npc:5901}: Narm's letter"] = "{npc:5901}: a carta de Narm",
		["{npc:5901}: Swart's letter"] = "{npc:5901}: a carta de Swart",
		["{npc:5901}: a new {quest:972}"] = "{npc:5901}: uma nova {quest:972}",
		["{npc:5901}: your {item:6637}"] = "{npc:5901}: sua {item:6637}",
		["{npc:5901}: {npc:5892}'s letter"] = "{npc:5901}: a carta de {npc:5892}",
		["{npc:5901}: {npc:5906}' letter"] = "{npc:5901}: a carta de {npc:5906}",
		["{npc:5901}: {spell:5394} and your {item:5177}"] = "{npc:5901}: {spell:5394} e seu {item:5177}",
		["{quest:63} (Horde)"] = "{quest:63} (Horda)",
} end)()
t.guides["forever/class/shaman/darkreaver"] = (function() return {
		["200 Horde reputation"] = "200 de reputação com a Horda",
		["A five-player dungeon event: {area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}. In the {object:179746}'s basement, first clear every mob in the room, then use the {item:18746} at its centre: four waves of spirits follow, each closing with an Aspect mini-boss (the first wave weak and slow, the rest elite). Fight in a corner so nothing else joins, and drink between waves: it is long. Then {npc:14516} (level 62 elite) appears: he Cleaves, casts {spell:686} and {spell:6958}, and Dominates a player's mind against the group. His head always drops."] = "Um evento de masmorra para cinco jogadores: {area:2057} fica sob {area:2298}, a cidade-ilha no sudeste de {zone:1422}. No porão do {object:179746}, primeiro mate todos os monstros da sala, depois use o {item:18746} no centro dela: seguem-se quatro ondas de espíritos, cada uma terminando com um mini-chefe Aspecto (a primeira onda fraca e lenta, as outras elite). Lute num canto para nada mais se juntar, e beba entre as ondas: é longo. Depois {npc:14516} (elite de nível 62) aparece: ele golpeia em arco, lança {spell:686} e {spell:6958} e domina a mente de um jogador contra o grupo. A cabeça dele sempre cai.",
		["A {area:2057} fight at 60 for Horde reputation; the {item:20134} may be gone in Forever."] = "Uma luta em {area:2057} no nível 60 por reputação da Horda; {item:20134} pode ter sumido no Forever.",
		["At 58 {npc:13417}, the shaman trainer in the {object:172957}, asks for two rare diamonds; every Horde shaman goes to him. Skyborne: Forever's quest page lists this quest for Orcs, Tauren and Trolls only: ask before you buy the diamonds."] = "No nível 58, {npc:13417}, o instrutor de xamã no {object:172957}, pede dois diamantes raros; todo xamã da Horda vai até ele. Celonatos: a página de missão do Forever lista esta missão só para Orcs, Taurens e Trolls: confirme antes de comprar os diamantes.",
		["Both diamonds are rare: the auction house is the quick way. Miners find the {item:12800} in about one Thorium vein in a hundred (the Small Thorium Veins north of {area:2418} in the {zone:1428} respawn every five minutes). The {item:18335} drops from high-level elites at about one in a hundred, best from the rare elite Revanchion (about one in nine)."] = "Os dois diamantes são raros: a Casa de Leilões é o jeito rápido. Mineiros acham {item:12800} em cerca de um veio de Tório a cada cem (os Veios de Tório Escasso ao norte de {area:2418}, em {zone:1428}, voltam a cada cinco minutos). {item:18335} cai de elites de nível alto em cerca de um a cada cem, melhor do elite raro Revanchion (cerca de um a cada nove).",
		["Two diamonds"] = "Dois diamantes",
		["he hands you the {item:18746}"] = "ele lhe entrega o {item:18746}",
		["{npc:13417}: 200 Horde reputation; the {item:20134} may be gone"] = "{npc:13417}: 200 de reputação da Horda; {item:20134} pode ter sumido",
		["{quest:7668} needs level 60."] = "{quest:7668} requer nível 60.",
} end)()
t.guides["forever/class/shaman/spirit-totem"] = (function() return {
		["A five-player dungeon: needs a group of five, about level 50-55. Fly to {area:75} and ride east. The {area:1417} ({area:1477}) stands in the middle of the {area:74}: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. Two feathers of each colour, one from each of six elite troll mini-bosses (level 51-52) on the balconies around the temple's great round room, every kill, and each player on the quest loots their own: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Mijan heals the others ({spell:139}, a {npc:3560}): kill him first; Hukku summons guardians and throws Shadow Bolt Volleys."] = "Uma masmorra para cinco jogadores: precisa de um grupo de cinco, de nível 50-55 mais ou menos. Voe para {area:75} e cavalgue para leste. {area:1417} ({area:1477}) fica no meio de {area:74}: suba as escadas do lado sul da ruína, mergulhe no salão alagado, nade para baixo por ele e siga as escadas e passagens até o portal. Duas penas de cada cor, uma de cada um dos seis minichefes trolls elite (nível 51-52) nas sacadas em volta do grande salão redondo do templo, a cada morte, e cada jogador com a missão saqueia as próprias: Talho e {npc:5716}, o Âmbar, Hukkah e Mirran, o Azul, Zolo e Lorro, o Verde. Mirran cura os outros ({spell:139}, um {npc:3560}): mate-o primeiro; Hukkah invoca guardiões e joga Salvas de Seta Sombria.",
		["At 50 {npc:13417}, the shaman trainer in the {object:172957}, asks for the four elements for {npc:6176}."] = "No nível 50, {npc:13417}, o instrutor de xamã no {object:172957}, pede os quatro elementos para {npc:6176}.",
		["At 50 {npc:3032}, a shaman trainer on {area:1640} in {zone:1456}, asks for the four elements for {npc:6176}. Skyborne: Forever's quest page lists {quest:8410} and {quest:8412} for Orcs, Tauren and Trolls only; if {npc:3032} has nothing for you, {npc:6176}'s own {quest:8411} is open to every Horde race, but {quest:8412} after it may still turn you away."] = "No nível 50, {npc:3032}, instrutor de xamã em {area:1640}, em {zone:1456}, pede os quatro elementos para {npc:6176}. Celonatos: a página de missões do Forever lista {quest:8410} e {quest:8412} só para Orcs, Taurens e Trolls; se {npc:3032} não tiver nada para você, {quest:8411} do próprio {npc:6176} está aberta a todas as raças da Horda, mas {quest:8412}, depois dela, ainda pode barrar você.",
		["Eight of each. Fly or ride to the {area:813} and on to the west edge of the {zone:1422}, north-west of {area:3197}: the Venom Mist Lurkers (level 50-51, they poison) give the {item:20610} and the Diseased Black Bears (level 51-52, {spell:3427}) the {item:20611}, one kill in five each; the two Carrion Vultures there drop either. The bigger Diseased Grizzlies and Plague Lurkers further east almost never drop them. A few bears and lurkers also roam south-east of {area:159} in Tirisfal."] = "Oito de cada. Voe ou cavalgue até {area:813} e siga até a borda oeste de {zone:1422}, a noroeste de {area:3197}: as Tocaieiras Rasterruça (nível 50-51, envenenam) soltam {item:20610} e os Ursos Pretos Doentes (nível 51-52, {spell:3427}) soltam {item:20611}, uma morte em cinco cada; os dois Abutres Carniceiros de lá soltam qualquer um. Os Ursos-cinzentos Doentes maiores e as Tocaieiras Pestilentas mais a leste quase nunca soltam. Alguns ursos e tocaieiras também rondam a sudeste de {area:159}, em Tirisfal.",
		["Experience and gold"] = "Experiência e ouro",
		["Experience and gold at 50, ending in the {area:1417}; the Classic item choice may be gone in Forever."] = "Experiência e ouro no nível 50, terminando em {area:1417}; a escolha de item do Classic pode ter sumido no Forever.",
		["One each of {item:7069}, Fire, Earth and Water; all four trade, so the auction house is quickest. To farm them, {zone:1417} has the exiles near {area:320} (level 38-39, about one kill in eight to ten, respawn under seven minutes): Thundering Exiles south-east of it (air), Rumbling Exiles south-west (earth), Burning Exiles far to the north-west (fire), and the {npc:2794} far to the south-west (water, about one in seven). Water comes easier from the Patches of Elemental Water in {zone:1447} (two in five) or {npc:14269} by {area:69} in Redridge."] = "Um de cada: {item:7069}, Fogo, Terra e Água; os quatro são negociáveis, então a Casa de Leilões é o mais rápido. Para farmar: {zone:1417} tem os exilados perto de {area:320} (nível 38-39, cerca de uma morte em oito a dez, voltam em menos de sete minutos): Exilados Trovejantes ao sudeste dela (ar), Exilados Tonitruantes ao sudoeste (terra), Exilados em Chamas bem ao noroeste (fogo) e {npc:2794} bem ao sudoeste (água, cerca de um em sete). A Água vem mais fácil das Poças de Água Elemental em {zone:1447} (dois em cinco) ou de {npc:14269}, perto de {area:69}, em Cristarrubra.",
		["Spider eye and bear claw"] = "Olho de aranha e garra de urso",
		["The four elements"] = "Os quatro elementos",
		["The {area:1417}"] = "{area:1417}",
		["{item:20606}: Gasher, {npc:5716}"] = "{item:20606}: Talho, {npc:5716}",
		["{item:20607}: Hukku, Mijan"] = "{item:20607}: Hukkah, Mirran",
		["{item:20608}: Zolo, Loro"] = "{item:20608}: Zolo, Lorro",
		["{item:7067}: Rumbling Exiles"] = "{item:7067}: Exilados Tonitruantes",
		["{item:7068}: Burning Exiles"] = "{item:7068}: Exilados em Chamas",
		["{item:7069}: Thundering Exiles"] = "{item:7069}: Exilados Trovejantes",
		["{item:7070}: the {npc:2794}, or {zone:1447}'s water patches"] = "{item:7070}: {npc:2794}, ou as poças de água de {zone:1447}",
		["{npc:6176} camps in the ruins of the east of {zone:1416}: from {area:272} follow the river east of town north into the hills."] = "{npc:6176} acampa nas ruínas do leste de {zone:1416}: a partir de {area:272}, siga para o norte, pelas colinas, o rio a leste da cidade.",
		["{npc:6176}: the old item choice may be gone, count on the experience"] = "{npc:6176}: a antiga escolha de item pode ter sumido, conte com a experiência",
		["{quest:8412} and {quest:8413}"] = "{quest:8412} e {quest:8413}",
} end)()
t.guides["forever/class/warlock/dread-mage-hat"] = (function() return {
		["A cloth hat in your late 20s: Zardeth's errand for any Alliance player pays warlocks this extra."] = "Um chapéu de pano no fim dos seus 20 e poucos níveis: a tarefa de Malvino serve a qualquer jogador da Aliança, e os bruxos ganham este extra.",
		["At 25 {npc:1435}, in the cellar of the {object:2164} in the {object:2101} (beside the warlock trainers), wants two ingredients for a brew. Do it when your leveling takes you to {zone:1431} and the {zone:1437}."] = "No nível 25, {npc:1435}, no porão do {object:2164}, no {object:2101} (ao lado dos instrutores de bruxo), quer dois ingredientes para uma poção. Faça quando sua subida de nível levar você a {zone:1431} e {zone:1437}.",
		["Back to Zardeth once more: he offers warlocks a reward, which his imp {npc:1733}, standing beside him, hands over."] = "De volta a Malvino mais uma vez: ele oferece uma recompensa aos bruxos, que o diabrete dele, {npc:1733}, ao lado dele, entrega.",
		["Back to Zardeth. He brews the {item:2788} and gives it to you for {npc:1439} in the Hall of Petitioners, the first hall on the right inside {object:2117}."] = "De volta a Malvino. Ele prepara {item:2788} e entrega a você, para {npc:1439}, no Hall of Petitioners, o primeiro salão à direita dentro de {object:2117}.",
		["The root grows at the water's edge in the pool below the small falls east of {area:836}, beside the {object:147516} cave below the {area:146}: a tall, spiky wooden root, not at the foot of the dam itself."] = "A raiz cresce na beira da água, na poça abaixo da pequena queda a leste de {area:836}, ao lado da caverna {object:147516} abaixo de {area:146}: uma raiz de madeira alta e espinhosa, não ao pé da própria represa.",
		["{area:1098} stands in the north-east of {zone:1431}, north of {area:42}. The {object:321} is a small white flower low in the grass of the fenced garden beside Stalvan's house: hard to see, so sweep the garden with your mouse. Fetid Corpses (level 29) wander the grounds and come quickly: at 25, send your voidwalker at the nearest one, grab the flower and leave. {npc:315} (32) is inside the house; leave him alone."] = "{area:1098} fica no nordeste de {zone:1431}, ao norte de {area:42}. {object:321} é uma florzinha branca baixa na grama do jardim cercado ao lado da casa de Stalvan: difícil de ver, então varra o jardim com o mouse. Cadáveres Fétidos (nível 29) rondam o terreno e chegam rápido: no nível 25, mande seu emissário do caos para cima do mais próximo, pegue a flor e saia. {npc:315} (32) fica dentro da casa; deixe-o em paz.",
} end)()
t.guides["forever/class/warlock/enchanted-gold-bloodrobe"] = (function() return {
		["A rare cloth robe for your 30s, which {npc:6266} makes from the parts you bring her."] = "Um manto de tecido raro para seus 30 e poucos, que {npc:6266} faz com as partes que você trouxer.",
		["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "No nível 31, {npc:3326}, na {object:172960}, manda você para {npc:6266}, em {area:392}. Compre {item:5770} e {item:3577} antes (próximos passos) para poupar uma viagem.",
		["At 31 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}; the zeppelin from {zone:1420} flies to {zone:1411}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "No nível 31, {npc:4563}, no {object:36082}, manda você para {npc:6266}, em {area:392}; o zepelim de {zone:1420} voa para {zone:1411}. Compre {item:5770} e {item:3577} antes (próximos passos) para poupar uma viagem.",
		["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "No nível 31, {npc:461}, no {object:2164}, no {object:2101}, manda você para {npc:6266}, em {area:392}. Compre {item:5770} e {item:3577} antes (próximos passos) para poupar uma viagem.",
		["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}. Buy a {item:5770} and a {item:3577} first (next steps) to save a trip."] = "No nível 31, {npc:5172}, em {zone:1455}, manda você para {npc:6266}, em {area:392}. Compre {item:5770} e {item:3577} antes (próximos passos) para poupar uma viagem.",
		["Back to {npc:2670} in {area:35}: he offers {quest:4785} as a quest you hand straight back to him. He may show no quest marker; talk to him anyway."] = "De volta a {npc:2670}, em {area:35}: ele oferece {quest:4785} como uma missão que você devolve direto a ele. Pode não ter marcador de missão; fale com ele mesmo assim.",
		["Back to {npc:6266}"] = "De volta a {npc:6266}",
		["Back to {npc:6266} with the thread, the coals and a {item:6265}. Then wait beside her while she works the robe (do not attack her: the quest log calls it a kill), and speak to her again."] = "De volta a {npc:6266} com a linha, os carvões e {item:6265}. Depois espere ao lado dela enquanto ela trabalha na túnica (não ataque: o registro de missões chama isso de morte), e fale com ela de novo.",
		["Tailors sew the {item:5770} from a rare pattern; miners smelt Gold Bars from {item:2776}. Everyone else buys both at the Auction House. If you wear the robe, take it off: {npc:6266} keeps it."] = "Alfaiates costuram {item:5770} a partir de um molde raro; mineiros fundem Barras de Ouro a partir de {item:2776}. Todos os outros compram os dois na Casa de Leilões. Se estiver usando a túnica, tire: {npc:6266} fica com ela.",
		["The Burning Exiles (level 38-39), fire elementals at the {area:334} in western {zone:1417}, drop the coal about one time in three. They resist fire: {spell:686} and Corruption. Below 38 they hit hard; the Cresting Charms from the Cresting Exiles near {area:321} finish one off once you have hurt it. Make a {item:6265} with {spell:1120} on the way."] = "Os Exilados em Chamas (nível 38-39), elementais de fogo em {area:334}, no oeste de {zone:1417}, soltam o carvão cerca de uma vez em três. Eles resistem a fogo: {spell:686} e Corrupção. Abaixo do nível 38 eles batem forte; os Patuás Pontudos dos Exilados Vagalhantes perto de {area:321} acabam com um deles depois que você o machuca. Faça {item:6265} com {spell:1120} no caminho.",
		["The Hatefury satyrs (level 31-32) hold {area:603} in the far north-east of {zone:1443}, past {area:608}: two kills in five give a vial, so plan on about 25. The Lesser Infernals (36-37) and Demon Portal Guardians (38) of {area:602}, in the south, drop the stone half the time; they resist fire, so use {spell:686} and Corruption."] = "Os sátiros Furiódio (nível 31-32) ocupam {area:603}, no extremo nordeste de {zone:1443}, depois de {area:608}: duas mortes em cinco soltam um frasco, então conte com umas 25. Os Infernais Menores (36-37) e os Guardiões do Portal Demoníaco (38) de {area:602}, ao sul, soltam a pedra em metade das vezes; eles resistem a fogo, então use {spell:686} e Corrupção.",
		["The boat from {area:392} sails to {area:35}. {npc:2670} runs {object:59851} on an upper level of the town. Give him the {item:3577}; he will spin the thread later."] = "O barco de {area:392} navega até {area:35}. {npc:2670} cuida de {object:59851} num nível superior da cidade. Entregue a ele o {item:3577}; ele fiará a linha depois.",
		["Vials of Hatefury Blood"] = "Ampolas de Sangue de Furiódio",
		["Wait beside {npc:6266} while she finishes the robe"] = "Espere ao lado de {npc:6266} enquanto ela termina a túnica",
		["You need no thread yet: {npc:6266} wants demon parts from {zone:1443} next."] = "Você ainda não precisa da linha: {npc:6266} quer partes de demônio de {zone:1443} a seguir.",
		["{item:3577}: the Auction House"] = "{item:3577}: a Casa de Leilões",
		["{item:5770} and a {item:3577}"] = "{item:5770} e {item:3577}",
		["{item:5770}: the Auction House"] = "{item:5770}: a Casa de Leilões",
		["{item:6265}: {spell:1120} on an Exile as it dies"] = "{item:6265}: {spell:1120} num Exilado enquanto ele morre",
		["{npc:6266} again"] = "{npc:6266} de novo",
		["{npc:6266} stands by {npc:6251}'s tower on the hill above {area:392}, behind the engineers' hut. She takes the robe, then sends the gold bar to {npc:2670} in {area:35}."] = "{npc:6266} fica ao lado da torre de {npc:6251}, no morro acima de {area:392}, atrás da cabana dos engenheiros. Ela pega a túnica e depois manda a barra de ouro para {npc:2670}, em {area:35}.",
		["{zone:1443} demons"] = "Demônios de {zone:1443}",
} end)()
t.guides["forever/class/warlock/felhunter-alliance"] = (function() return {
		["At 30 {npc:6120}, in the {object:32383}, sends you to {npc:6251} in {area:392}."] = "No nível 30, {npc:6120}, em {object:32383}, envia você a {npc:6251} em {area:392}.",
		["At 30 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6251} in {area:392}."] = "No nível 30, {npc:6122}, no porão de {object:2164} no {object:2101}, envia você a {npc:6251} em {area:392}.",
		["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "De volta a {npc:6251}, em {area:392}. Quando você aceita, ele desenha o círculo de invocação e os acólitos canalizam um círculo maior sobre ele: espere dentro da torre até os dois terminarem. Depois use {quest:1804} no círculo. O caçador vil (nível 30, não elite) silencia e come mana, e some depois de dois minutos: deixe seu emissário do caos fora, abra de imediato com seu dano ao longo do tempo e deixe o emissário tankar. Se você morrer ou ele vencer, abandone {quest:1795} e pegue de novo com {npc:6251}. Guarde o tomo: {npc:6251} pega de volta.",
		["Back to {npc:6294}"] = "De volta a {npc:6294}",
		["Felhunter (Alliance)"] = "Caçador Vil (Aliança)",
		["Rods of Channeling"] = "Bastões de Canalização",
		["Rods of Channeling, from the Dragonmaw casters"] = "Bastões de Canalização, dos conjuradores Presa do Dragão",
		["The Dragonmaw hold {area:1036} in the hills east of the road from {area:150} to {area:836}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "Os Presa do Dragão ocupam {area:1036}, nas colinas a leste da estrada de {area:150} para {area:836}. Só os conjuradores soltam os bastões, quatro mortes em cinco: os Guarda-ossos (nível 27, com ajudantes esqueletos) e os Guarda-sombras (28). Uma trilha íngreme ao norte do curandeiro de espíritos central leva até o acampamento, passando pela maioria dos guerreiros.",
		["The centaur cave opens in the cliffs north of {area:484}, a Horde town: keep clear of its guards. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "A caverna dos centauros se abre nos penhascos ao norte de {area:484}, uma cidade da Horda: fique longe dos guardas. Lá dentro, vá pela direita em cada bifurcação, atravesse a lagoa junto à pequena cachoeira e abra a caixinha escura encostada na parede ao lado de um baú maior: o maior é o errado. Você só consegue abrir enquanto está na missão. Os centauros reaparecem atrás de você na saída.",
		["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "O caçador vil, o demônio para usar contra lançadores de feitiços, e uma {item:22244} para seus fragmentos.",
		["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "O tomo é um livrinho cinza-azulado caído na areia de um acampamento de murlocs na costa a sudoeste de {area:271}, perto da beira da água. Seis ou sete murlocs guardam e mais ficam à espreita debaixo d'água: vêm em grupos, então use Medo em um e mantenha seu emissário do caos nos outros. Desça até a água para clicar nele; da encosta, as caixas atrapalham o cursor.",
		["{area:392} is a neutral goblin port on the {zone:1413} coast: the boat from {area:35} docks there. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6294} in {zone:1455}."] = "{area:392} é um porto goblin neutro na costa de {zone:1413}: o barco de {area:35} atraca lá. {npc:6251} fica no morro acima da cidade, atrás da cabana dos engenheiros, ao lado da torrezinha dele; {npc:6266} e dois acólitos estão com ele. Ele manda você para {npc:6294}, em {zone:1455}.",
		["{item:6931}, from the {quest:1802} on the sand"] = "{item:6931}, de {quest:1802}, na areia",
		["{item:6997}, in the {object:92423}"] = "{item:6997}, no {object:92423}",
		["{npc:6294} is in the library of the {object:32356}. He wants two lost pieces of the {quest:1758}: one on the {area:287} coast, one in {zone:1441}."] = "{npc:6294} fica na biblioteca do {object:32356}. Ele quer duas peças perdidas do {quest:1758}: uma na costa de {area:287}, outra em {zone:1441}.",
		["{npc:6294} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "{npc:6294} junta as peças do tomo e entrega {item:7006} a você: guarde, {npc:6251} pega junto com os bastões.",
		["{quest:1804}, on the circle"] = "{quest:1804}, no círculo",
} end)()
t.guides["forever/class/warlock/felhunter-horde"] = (function() return {
		["At 30 {npc:5675}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}. Take only one {quest:2996}: if {npc:6251} offers nothing, drop the duplicate from your log."] = "No nível 30, {npc:5675}, no {object:36082}, manda você a {npc:6251} em {area:392}. O zepelim de {zone:1420} voa para {zone:1411}. Pegue só um {quest:2996}: se {npc:6251} não oferecer nada, abandone a cópia no seu diário de missões.",
		["At 30 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:6251} in {area:392}."] = "No nível 30, {npc:5875}, na {object:172960} sob o {object:172982}, envia você a {npc:6251} em {area:392}.",
		["Back to {npc:6251} in {area:392}. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the {quest:1804} on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon {quest:1795} and take it again from {npc:6251}. Keep the tome: {npc:6251} takes it back."] = "De volta a {npc:6251}, em {area:392}. Quando você aceita, ele desenha o círculo de invocação e os acólitos canalizam um círculo maior sobre ele: espere dentro da torre até os dois terminarem. Depois use {quest:1804} no círculo. O caçador vil (nível 30, não elite) silencia e come mana, e some depois de dois minutos: deixe seu emissário do caos fora, abra de imediato com seu dano ao longo do tempo e deixe o emissário tankar. Se você morrer ou ele vencer, abandone {quest:1795} e pegue de novo com {npc:6251}. Guarde o tomo: {npc:6251} pega de volta.",
		["Back to {npc:6293}"] = "De volta a {npc:6293}",
		["Felhunter (Horde)"] = "Caçador Vil (Horda)",
		["Rods of Channeling"] = "Bastões de Canalização",
		["Rods of Channeling, from the Dragonmaw casters"] = "Bastões de Canalização, dos conjuradores Presa do Dragão",
		["The Dragonmaw hold {area:1036} in the hills east of the road through the {zone:1437}, south of the {area:881} you cross from {zone:1417}. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors."] = "Os Presa do Dragão ocupam {area:1036}, nas colinas a leste da estrada que passa por {zone:1437}, ao sul de {area:881}, que você atravessa vindo de {zone:1417}. Só os conjuradores soltam os bastões, quatro mortes em cinco: os Guarda-ossos (nível 27, com ajudantes esqueletos) e os Guarda-sombras (28). Uma trilha íngreme ao norte do curandeiro de espíritos central leva até o acampamento, passando pela maioria dos guerreiros.",
		["The centaur cave opens in the cliffs north of {area:484}. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out."] = "A caverna dos centauros se abre nos penhascos ao norte de {area:484}. Lá dentro, vá pela direita em cada bifurcação, atravesse a lagoa junto à pequena cachoeira e abra a caixinha escura encostada na parede ao lado de um baú maior: o maior é o errado. Você só consegue abrir enquanto está na missão. Os centauros reaparecem atrás de você na saída.",
		["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "O Caçador Vil, o demônio para enfrentar conjuradores, e uma {item:22244} para seus fragmentos.",
		["The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of {area:271}, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor."] = "O tomo é um livrinho cinza-azulado caído na areia de um acampamento de murlocs na costa a sudoeste de {area:271}, perto da beira da água. Seis ou sete murlocs guardam e mais ficam à espreita debaixo d'água: vêm em grupos, então use Medo em um e mantenha seu emissário do caos nos outros. Desça até a água para clicar nele; da encosta, as caixas atrapalham o cursor.",
		["{area:392}'s flight point is a short flight from {zone:1454}'s. {npc:6251} stands on the hill above the town, behind the engineers' hut, by his little tower; {npc:6266} and two acolytes are with him. He sends you to {npc:6293} in the {zone:1458}."] = "O ponto de voo de {area:392} é um voo curto a partir do de {zone:1454}. {npc:6251} fica no morro acima da cidade, atrás da cabana dos engenheiros, ao lado da torrezinha dele; {npc:6266} e dois acólitos estão com ele. Ele manda você para {npc:6293}, na {zone:1458}.",
		["{item:6931}, from the {quest:1803} on the sand"] = "{item:6931}, de {quest:1803}, na areia",
		["{item:6997}, in the {object:92423}"] = "{item:6997}, no {object:92423}",
		["{npc:6293} is in the {object:36082} of the {zone:1458}. He wants two lost pieces of the {quest:1801}: one on the {area:287} coast, one in {zone:1441}."] = "{npc:6293} fica no {object:36082} da {zone:1458}. Ele quer duas peças perdidas do {quest:1801}: uma na costa de {area:287}, outra em {zone:1441}.",
		["{npc:6293} pieces the tome together and gives you the {item:7006}: keep it, {npc:6251} takes it with the rods."] = "{npc:6293} junta as peças do tomo e entrega {item:7006} a você: guarde, {npc:6251} pega junto com os bastões.",
		["{quest:1804}, on the circle"] = "{quest:1804}, no círculo",
} end)()
t.guides["forever/class/warlock/imp-alliance"] = (function() return {
		["Feather Charms"] = "Patuás de Penas",
		["Imp (Alliance)"] = "Diabrete (Aliança)",
		["The Defias tent stands in the vineyard east of the Abbey. The book is small: it lies on the ground just right of the tent's opening, beside a blue jug. Three Defias Thugs (level 3-4) guard the tent; pull them one at a time, or step inside the tent and click the book, where they cannot reach you. The book respawns three minutes after someone takes it."] = "A tenda dos Défias fica no vinhedo a leste da Abadia. O livro é pequeno: está no chão, logo à direita da abertura da tenda, ao lado de uma jarra azul. Três Capangas Défias (nível 3-4) guardam a tenda; puxe um de cada vez, ou entre na tenda e clique no livro, onde eles não alcançam você. O livro volta três minutos depois de alguém pegá-lo.",
		["The Frostmane Novices (level 3-4) sit at the back of the troll cave south of {area:77}, near Grek'nir the Cold by the icy pool: take the left tunnel past the entrance. Four kills in five drop a charm, but only two or three novices spawn, so you may wait out their three-minute respawn. They throw frostbolts from range; the Troll Whelps at the cave mouth jump anyone who passes. With the charms, your hearthstone takes you straight back: a new character's is set to {area:132}."] = "Os Noviços Jubafria (nível 3-4) ficam no fundo da caverna dos trolls ao sul de {area:77}, perto de Grek'nir, o Frio, junto à lagoa gelada: pegue o túnel da esquerda depois da entrada. Quatro mortes em cinco soltam um patuá, mas só dois ou três noviços aparecem, então você pode ter de esperar os três minutos de reaparecimento. Eles jogam setas de gelo à distância; os Filhotes de Troll na boca da caverna atacam quem passa. Com os patuás, sua Pedra de Regresso leva você direto de volta: a de um personagem novo está definida para {area:132}.",
		["The {object:83763}"] = "{object:83763}",
		["Your first demon at level 1-4: the imp, from your start zone's warlock trainer."] = "Seu primeiro demônio no nível 1-4: o diabrete, com o instrutor de bruxo da sua zona inicial.",
		["Your first letter ({item:9576}, from {npc:197} after Kobold Camp Cleanup) points you to {npc:459}, the warlock trainer in the little graveyard beside {area:24}. She asks for a book the Defias stole."] = "Sua primeira carta ({item:9576}, de {npc:197} depois de Limpeza no acampamento dos kobolds) leva você a {npc:459}, a instrutora de bruxo no cemitériozinho ao lado de {area:24}. Ela pede um livro que os Défias roubaram.",
		["Your first letter ({item:9577}, from {npc:658} after Dwarven Outfitters) points you to {npc:460}, the warlock trainer upstairs inside {area:77}. He asks for three Feather Charms."] = "Sua primeira carta ({item:9577}, de {npc:658} depois de Provedores enânicos) leva você a {npc:460}, o instrutor de bruxo no andar de cima de {area:77}. Ele pede três Patuás de Penas.",
		["{item:6785}, from the {object:83763}"] = "{item:6785}, de {object:83763}",
		["{npc:459} (Humans)"] = "{npc:459} (Humanos)",
		["{npc:459} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:459} ensina {spell:688} na entrega: invoque na hora, não custa nada e luta ao seu lado.",
		["{npc:460} (Gnomes)"] = "{npc:460} (Gnomos)",
		["{npc:460} teaches you {spell:688} at the hand-in: summon it right away, it costs nothing and fights beside you."] = "{npc:460} ensina {spell:688} na entrega: invoque na hora, não custa nada e luta ao seu lado.",
} end)()
t.guides["forever/class/warlock/imp-horde"] = (function() return {
		["Imp (Horde)"] = "Diabrete (Horda)",
		["Rattlecage Skulls"] = "Crânios de Range-ossos",
		["The Rattlecage Skeletons (level 2-3) stand around the old smithy buildings just north of {area:154}, often right against the walls. Four kills in five drop a skull, so plan on about five; twenty of them spawn there and each comes back after five minutes."] = "Os Esqueletos Range-ossos (nível 2-3) ficam em volta dos velhos prédios da forja logo ao norte de {area:154}, muitas vezes encostados nas paredes. Quatro mortes em cinco soltam um crânio, então conte com umas cinco; vinte aparecem ali e cada um volta depois de cinco minutos.",
		["The {quest:1485} (level 3-4) swarm the {area:365}, the cave north of the Den, inside and around its mouth. Almost every kill drops a head (80%), so about eight kills does it; they throw small fireballs, so pull them one at a time. They respawn in just over three minutes. Other classes hunt the same imps for their own {quest:1485} quest."] = "Os {quest:1485} (nível 3-4) infestam {area:365}, a caverna ao norte da Toca, por dentro e em volta da boca. Quase toda morte solta uma cabeça (80%), então umas oito mortes resolvem; eles jogam bolas de fogo pequenas, então puxe um de cada vez. Voltam em pouco mais de três minutos. Outras classes caçam os mesmos diabretes para a própria missão de {quest:1485}.",
		["Vile Familiar Heads"] = "Cabeças de Demônio Familiar Vil",
		["Your first demon at level 1-4: the imp, with a starter blade or staff for Orcs and Trolls."] = "Seu primeiro demônio no nível 1-4: o diabrete, com uma lâmina ou cajado inicial para Orcs e Trolls.",
		["Your first letter ({item:9578}, from {npc:1569} after The Mindless Ones) points you to Maximillion, the warlock trainer in {area:154}. {npc:5667} waits inside the building beside him and asks for three Rattlecage Skulls."] = "Sua primeira carta ({item:9578}, de {npc:1569} depois de Os desmiolados) leva você a Maximillion, o instrutor de bruxo em {area:154}. {npc:5667} espera dentro do prédio ao lado dele e pede três Crânios de Range-ossos.",
		["Your first letter ({item:9579} for Orcs, {item:282346} for Trolls, from Gornek after Cutting Teeth) points you to Nartok, the warlock trainer in the Den. {npc:5765} stands just outside the Den in the {area:363} and asks for six Vile Familiar Heads."] = "Sua primeira carta ({item:9579} para Orcs, {item:282346} para Trolls, de Gornek depois de Dentes cortantes) leva você a Nartok, o instrutor de bruxo na Toca. {npc:5765} fica logo fora da Toca, em {area:363}, e pede seis Cabeças de Demônio Familiar Vil.",
		["{npc:5667} (Undead)"] = "{npc:5667} (Mortos-vivos)",
		["{npc:5667} teaches you {spell:688} when you hand in the skulls: summon it right away, it costs nothing and fights beside you."] = "{npc:5667} ensina {spell:688} quando você entrega os crânios: invoque na hora, não custa nada e luta ao seu lado.",
		["{npc:5765} (Orcs and Trolls)"] = "{npc:5765} (Orcs e Trolls)",
		["{npc:5765} teaches you {spell:688} when you hand in the heads: summon it right away, it costs nothing and fights beside you. Then speak with {npc:3145} a few steps away for a starter weapon."] = "{npc:5765} ensina {spell:688} quando você entrega as cabeças: invoque na hora, não custa nada e luta ao seu lado. Depois fale com {npc:3145}, a poucos passos, para pegar uma arma inicial.",
} end)()
t.guides["forever/class/warlock/impsys-request"] = (function() return {
		["A staff, off-hand or robe for your 50s; {npc:14470}'s own errand, not a step of the Dreadsteed chain."] = "Um cajado, item de mão secundária ou toga para os 50; tarefa própria de {npc:14470}, não uma etapa da série do Corcel Medonho.",
		["Amber Voodoo Feathers: Gasher, {npc:5716}"] = "Penas Vodu Âmbar: Talho, {npc:5716}",
		["At 50 {npc:3326} in the {object:172960} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "No nível 50, {npc:3326} na {object:172960} manda você a {npc:14470} em {zone:1448} com um pedaço de {item:14256}.",
		["At 50 {npc:4563} in the {object:36082} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "No nível 50, {npc:4563} no {object:36082} manda você a {npc:14470} em {zone:1448} com um pedaço de {item:14256}.",
		["At 50 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "No nível 50, {npc:461}, no {object:2164}, no {object:2101}, manda você para {npc:14470}, em {zone:1448}, com um pedaço de {item:14256}.",
		["At 50 {npc:5172} in {zone:1455} sends you to {npc:14470} in {zone:1448} with a piece of {item:14256}."] = "No nível 50, {npc:5172}, em {zone:1455}, manda você para {npc:14470}, em {zone:1448}, com um pedaço de {item:14256}.",
		["Blue Voodoo Feathers: Hukku, Mijan"] = "Penas Vodu Azuis: Hukkah, Mirran",
		["Choose the {item:20536} (staff), the {item:20534} (off-hand) or the {item:20530}."] = "Escolha {item:20536} (cajado), {item:20534} (mão secundária) ou {item:20530}.",
		["Green Voodoo Feathers: Zolo, Loro"] = "Penas Vodu Verdes: Zolo, Lorro",
		["One {item:14256}: the Jadefire satyrs of {zone:1448} drop it about one kill in fourteen, and so do the Legashi satyrs and the Felguard Sentries you hunt for Niby's essences. Quicker: buy one at the Auction House. You need it for the trainer's {quest:8419} or for {npc:14470}'s own {quest:8420}, the same errand: whichever you hold."] = "Um {item:14256}: os sátiros Jadefire de {zone:1448} soltam cerca de uma morte em catorze, e os sátiros Legashi e as Sentinelas Guarda Vil que você caça para as essências de Niby também. Mais rápido: compre um na Casa de Leilões. Você precisa dele para {quest:8419} do instrutor ou para {quest:8420} do próprio {npc:14470}, a mesma tarefa: a que você tiver.",
		["The Irontree treants (level 52) of {area:1767}, in northern {zone:1448} west of {area:1998}, drop {item:20613} one time in four; the big {npc:7149} (55) often drops three at once but hits hard and dazes. The Tainted Oozes (51) around {npc:14470} and along the Bloodvenom drop the essence one time in five."] = "Os ents Irontree (nível 52) de {area:1767}, no norte de {zone:1448}, a oeste de {area:1998}, soltam {item:20613} uma vez em quatro; o grande {npc:7149} (55) costuma soltar três de uma vez, mas bate forte e atordoa. As Gosmas Maculadas (51) em volta de {npc:14470} e ao longo do Bloodvenom soltam a essência uma vez em cinco.",
		["The {area:1417}"] = "O {area:1417}",
		["The {area:1417} ({area:1477}, level 50-56, a group of five) stands in the middle of the {area:74}: swim down into the temple and take the stairs to the entrance. The six troll guardians (level 51-52, elite) stand on the balconies around the central pit, each with adds; each drops his feather every time: Gasher and {npc:5716} the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Not soloable at 52."] = "{area:1417} ({area:1477}, nível 50-56, grupo de cinco) fica no meio de {area:74}: nade para baixo até o templo e pegue as escadas até a entrada. Os seis guardiões trolls (nível 51-52, elite) ficam nas sacadas em volta do fosso central, cada um com reforços; cada um solta a pena dele toda vez: Talho e {npc:5716}, o Âmbar, Hukkah e Mirran, o Azul, Zolo e Lorro, o Verde. Não dá para fazer solo no 52.",
		["{item:20613} and Bloodvenom"] = "{item:20613} e Peçonha",
		["{npc:14470} again"] = "{npc:14470} de novo",
		["{npc:14470} now wants six {item:20609} from the {area:1417}: a dungeon run."] = "{npc:14470} agora quer seis {item:20609} de {area:1417}: uma corrida de masmorra.",
		["{npc:14470} waits beside {npc:14469} on a rise just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. Hand him the trainer's {quest:8419} with the cloth. Next he wants ten {item:20613} and four {item:20614}."] = "{npc:14470} espera ao lado de {npc:14469} numa elevação logo a nordeste de {area:1997}: vindo para o norte pela ponte de {area:1765}, eles ficam fora da estrada, a leste, depois de algumas gosmas. Entregue a ele {quest:8419} do instrutor com o pano. Em seguida ele quer dez {item:20613} e quatro {item:20614}.",
		["{npc:14470} waits beside {npc:14469} on a rise just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. Take his own {quest:8420} and hand him the cloth at once. Next he wants ten {item:20613} and four {item:20614}."] = "{npc:14470} espera ao lado de {npc:14469} numa elevação logo a nordeste de {area:1997}: vindo para o norte pela ponte de {area:1765}, eles ficam fora da estrada, a leste, depois de algumas gosmas. Pegue {quest:8420} dele e entregue o pano na hora. Em seguida ele quer dez {item:20613} e quatro {item:20614}.",
} end)()
t.guides["forever/class/warlock/incubus-alliance"] = (function() return {
		["At 20 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257}."] = "No nível 20, {npc:6120}, o instrutor de bruxo na {object:32383} de {zone:1455}, manda você para {npc:6122}, em {zone:1453}. Pegue o {area:2257}.",
		["At 20 {npc:6122}, in the cellar of the {object:2164} in the {object:2101}, sends you to {npc:6244} in the {zone:1413}: a long trip for the Alliance. Take the boat from {area:150} to Theramore and head west through {zone:1445}, or the boat from {area:35} to {area:392}."] = "No nível 20, {npc:6122}, no porão do {object:2164}, no {object:2101}, manda você para {npc:6244}, em {zone:1413}: uma viagem longa para a Aliança. Pegue o barco de {area:150} até Theramore e siga para oeste por {zone:1445}, ou o barco de {area:35} até {area:392}.",
		["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "No nível 20: o súcubo e o íncubo do Forever, seu gêmeo masculino, cada um com uma bolsa de almas para seus fragmentos.",
		["Back to {npc:6122} with the {quest:1738}. He hands you the {item:6913}: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, {npc:6122} takes it back."] = "De volta a {npc:6122} com {quest:1738}. Ele entrega {item:6913} a você: desça as escadas atrás dele até a cripta; no meio do corredor mais baixo, uma escada lateral à esquerda leva à sala com o círculo roxo. Fique nele e use o núcleo. Invoque seu emissário do caos primeiro e mantenha o súcubo (nível 20, não elite) no círculo, senão os guardas podem matá-lo e a morte não conta. Se ele vencer, use o núcleo de novo; guarde, {npc:6122} pega de volta.",
		["Give Gakin the figurine, then use the {item:190309} at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: {npc:6122} takes it back."] = "Entregue a estatueta a Gakin, depois use {item:190309} no meio do mesmo círculo e derrote o íncubo que ele chama (nível 20, não elite; ele pode enfeitiçar você) com seu emissário do caos tankando. Guarde a estatueta: {npc:6122} pega de volta.",
		["Ordil'Aran lies in north-west {zone:1440}, north of {area:415} along the road toward {zone:1439}. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the {quest:1738} from as far away as it lets you. It is turned in to {npc:6122}, not to Takar."] = "Ordil'Aran fica no noroeste de {zone:1440}, ao norte de {area:415}, pela estrada rumo a {zone:1439}. Cerca de vinte cultistas da Linhagem das Trevas ocupam as ruínas em volta da grande árvore: fique junto à muralha externa e clique em {quest:1738} da maior distância que ele permitir. A entrega é a {npc:6122}, não a Takar.",
		["Succubus and Incubus (Alliance)"] = "Súcubo e Íncubo (Aliança)",
		["The house stands alone in the trees of north-western {zone:1440}, north-west of Ordil'Aran and well north of {area:413}: do it on the same trip as the {quest:1738}. Take the {item:190307} from the table outside, light it at a campfire (a {object:29784} of your own, or Talen's fire on {area:414}), and go straight back: the {item:190308} burns out after five minutes, so a fire of your own beside the house is quickest. Without it the figure in the house stops you. The figurine is upstairs."] = "A casa fica sozinha entre as árvores do noroeste de {zone:1440}, a noroeste de Ordil'Aran e bem ao norte de {area:413}: faça na mesma viagem de {quest:1738}. Pegue {item:190307} da mesa lá fora, acenda numa fogueira ({object:29784} sua, ou a fogueira de Talen em {area:414}) e volte direto: {item:190308} se apaga em cinco minutos, então uma fogueira sua ao lado da casa é o mais rápido. Sem ele, a figura na casa impede você. A estatueta fica no andar de cima.",
		["The {item:190309}"] = "{item:190309}",
		["the incubus"] = "o íncubo",
		["the succubus"] = "o súcubo",
		["{item:190307}, on the table outside"] = "{item:190307}, na mesa lá fora",
		["{item:190309}, upstairs"] = "{item:190309}, no andar de cima",
		["{item:6913}, on the circle in the crypt"] = "{item:6913}, no círculo da cripta",
		["{npc:185335}, at the circle in the crypt"] = "{npc:185335}, no círculo da cripta",
		["{npc:6244} camps at a tent with a campfire just north-east of {area:378}, by a fork in the road: Horde ground, so come in from the east and keep clear of the Taurajo guards. {npc:6247} beside him starts the {item:6898}. Takar offers both branches: take both."] = "{npc:6244} acampa numa tenda com fogueira logo a nordeste de {area:378}, numa bifurcação da estrada: terreno da Horda, então entre pelo leste e fique longe dos guardas de Taurajo. {npc:6247}, ao lado dele, inicia {item:6898}. Takar oferece os dois caminhos: pegue os dois.",
		["{quest:1717} (Gnomes)"] = "{quest:1717} (Gnomos)",
		["{quest:1739}: succubus"] = "{quest:1739}: súcubo",
		["{quest:65603}: incubus"] = "{quest:65603}: íncubo",
} end)()
t.guides["forever/class/warlock/incubus-horde"] = (function() return {
		["At 20 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:5909} a few steps away. Two trainers start these demons, {npc:5875} here and {npc:5675} in the {zone:1458}, and you can take only one; this guide follows whichever {quest:1472} you took. {npc:5909} offers both of {zone:1454}'s branches: take both."] = "No nível 20, {npc:5875}, na {object:172960} sob o {object:172982}, envia você a {npc:5909}, a poucos passos. Dois instrutores iniciam esses demônios, {npc:5875} aqui e {npc:5675} na {zone:1458}, e você só pode pegar um; este guia segue a {quest:1472} que você pegou. {npc:5909} oferece os dois ramos de {zone:1454}: pegue os dois.",
		["At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards."] = "No nível 20: o súcubo e o íncubo do Forever, seu gêmeo masculino, cada um com uma bolsa de almas para seus fragmentos.",
		["Back to {npc:5675} with Dalin's and {npc:5683}'s hearts. He hands you the {item:6286}: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, {npc:5675} takes them back."] = "De volta a {npc:5675} com os corações de Dalin e de {npc:5683}. Ele entrega {item:6286}: desça ao círculo de invocação abaixo dele, fique nele e use-os. Invoque seu emissário do caos primeiro e mantenha a luta no círculo, ou os guardas podem matá-la e a morte não conta. Se ela vencer, use os corações de novo; guarde-os, {npc:5675} os pega de volta.",
		["Back to {npc:5675} with the lovers' hearts, then place the {item:190181} on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: {npc:5675} takes them back."] = "De volta a {npc:5675} com os corações dos amantes, depois coloque {item:190181} no mesmo círculo e derrote o íncubo que eles chamam (nível 20, não elite; ele pode enfeitiçar você). Guarde os corações: {npc:5675} pega de volta.",
		["Back to {npc:5875} with the pendant. He hands you {item:6626}: take it across the {object:172960} to {npc:3216}'s tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: {npc:5875} takes it back."] = "De volta a {npc:5875} com o pingente. Ele entrega {item:6626}: leve-o pela {object:172960} até a tenda de {npc:3216}, fique no círculo roxo e use-o. Invoque seu emissário do caos primeiro e deixe-o segurar a atenção dela: a súcubo (nível 20, não elite) enfeitiça e chicoteia; mantenha seu dano ao longo do tempo nela. Se ela vencer, use o pingente de novo. Guarde o pingente: {npc:5875} o pega de volta.",
		["Back to {npc:5875} with the scarf, then use the {item:190232} on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: {npc:5875} takes it back."] = "De volta a {npc:5875} com o lenço, depois use {item:190232} no mesmo círculo da tenda de Neeru e derrote o íncubo que ele chama (nível 20, não elite) com seu emissário do caos tankando. Guarde o lenço: {npc:5875} pega de volta.",
		["Silverpine hearts"] = "Corações de Pinhaprata",
		["Succubus and Incubus (Horde)"] = "Súcubo e Íncubo (Horda)",
		["Take the road west from the Crossroads into {zone:1442} and, just past the border, the faint trail up to the left (south): {area:2539} cannot be reached from the main road. {npc:4197} hands you her draught for {npc:5911}."] = "Siga a estrada para o oeste da Encruzilhada até {zone:1442} e, logo depois da divisa, a trilha fraca que sobe à esquerda (sul): {area:2539} não pode ser alcançada pela estrada principal. {npc:4197} entrega a você a poção dela para {npc:5911}.",
		["the incubus"] = "o íncubo",
		["the succubus"] = "o súcubo",
		["{area:422} lies in southern {zone:1440}, south-west of {area:431}. The Shadethicket Stone Movers and Bark Rippers (level 25-26) around the lake drop the {item:190232} about one time in twenty, and the lone {npc:3931} (30) can drop it too: plan on a good number of kills, so come at 25 or later (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in {zone:1440}. They respawn in five minutes."] = "{area:422} fica no sul de {zone:1440}, a sudoeste de {area:431}. Os Move-pedras Umbrárvore e Rasga-cascas (nível 25-26) em volta do lago soltam {item:190232} cerca de uma vez em vinte, e o solitário {npc:3931} (30) também pode soltar: conte com bastantes mortes, então venha no 25 ou depois (o Forever deixou esta missão no nível 27); com o súcubo já ligado, você pode deixar para a sua subida de nível nos 20 e tantos em {zone:1440}. Voltam em cinco minutos.",
		["{item:6286}, on the circle below {npc:5675}"] = "{item:6286}, no círculo embaixo de {npc:5675}",
		["{item:6626}, on the circle in Neeru's tent"] = "{item:6626}, no círculo da tenda de Neeru",
		["{npc:185333} (level 22) works as a tailor for the {area:279} wizards at {area:233}, in eastern Silverpine: the wizards around her are hostile. {npc:5682} (level 20, not elite) patrols near the {area:230} in the far south. Both are Alliance-friendly humans: attacking them can flag you for PvP. Each drops her or his heart."] = "{npc:185333} (nível 22) trabalha como alfaiate para os magos de {area:279} em {area:233}, no leste de Pinhaprata: os magos em volta dela são hostis. {npc:5682} (nível 20, não elite) patrulha perto de {area:230}, no extremo sul. Os dois são humanos amigos da Aliança: atacá-los pode marcar você para JxJ. Cada um solta o coração dela ou dele.",
		["{npc:185334} (level 22) works in {area:392}, on the {zone:1413} coast, at one of two spots in town: take the zeppelin to {zone:1411} and head south, or fly from {zone:1454}. He is an Alliance-friendly human: attacking him can flag you for PvP."] = "{npc:185334} (nível 22) trabalha em {area:392}, na costa de {zone:1413}, em um de dois pontos da cidade: pegue o zepelim até {zone:1411} e siga para o sul, ou voe a partir de {zone:1454}. Ele é um humano amigo da Aliança: atacá-lo pode marcar você para JxJ.",
		["{npc:185335}, at the circle below {npc:5675}"] = "{npc:185335}, no círculo embaixo de {npc:5675}",
		["{npc:185335}, at the circle in Neeru's tent"] = "{npc:185335}, no círculo da tenda de Neeru",
		["{npc:3363} keeps {object:173018} on the main street east of the {object:172960}. He asks you to look for his mate Krilge in {zone:1440}."] = "{npc:3363} cuida de {object:173018}, a leste da {object:172960}, na rua principal. Ele pede que você procure sua companheira, Krilge, em {zone:1440}.",
		["{npc:3464} waits in front of the inn at the Crossroads. He sends you on to {npc:4197} at {area:2539}, in {zone:1442}."] = "{npc:3464} espera na frente da estalagem na Encruzilhada. Ele manda você a {npc:4197} em {area:2539}, em {zone:1442}.",
		["{npc:5683} (level 22, not elite; Comar in older records) wanders the north of the {zone:1437} just past the {area:881}, to the right as you come off the bridge. From the {zone:1458} head through {area:287} and {zone:1417}, where the mobs are 30 and up. Attacking her flags you for PvP."] = "{npc:5683} (nível 22, não elite; Comar nos registros antigos) anda pelo norte de {zone:1437}, logo depois de {area:881}, à direita ao sair da ponte. Da {zone:1458}, siga por {area:287} e {zone:1417}, onde os monstros são de nível 30 para cima. Atacá-la marca você para JxJ.",
		["{npc:5910} lives in a hut up on the cliffs on the west side of the city, above the {object:172982}: climb the wind rider tower, cross the bridge at its top to the west and turn right off it. She sends you to the Crossroads."] = "{npc:5910} mora numa cabana nos penhascos do lado oeste da cidade, acima do {object:172982}: suba a torre de mantícoras, atravesse a ponte no alto dela para o oeste e vire à direita saindo dela. Ela manda você para a Encruzilhada.",
		["{npc:5911} stands at {area:378}, south down the road from the Crossroads. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for {npc:5875}. Keep it."] = "{npc:5911} fica em {area:378}, ao sul pela estrada saindo da Encruzilhada. Ele manda você ao norte, ao acampamento de quilboar onde Dogran é mantido: o acampamento com duas cabanas lado a lado, a noroeste de um acampamento falso cujas cabanas ficam separadas. Um quilboar raro elite de nível 22 às vezes guarda as cabanas: mande seu emissário do caos entrar, sacrifique-o se precisar e fale com Dogran. Ele dá a você um pingente para {npc:5875}. Guarde-o.",
		["{object:1661}'s version, for warlocks who took {npc:5675}'s {quest:1472} instead of {npc:5875}'s. At 20 {npc:5675}, in the {object:36082}, sends you to {npc:5693} close by. {npc:5693} shows you an image of each quarry and offers both branches: take both."] = "A versão da {object:1661}, para bruxos que pegaram {quest:1472} de {npc:5675} em vez de {npc:5875}. No nível 20, {npc:5675}, no {object:36082}, manda você a {npc:5693}, ali perto. {npc:5693} mostra a você uma imagem de cada presa e oferece os dois ramos: pegue os dois.",
		["{quest:1474}: succubus ({zone:1458})"] = "{quest:1474}: súcubo ({zone:1458})",
		["{quest:1513}: succubus ({zone:1454})"] = "{quest:1513}: súcubo ({zone:1454})",
		["{quest:65597}: incubus ({zone:1458})"] = "{quest:65597}: íncubo ({zone:1458})",
		["{quest:65604}: incubus ({zone:1454})"] = "{quest:65604}: íncubo ({zone:1454})",
} end)()
t.guides["forever/class/warlock/orb-of-orahil"] = (function() return {
		["An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick."] = "Um orbe de mão secundária ou um cajado perto do nível 40, pelo caminho do canisvil ou do infernal, à sua escolha.",
		["At 35 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "No nível 35, {npc:3326}, na {object:172960}, envia você a {npc:6266} em {area:392}.",
		["At 35 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "No nível 35, {npc:4563}, no {object:36082}, envia você a {npc:6266} em {area:392}. O zepelim de {zone:1420} voa para {zone:1411}.",
		["At 35 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "No nível 35, {npc:461}, em {object:2164}, no {object:2101}, envia você a {npc:6266} em {area:392}.",
		["At 35 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "No nível 35, {npc:5172}, em {zone:1455}, envia você a {npc:6266} em {area:392}.",
		["Back to {npc:6266} in the tower above {area:392} with the cleansed orb. On the felhound path, accept her last quest and wait beside her while she completes the {item:15108} (do not attack her: the quest log calls it a kill), then speak to her again and pick the off-hand orb or the staff."] = "De volta a {npc:6266}, na torre acima de {area:392}, com o orbe purificado. No caminho do cão vil, aceite a última missão dela e espere ao lado enquanto ela termina {item:15108} (não ataque: o registro de missões chama isso de morte), depois fale com ela de novo e escolha o orbe de mão secundária ou o cajado.",
		["Back to {npc:6266} in the tower above {area:392} with the spirit and the gem first: her orb follows from it."] = "De volta a {npc:6266}, na torre acima de {area:392}, primeiro com o espírito e a gema: o orbe dela vem a partir disso.",
		["Choose an acolyte"] = "Escolha uma acólita",
		["On the infernal path, accept her last quest and wait beside {npc:6266} while she completes the {item:15107}, then speak to her again and pick the off-hand orb or the staff."] = "No caminho do infernal, aceite a última missão dela e espere ao lado de {npc:6266} enquanto ela termina {item:15107}, depois fale com ela de novo e escolha o orbe de mão secundária ou o cajado.",
		["Orb of Orahil"] = "Orbe de Orahil",
		["Pick one acolyte: you can take only one of their quests. {npc:6254}'s felhound path ends with the Orb or {item:15106}, the shadow versions; {npc:6252}'s infernal path with the Orb or {item:15105}, much the same items on the fire side. Most warlocks lean on shadow, but compare the four in their tooltips first. The guide follows the one you take. Keep the ruby or the emerald: it is handed back."] = "Escolha um acólito: você só pode pegar uma das missões deles. O caminho do cão vil de {npc:6254} termina com o Orbe ou {item:15106}, as versões das sombras; o caminho do infernal de {npc:6252} termina com o Orbe ou {item:15105}, itens parecidos do lado do fogo. A maioria dos bruxos prefere as sombras, mas compare os quatro nas dicas antes. O guia segue o que você pegar. Guarde o rubi ou a esmeralda: eles são devolvidos.",
		["The demon's spirit"] = "O espírito do demônio",
		["The {item:15107}"] = "{item:15107}",
		["The {item:15108}"] = "{item:15108}",
		["Wait beside {npc:6266} while she makes the orb"] = "Espere ao lado de {npc:6266} enquanto ela faz o orbe",
		["{area:602} fills south-central {zone:1443}, east of {area:2408}. The Burning Blade Summoners (level 38-39, warlocks with imps) carry the {item:7291} every time. For the spirit, bring your demon to low health with your damage over time, then channel the ruby or the emerald on it and keep channelling while it dies, as with {spell:1120}: the gem does no damage of its own. The ruby works on the coven's felhounds: the two Mana Eaters (37-38) in the north, and the Mage Hunters (38) and Ley Hunters (39) further south. The emerald works on the Lesser Infernals (36-37, sixteen of them, fire-resistant)."] = "{area:602} ocupa o centro-sul de {zone:1443}, a leste de {area:2408}. Os Evocadores da Lâmina Ardente (nível 38-39, bruxos com diabretes) soltam {item:7291} toda vez. Para o espírito, leve seu demônio a pouca vida com seu dano ao longo do tempo, depois canalize o rubi ou a esmeralda nele e continue canalizando enquanto ele morre, como com {spell:1120}: a gema não causa dano nenhum. O rubi funciona nos cães vis do coven: os dois Manávoros (37-38) no norte, e os Caça-magos (38) e Caçadores do Meridiano (39) mais ao sul. A esmeralda funciona nos Infernais Menores (36-37, dezesseis deles, resistentes a fogo).",
		["{item:12648}, from a {npc:4678}, {npc:4681} or {npc:4685}"] = "{item:12648}, de {npc:4678}, {npc:4681} ou {npc:4685}",
		["{item:12649}, from a {npc:4676}"] = "{item:12649}, de um {npc:4676}",
		["{item:7291}, from the Burning Blade Summoners"] = "{item:7291}, dos Evocadores da Lâmina Ardente",
		["{npc:6252}: he gives you the {item:12646}"] = "{npc:6252}: ela lhe dá a {item:12646}",
		["{npc:6254}: she gives you the {item:12647}"] = "{npc:6254}: ela lhe dá o {item:12647}",
		["{npc:6266} and her two acolytes stand in {npc:6251}'s tower on the hill above {area:392}."] = "{npc:6266} e seus dois acólitos ficam na torre de {npc:6251}, no morro acima de {area:392}.",
		["{npc:6546} lives at her farm in the middle of {zone:1445}, south of the road from the {zone:1413} and south-west of Theramore; a spirit healer stands beside it. Deadmire, a level 45 crocolisk, patrols the creeks just north-east. Before you accept Cleansing, clear the spiders and crocolisks around her paddock. Accepting starts a 3-minute timer: she walks to the paddock and lets the {npc:6549} out. It is elite (level 40): grouping up is encouraged; a warlock of about 40 can solo it with Fear or {spell:710} and damage over time, a level 35-38 one brings a friend. The timer keeps running after the kill, so hand in at once. If time runs out, abandon the quest and take it from {npc:6546} again."] = "{npc:6546} mora na fazenda dela, no meio de {zone:1445}, ao sul da estrada de {zone:1413} e a sudoeste de Theramore; um curandeiro de espíritos fica ao lado. Mortocharco, um crocolisco de nível 45, patrulha os riachos logo a nordeste. Antes de aceitar Purificação, limpe as aranhas e os crocoliscos em volta do cercado dela. Aceitar inicia um cronômetro de 3 minutos: ela anda até o cercado e solta {npc:6549}. Ele é elite (nível 40): vale a pena formar grupo; um bruxo de uns 40 consegue sozinho com Medo ou {spell:710} e dano ao longo do tempo, um de nível 35-38 leva um amigo. O cronômetro continua depois da morte, então entregue na hora. Se o tempo acabar, abandone a missão e pegue de novo com {npc:6546}.",
} end)()
t.guides["forever/class/warlock/orb-of-soranruk"] = (function() return {
		["A rare off-hand orb or staff for your 20s, for fragments from two dungeons."] = "Um orbe raro de mão secundária ou um cajado para os seus 20 e poucos níveis, por fragmentos de duas masmorras.",
		["Back to {npc:6247}"] = "De volta a {npc:6247}",
		["Choose the off-hand {item:6898} or the two-handed {item:15109}."] = "Escolha {item:6898}, de mão secundária, ou {item:15109}, de duas mãos.",
		["Soran'ruk Fragments, from the Twilight Acolytes inside"] = "Fragmentos de Soran'ruk, dos Acólitos do Crepúsculo lá dentro",
		["{area:236} (level 22-30, a group of five) stands on the hill south of the {area:228}. Free the prisoner in the cells right of the entrance and he opens the way into the courtyard. The Shadowfang Darksouls (level 20-21, elite) are not in the courtyard: they walk the halls past it, up the ramp that curves left and in the building after. About twelve stand in a run and one in five drops the Large Fragment, so clear every Darksoul and run it again if it does not drop."] = "{area:236} (nível 22-30, grupo de cinco) fica no morro ao sul de {area:228}. Liberte o prisioneiro nas celas à direita da entrada e ele abre o caminho para o pátio. As Almanegras Presa Negra (nível 20-21, elite) não ficam no pátio: andam pelos salões depois dele, pela rampa que curva à esquerda e no prédio seguinte. Cerca de doze aparecem por corrida e uma em cinco solta o Fragmento Grande, então limpe todas as Almanegras e refaça a corrida se não cair.",
		["{area:2797} (level 24-32, a group of five) opens in the ruins on the north-west coast of {zone:1440}, under the water at {area:414}. The Twilight Acolytes (level 24-25, elite, healers) stand in the last halls, around {npc:4832} and the altar before {npc:4829}; each one drops a fragment, but only three spawn in a run and they do not come back for two hours, so one run covers one warlock: kill them first, before they heal the rest."] = "{area:2797} (nível 24-32, grupo de cinco) abre nas ruínas da costa noroeste de {zone:1440}, embaixo d'água em {area:414}. Os Acólitos do Crepúsculo (nível 24-25, elite, curandeiros) ficam nos últimos salões, em volta de {npc:4832} e do altar diante de {npc:4829}; cada um solta um fragmento, mas só três aparecem por corrida e eles não voltam por duas horas, então uma corrida serve a um bruxo: mate-os primeiro, antes que curem os outros.",
		["{item:6915}, from the Shadowfang Darksouls inside"] = "{item:6915}, das Almanegras Presa Negra lá dentro",
		["{npc:6247} camps beside {npc:6244}, at a tent just north-east of {area:378} in the southern {zone:1413}. Alliance warlocks reach him from {area:392} or Theramore; Horde ones head south from the Crossroads. He wants fragments from two dungeons: take the quest before your {area:2797} and {area:236} runs."] = "{npc:6247} acampa ao lado de {npc:6244}, numa tenda a nordeste de {area:378}, no sul de {zone:1413}. Bruxos da Aliança chegam a ele de {area:392} ou Theramore; os da Horda vão para o sul saindo da Encruzilhada. Ele quer fragmentos de duas masmorras: pegue a missão antes das suas idas a {area:2797} e {area:236}.",
} end)()
t.guides["forever/class/warlock/shard-of-the-green-flame"] = (function() return {
		["A rare off-hand for your 50s from {npc:14469} and {npc:14470} in {zone:1448}, the camp that also offers An Imp's Request."] = "Um item de mão secundária raro para os níveis 50, de {npc:14469} e {npc:14470} em {zone:1448}, o acampamento que também oferece Pedido de diabrete.",
		["At 50 {npc:14469} and his imp {npc:14470} wait on a rise in central {zone:1448} just north-east of {area:1997}: coming north over the {area:1765} bridge, they stand off the road to the east, past a few oozes. {npc:14469} sends you to {npc:14470}, beside him, who wants three Flawless Fel Essences from three places."] = "No nível 50, {npc:14469} e o diabrete dele, {npc:14470}, esperam numa elevação no centro de {zone:1448}, logo a nordeste de {area:1997}: vindo para o norte pela ponte de {area:1765}, eles ficam fora da estrada, a leste, depois de algumas gosmas. {npc:14469} manda você para {npc:14470}, ao lado dele, que quer três Essências Vis Impecáveis de três lugares.",
		["Back to {npc:14469}"] = "De volta a {npc:14469}",
		["Back to {npc:14470}. He hands you the {item:18626}: keep it, it wakes the infernal {npc:14467}."] = "De volta a {npc:14470}. Ele entrega {item:18626} a você: guarde, ele acorda o infernal {npc:14467}.",
		["The Felguard Sentries (level 54) walk around the {area:72} in the south of the {zone:1419}, each with a felhunter. Leave the level 57 Servants of Razelikh alone: they cannot be killed without their own quest."] = "As Sentinelas Guarda Vil (nível 54) andam em volta de {area:72}, no sul de {zone:1419}, cada uma com um caçador vil. Deixe os Servos de Razelikh de nível 57 em paz: eles não podem ser mortos sem a missão própria.",
		["The Legashi satyrs (level 51-53) hold the Legash Encampment on {zone:1447}'s northern coast. Every kind drops the essence three times in four; the satyrs burn mana and the Hellcallers rain fire, so pull them singly."] = "Os sátiros Legashi (nível 51-53) ocupam o Acampamento Legash, na costa norte de {zone:1447}. Todos os tipos soltam a essência três vezes em quatro; os sátiros queimam mana e os Infernarautos fazem chover fogo, então puxe um de cada vez.",
		["{area:1763} lies just south of {area:1997}, west of the road. Of its two caves, {area:1770} is the northern one, further up the hill; the other has no Legionnaires. {area:1770}'s tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward {npc:9516}'s chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of {area:1763} and {area:1770} are all hostile."] = "{area:1763} fica logo ao sul de {area:1997}, a oeste da estrada. Das duas cavernas, {area:1770} é a do norte, mais acima no morro; a outra não tem Legionários. Os túneis de {area:1770} correm para o norte por baixo das colinas, e os Legionários de Jaedenar (nível 55) ficam nos salões mais fundos, das primeiras rampas até a câmara de {npc:9516}; eles dão Golpe Ascendente em quem luta corpo a corpo. Três mortes em quatro dão a essência, mas só uns onze aparecem: abra caminho e espere um reaparecimento de cinco minutos, se precisar. Os cultistas de {area:1763} e {area:1770} são todos hostis.",
		["{item:18626}, at {object:179677}"] = "{item:18626}, em {object:179677}",
		["{npc:14467}' remains lie in {area:1766}, the burnt crater north of {npc:14469}: follow the road north from his camp; the remains lie a little east of it. Use the {item:18626} beside them and wait for him to rise. {npc:14467} is elite (level 55): grouping up is encouraged; a warlock of 55 or more can solo him with Fear and damage over time, or with Enslave Demon, but fire spells do nothing to him and he knocks you back. If you die he heals to full; he rises again three minutes after he dies. An elite infernal patrols the pool south of the remains: pull {npc:14467} away from it. He always drops his core. Lost the {item:18626}? Abandon the quest and take it again from {npc:14470}."] = "Os restos de {npc:14467} ficam em {area:1766}, a cratera queimada ao norte de {npc:14469}: siga a estrada para o norte saindo do acampamento dele; os restos ficam um pouco a leste dela. Use {item:18626} ao lado deles e espere ele se erguer. {npc:14467} é elite (nível 55): vale a pena formar grupo; um bruxo de nível 55 ou mais consegue sozinho com Medo e dano ao longo do tempo, ou com Escravizar Demônio, mas magias de fogo não fazem nada nele e ele repele você. Se você morrer, ele se cura por completo; ele se ergue de novo três minutos depois de morrer. Um infernal elite patrulha a lagoa ao sul dos restos: puxe {npc:14467} para longe dele. Ele sempre solta o núcleo. Perdeu {item:18626}? Abandone a missão e pegue de novo com {npc:14470}.",
} end)()
t.guides["forever/class/warlock/tome-of-sacrifice"] = (function() return {
		["A rare off-hand at 60, {npc:14463}'s payment for capturing a {npc:12396} in the {zone:1419}."] = "Um item de mão secundária raro no nível 60, o pagamento de {npc:14463} por capturar um {npc:12396} nas {zone:1419}.",
		["At 60 {npc:14463} waits in the {area:73}, the demon-filled hollow in the west of the {zone:1419}. The Scar is full of hard-hitting elites: Soulstone yourself first, then keep to the right-hand wall going in, or ride through mounted. {npc:14463} gives you two errands at once."] = "No nível 60, {npc:14463} espera em {area:73}, a depressão cheia de demônios no oeste de {zone:1419}. A Cicatriz é cheia de elites que batem forte: use Pedra da Alma em você primeiro, depois mantenha-se na parede da direita ao entrar, ou atravesse montado. {npc:14463} entrega duas tarefas de uma vez.",
		["Back to {npc:14463}"] = "De volta a {npc:14463}",
		["Hand both in to {npc:14463} and take the {item:18601}. Find a {npc:12396} (level 61, elite) standing alone in the {area:73}, open from about 30 yards with your voidwalker on him, and channel the prison on him for about 20 seconds: he attacks you to break free, and his {spell:45} can interrupt the channel, so sacrifice the voidwalker for its shield if you must. Grouping up is encouraged: a second player to tank makes it easy. When the channel finishes he becomes the {item:18605}: click it. If the channel breaks, kill him or run, and try another."] = "Entregue os dois a {npc:14463} e pegue {item:18601}. Encontre um {npc:12396} (nível 61, elite) sozinho em {area:73}, abra de uns 30 metros com seu emissário do caos nele e canalize a prisão nele por uns 20 segundos: ele ataca você para se soltar, e o {spell:45} dele pode interromper a canalização, então sacrifique o emissário pelo escudo, se precisar. Vale a pena formar grupo: um segundo jogador para tankar facilita. Quando a canalização termina, ele vira {item:18605}: clique. Se a canalização quebrar, mate-o ou fuja e tente outro.",
		["The Hederine demons (level 57-60, elite) hold {area:2256} in the far south of {zone:1452}: grouping up is encouraged. Two Slayers guard the gorge past the bridge; the western tunnel leads to more Initiates, the easiest of them (watch for their {spell:7645}). A warlock can solo them one at a time with Fear or {spell:710} and damage over time, but slowly. Any of them can drop the Tears, four kills in five."] = "Os demônios Hederine (nível 57-60, elite) ocupam {area:2256}, no extremo sul de {zone:1452}: vale a pena formar grupo. Dois Matadores guardam a garganta depois da ponte; o túnel do oeste leva a mais Iniciados, os mais fáceis (cuidado com o {spell:7645} deles). Um bruxo consegue sozinho, um de cada vez, com Medo ou {spell:710} e dano ao longo do tempo, mas devagar. Qualquer um deles pode soltar as Lágrimas, quatro mortes em cinco.",
		["The Wildspawn satyrs (level 55-57, elite) fill the Warpwood Quarter, {area:2577}'s eastern wing: bring a group of five. Four in five drop a blood, but they do not come back for two hours and one full clear may come up short of fifteen; reset and run it again. The back door at {area:2518} needs the {item:18249}, which drops inside this wing; until someone has it, go in by {area:2577}'s main gate in central {zone:1444}."] = "Os sátiros Wildspawn (nível 55-57, elite) enchem o Quarteirão Warpwood, a ala leste de {area:2577}: leve um grupo de cinco. Quatro em cinco soltam um sangue, mas não voltam por duas horas e uma limpeza completa pode ficar abaixo de quinze; reinicie e refaça. A porta dos fundos em {area:2518} precisa de {item:18249}, que cai dentro desta ala; até alguém ter, entre pelo portão principal de {area:2577}, no centro de {zone:1444}.",
		["{item:18601}, on a {npc:12396}"] = "{item:18601}, em um {npc:12396}",
		["{item:18603}, from the Wildspawn inside"] = "{item:18603}, dos Wildspawn lá dentro",
		["{item:18605}, click it"] = "{item:18605}, clique",
} end)()
t.guides["forever/class/warlock/voidwalker-alliance"] = (function() return {
		["At 10 {npc:6120}, the warlock trainer in {zone:1455}'s {object:32383}, sends you to {npc:6122} in {zone:1453}. Take the {area:2257} from {object:171524}. If {npc:6120} does not offer it, go to {npc:6122} anyway: he still gives you the next quest."] = "No nível 10, {npc:6120}, o instrutor de bruxo na {object:32383} de {zone:1455}, manda você para {npc:6122}, em {zone:1453}. Pegue o {area:2257} a partir de {object:171524}. Se {npc:6120} não oferecer, vá até {npc:6122} mesmo assim: ele ainda entrega a próxima missão.",
		["At 10 {npc:6121}, in the cellar of the Lion's Pride Inn in {area:87} (the stairs down are in the back room past the butcher's table), sends you to {npc:6122} in {zone:1453}."] = "No nível 10, {npc:6121}, no porão da Estalagem Orgulho do Leão, em {area:87} (a escada para baixo fica no quarto dos fundos, depois da mesa do açougueiro), manda você para {npc:6122}, em {zone:1453}.",
		["Back to {npc:6122}. He hands you the {item:6928}. The circle is hard to find: take the stairs behind {npc:6122} down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: {spell:14868}, Corruption and {spell:348} with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: {npc:6122} takes it back."] = "De volta a {npc:6122}. Ele entrega {item:6928} a você. O círculo é difícil de achar: desça as escadas atrás de {npc:6122}; no meio do corredor mais baixo, uma escada lateral à esquerda leva a uma sala com um círculo roxo brilhante no meio. Fique nele e use o colar. O emissário do caos (nível 10, não elite) fica perigoso abaixo de 30% de vida: {spell:14868}, Corrupção e {spell:348} com seu diabrete nele, Medo quando ele chegar perto. Se ele vencer você, use o colar de novo. Guarde o colar: {npc:6122} pega de volta.",
		["Voidwalker (Alliance)"] = "Emissário do Caos (Aliança)",
		["Your tank demon at 10: the voidwalker, after a dark sorceress's choker and a fight in {npc:6122}'s crypt."] = "Seu demônio tanque no nível 10: o emissário do caos, depois do colar de uma feiticeira sombria e de uma luta na cripta de {npc:6122}.",
		["{item:6928}, on the circle in the crypt"] = "{item:6928}, no círculo da cripta",
		["{npc:6121}, Lion's Pride Inn cellar"] = "{npc:6121}, porão da Lion's Pride Inn",
		["{npc:881} (level 9) is inside the farmhouse at the {area:62}, south-east Elwynn near the Redridge road. {npc:473} (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on {npc:881} first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop."] = "{npc:881} (nível 9) está dentro da casa de fazenda em {area:62}, no sudeste de Elwynn, perto da estrada de Cristarrubra. {npc:473} (nível 10) e um guerreiro ficam com ela e entram na luta; Morgan fere e vai atrás do seu diabrete, então mantenha-o sob Medo. Ponha seu dano ao longo do tempo em {npc:881} primeiro, use Medo nos outros e saqueie o colar dela antes de acabar com eles: ele continua seu mesmo que você morra depois. Ela joga bolas de fogo à distância e volta três minutos depois de morrer. Tenha a missão antes de matá-la, senão o colar não cai.",
		["{quest:1685} (Humans)"] = "{quest:1685} (Humanos)",
		["{quest:1715} (Gnomes)"] = "{quest:1715} (Gnomos)",
		["{quest:1715} is the tavern in the {object:2101}; {npc:6122} is in its cellar, down the stairs inside."] = "{quest:1715} é a taberna do {object:2101}; {npc:6122} fica no porão dela, descendo as escadas lá dentro.",
} end)()
t.guides["forever/class/warlock/voidwalker-horde"] = (function() return {
		["At 10 {npc:3294} sends you to {npc:5875}. He stands outside at the back of {area:362}'s barracks, the big building on the east side of town (not the inn), a few steps from {npc:3172}, the warlock trainer. {npc:5875} stands with the senior warlocks in the {object:172960}, the cavern under {zone:1454}'s {object:172982}. An Orc or Troll leveling in {zone:1420} can take the {zone:1458} version from {npc:5724} in {area:159} instead (the {zone:1458} steps below): you can do only one of the two."] = "No nível 10, {npc:3294} manda você a {npc:5875}. Ele fica do lado de fora, nos fundos do quartel de {area:362}, o prédio grande no lado leste da cidade (não a estalagem), a poucos passos de {npc:3172}, o instrutor de bruxo. {npc:5875} fica com os bruxos mais experientes na {object:172960}, a caverna sob o {object:172982} de {zone:1454}. Um Orc ou Troll subindo de nível em {zone:1420} pode pegar a versão da {zone:1458} com {npc:5724} em {area:159} (as etapas da {zone:1458} abaixo): você só pode fazer uma das duas.",
		["At 10 {npc:5724}, upstairs in the {area:2119} in {area:159}, sends you to {npc:5675}: the version for the Undead, and for Orcs and Trolls who level in {zone:1420} instead of taking {npc:5875}'s. {npc:5675} stands in the {zone:1458}'s {object:36082}, by the Temple of the Damned."] = "No nível 10, {npc:5724}, no andar de cima da {area:2119} em {area:159}, manda você a {npc:5675}: a versão para os Mortos-vivos, e para Orcs e Trolls que sobem de nível em {zone:1420} em vez de pegar a de {npc:5875}. {npc:5675} fica no {object:36082} da {zone:1458}, junto ao Temple of the Damned.",
		["Back to {npc:5675}. He hands you the {item:6284}: go down the stairs from him to the summoning circle and use them while standing on it. Fight the voidwalker (level 10, not elite) on the circle: if it wanders off, the city guards may kill it and the kill does not count. {spell:14868}, Corruption and {spell:348} with your imp tanking bring it down; it hits harder below 30%. If you lose, use the runes again. Keep the runes: {npc:5675} takes them back."] = "De volta a {npc:5675}. Ele entrega {item:6284} a você: desça as escadas dele até o círculo de invocação e use enquanto estiver em cima dele. Lute com o emissário do caos (nível 10, não elite) no círculo: se ele se afastar, os guardas da cidade podem matá-lo e a morte não conta. {spell:14868}, Corrupção e {spell:348} com seu diabrete tankando derrubam ele; bate mais forte abaixo de 30%. Se perder, use as runas de novo. Guarde as runas: {npc:5675} pega de volta.",
		["Back to {npc:5875}. He hands you the {item:7464}: take them across the {object:172960} to {npc:3216}'s tent, stand on the purple circle on its floor and use them. The voidwalker (level 10, not elite) hits hard at 30% health and leaves after three minutes, so start at once: {spell:14868}, Corruption and {spell:348}, send your imp in, and Fear it when you need a breather. If it beats you or leaves, the glyphs are not used up: use them again on the circle. Keep the glyphs: {npc:5875} takes them back."] = "De volta a {npc:5875}. Ele entrega {item:7464}: leve-os pela {object:172960} até a tenda de {npc:3216}, fique no círculo roxo no chão dela e use-os. O emissário do caos (nível 10, não elite) bate forte com 30% de vida e vai embora depois de três minutos, então comece na hora: {spell:14868}, Corrupção e {spell:348}, mande seu diabrete e use Medo nele quando precisar de fôlego. Se ele vencer você ou for embora, os glifos não se esgotam: use-os de novo no círculo. Guarde os glifos: {npc:5875} os pega de volta.",
		["The Scarlet tower stands in the fields west of the {zone:1458}'s ruins (not the tower near {area:154}). The grimoire is in the small chest on the ground floor, under the stairs; ignore the chest upstairs. {npc:1662} (level 9) and a {npc:1537} guard it: kill them, or Fear the zealot while you deal with Perrine. Scarlet Missionaries and Zealots (level 7-9) walk the fields around the tower. The chest is back three seconds after anyone opens it."] = "A torre Escarlate fica nos campos a oeste das ruínas da {zone:1458} (não a torre perto de {area:154}). O grimório está no baú pequeno do térreo, embaixo da escada; ignore o baú do andar de cima. {npc:1662} (nível 9) e um {npc:1537} guardam: mate-os, ou use Medo no fanático enquanto cuida de Perrine. Missionários e Fanáticos Escarlates (nível 7-9) andam pelos campos em volta da torre. O baú volta três segundos depois de qualquer um abri-lo.",
		["Voidwalker (Horde)"] = "Emissário do Caos (Horda)",
		["Your tank demon at 10: the voidwalker, after a stolen book and a fight at a summoning circle."] = "Seu demônio tanque no nível 10: o emissário do caos, depois de um livro roubado e de uma luta num círculo de invocação.",
		["{area:817} is the cave in the cliffs just east of {zone:1454}'s gate. Inside, take the right-hand ramp up and follow it to the top: the {object:58595} sits on that upper ledge, which cannot be reached from the lower floor. The cave is packed with Burning Blade Apprentices and Fanatics (level 9-11, many with voidwalkers) that respawn quickly, and {npc:3204}, a level 14 Burning Blade warlock, stands near the stash. Old notes call him elite; Forever's data lists him as normal. At 10 it is hard alone: pull one pack at a time and Fear the extra, wait for 11, or go with a friend. The stash always holds the tablet."] = "{area:817} é a caverna nos penhascos logo a leste do portão de {zone:1454}. Lá dentro, suba a rampa da direita e siga até o topo: {object:58595} fica nessa saliência de cima, que não dá para alcançar pelo andar de baixo. A caverna está cheia de Aprendizes e Fanáticos da Lâmina Ardente (nível 9-11, muitos com emissários do caos) que voltam rápido, e {npc:3204}, um bruxo da Lâmina Ardente de nível 14, fica perto do esconderijo. As notas antigas o chamam de elite; os dados do Forever o listam como normal. No 10, é difícil sozinho: puxe um grupo de cada vez e use Medo no extra, espere o 11, ou vá com um amigo. O esconderijo sempre guarda a tábua.",
		["{item:6284}, on the circle below {npc:5675}"] = "{item:6284}, no círculo embaixo de {npc:5675}",
		["{item:6285}, in {object:37098}"] = "{item:6285}, em {object:37098}",
		["{item:6535}, in the {object:58595}"] = "{item:6535}, em {object:58595}",
		["{item:7464}, on the circle in Neeru's tent"] = "{item:7464}, no círculo da tenda de Neeru",
		["{npc:5724}, upstairs in the {area:159} inn"] = "{npc:5724}, no andar de cima da estalagem de {area:159}",
		["{quest:1506} (Orcs and Trolls)"] = "{quest:1506} (Orcs e Trolls)",
} end)()
t.guides["forever/class/warrior/brutal-armor"] = (function() return {
		["At 20, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6394} in {area:378}."] = "No nível 20, {npc:3041}, o instrutor de guerreiro de {zone:1456}, manda você a {npc:6394} no {area:378}.",
		["At 20, {npc:3354} in the {object:172958} sends you to {npc:6394} in {area:378}."] = "No nível 20, {npc:3354} no {object:172958} manda você a {npc:6394} no {area:378}.",
		["At 20, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6394} in {area:378}."] = "No nível 20, {npc:4595}, um instrutor de guerreiro de {zone:1458}, manda você a {npc:6394} no {area:378}.",
		["Back to {npc:5878} on {area:1699}. {quest:1848} is the first piece; he then sends you to three crafters, one per piece: take all three."] = "De volta a {npc:5878}, em {area:1699}. {quest:1848} é a primeira peça; depois ele manda você para três artesãos, um por peça: pegue as três.",
		["Fly to {area:378}. {npc:6394} stands in the hut with the leatherworking and tailoring trainers."] = "Voe para {area:378}. {npc:6394} fica na cabana com os instrutores de couraria e alfaiataria.",
		["Hillsbrad Miners"] = "Mineradores de Eira dos Montes",
		["Iron Bars"] = "Barras de Ferro",
		["Iron Bars: {npc:8673}"] = "Barras de Ferro: {npc:8673}",
		["Roogug in {area:1717}"] = "Rugug em {area:1717}",
		["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, his guards come with him. Inside take the left path at the first fork, cross the vine bridge over the pig pens, go past the room with the big cauldron: he waits in the room on the right. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "Rugug é um quilboar elite (nível 28) dentro de {area:1717}, a masmorra no extremo sul de {zone:1413}; uma masmorra para cinco jogadores: precisa de um grupo de cinco, os guardas dele vêm junto. Lá dentro, pegue o caminho da esquerda na primeira bifurcação, atravesse a ponte de cipós sobre os chiqueiros e passe pela sala do caldeirão grande: ele espera na sala da direita. Ele lança {spell:403} e chama Estrondores da Terra. O frasco sempre cai.",
		["Starts now at 20 at your trainer; four armor pieces at 30 (hauberk, helm, gauntlets, legguards), a shield on the way."] = "Começa agora no nível 20, com seu instrutor; quatro peças de armadura no 30 (cota, elmo, manoplas, perneiras), um escudo no caminho.",
		["Take the zeppelin from {zone:1454} to {zone:1420}; {npc:6411} works in the {zone:1458}'s {object:36078}. She wants 8 Sturdy Dragonmaw Shinbones."] = "Pegue o zepelim de {zone:1454} até {zone:1420}; {npc:6411} trabalha no {object:36078} da {zone:1458}. Ela quer 8 Tíbias Firmes de Presa do Dragão.",
		["The Dragonmaw orcs (level 26-30) camp in the middle of the {zone:1437}; from {area:321} in Arathi head south over the {area:881} ({area:150} is Alliance). With {quest:1846} from {npc:6411} in your log, every Raider, Swamprunner, Centurion, Shadowwarder and Bonewarder drops a {item:7131} (without the quest they drop none): right-click it to test it, and about one in four comes out sturdy, the rest break, so expect 30 or more kills for 8. You can test while moving or fighting. The orcs run for help at 15%; Raiders net you, Centurions shield-bash, Shadowwarders cast {spell:686}, Bonewarders raise skeletons."] = "Os orcs Presa do Dragão (nível 26-30) acampam no meio de {zone:1437}; a partir de {area:321}, em Arathi, siga para o sul pela {area:881} ({area:150} é da Aliança). Com {quest:1846}, de {npc:6411}, no seu registro, todo Saqueador, Corredor do Pântano, Centurião, Guarda-sombras e Guarda-ossos solta {item:7131} (sem a missão eles não soltam nenhuma): clique com o botão direito para testar, e cerca de uma em quatro sai firme, o resto quebra, então conte com 30 ou mais mortes para conseguir 8. Dá para testar andando ou lutando. Os orcs correm atrás de ajuda com 15%; os Saqueadores prendem você em rede, os Centuriões dão pancada de escudo, os Guarda-sombras lançam {spell:686}, os Guarda-ossos levantam esqueletos.",
		["The satyrs of {area:430}, north-east of {area:431} ({area:429}, level 28-30), and the Felmusk satyrs north-west of the post (25-27) drop a hoof four kills in five. A {area:429} satyr at 15% health may cast {spell:6925} and heal to full: finish it fast or stun it. Hellcallers throw Fireballs from 40 yards; Felmusk satyrs reek in melee and run for help at 15%."] = "Os sátiros de {area:430}, a nordeste de {area:431} ({area:429}, nível 28-30), e os sátiros Felmusk a noroeste do posto (25-27) soltam um casco em quatro de cada cinco mortes. Um sátiro de {area:429} com 15% de vida pode lançar {spell:6925} e se curar por completo: acabe com ele rápido ou atordoe. Os Infernarautos jogam Bolas de Fogo a 40 metros; os sátiros Felmusk fedem em combate corpo a corpo e correm atrás de ajuda com 15%.",
		["The {npc:6167} (level 28, not elite, larger than the young ones around her) roams the south edge of the {area:465} in south-west Stonetalon, near the road to {zone:1443}. She is the only one: she returns 5 minutes after dying and drops the {item:6840} four kills in five. She spits {spell:3396} from 30 yards."] = "{npc:6167} (nível 28, não elite, maior que as jovens em volta dela) ronda a borda sul de {area:465}, no sudoeste das Torres de Pedra, perto da estrada para {zone:1443}. Ela é a única: volta 5 minutos depois de morrer e solta {item:6840} em quatro de cada cinco mortes. Ela cospe {spell:3396} a 30 metros.",
		["You have 30 minutes, and each {item:7119} rots 15 minutes after you loot it, so take the quest only when ready (logging out does not stop the clock). The Silithid Mounds dot the {area:390} south of {area:378}; every silithid drops an antenna. Creepers (level 20-21) and Grubs are the easiest: Swarmers (21-22) call small swarms and Creepers lay eggs that hatch adds. The eastern part of the field has plenty of Creepers. {item:7120}, a shield, is the reward."] = "Você tem 30 minutos, e cada {item:7119} apodrece 15 minutos depois de saqueada, então pegue a missão só quando estiver pronto (deslogar não para o relógio). Os Montes de Terra Silitídeos se espalham por {area:390}, ao sul de {area:378}; todo silitídeo solta uma antena. Os Rastejantes (nível 20-21) e as Larvas são os mais fáceis: os Enxameadores (21-22) chamam pequenos enxames e os Rastejantes botam ovos que chocam reforços. A parte leste do campo tem Rastejantes de sobra. {item:7120}, um escudo, é a recompensa.",
		["You need 10 Iron Bars. Miners smelt them from {item:2772} (one ore a bar, {spell:3307} at {skill:186} 125); everyone else buys them at the auction house in {zone:1454}."] = "Você precisa de 10 Barras de Ferro. Mineiros fundem a partir de {item:2772} (um minério por barra, {spell:3307} em {skill:186} 125); todos os outros compram na Casa de Leilões de {zone:1454}.",
		["You need 10 {item:7127}. The Hillsbrad Miners (level 26-27) work the mine in the hills west of {area:271} and drop the azurite four kills in five; they fight in {spell:71}, sunder your armor and run for help at 30% health. Fly to {area:272} and head south-west."] = "Você precisa de 10 {item:7127}. Os Mineradores de Eira dos Montes (nível 26-27) trabalham na mina nas colinas a oeste de {area:271} e soltam a azurita em quatro de cada cinco mortes; eles lutam em {spell:71}, destroem sua armadura e correm atrás de ajuda com 30% de vida. Voe para {area:272} e siga para sudoeste.",
		["You need 15 Smoky Iron Ingots. The {area:2160} lies at the east end of {area:461}, east of {area:460}; every Windshear kobold (level 19-23) drops an ingot four kills in five. Stonecutters, Geomancers and Overlords run for help when low; Geomancers cast {spell:116}."] = "Você precisa de 15 Lingotes Fumegantes de Ferro. {area:2160} fica no extremo leste de {area:461}, a leste de {area:460}; todo kobold Cortavento (nível 19-23) solta um lingote em quatro de cada cinco mortes. Os Cortapedras, Geomantes e Senhores correm atrás de ajuda quando com pouca vida; os Geomantes lançam {spell:116}.",
		["from the Dragonmaw orcs: right-click to test it"] = "dos orcs Presa do Dragão: clique com o botão direito para testar",
		["{item:6840}, from the {npc:6167}"] = "{item:6840}, de {npc:6167}",
		["{item:6841}, from Roogug"] = "{item:6841}, de Rugug",
		["{item:7119}, from the silithid"] = "{item:7119}, do silitídeo",
		["{item:7126}, from the Windshear kobolds"] = "{item:7126}, dos kobolds Cortavento",
		["{item:7127}, from the Hillsbrad Miners"] = "{item:7127}, dos Mineradores de Eira dos Montes",
		["{npc:5878}'s hut sits on top of {area:1699}, east of the Crossroads: climb the broad ridge on the north or east side. {quest:1838} is a level 30 quest; take it now and gather on the way. {item:7587} list where each material comes from."] = "A cabana de {npc:5878} fica no alto de {area:1699}, a leste da Encruzilhada: suba pela crista larga do lado norte ou leste. {quest:1838} é uma missão de nível 30; pegue-a agora e vá coletando pelo caminho. {item:7587} indicam de onde vem cada material.",
		["{npc:6408} is in {area:367} on the {zone:1411} coast. He wants 7 Uncloven Satyr Hooves."] = "{npc:6408} fica em {area:367}, na costa de {zone:1411}. Ele quer 7 Cascos Não Fendidos de Sátiro.",
		["{npc:6410} works on {zone:1456}'s lowest level, close to the blacksmith."] = "{npc:6410} trabalha no andar mais baixo de {zone:1456}, perto do ferreiro.",
} end)()
t.guides["forever/class/warrior/fire-hardened-armor"] = (function() return {
		["At 20, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {quest:1698} in Redridge."] = "No nível 20, {npc:5113}, o instrutor de guerreiros de {zone:1455}, envia você a {quest:1698} nas Montanhas Cristarrubra.",
		["At 20, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {quest:1698} in Redridge."] = "No nível 20, {npc:5479}, ao lado de {npc:5480}, no prédio dos instrutores de guerreiro de {object:2100}, manda você para {quest:1698}, em Cristarrubra.",
		["At 20, {npc:7315}, the warrior trainer of {zone:1457}, sends you to {quest:1698} in Redridge."] = "No nível 20, {npc:7315}, o instrutor de guerreiros de {zone:1457}, envia você a {quest:1698} nas Montanhas Cristarrubra.",
		["Back to {npc:5413} in the {object:28027} for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly."] = "De volta a {npc:5413}, no {object:28027}, para pegar a couraça. Ele manda você depois para o ferreiro da sua raça; as peças dos outros dois ferreiros também estão abertas a você: fale direto com eles.",
		["Charred and Galvanized Horns"] = "Chifres Calcinados e Galvanizados",
		["Enter the {area:98} and come back"] = "Entre em {area:98} e volte",
		["Fire Hardened Armor"] = "Armadura Endurecida pelo Fogo",
		["Ride the {area:2257} from {zone:1453} to {zone:1455}. {quest:1704}, a gnome smith, works in {object:171524} near the engineering trainers. He wants 20 {item:6848}."] = "Pegue o {area:2257} de {zone:1453} até {zone:1455}. {quest:1704}, um ferreiro gnomo, trabalha em {object:171524}, perto dos instrutores de engenharia. Ele quer 20 {item:6848}.",
		["Roogug in {area:1717}"] = "Rugug em {area:1717}",
		["Roogug is an elite quilboar (level 28) inside {area:1717}, the dungeon at the south end of the {zone:1413}; a five-player dungeon: needs a group of five, and his guards come with him. Inside take the left path at the first fork, cross the root bridge, go past the big empty cauldron: he is in a dead end on the right, with about ten elites on the way. He casts {spell:403} and calls Earth Rumblers. The vial always drops."] = "Rugug é um quilboar elite (nível 28) dentro de {area:1717}, a masmorra no extremo sul de {zone:1413}; uma masmorra para cinco jogadores: precisa de um grupo de cinco, e os guardas dele vêm junto. Lá dentro, pegue o caminho da esquerda na primeira bifurcação, atravesse a ponte de raízes e passe pelo caldeirão grande vazio: ele fica num beco sem saída à direita, com uns dez elites no caminho. Ele lança {spell:403} e chama Estrondores da Terra. O frasco sempre cai.",
		["Scorched Spider Fangs"] = "Presas de Aranha Calcinadas",
		["Starts now at 20 with a shield; a hauberk at 28, then a coif, leggings and gauntlets from three smiths."] = "Começa agora no nível 20, com um escudo; uma cota no 28, depois uma coifa, perneiras e manoplas de três ferreiros.",
		["The Nightbane worgen of {zone:1431} (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of {area:42} drop the {quest:1705} four kills in five. {npc:6170} (level 32, not elite) carries the {item:6845} (also four in five): he walks between the inside and the mouth of the {area:2161} mine south-east of {area:42}, so wait at the entrance and pull him outside. {npc:6170} and the Tainted Ones poison and howl; Vile Fangs cause {spell:3427}."] = "Os worgen Nightbane de {zone:1431} (Corredores das Trevas, Presas Vis, Tecelões das Sombras, Worgen e Maculados, nível 26-31) ao sul e oeste de {area:42} soltam {quest:1705} em quatro de cada cinco mortes. {npc:6170} (nível 32, não elite) carrega {item:6845} (também quatro em cinco): ele anda entre o interior e a boca da mina de {area:2161}, ao sudeste de {area:42}, então espere na entrada e puxe-o para fora. {npc:6170} e os Maculados envenenam e uivam; as Presas Vis causam {spell:3427}.",
		["The chimaeras live south-west of {area:460} in the {area:465}: you need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the {item:6840} from the {npc:6167} (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit {spell:3396}, the Young cast {spell:403}. Alliance: fly to {area:467} and head south."] = "As quimeras vivem a sudoeste de {area:460}, em {area:465}: você precisa de 12 Chifres Calcinados das Quimeras Filhotes (nível 25-27) e Jovens (23-25), quatro mortes em cinco, e de {item:6840} de {npc:6167} (28, a grande), também quatro em cinco. Só vivem lá três Filhotes, duas Jovens e uma Matriarca, cada uma volta em 5 minutos, então você vai ter de esperar. Os Filhotes e a Matriarca cospem {spell:3396}, as Jovens lançam {spell:403}. Aliança: voe para {area:467} e siga para o sul.",
		["The shells lie on the ground under the wyvern nests at {area:482} in western {zone:1441}, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once."] = "As cascas ficam no chão embaixo dos ninhos de mantícoras em {area:482}, no oeste de {zone:1441}, mais fundo no desfiladeiro. Só existem nove e cada uma volta 3 minutos depois de você pegar, então você vai esperar; algumas coisas parecidas com cascas ali não podem ser saqueadas. As Mantícoras de Alcândora (nível 28-31) guardam e às vezes vêm várias de uma vez.",
		["The {quest:1708} grows on the sea floor just south of {area:150}, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and a {item:5996} removes the risk."] = "{quest:1708} cresce no fundo do mar logo ao sul de {area:150}, junto às cabanas de murlocs e a um barco naufragado: oito ali e dois a sudeste do porto, cada um volta em 3 minutos, então você vai esperar os reaparecimentos para chegar a 20. Os murlocs podem lançar rede em você debaixo d'água: cuide do fôlego, e uma {item:5996} elimina o risco.",
		["You have one hour, and {npc:6166}'s {spell:8553} leaves you drunk for 8-10 minutes. Run north-west into the {area:98}, keeping close to the cliff wall to miss most gnoll packs, and go in as far as the first fork; then come back to {npc:6166} (from the ridge you can jump down into {area:69}). Dying and releasing your spirit fails the quest: abandon it and {npc:6166} gives it again."] = "Você tem uma hora, e {spell:8553} de {npc:6166} deixa você bêbado por 8 a 10 minutos. Corra para noroeste até {area:98}, rente à parede do penhasco para evitar a maioria dos grupos de gnolls, e entre até a primeira bifurcação; depois volte a {npc:6166} (da crista dá para pular até {area:69}). Morrer e liberar o espírito faz a missão falhar: abandone e {npc:6166} entrega de novo.",
		["You need 50 fangs. The Leech Stalkers and Cave Stalkers (level 21-22) crawl in the middle of the {zone:1437}, north of {area:836}; every one drops a fang. They poison; back in 5 minutes."] = "Você precisa de 50 presas. As Espreitadoras Sanguessuga e Espreitadoras da Caverna (nível 21-22) rastejam no meio de {zone:1437}, ao norte de {area:836}; todas soltam uma presa. Elas envenenam; voltam em 5 minutos.",
		["{item:6839}, from the young chimaeras"] = "{item:6839}, das quimeras jovens",
		["{item:6840}, from the {npc:6167}"] = "{item:6840}, de {npc:6167}",
		["{item:6841}, from Roogug"] = "{item:6841}, de Rugug",
		["{item:6845}, from {npc:6170}"] = "{item:6845}, de {npc:6170}",
		["{item:6848}, from {quest:1708}"] = "{item:6848}, de {quest:1708}",
		["{npc:1416} keeps the weapon shop in the north-west of the {object:28027}, a short walk from {npc:5413}. He wants 20 {quest:1705} and the {item:6845}."] = "{npc:1416} cuida da loja de armas no noroeste do {object:28027}, a uma curta caminhada de {npc:5413}. Ele quer 20 {quest:1705} e {item:6845}.",
		["{npc:5413} works in the Dwarven District of Stormwind. He takes the {item:6843} (lost it? abandon the quest and {npc:6166} gives a new one) and gives you {item:6970}, a shield; {quest:1701} is a level 28 quest, with {item:6842} listing what it needs."] = "{npc:5413} trabalha no Distrito dos Anões de Ventobravo. Ele pega {item:6843} (perdeu? abandone a missão e {npc:6166} entrega uma nova) e entrega {item:6970}, um escudo; {quest:1701} é uma missão de nível 28, e {item:6842} lista o que ela precisa.",
		["{quest:1698} sits in the inn at {area:69}. His test is timed: before you take it, clear the Redridge gnolls on the path to the {area:98} in the hills north-west of {area:69}, including the two on the rock by the cave mouth (climb it from its right side)."] = "{quest:1698} fica na estalagem de {area:69}. A prova dele tem tempo: antes de pegar, limpe os gnolls de Cristarrubra no caminho para {area:98}, nas colinas a noroeste de {area:69}, inclusive os dois na pedra junto à boca da caverna (suba pelo lado direito dela).",
		["{quest:1703} works on the south side of the {area:1660} in {zone:1457}. He wants 20 {quest:1710}."] = "{quest:1703} trabalha no lado sul de {area:1660}, em {zone:1457}. Ele quer 20 {quest:1710}.",
		["{quest:1705}, from the Nightbane worgen"] = "{quest:1705}, dos worgen Nightbane",
} end)()
t.guides["forever/class/warrior/haggards-weapons"] = (function() return {
		["At 10, {npc:1229}, the warrior trainer in {area:131}, sends you to {quest:1679} in {zone:1455}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} is the quickest stance (one fight in a tavern), with a Haggard's weapon after it."] = "No nível 10, {npc:1229}, o instrutor de guerreiro em {area:131}, manda você para {quest:1679}, em {zone:1455}. Qualquer guerreiro da Aliança pode pegar um dos três caminhos, nunca dois: está em {zone:1453} no nível 10 de qualquer jeito? {quest:1638}, de {npc:5480}, é a postura mais rápida (uma luta numa taberna), com uma arma de Haggard depois.",
		["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "No nível 10, {npc:252377} fica com os instrutores junto ao portão oeste de {area:16638}. Uma cultista, {npc:257196}, guarda o escudo da família dela em {area:16629}.",
		["At 10, {npc:3598}, the warrior trainer in {area:186}, or {npc:2151}, who patrols the road west of {area:186}, sends you to {quest:1684} on the {area:1660} in {zone:1457}. Any Alliance warrior may take one of the three roads, never two: in {zone:1453} at 10 anyway? {npc:5480}'s {quest:1638} teaches the same stance after one fight in a tavern."] = "No nível 10, {npc:3598}, o instrutor de guerreiro em {area:186}, ou {npc:2151}, que patrulha a estrada a oeste de {area:186}, manda você para {quest:1684}, em {area:1660}, em {zone:1457}. Qualquer guerreiro da Aliança pode pegar um dos três caminhos, nunca dois: está em {zone:1453} no nível 10 de qualquer jeito? {quest:1638}, de {npc:5480}, ensina a mesma postura depois de uma luta numa taberna.",
		["At 10, {npc:913}, the warrior trainer by the inn in {area:87}, sends you to {npc:6089} in {zone:1453}; {npc:5480}, the warrior trainer in {zone:1453}'s {object:2100}, offers it too."] = "No nível 10, {npc:913}, o instrutor de guerreiro ao lado da estalagem de {area:87}, manda você para {npc:6089}, em {zone:1453}; {npc:5480}, o instrutor de guerreiro em {object:2100}, de {zone:1453}, também oferece.",
		["Back on the {area:1660}: {npc:4088} hands you the {item:6812}; {npc:6142} works on the far, south side of the same terrace, easy to miss."] = "De volta a {area:1660}: {npc:4088} entrega {item:6812} a você; {npc:6142} trabalha no lado distante, ao sul, do mesmo terraço, fácil de passar batido.",
		["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:6090}'s road below still gives a weapon, once you reach {zone:1453}."] = "De volta a {npc:252377}, em {area:16638}. Ela ensina {spell:71} e entrega {item:275290}, um escudo para usar com ela. O caminho de {npc:6090}, abaixo, ainda dá uma arma, quando você chegar a {zone:1453}.",
		["Back to {npc:294}"] = "De volta a {npc:294}",
		["Back to {npc:6114} for {spell:71}, then to {quest:1680} at the {object:32372} in the middle of {zone:1455}."] = "De volta a {npc:6114} para {spell:71}, depois a {quest:1680} na {object:32372}, no meio de {zone:1455}.",
		["Elunite under {area:442}"] = "Elunita embaixo de {area:442}",
		["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "Siga para noroeste saindo de {area:16638} até {area:16629}. {npc:257196} fica a oeste da aproximação do santuário, entre os Guardiões, Evocaespíritos e Mestres-lâmina do culto: puxe-os um de cada vez antes de pegá-lo. Ele solta {item:263993}.",
		["Take the boat from {area:702} to {area:442}. The wreck lies underwater just south of {area:442}'s southern pier, where the Menethil boat docks. Open Crates of Elunite on the sea floor around the wreck, by a huge sunken turtle, toward the beach and under the pier until you have eight; every crate holds ore and comes back in 3-5 minutes. The grey {npc:6133} (level 11) drifts around the middle of the wreck and always drops the medallion: target it when you see it, so you can find it after surfacing for air. Watch your breath; Threshers can join in."] = "Pegue o barco de {area:702} até {area:442}. O naufrágio fica debaixo d'água, logo ao sul do cais sul de {area:442}, onde atraca o barco de Menethil. Abra Caixotes de Elunita no fundo do mar em volta do naufrágio, ao lado de uma tartaruga gigante afundada, em direção à praia e embaixo do cais, até ter oito; cada caixote guarda minério e volta em 3 a 5 minutos. O cinzento {npc:6133} (nível 11) flutua pelo meio do naufrágio e sempre solta o medalhão: selecione-o como alvo quando vir, para achar depois de subir para respirar. Fique de olho no fôlego; Debulhadores podem entrar na luta.",
		["from {npc:6093}"] = "de {npc:6093}",
		["{item:263993}, from {npc:257196}"] = "{item:263993}, de {npc:257196}",
		["{item:6782}, from {object:85563}"] = "{item:6782}, de {object:85563}",
		["{item:6800}, from {object:85562}"] = "{item:6800}, de {object:85562}",
		["{item:6808}, from Crates of Elunite"] = "{item:6808}, dos Caixotes de Elunita",
		["{item:6809}, from the {npc:6133}"] = "{item:6809}, de {npc:6133}",
		["{npc:252377} in {area:16638}"] = "{npc:252377} em {area:16638}",
		["{npc:294}'s manor stands at the south-east edge of the {area:88} in eastern Elwynn, at the end of a short road that does not join the main one."] = "A mansão de {npc:294} fica na borda sudeste de {area:88}, no leste de Elwynn, no fim de uma estradinha que não se liga à principal.",
		["{npc:6089} and {npc:6090} are in the Pig and Whistle tavern in {object:2100}; {npc:6090} is the drunk at the far end of the bar. {npc:6090} (level 10) hits harder than his level, so start at full health; he gives up at low health instead of dying. If he wins, he disappears for about three minutes: keep the quest and talk to him again when he is back. A Dwarf, Gnome or Night Elf who took {quest:1638} from {npc:5480} instead of their home road is led through {zone:1453} from here."] = "{npc:6089} e {npc:6090} ficam na Taberna do Javatusco Saltitante, em {object:2100}; {npc:6090} é o bêbado na ponta do balcão. {npc:6090} (nível 10) bate mais forte que o nível dele, então comece com vida cheia; ele desiste com pouca vida em vez de morrer. Se ele vencer, some por uns três minutos: mantenha a missão e fale com ele de novo quando ele voltar. Um Anão, Gnomo ou Elfo Noturno que pegou {quest:1638} com {npc:5480} em vez do caminho da própria terra é conduzido por {zone:1453} a partir daqui.",
		["{npc:6093} (level 11) camps in the far south-east of Elwynn. A guard stands beside him and Defias and wolves are spread around the camp (now and then a rarer guard too): clear them one at a time, then kill Jack. He always drops {item:6783}; open {object:85563} in the crates by him for {item:6782}. Jack returns 3 minutes after dying, the box 1 minute after opening."] = "{npc:6093} (nível 11) acampa no extremo sudeste de Elwynn. Um guarda fica ao lado dele e Défias e lobos estão espalhados pelo acampamento (de vez em quando também um guarda mais raro): limpe um de cada vez e depois mate Jack. Ele sempre solta {item:6783}; abra {object:85563} nos caixotes ao lado dele para pegar {item:6782}. Jack volta 3 minutos depois de morrer, a caixa 1 minuto depois de aberta.",
		["{quest:1678} (level 11, a lone troll) waits at his hut on a hill south of {area:135}, near the mountains at the top of a short ramp, with no other trolls around; the hut at the front of {area:135} is the wrong one. He fights in {spell:71} and sunders your armor; {spell:6343} slows him. His head always drops; he returns about 8 minutes after dying."] = "{quest:1678} (nível 11, um troll solitário) espera na cabana dele, num morro ao sul de {area:135}, perto das montanhas, no topo de uma rampa curta, sem outros trolls por perto; a cabana da frente de {area:135} é a errada. Ele luta em {spell:71} e destrói sua armadura; {spell:6343} o deixa mais lento. A cabeça dele sempre cai; ele volta cerca de 8 minutos depois de morrer.",
		["{quest:1679} in {zone:1455}"] = "{quest:1679} em {zone:1455}",
		["{quest:1679} stands in the {object:32390} in the {object:32359}."] = "{quest:1679} fica no {object:32390}, na {object:32359}.",
		["{quest:1681} lies in eastern {zone:1426}, below {area:212} on its south side. Dark Iron Spies (level 8-10) stand along the way, far enough apart to pull one at a time. {object:85562} is in the basement of the southernmost house; {npc:6124} (level 11) stands by it and charges on sight. The box always holds the ore and refills 15 minutes after opening."] = "{quest:1681} fica no leste de {zone:1426}, embaixo de {area:212}, no lado sul. Espiões Ferro Negro (nível 8-10) ficam pelo caminho, afastados o bastante para puxar um de cada vez. {object:85562} fica no porão da casa mais ao sul; {npc:6124} (nível 11) fica ao lado e ataca assim que vê você. A caixa sempre guarda o minério e se enche 15 minutos depois de aberta.",
		["{quest:1683} (level 10, a satyr) stands at a hidden moonwell up a hillside west of {area:186}. The trail is hard to spot: it starts behind a Gnarlpine camp and climbs in switchbacks lined with lamp posts. The furbolgs below can come in groups. His horn always drops; he returns 5 minutes after dying."] = "{quest:1683} (nível 10, um sátiro) fica num poço lunar escondido, morro acima a oeste de {area:186}. A trilha é difícil de achar: começa atrás de um acampamento Gnarlpine e sobe em ziguezague, ladeada de postes de lampião. Os furbolgs lá embaixo podem vir em grupos. O chifre dele sempre cai; ele volta 5 minutos depois de morrer.",
		["{quest:1684} in {zone:1457}"] = "{quest:1684} em {zone:1457}",
		["{quest:1684} stands on the {area:1660}."] = "{quest:1684} fica em {area:1660}.",
		["{spell:71} and a Weapon (Alliance)"] = "{spell:71} e uma Arma (Aliança)",
		["{spell:71} at 10 and a one-hand weapon of your choice from {zone:1453}, {zone:1455} or {zone:1457}."] = "{spell:71} no nível 10 e uma arma de uma mão à sua escolha em {zone:1453}, {zone:1455} ou {zone:1457}.",
} end)()
t.guides["forever/class/warrior/heirloom-weapon"] = (function() return {
		["At 10, {npc:2131}, the warrior trainer inside the inn of {area:159}, sends you to {npc:1496} by the graveyard on {area:159}'s west edge. This road and {npc:5810}'s exclude each other: drop {quest:1505} or {quest:1498} from your log if you hold one."] = "No nível 10, {npc:2131}, o instrutor de guerreiro dentro da estalagem de {area:159}, manda você para {npc:1496}, junto ao cemitério na borda oeste de {area:159}. Este caminho e o de {npc:5810} se excluem: descarte {quest:1505} ou {quest:1498} do seu registro, se tiver uma.",
		["At 10, {npc:252377} stands with the trainers by {area:16638}'s west gate. A cultist, {npc:257196}, holds her family's shield at the {area:16629}."] = "No nível 10, {npc:252377} fica com os instrutores junto ao portão oeste de {area:16638}. Uma cultista, {npc:257196}, guarda o escudo da família dela em {area:16629}.",
		["At 10, {npc:3063}, the warrior trainer of {area:222}, sends you to {npc:5810} in the {zone:1413}. {npc:3041} in {zone:1456} offers it too."] = "No nível 10, {npc:3063}, o instrutor de guerreiro de {area:222}, manda você para {npc:5810}, em {zone:1413}. {npc:3041}, em {zone:1456}, também oferece.",
		["At 10, {npc:3169}, the warrior trainer in the barracks of {area:362}, sends you to {npc:5810} in the {zone:1413}. Sorek in {zone:1454}'s {object:172958} offers it too. Any Horde warrior may take one of the two roads, never both: heading to {zone:1420} at 10 anyway? {npc:2131} in {area:159}'s inn offers the other: one fight by {area:159}'s graveyard for the same stance, then the Agamand crypt for an heirloom weapon."] = "No nível 10, {npc:3169}, o instrutor de guerreiro no quartel de {area:362}, manda você a {npc:5810} em {zone:1413}. Sorek, no {object:172958} de {zone:1454}, também a oferece. Qualquer guerreiro da Horda pode tomar um dos dois caminhos, nunca os dois: vai para {zone:1420} no nível 10 de qualquer jeito? {npc:2131}, na estalagem de {area:159}, oferece o outro: uma luta junto ao cemitério de {area:159} pela mesma postura, depois a cripta dos Agamand para uma arma de herança.",
		["Back to {npc:1500}"] = "De volta a {npc:1500}",
		["Back to {npc:252377} in {area:16638}. She teaches {spell:71} and gives you the {item:275290}, a shield to use it with. {npc:5810}'s road below still gives a weapon later, once you reach Kalimdor."] = "De volta a {npc:252377}, em {area:16638}. Ela ensina {spell:71} e entrega {item:275290}, um escudo para usar com ela. O caminho de {npc:5810}, abaixo, ainda dá uma arma depois, quando você chegar a Kalimdor.",
		["Back to {npc:5810} under his tree west of {area:379}."] = "De volta a {npc:5810}, embaixo da árvore dele, a oeste de {area:379}.",
		["Dillinger stands by the graveyard on {area:159}'s west edge. An Orc, Troll, Tauren or Skyborne who took {quest:1818} from {npc:2131} instead of {npc:5810}'s road is led through {area:159} from here."] = "Dillinger fica junto ao cemitério na borda oeste de {area:159}. Um Orc, Troll, Tauren ou Celonato que pegou {quest:1818} com {npc:2131} em vez do caminho de {npc:5810} é conduzido por {area:159} a partir daqui.",
		["Head north-west from {area:16638} to the {area:16629}. {npc:257196} stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the {item:263993}."] = "Siga para noroeste saindo de {area:16638} até {area:16629}. {npc:257196} fica a oeste da aproximação do santuário, entre os Guardiões, Evocaespíritos e Mestres-lâmina do culto: puxe-os um de cada vez antes de pegá-lo. Ele solta {item:263993}.",
		["Singed Scales in {area:369}"] = "Escamas Chamuscadas em {area:369}",
		["The four Agamand Weapon Racks are inside the {area:158} at the north end of {area:157}, north of {area:159}, one rack per room: one in the lowest room, two in the pair of rooms up the stairs, one in the room above those. The axe rack stands in a dark corner. The crypt's undead come in packs of three or more and return quickly; the ones in the top room are not linked. The axe, dagger and mace racks take 15 minutes to refill after someone loots them."] = "Os quatro Cavaletes de Armas dos Agamand ficam dentro de {area:158}, no extremo norte de {area:157}, ao norte de {area:159}, um cavalete por sala: um na sala mais baixa, dois no par de salas escada acima, um na sala acima dessas. O cavalete do machado fica num canto escuro. Os mortos-vivos da cripta vêm em grupos de três ou mais e voltam rápido; os da sala de cima não são ligados. Os cavaletes de machado, adaga e maça levam 15 minutos para se encher depois que alguém saqueia.",
		["The {area:158}"] = "{area:158}",
		["The {object:58369} stands by a broken wagon in the Razormane camp north-west of {npc:5878}, north-east of the Crossroads. Two Razormanes guard it and their hunters pull more quilboar: clear them one at a time, then open the chest (it refills within seconds, so a friend can loot it too)."] = "{object:58369} fica ao lado de uma carroça quebrada no acampamento dos Crinavalha a noroeste de {npc:5878}, a nordeste da Encruzilhada. Dois Crinavalha guardam e os caçadores deles puxam mais quilboar: limpe um de cada vez e depois abra o baú (ele se enche em segundos, então um amigo também pode saquear).",
		["You need five Singed Scales. Thunder Lizards (level 9-10) and Lightning Hides (10-11) live down in the {area:369} crevasse in north-west {zone:1411}, south of {zone:1454}: from the {zone:1413} bridge turn left and follow the river north into it. Both drop a scale about four kills in five; both cast {spell:5401}."] = "Você precisa de cinco Escamas Chamuscadas. Lagartos Trovejantes (nível 9-10) e Pelegos de Relâmpago (10-11) vivem lá embaixo, na fenda de {area:369}, no noroeste de {zone:1411}, ao sul de {zone:1454}: a partir da ponte de {zone:1413}, vire à esquerda e siga o rio para o norte, entrando nela. Os dois soltam uma escama em cerca de quatro de cada cinco mortes; os dois lançam {spell:5401}.",
		["{item:263993}, from {npc:257196}"] = "{item:263993}, de {npc:257196}",
		["{item:6486}, from the lizards"] = "{item:6486}, dos lagartos",
		["{item:6534}, from the {object:58369}"] = "{item:6534}, de {object:58369}",
		["{npc:1500} is in the {area:2119}, the inn on {area:159}'s east side."] = "{npc:1500} fica na {area:2119}, a estalagem no lado leste de {area:159}.",
		["{npc:252377} in {area:16638}"] = "{npc:252377} em {area:16638}",
		["{npc:5810} at {area:379}"] = "{npc:5810} em {area:379}",
		["{npc:5810} is easy to miss: he stands under a small canopy by a large tree just west of {area:379}, below the road's south side, with the post in sight to his east. Going straight south from the post does not lead to him. From {zone:1411} cross the bridge west; from {zone:1412} head north past the Crossroads."] = "{npc:5810} é fácil de não ver: ele fica sob um pequeno toldo junto a uma árvore grande logo a oeste de {area:379}, abaixo do lado sul da estrada, com o posto à vista a leste dele. Ir direto para o sul a partir do posto não leva a ele. De {zone:1411}, atravesse a ponte para oeste; de {zone:1412}, siga para o norte passando pela Encruzilhada.",
		["{npc:5878}'s hut sits on top of {area:1699}, east of the Crossroads. Most slopes are too steep: climb the broad ridge on the north or east side."] = "A cabana de {npc:5878} fica no alto de {area:1699}, a leste da Encruzilhada. A maioria das encostas é íngreme demais: suba pela crista larga do lado norte ou leste.",
		["{npc:6390} sleeps in the mausoleum in the graveyard just north of Dillinger. To wake him, click the flat skull plaque on the ground, left of the path to the mausoleum door; the seal lifts and {npc:6390} (level 11, not elite) walks out. Start at full health."] = "{npc:6390} dorme no mausoléu do cemitério, logo ao norte de Dillinger. Para acordá-lo, clique na placa de caveira plana no chão, à esquerda do caminho até a porta do mausoléu; o selo se ergue e {npc:6390} (nível 11, não elite) sai andando. Comece com vida cheia.",
		["{spell:71} and a Weapon (Horde)"] = "{spell:71} e uma Arma (Horda)",
		["{spell:71} at 10 and a one-hand weapon of your choice: {npc:5810}'s road, {area:159}'s crypt, or the Skybreaker shield."] = "{spell:71} no nível 10 e uma arma de uma mão à sua escolha: o caminho de {npc:5810}, a cripta de {area:159}, ou o escudo Skybreaker.",
} end)()
t.guides["forever/class/warrior/quelserrar"] = (function() return {
		["A tank sword at 60: a {area:2577} book, then {npc:10184}'s breath tempers the blade (the sword is not in Forever's items yet)."] = "Uma espada de tanque no nível 60: um livro de {area:2577}, e depois o sopro de {npc:10184} tempera a lâmina (a espada ainda não está nos itens do Forever).",
		["Back to {npc:14368} in the Athenaeum of Dire Maul West: through the West door with the {item:18249} again, and a group to reach the library."] = "De volta a {npc:14368}, no Ateneu de Gládio Cruel Oeste: pela porta do Oeste, com {item:18249} de novo, e um grupo para chegar à biblioteca.",
		["Kill {npc:10184}, then target her corpse and use the {item:18488} on it before the 20 minutes run out. It becomes the {item:18492}, with no time limit."] = "Mate {npc:10184}, depois selecione o cadáver dela como alvo e use {item:18488} nele antes que os 20 minutos acabem. Ele vira {item:18492}, sem limite de tempo.",
		["Shen'dralar reputation"] = "Reputação com os Shen'dralar",
		["The book is a rare random drop from the bosses of all three {area:2577} wings (Alzzin, Hydrospawn and the rest of the East, Tendris, Illyanna, Kalendris, {npc:11496} and the West, {npc:11501} and the North's guards) and very rarely from the tribute chest; it can be traded, so the auction house may have one. {area:2577} is a five-player dungeon in the ruins of central {zone:1444}: needs a group of five. Right-click the book to start the quest; it stays in your bags."] = "O livro é um saque aleatório raro dos chefes das três alas de {area:2577} (Alzzin, Rebentágua e o resto do Leste, Tendris, Illyanna, Kalendris, {npc:11496} e o Oeste, {npc:11501} e os guardas do Norte) e, muito raramente, do baú de tributo; pode ser negociado, então a Casa de Leilões pode ter um. {area:2577} é uma masmorra para cinco jogadores nas ruínas do centro de {zone:1444}: precisa de um grupo de cinco. Clique com o botão direito no livro para começar a missão; ele fica nas suas bolsas.",
		["click the heated blade on the ground"] = "clique na lâmina aquecida no chão",
		["from {item:18401}"] = "de {item:18401}",
		["{item:18488}, on her corpse"] = "{item:18488}, no cadáver dela",
		["{item:18489}: plant it in her breath"] = "{item:18489}: plante no sopro dela",
		["{npc:10184} is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}; she returns once a week. Tell the raid first. Late in the fight (around 10-15% health, when she has landed again) use the {item:18489} to plant it in the path of her fire breath, usually by the main tank's feet. When her breath has heated it, click the {object:179562} to take the {item:18488}: from then you have 20 minutes. Her breath can kill you while you plant or pick up the blade; if you die and nobody brings you back before she dies, wait for next week. Planted in the wrong place? Abandon the quest, take it again from Lydros for a new blade."] = "{npc:10184} é a chefe de raide de 40 jogadores de {area:2159}, uma caverna em {area:511}, no sul de {zone:1445}; ela volta uma vez por semana. Avise a raide antes. No fim da luta (por volta de 10-15% de vida, depois que ela pousa de novo), use {item:18489} para plantá-la no caminho do sopro de fogo dela, em geral aos pés do tanque principal. Depois que o sopro a esquentar, clique em {object:179562} para pegar {item:18488}: a partir daí, você tem 20 minutos. O sopro dela pode matar você enquanto planta ou pega a lâmina; se você morrer e ninguém ressuscitar você antes de ela morrer, espere a semana que vem. Plantou no lugar errado? Abandone a missão e pegue de novo com Lydros para ter uma lâmina nova.",
		["{npc:10184}'s breath"] = "O sopro de {npc:10184}",
		["{npc:10184}'s corpse"] = "o cadáver de {npc:10184}",
		["{npc:14368} stands in the Athenaeum, the library at the far end of Dire Maul West, past the Court of the Highborne and the Prison of Immol'thar. The West door needs the {item:18249}, which Pusillin drops in Dire Maul East (he runs; chase him), or a rogue to pick it. Clearing to the library needs your group of five. He takes the book, hands you {item:18513} to give straight back, then the {item:18489}. Keep that blade: lose it, and you must abandon the quest and take it again."] = "{npc:14368} fica no Ateneu, a biblioteca no fundo de Gládio Cruel Oeste, depois da Court of the Highborne e da Prison of Immol'thar. A porta do Oeste precisa de {item:18249}, que Pusillin solta em Gládio Cruel Leste (ele corre; persiga), ou de um ladino para arrombar. Limpar até a biblioteca exige seu grupo de cinco. Ele pega o livro, entrega {item:18513} para você devolver na hora, e depois {item:18489}. Guarde essa lâmina: se perder, você precisa abandonar a missão e pegar de novo.",
		["{npc:14368}, in the Athenaeum"] = "{npc:14368}, no Ateneu",
		["{npc:14368}: hand back the Dull and Flat Elven Blade"] = "{npc:14368}: devolva a Lâmina Élfica Sem Fio e Chata",
} end)()
t.guides["forever/class/warrior/voodoo-feathers"] = (function() return {
		["At 50, {npc:3041}, the warrior trainer of {zone:1456}, sends you to the {npc:7572} in the {zone:1435}."] = "No nível 50, {npc:3041}, o instrutor de guerreiros de {zone:1456}, envia você ao {npc:7572} no {zone:1435}.",
		["At 50, {npc:3354} in the {object:172958} sends you to the {npc:7572} in the {zone:1435}."] = "No nível 50, {npc:3354}, no {object:172958}, envia você ao {npc:7572} no {zone:1435}.",
		["At 50, {npc:4593}, a warrior trainer of the {zone:1458}, sends you to the {npc:7572} in the {zone:1435}."] = "No nível 50, {npc:4593}, um instrutor de guerreiros da {zone:1458}, envia você ao {npc:7572} no {zone:1435}.",
		["At 50, {npc:5113}, the warrior trainer of {zone:1455}, sends you to the {npc:7572} in the {zone:1435}."] = "No nível 50, {npc:5113}, o instrutor de guerreiros de {zone:1455}, envia você ao {npc:7572} no {zone:1435}.",
		["At 50, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to the {npc:7572} in the {zone:1435}."] = "No nível 50, {npc:5479}, ao lado de {npc:5480}, no prédio dos instrutores de guerreiro de {object:2100}, manda você para {npc:7572}, em {zone:1435}.",
		["At 50, {npc:7315}, the warrior trainer of {zone:1457}, sends you to the {npc:7572} in the {zone:1435}."] = "No nível 50, {npc:7315}, o instrutor de guerreiros de {zone:1457}, envia você ao {npc:7572} no {zone:1435}.",
		["Back to the {npc:10996}"] = "Volte ao {npc:10996}",
		["Experience"] = "Experiência",
		["Experience at 50, ending in the {area:1417}; Classic's item choice may be gone on Forever."] = "Experiência no nível 50, terminando em {area:1417}; a escolha de item do Classic pode ter sumido no Forever.",
		["Helboars"] = "Javiltuscos",
		["In Classic the {npc:10996} let you choose the {item:20130}, the {item:20521} or the {item:20517} here. Forever's change notes say the choice is gone, though its quest page still lists three unnamed rewards: look at the reward window before you hand in."] = "No Classic, {npc:10996} deixava você escolher {item:20130}, {item:20521} ou {item:20517} aqui. As notas de mudança do Forever dizem que a escolha sumiu, embora a página da missão ainda liste três recompensas sem nome: olhe a janela de recompensa antes de entregar.",
		["Seven Helboars (level 52-53, not elite) roam the north-west of the {zone:1419}, south-west of {area:1438}; some stand near the ogres on the mountainside by the road. They charge from 25 yards and cast {spell:8349}. They share spawn points with the Felbeasts and scorpids: if no boars are around, kill those and boars may appear instead. Back in 5 minutes."] = "Sete Javiltuscos (nível 52-53, não elite) rondam o noroeste de {zone:1419}, a sudoeste de {area:1438}; alguns ficam perto dos ogros na encosta da montanha, junto à estrada. Eles investem de 25 metros e lançam {spell:8349}. Dividem pontos de aparição com os Feravis e escorpiões: se não houver javalis por perto, mate esses e javalis podem aparecer no lugar. Voltam em 5 minutos.",
		["Shadowsworn camps"] = "Acampamentos dos Devotos da Sombra",
		["The Shadowsworn camp around the mouth of the {area:1440} cave, south of {area:1438} on the way to the {area:72}. You need 20 Adepts (level 52-53, they leech blood and heal hurt allies: kill them first), 10 Cultists (51-52, they throw from range, so close in) and 20 Thugs (52-53, Thrash and {spell:1766}). Thugs can run short before the others: kill every Shadowsworn you pass."] = "Os Devotos da Sombra acampam em volta da boca da caverna de {area:1440}, ao sul de {area:1438}, no caminho para {area:72}. Você precisa de 20 Adeptos (nível 52-53, sugam sangue e curam aliados feridos: mate-os primeiro), 10 Cultistas (51-52, atiram à distância, então chegue perto) e 20 Capangas (52-53, Pancada e {spell:1766}). Os Capangas podem faltar antes dos outros: mate todo Devoto da Sombra que encontrar.",
		["The {area:1417}"] = "{area:1417}",
		["The {npc:7572}"] = "{npc:7572}",
		["The {npc:7572}, a ghost, stands in the south-west of the {zone:1435}, at the pass into the {zone:1419}, a short ride south-west of {area:75}. Horde: fly to {area:75}. Alliance: fly to {area:1438} in the {zone:1419} and ride north through the pass. High-level beasts roam the way."] = "{npc:7572}, um fantasma, fica no sudoeste de {zone:1435}, na passagem para {zone:1419}, uma cavalgada curta a sudoeste de {area:75}. Horda: voe para {area:75}. Aliança: voe para {area:1438}, em {zone:1419}, e cavalgue para o norte pela passagem. Feras de nível alto rondam o caminho.",
		["You need two feathers of each colour from the six Atal'ai troll guardians (level 51-52, elite) on the {area:1417}'s balcony, who hold the barrier in front of {npc:5710}: Gasher and {npc:5716} drop the amber, Hukku and Mijan the blue, Zolo and Loro the green, every kill; each player on the quest loots their own set. The {area:1417} is a five-player dungeon: needs a group of five. It lies in the {area:74} in eastern {zone:1435}: climb the temple's outer steps, dive into the flooded hall and follow the stairs down to the entrance. Inside, reach the balcony by the stairs or the path on the right, not the spiral stairs. Hukku calls guardians and casts {spell:9081} and {spell:8282}; Mijan heals the others ({spell:139}, a {npc:3560}, {spell:331} below half health): kill her or her ward fast; {npc:5716} cleaves."] = "Você precisa de duas penas de cada cor dos seis guardiões trolls Atal'ai (nível 51-52, elite) na sacada de {area:1417}, que seguram a barreira diante de {npc:5710}: Talho e {npc:5716} soltam a âmbar, Hukkah e Mirran a azul, Zolo e Lorro a verde, a cada morte; cada jogador na missão saqueia o próprio conjunto. {area:1417} é uma masmorra para cinco jogadores: precisa de um grupo de cinco. Ela fica em {area:74}, no leste de {zone:1435}: suba os degraus externos do templo, mergulhe no salão alagado e siga as escadas para baixo até a entrada. Lá dentro, chegue à sacada pelas escadas ou pelo caminho da direita, não pela escada em espiral. Hukkah chama guardiões e lança {spell:9081} e {spell:8282}; Mirran cura os outros ({spell:139}, um {npc:3560}, {spell:331} abaixo da metade da vida): mate-a ou o ajudante dela rápido; {npc:5716} golpeia em área.",
		["{item:20606}, from Gasher and {npc:5716}"] = "{item:20606}, de Talho e {npc:5716}",
		["{item:20607}, from Hukku and Mijan"] = "{item:20607}, de Hukkah e Mirran",
		["{item:20608}, from Zolo and Loro"] = "{item:20608}, de Zolo e Lorro",
} end)()
t.guides["forever/class/warrior/whirlwind-weapon"] = (function() return {
		["At 30, {npc:3041}, the warrior trainer of {zone:1456}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "No nível 30, {npc:3041}, o instrutor de guerreiros de {zone:1456}, envia você a {npc:6236} na {area:720}, em {zone:1413}.",
		["At 30, {npc:3354} in the {object:172958} sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "No nível 30, {npc:3354}, no {object:172958}, envia você a {npc:6236} na {area:720}, em {zone:1413}.",
		["At 30, {npc:4595}, a warrior trainer of the {zone:1458}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "No nível 30, {npc:4595}, um instrutor de guerreiros de {zone:1458}, envia você a {npc:6236} na {area:720}, em {zone:1413}.",
		["At 30, {npc:5113}, the warrior trainer of {zone:1455}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "No nível 30, {npc:5113}, o instrutor de guerreiros de {zone:1455}, envia você a {npc:6236} na {area:720}, em {zone:1413}.",
		["At 30, {npc:5479}, beside {npc:5480} in the warrior trainers' building of {object:2100}, sends you to {npc:6236} on {area:720} in the {zone:1413}."] = "No nível 30, {npc:5479}, ao lado de {npc:5480}, no prédio dos instrutores de guerreiro de {object:2100}, manda você para {npc:6236}, em {area:720}, em {zone:1413}.",
		["Back to {npc:6176}. Accepting {quest:1713} starts his ritual, and {quest:1712} appears just north of his camp. {quest:1712} is elite (level 40): grouping up is encouraged; it needs a group of two or three around level 40. It deals nature damage (a {item:6052} soaks it), whirls, and {spell:10101} throws you far while it heals itself as you run back: fight with your back to a slope or rock. The {item:6894} always drops. If the fight fails {npc:6176} stops answering: abandon {quest:1713} and take it again for a new summon; the earlier items are not needed again."] = "De volta a {npc:6176}. Aceitar {quest:1713} inicia o ritual dele, e {quest:1712} aparece logo ao norte do acampamento. {quest:1712} é elite (nível 40): vale a pena formar grupo; precisa de um grupo de duas ou três pessoas por volta do nível 40. Ele causa dano de natureza ({item:6052} absorve), gira e {spell:10101} joga você longe enquanto ele se cura quando você corre de volta: lute com as costas para uma encosta ou pedra. {item:6894} sempre cai. Se a luta falhar, {npc:6176} para de responder: abandone {quest:1713} e pegue de novo para uma nova invocação; os itens anteriores não são necessários de novo.",
		["Bloodscalp Tusks"] = "Presas de Sanguescalpo",
		["Fly to {area:392} and go south along the {area:391}. {area:720} lies offshore to the south-east: wade across on the shallow sand bar; off it the water is deep and fatigue sets in. {npc:6236} stands by the arena."] = "Voe para {area:392} e siga para o sul por {area:391}. {area:720} fica ao largo, a sudeste: atravesse a vau pelo banco de areia raso; fora dele, a água é funda e a fadiga bate. {npc:6236} fica ao lado da arena.",
		["Put the 24 charms into {object:89931}: it hands you the {quest:1714}."] = "Coloque os 24 patuás em {object:89931}: ele entrega {quest:1714} a você.",
		["The cauldron wants 8 of each charm, 24 in all, and each exile drops its charm about one kill in three, so plan on some 70 kills. All are level 38-39, not elite, and hit hard at 30-33: bring a friend or come at 35 or more. Burning Exiles (fire) by the {area:334} in the north-west, north-west of {area:320}; Thundering Exiles (air) by the {area:336} south-east of {area:320}, casting {spell:403} from 40 yards; Cresting Exiles (water) by the {area:333}, north-west of {area:321}, with {spell:122}. About a dozen of each, back in under 7 minutes. The charms trade and sell on the auction house; using one banishes another kind of exile for a while (Burning on Thundering, Thundering on Cresting, Cresting on Burning)."] = "O caldeirão quer 8 de cada patuá, 24 ao todo, e cada exilado solta o patuá dele em cerca de uma morte em três, então conte com umas 70 mortes. Todos são de nível 38-39, não elite, e batem forte nos níveis 30-33: leve um amigo ou venha no 35 ou mais. Exilados em Chamas (fogo) perto de {area:334}, no noroeste, a noroeste de {area:320}; Exilados Trovejantes (ar) perto de {area:336}, a sudeste de {area:320}, lançando {spell:403} a 40 metros; Exilados Vagalhantes (água) perto de {area:333}, a noroeste de {area:321}, com {spell:122}. Cerca de uma dúzia de cada, voltam em menos de 7 minutos. Os patuás são negociáveis e vendáveis na Casa de Leilões; usar um bane outro tipo de exilado por um tempo (Chamas sobre Trovejantes, Trovejantes sobre Vagalhantes, Vagalhantes sobre Chamas).",
		["The exiles of Arathi"] = "Os exilados de Arathi",
		["You have 10 minutes. Eat and drink to full, then step onto the grate in the middle of the crowd: {npc:6248} announces the challengers (level 26-27), who come one at a time, 15-20 seconds apart, and only while you stand near the grate. After each kill, step off the grate to eat or bandage; step back on when ready for the next. Six of them, then {npc:6238} (level 33, not elite) walks out; he stays neutral until you attack him, so bandage or eat first. Do not use {spell:1160}: it sends the challengers running and more of them pile in at once. If nothing starts, step off and on the grate again, or abandon the quest and take it again."] = "Você tem 10 minutos. Coma e beba até encher, depois suba na grade no meio da multidão: {npc:6248} anuncia os desafiantes (nível 26-27), que vêm um de cada vez, com 15 a 20 segundos de intervalo, e só enquanto você ficar perto da grade. Depois de cada morte, saia da grade para comer ou fazer curativo; volte quando estiver pronto para o próximo. São seis, e depois {npc:6238} (nível 33, não elite) entra; ele fica neutro até você atacar, então faça curativo ou coma antes. Não use {spell:1160}: ele faz os desafiantes fugirem e mais deles chegam de uma vez. Se nada começar, saia da grade e suba de novo, ou abandone a missão e pegue de novo.",
		["You need 30 tusks. Every Bloodscalp troll (level 33-37) of north-west Stranglethorn drops one about one kill in three, so plan on some 80 kills: the camps and ruins north and north-west of {area:117} and around the {area:123} on the coast. They enrage below 30% health and the Warriors disarm; back in 5 minutes."] = "Você precisa de 30 presas. Todo troll Sanguescalpo (nível 33-37) do noroeste do Espinhaço solta uma em cerca de uma morte em três, então conte com umas 80 mortes: os acampamentos e ruínas ao norte e noroeste de {area:117} e em volta de {area:123}, na costa. Eles ficam enfurecidos abaixo de 30% de vida e os Guerreiros desarmam; voltam em 5 minutos.",
		["You need 8 {item:3357}. Herbalists pick it by rivers and lakes in the {zone:1437}, {zone:1417} and {zone:1434}; otherwise the auction house. Herb vendors keep only one at a time and restock every two hours: {npc:1302} and {npc:1313} in {zone:1453}, {npc:844} on the road in eastern Elwynn, Jeeda at {area:460} in Stonetalon, Montarr in {zone:1441}. Kurzen Medicine Men in northern Stranglethorn drop one about one kill in twelve."] = "Você precisa de 8 {item:3357}. Herbalistas colhem em rios e lagos de {zone:1437}, {zone:1417} e {zone:1434}; senão, a Casa de Leilões. Os vendedores de ervas guardam só um por vez e reabastecem a cada duas horas: {npc:1302} e {npc:1313} em {zone:1453}, {npc:844} na estrada do leste de Elwynn, Jeeda em {area:460}, nas Torres de Pedra, Montarr em {zone:1441}. Os Curandeiros de Kurzen do norte do Espinhaço soltam uma em cerca de uma morte em doze.",
		["{item:4479}, from Burning Exiles"] = "{item:4479}, dos Exilados em Chamas",
		["{item:4480}, from Thundering Exiles"] = "{item:4480}, dos Exilados Trovejantes",
		["{item:4481}, from Cresting Exiles"] = "{item:4481}, dos Exilados Vagalhantes",
		["{item:6894}, from {quest:1712}"] = "{item:6894}, de {quest:1712}",
		["{npc:6176} camps by ruins on the east bank of the river that runs past {area:272}, a short walk north-east of the town, just over the border in {zone:1416}; his cauldron stands beside him. Horde: fly to {area:272}. Alliance: fly to {area:271} and go north along the river; {area:272}'s guards are level 42 elites, so keep away from the town. Accepting {quest:1712} gives you {item:6929}, the list of what he needs: 8 {item:3357}, 30 Bloodscalp Tusks and the {quest:1714} from his cauldron. Click the cauldron for that quest."] = "{npc:6176} acampa junto a ruínas na margem leste do rio que passa por {area:272}, a uma curta caminhada a nordeste da cidade, logo depois da divisa, em {zone:1416}; o caldeirão dele fica ao lado. Horda: voe para {area:272}. Aliança: voe para {area:271} e siga o rio para o norte; os guardas de {area:272} são elites de nível 42, então fique longe da cidade. Aceitar {quest:1712} entrega {item:6929}, a lista do que ele precisa: 8 {item:3357}, 30 Presas de Sanguescalpo e {quest:1714} do caldeirão dele. Clique no caldeirão para essa missão.",
		["{npc:6176}: {item:6975}, Sword or Warhammer"] = "{npc:6176}: {item:6975}, Espada ou Martelo de Guerra",
		["{quest:1714}, from the cauldron by {npc:6176}"] = "{quest:1714}, do caldeirão ao lado de {npc:6176}",
		["{spell:2458} at 30 and a {spell:1680} axe, sword or warhammer at 40."] = "{spell:2458} no nível 30 e um machado, espada ou martelo de guerra de {spell:1680} no nível 40.",
} end)()
t.guides["forever/collectibles/mounts/alliance/black-war-mounts"] = (function() return {
		["Black War Mounts"] = "Montarias de Guerra Pretas",
		["PvP rank 11"] = "Patente JxJ 11",
		["{item:18243}, {spell:10907}, 100g"] = "{item:18243}, {spell:10907}, 100g",
		["{item:18244}, {spell:826}, 100g"] = "{item:18244}, {spell:826}, 100g",
		["{npc:12783} sells the mounts in {zone:1453}'s {object:2100} by the {area:2918}, beside the other honor quartermasters. The Forever client lists each at 100g. Each one also needs its kind's riding: Humans ride the steed, Night Elves the tiger, Gnomes the battlestrider, Dwarves the ram. A Skyborne, or anyone choosing another race's mount, first needs that riding from its trainer (Exalted with the race's city)."] = "{npc:12783} vende as montarias na {object:2100} de {zone:1453}, junto a {area:2918}, ao lado dos outros intendentes de honra. O cliente do Forever lista cada uma por 100g. Cada uma também exige a equitação do seu tipo: Humanos montam o corcel, Elfos Noturnos o tigre, Gnomos o mecanotrote, Anões o carneiro. Um Celonato, ou quem escolher a montaria de outra raça, precisa primeiro dessa equitação com o instrutor dela (Exaltado com a cidade da raça).",
		["{npc:14332}, {spell:824}, 100g"] = "{npc:14332}, {spell:824}, 100g",
		["{spell:1299382} come from battlegrounds, PvP quests and the season's weekly tasks, with a weekly cap; Commander (rank 11) unlocks the Black War mounts. The Player vs. Player tab of your character pane shows your rank and what you may buy. {skill:762} one at full speed needs Journeyman {skill:762} (level 60). Polestar cannot read your rank, so this step waits for level 60 and Journeyman {skill:762}."] = "{spell:1299382} vêm de campos de batalha, missões JxJ e tarefas semanais da temporada, com limite semanal; Comandante (patente 11) libera as montarias de guerra negras. A aba Jogador x Jogador do painel do personagem mostra sua patente e o que você pode comprar. {skill:762} uma delas em velocidade máxima exige {skill:762} Profissional (nível 60). O Polestar não consegue ler sua patente, então este passo espera o nível 60 e {skill:762} Profissional.",
		["{spell:22723}, {spell:828}, 100g"] = "{spell:22723}, {spell:828}, 100g",
} end)()
t.guides["forever/collectibles/mounts/alliance/horse"] = (function() return {
		["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "Qualquer raça da Aliança pode comprar estes cavalos, mas montar um também exige {spell:824}, que só os Humanos recebem com {skill:762}. {npc:4732} ensina às outras raças quando elas estão Exaltadas com {faction:72} (o guia Reputação: Ventobravo mostra o caminho). Até lá, não compre cavalo para este personagem.",
		["Horse"] = "Cavalo",
		["Learn to ride"] = "Aprenda a montar",
		["Pick a colour"] = "Escolha uma cor",
		["The {npc:5404} is not at {npc:384}: {npc:1460} sells it, at the stables of {area:150} in the {zone:1437} (20g in the Forever client). Skip this unless you want that colour."] = "{npc:5404} não está com {npc:384}: {npc:1460} vende, nos estábulos de {area:150}, em {zone:1437} (20g no cliente do Forever). Pule, a menos que queira essa cor.",
		["{item:2411}, 20g, {npc:1460}"] = "{item:2411}, 20g, {npc:1460}",
		["{item:2414}, 20g"] = "{item:2414}, 20g",
		["{item:5655}, 20g"] = "{item:5655}, 20g",
		["{item:5656}, 20g"] = "{item:5656}, 20g",
		["{npc:384} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:384} vende as outras cores (20g cada no cliente Forever). Compre as que quiser, ou nenhuma se gostar da montaria que ganhou.",
		["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 40 {npc:4732} teaches {skill:762} to Humans for 100g (10% less at Honored with {faction:72}), and it comes with a horse. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4732} e o cercado de cavalos de {npc:384} ficam em {area:88}, no leste de {zone:1429}. No nível 40, {npc:4732} ensina {skill:762} aos Humanos por 100g (10% menos com Honrado em {faction:72}), e vem junto um cavalo. As outras raças aprendem {skill:762}, com a própria primeira montaria, no instrutor de equitação da própria raça.",
		["{npc:4732}, riding trainer"] = "{npc:4732}, instrutor de equitação",
		["{npc:5404} in {area:150}"] = "{npc:5404} em {area:150}",
		["{spell:824} for other races"] = "{spell:824} para outras raças",
} end)()
t.guides["forever/collectibles/mounts/alliance/mechanostrider"] = (function() return {
		["Any Alliance race can buy these mechanostriders, but riding one also takes {spell:10907}, which only Gnomes get with {skill:762}. {npc:7954} teaches it to other races once they are Exalted with {faction:54} (the Gnomeregan Exiles Reputation guide shows the way). Until then, don't buy a mechanostrider for this character."] = "Qualquer raça da Aliança pode comprar estes mecanotrotes, mas montar um também exige {spell:10907}, que só os Gnomos recebem com {skill:762}. {npc:7954} ensina às outras raças quando elas estão Exaltadas com {faction:54} (o guia Reputação: Exilados de Gnomeregan mostra o caminho). Até lá, não compre mecanotrote para este personagem.",
		["In Classic only Dwarves and Gnomes could ride mechanostriders; in Forever every Alliance race can learn {spell:10907}."] = "No Classic, só Anões e Gnomos podiam montar mecanotrotes; no Forever, toda raça da Aliança pode aprender {spell:10907}.",
		["Learn to ride"] = "Aprenda a cavalgar",
		["Mechanostrider"] = "Mecanostruz",
		["Pick a colour"] = "Escolha uma cor",
		["{area:189} is just east of {area:131}; {npc:7954} stands beside {npc:7955}'s mechanostriders. At 40 {npc:7954} teaches {skill:762} to Gnomes for 100g (10% less at Honored with {faction:54}), and it comes with a mechanostrider. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{area:189} fica logo a leste de {area:131}; {npc:7954} fica ao lado dos mecanotrotes de {npc:7955}. No nível 40, {npc:7954} ensina {skill:762} aos Gnomos por 100g (10% menos com Honrado em {faction:54}), e vem junto um mecanotrote. As outras raças aprendem {skill:762}, com a própria primeira montaria, no instrutor de equitação da própria raça.",
		["{item:13321}, 20g"] = "{item:13321}, 20g",
		["{item:13322}, 20g"] = "{item:13322}, 20g",
		["{item:8563}, 20g"] = "{item:8563}, 20g",
		["{item:8595}, 20g"] = "{item:8595}, 20g",
		["{npc:7954}, riding trainer"] = "{npc:7954}, instrutor de equitação",
		["{npc:7955} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:7955} vende as outras cores (20g cada no cliente Forever). Compre as que quiser, ou nenhuma se a montaria que recebeu é a que você gosta.",
		["{spell:10907} for other races"] = "{spell:10907} para outras raças",
} end)()
t.guides["forever/collectibles/mounts/alliance/pack-kodo"] = (function() return {
		["6,000 Merchant's Favor"] = "6.000 de Merchant's Favor",
		["The camp is at {area:1002} in western {zone:1433}, where the roads from {zone:1429}, {zone:1431} and {area:69} meet. {npc:256736} sells the {npc:10636} only once you are Exalted with the {faction:2586}, and it costs 6,000 Merchant's Favor. Crates pay only Favor (about 15 a crate return); the reputation comes from Craftsman's Writs and the one-time {item:280179}, so follow the Supply Factions Reputation guide and keep 6,000 Favor aside."] = "O acampamento fica em {area:1002}, no oeste de {zone:1433}, onde se encontram as estradas de {zone:1429}, {zone:1431} e {area:69}. {npc:256736} só vende {npc:10636} quando você está Exaltado com {faction:2586}, e custa 6.000 de Merchant's Favor. Os caixotes pagam só Favor (cerca de 15 por caixote devolvido); a reputação vem das Escrituras do artífice e de {item:280179}, único, então siga o guia Reputação das Facções de Suprimentos e guarde 6.000 de Favor.",
		["The reins need level 60 and Journeyman Riding to ride (Forever client); you can buy them earlier."] = "As rédeas exigem nível 60 e Equitação de Profissional para montar (cliente Forever); dá para comprar antes.",
		["{faction:2586} camp"] = "Acampamento de {faction:2586}",
} end)()
t.guides["forever/collectibles/mounts/alliance/paladin-charger"] = (function() return {
		["An {item:12800} comes from Thorium veins and obsidian, about one vein in a hundred; a {item:18335} drops rarely from elites of level 59 and up (Revanchion and {npc:14695} about one kill in nine and one in a hundred). The Auction House is the usual source of both."] = "{item:12800} vem de veios de Tório e obsidiana, cerca de um veio em cem; {item:18335} cai raramente de elites de nível 59 ou mais (Revanchion e {npc:14695}, cerca de uma morte em nove e uma em cem). A Casa de Leilões é a fonte de costume dos dois.",
		["Arcanite Bars x6: an alchemist, or the Trade District Auction House"] = "Barras de Arcanita x6: um alquimista, ou a Casa de Leilões do Distrito Comercial",
		["At 60 {npc:5149} in the {object:32362} sends you to {quest:7638} in {zone:1453}'s Cathedral of Light."] = "No nível 60, {npc:5149} na {object:32362} manda você a {quest:7638} na Catedral da Luz de {zone:1453}.",
		["Back to Lord Grayson"] = "De volta a Lorde Grayson",
		["Bring the materials and 150 gold, taken at the hand-in. {npc:1416} walks to his forge and hands you the {item:18753}."] = "Leve os materiais e 150 de ouro, cobrados na entrega. {npc:1416} vai até a forja dele e entrega {item:18753} a você.",
		["Dire Maul West's door"] = "A porta de Gládio Cruel Oeste",
		["Enriched Manna Biscuits"] = "Biscoitos de Maná Enriquecidos",
		["Enriched Manna Biscuits: {npc:10857}, {area:3197}"] = "Biscoitos de Maná Enriquecidos: {npc:10857}, {area:3197}",
		["Lord Grayson blesses the censer into the {item:18752} for {area:2627}."] = "Lord Grayson abençoa o incensário e o transforma em {item:18752}, para {area:2627}.",
		["Lord Grayson hands you {item:18804}: open it for the {item:18746} and the {item:18792}. Keep both."] = "Lord Grayson entrega {item:18804} a você: abra para pegar {item:18746} e {item:18792}. Guarde os dois.",
		["Lord Grayson keeps the barding for now: you get it back with the next quest."] = "Lord Grayson fica com a armadura de montaria por enquanto: você a recebe de volta com a próxima missão.",
		["Lord Grayson takes the censer back."] = "Lord Grayson pega o incensário de volta.",
		["Paladin Charger"] = "Corcel de Paladino",
		["Stratholme Supply Crates, inside"] = "Caixotes de Suprimentos de Stratholme, lá dentro",
		["Terrordale Spirits x25"] = "Espíritos da Várzea do Medo x25",
		["The {spell:23214} chain is long: {area:2279}, Dire Maul West and {area:2057} with a group, 350 gold in donations, and materials worth several hundred more (6 Arcanite Bars, 40 {item:14047}, 10 {item:8836}, two diamonds). Start saving early. Lord Grayson stands in the Cathedral of Light, {npc:6171} nearby."] = "A cadeia de {spell:23214} é longa: {area:2279}, Gládio Cruel Oeste e {area:2057} com grupo, 350 de ouro em doações e materiais que valem várias centenas a mais (6 Barras de Arcanita, 40 {item:14047}, 10 {item:8836}, dois diamantes). Comece a juntar cedo. Lord Grayson fica na Catedral da Luz, {npc:6171} por perto.",
		["Two diamonds"] = "Dois diamantes",
		["Your epic mount at 60, summoned at will: the faster step up from the Warhorse."] = "Sua montaria épica no nível 60, evocada quando quiser: o passo mais rápido depois do Cavalo de Guerra.",
		["{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}; the door needs the {item:13704} (The Key to {area:2057}). Clear the {object:179746}, Rattlegore's room in the basement, then use the {item:18746} at its centre. Four waves of spirits come, each ending with an Aspect: players judge them with {spell:1105}, Justice, Righteousness and then Light, which stuns them. {npc:14516} (level 62 elite) comes after the last; he mind-controls players. Loot the {item:18749}, use it inside the Ossuary to redeem it, and give it and the {item:18792} to {npc:14568}. If the group wipes, the gates lock and the scryer is gone: abandon the quest and take it again from Lord Grayson for a new satchel. A group of five at 60. Again Into the {object:179746}, after the mount, lets you fight him again."] = "{area:2057} fica embaixo de {area:2298}, a cidade na ilha no sudeste de {zone:1422}; a porta precisa de {item:13704} (A Chave de {area:2057}). Limpe O Grande Ossuário, a sala de Rattlegore no porão, e use {item:18746} no centro. Vêm quatro ondas de espíritos, cada uma terminando com um Aspecto: os jogadores os julgam com {spell:1105}, Justiça, Retidão e depois Luz, que os atordoa. {npc:14516} (elite de nível 62) vem depois da última; ele controla a mente de jogadores. Saqueie {item:18749}, use no Ossuário para redimir e entregue-o, junto com {item:18792}, a {npc:14568}. Se o grupo morrer, os portões se trancam e o vidente some: abandone a missão e pegue de novo com Lord Grayson para receber uma sacola nova. Um grupo de cinco no nível 60. A missão Again Into the O Grande Ossuário, depois da montaria, permite lutar com ele de novo.",
		["{area:2279} is a dungeon for a group of five at 58-60, at the north end of the {zone:1423}. Stratholme Supply Crates along the streets of both halves hold the Holy Water, one to three each; they come back after three minutes. Some crates let out a swarm of plagued rats or maggots: be ready. The main gate (the Scarlet half) needs no key."] = "{area:2279} é uma masmorra para um grupo de cinco no nível 58-60, no extremo norte de {zone:1423}. Os Caixotes de Suprimentos de Stratholme pelas ruas das duas metades guardam a Água Benta, de um a três cada; voltam depois de três minutos. Alguns caixotes soltam um enxame de ratos pestilentos ou larvas: esteja preparado. O portão principal (a metade Escarlate) não precisa de chave.",
		["{area:2577} lies in central {zone:1444}. From the gate at the foot of the ruins, walk up through the outer courtyards to the West wing's door at their north end; it needs a {item:18249} (from Pusillin in Dire Maul East) or a rogue's lockpicking. {npc:11489} (level 60 elite) stands at the far end of the West wing's first courtyard. Once attacked he calls every {npc:11459} still alive in the courtyard: kill them first. His death frees the {quest:7643}: talk to it to give it the horse feed and the {item:18753}, and it blesses the barding. A group of five at 60."] = "{area:2577} fica no centro de {zone:1444}. A partir do portão ao pé das ruínas, suba pelos pátios externos até a porta da ala Oeste, no extremo norte deles; ela precisa de {item:18249} (de Pusillin, em Gládio Cruel Leste) ou do arrombamento de um ladino. {npc:11489} (elite de nível 60) fica no fundo do primeiro pátio da ala Oeste. Quando atacado, ele chama todos os {npc:11459} ainda vivos no pátio: mate-os primeiro. A morte dele liberta {quest:7643}: fale com ele para entregar a ração do cavalo e {item:18753}, e ele abençoa a armadura de montaria. Um grupo de cinco no nível 60.",
		["{area:2627} lies in the far north-west of the {zone:1423}, west of the {area:2279} gates. Stand inside a green glowing patch on the ground (a {object:179747}; some are inside the ruined houses) and use the {item:18752}: up to three Terrordale Spirits (level 59-60) rise and attack. Their {spell:7713} lowers all your stats by 30%: fight them one at a time and use {spell:2878}. The patches come back quickly; several paladins can work side by side."] = "{area:2627} fica no extremo noroeste de {zone:1423}, a oeste dos portões de {area:2279}. Fique dentro de uma mancha verde brilhante no chão (Terrordale Haunting Spirit; algumas ficam dentro das casas em ruínas) e use {item:18752}: até três Espíritos da Várzea do Medo (nível 59-60) se erguem e atacam. O {spell:7713} deles reduz todos os seus atributos em 30%: lute com um de cada vez e use {spell:2878}. As manchas voltam rápido; vários paladinos podem trabalhar lado a lado.",
		["{item:14047} drops from humanoids of level 50 and up ({area:2255}'s Bruisers, the Scarlet Crusade in the Plaguelands, the {area:2577} ogres). {item:8836} is a Plaguelands herb ({skill:182} 220), common around {area:3197}. An {item:12360} is an alchemist's transmute from a {item:12359} and an {item:12363}, once every two days per alchemist: ask a guild alchemist early, or buy the bars. The Auction House sells all three."] = "{item:14047} cai de humanoides de nível 50 ou mais (os Brutamontes de {area:2255}, a Cruzada Escarlate nas Terras Pestilentas, os ogros de {area:2577}). {item:8836} é uma erva das Terras Pestilentas ({skill:182} 220), comum em volta de {area:3197}. {item:12360} é uma transmutação de alquimista, feita de {item:12359} e {item:12363}, uma vez a cada dois dias por alquimista: peça cedo a um alquimista da guilda, ou compre as barras. A Casa de Leilões vende os três.",
		["{item:14047} x40"] = "{item:14047} x40",
		["{item:18749}, inside the {object:179746}"] = "{item:18749}, dentro de O Grande Ossuário",
		["{item:18752}, inside a green patch"] = "{item:18752}, dentro de uma mancha verde",
		["{item:18792}, from the satchel"] = "{item:18792}, da sacola",
		["{item:8836} x10"] = "{item:8836} x10",
		["{npc:11406}, the priest trainer, walks about the {object:32386} in {zone:1455}'s {object:32362}. He gives you his censer for a donation of 150 gold, taken at the hand-in. Keep the censer."] = "{npc:11406}, o instrutor de sacerdote, anda pelo Salão dos Mistérios, no Ala Mística de {zone:1455}. Ele entrega o incensário dele por uma doação de 150 de ouro, cobrada na entrega. Guarde o incensário.",
		["{npc:11406}: 150 gold"] = "{npc:11406}: 150 de ouro",
		["{npc:11489}, inside the West wing"] = "{npc:11489}, dentro da ala Oeste",
		["{npc:1416} works in {zone:1453}'s {object:28027}. He forges the {item:18753} from your materials and 150 gold."] = "{npc:1416} trabalha no {object:28027} de {zone:1453}. Ele forja {item:18753} com seus materiais e 150 de ouro.",
		["{npc:1416}'s materials"] = "Materiais de {npc:1416}",
		["{npc:1416}: 150 gold"] = "{npc:1416}: 150 de ouro",
		["{npc:2357} breeds horses in {area:271}'s stable. She makes the {quest:7645} from the 20 biscuits and 50 gold, taken at the hand-in."] = "{npc:2357} cria cavalos no estábulo de {area:271}. Ela faz {quest:7645} com os 20 biscoitos e 50 de ouro, cobrados na entrega.",
		["{npc:6171}, Cathedral of Light"] = "{npc:6171}, Catedral da Luz",
		["{npc:928}: the {item:18753}"] = "{npc:928}: a {item:18753}",
		["{object:2160} quartermasters sell Enriched Manna Biscuits, five for 60 silver, once the {object:92525} is Friendly with you: {npc:10857} at {area:3197} or {npc:11536} at {area:2268}. Scourgestones and the Plaguelands quests raise the standing."] = "Os intendentes de {object:2160} vendem Biscoitos de Maná Enriquecidos, cinco por 60 pratas, quando Aurora Argêntea está Amigável com você: {npc:10857} em {area:3197} ou {npc:11536} em {area:2268}. As Pedras do Flagelo e as missões das Terras Pestilentas aumentam a reputação.",
} end)()
t.guides["forever/collectibles/mounts/alliance/paladin-warhorse"] = (function() return {
		["At 40 {npc:6179}, upstairs in the {object:32386}, sends you to {npc:6171} in {zone:1453} ({npc:5149} downstairs gives the same errand; take one). Take the {area:2257} to {zone:1453}."] = "No nível 40, {npc:6179}, no andar de cima do Salão dos Mistérios, manda você para {npc:6171}, em {zone:1453} ({npc:5149}, no andar de baixo, dá a mesma tarefa; pegue uma). Pegue o {area:2257} até {zone:1453}.",
		["Paladin Warhorse"] = "Cavalo de Guerra de Paladino",
		["Your first mount at 40, summoned at will: a paladin buys no horse."] = "Sua primeira montaria no nível 40, evocada à vontade: paladinos não compram cavalo.",
		["{npc:6171} stands in the Cathedral of Light. At 40 he offers {quest:1661}: accept it and hand it straight back to learn {spell:13819}. Paladins do not buy a horse."] = "{npc:6171} fica na Catedral da Luz. No nível 40, ele oferece {quest:1661}: aceite e devolva na hora para aprender {spell:13819}. Paladinos não compram cavalo.",
} end)()
t.guides["forever/collectibles/mounts/alliance/ram"] = (function() return {
		["Any Alliance race can buy these rams, but riding one also takes {spell:826}, which only Dwarves get with {skill:762}. {npc:4772} teaches it to other races once they are Exalted with {faction:47} (the Ironforge Reputation guide shows the way). Until then, don't buy a ram for this character."] = "Qualquer raça da Aliança pode comprar estes carneiros, mas montar um também exige {spell:826}, que só os Anões recebem com {skill:762}. {npc:4772} ensina às outras raças quando elas estão Exaltadas com {faction:47} (o guia Reputação: Altaforja mostra o caminho). Até lá, não compre carneiro para este personagem.",
		["Learn to ride"] = "Aprenda a cavalgar",
		["Pick a colour"] = "Escolha uma cor",
		["Ram"] = "Carneiro",
		["{area:803} is east of {area:131} on the road to {zone:1432}; {npc:4772} stands beside {npc:1261}'s rams. At 40 {npc:4772} teaches {skill:762} to Dwarves for 100g (10% less at Honored with {faction:47}), and it comes with a ram. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{area:803} fica a leste de {area:131}, na estrada para {zone:1432}; {npc:4772} fica ao lado dos carneiros de {npc:1261}. No nível 40, {npc:4772} ensina {skill:762} aos Anões por 100g (10% menos com Honrado em {faction:47}), e vem junto um carneiro. As outras raças aprendem {skill:762}, com a própria primeira montaria, no instrutor de equitação da própria raça.",
		["{item:5864}, 20g"] = "{item:5864}, 20g",
		["{item:5872}, 20g"] = "{item:5872}, 20g",
		["{item:5873}, 20g"] = "{item:5873}, 20g",
		["{npc:1261} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:1261} vende as outras cores (20g cada no cliente Forever). Compre as que quiser, ou nenhuma se a montaria que recebeu é a que você gosta.",
		["{npc:4772}, riding trainer"] = "{npc:4772}, instrutor de equitação",
		["{spell:826} for other races"] = "{spell:826} para outras raças",
} end)()
t.guides["forever/collectibles/mounts/alliance/saber"] = (function() return {
		["Any Alliance race can buy these sabers, but riding one also takes {spell:828}, which only Night Elves get with {skill:762}. {npc:4753} teaches it to other races once they are Exalted with {faction:69} (the Darnassus Reputation guide shows the way). Until then, don't buy a saber for this character."] = "Qualquer raça da Aliança pode comprar estes sabres, mas montar um também exige {spell:828}, que só os Elfos Noturnos recebem com {skill:762}. {npc:4753} ensina às outras raças quando elas estão Exaltadas com {faction:69} (o guia Reputação: Darnassus mostra o caminho). Até lá, não compre sabre para este personagem.",
		["Learn to ride"] = "Aprenda a montar",
		["Pick a colour"] = "Escolha uma cor",
		["Saber"] = "Sabre",
		["new in Forever, 20g; beta players found it here"] = "novo no Forever, 20g; jogadores do beta o encontraram aqui",
		["{item:8629}, 20g"] = "{item:8629}, 20g",
		["{item:8631}, 20g"] = "{item:8631}, 20g",
		["{item:8632}, 20g"] = "{item:8632}, 20g",
		["{npc:4730} sells the other colours (20g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:4730} vende as outras cores (20g cada no cliente do Forever). Compre as que quiser, ou nenhuma se a montaria que você ganhou for a que você gosta.",
		["{npc:4753} and {npc:4730}'s sabers are in the {area:1658}'s riding grounds in {faction:69}. At 40 {npc:4753} teaches {skill:762} to Night Elves for 100g (10% less at Honored with {faction:69}), and it comes with a saber. Other races learn {skill:762}, with their own first mount, at their own race's riding trainer."] = "{npc:4753} e os sabres de {npc:4730} ficam nos campos de equitação de {area:1658}, em {faction:69}. No nível 40, {npc:4753} ensina {skill:762} aos Elfos Noturnos por 100g (10% menos com Honrado em {faction:69}), e vem junto um sabre. As outras raças aprendem {skill:762}, com a própria primeira montaria, no instrutor de equitação da própria raça.",
		["{npc:4753}, riding trainer"] = "{npc:4753}, instrutor de equitação",
		["{spell:828} for other races"] = "{spell:828} para outras raças",
} end)()
t.guides["forever/collectibles/mounts/alliance/stormpike-battle-charger"] = (function() return {
		["The Forever client lists it at 200g and level 60. It runs at full speed, so riding it needs Journeyman {skill:762}; any Alliance race can ride it."] = "O cliente do Forever a lista por 200g e nível 60. Ela corre em velocidade máxima, então montar exige {skill:762} Profissional; qualquer raça da Aliança pode montar.",
		["{area:2839} (level 51+) raises {faction:730}: win, capture towers and graveyards, and hand in the battleground's turn-ins; the Alterac Valley Reputation guide shows the fastest way. {npc:13217} waits outside the battleground on the {zone:1416} border above {area:287}; {npc:13216} inside {area:2839} sells the same mount."] = "{area:2839} (nível 51+) aumenta {faction:730}: vença, capture torres e cemitérios e entregue as missões do campo de batalha; o guia Reputação: Vale Alterac mostra o jeito mais rápido. {npc:13217} espera fora do campo de batalha, na divisa de {zone:1416}, acima de {area:287}; {npc:13216}, dentro de {area:2839}, vende a mesma montaria.",
		["{npc:13217}, 200g"] = "{npc:13217}, 200g",
} end)()
t.guides["forever/collectibles/mounts/alliance/swift-horse"] = (function() return {
		["Any Alliance race can buy these horses, but riding one also takes {spell:824}, which only Humans get with {skill:762}. {npc:4732} teaches it to other races once they are Exalted with {faction:72} (the Stormwind Reputation guide shows the way). Until then, don't buy a horse for this character."] = "Qualquer raça da Aliança pode comprar estes cavalos, mas montar um também exige {spell:824}, que só os Humanos recebem com {skill:762}. {npc:4732} ensina às outras raças quando elas estão Exaltadas com {faction:72} (o guia Reputação: Ventobravo mostra o caminho). Até lá, não compre cavalo para este personagem.",
		["Journeyman {skill:762}"] = "{skill:762} (Profissional)",
		["Pick a colour"] = "Escolha uma cor",
		["Swift Horse"] = "Cavalo Veloz",
		["{item:18776}, 200g"] = "{item:18776}, 200g",
		["{item:18777}, 200g"] = "{item:18777}, 200g",
		["{item:18778}, 200g"] = "{item:18778}, 200g",
		["{npc:384} sells the other colours (200g each in the Forever client). Buy any you want, or none if the mount you were given is the one you like."] = "{npc:384} vende as outras cores (200g cada no cliente Forever). Compre as que quiser, ou nenhuma se gostar da montaria que ganhou.",
		["{npc:4732} and {npc:384}'s horse pen are at {area:88} in eastern {zone:1429}. At 60 {npc:4732} teaches Journeyman {skill:762} to Humans for 1,000g (10% less at Honored with {faction:72}); Blizzard says it comes with a mount. Other races train it at their own race's riding trainer. Each swift horse costs 200g here."] = "{npc:4732} e o cercado de cavalos de {npc:384} ficam em {area:88}, no leste de {zone:1429}. No nível 60, {npc:4732} ensina {skill:762} Profissional aos Humanos por 1.000g (10% menos com Honrado em {faction:72}); a Blizzard diz que vem junto uma montaria. As outras raças treinam no instrutor de equitação da própria raça. Cada cavalo veloz custa 200g aqui.",
		["{npc:4732}, riding trainer"] = "{npc:4732}, instrutor de equitação",
		["{spell:824} for other races"] = "{spell:824} para outras raças",
} end)()
