		["Go back into southern {zone:1443}; the road continues south into {zone:1444}."] = "Volte ao sul de {zone:1443}; a estrada segue para o sul até {zone:1444}.",
		["Horde town: Alliance characters only need to touch its edge (guards)"] = "Cidade da Horda: personagens da Aliança só precisam tocar a borda (guardas)",
		["Horde town: Alliance characters only need to touch its edge (guards); any one of these names counts"] = "Cidade da Horda: personagens da Aliança só precisam tocar a borda (guardas); qualquer um destes nomes vale",
		["Picks up west of the {zone:1413}, in {zone:1443}, and ends in {zone:1445}. 15 areas to discover here, levels 30-39."] = "Começa a oeste de {zone:1413}, em {zone:1443}, e termina em {zone:1445}. 15 áreas a descobrir aqui, níveis 30-39.",
		["any one of these names counts"] = "qualquer um destes nomes vale",
		["level 60 area, well above this guide's range"] = "área de nível 60, bem acima da faixa deste guia",
		["level 61 area, well above this guide's range"] = "área de nível 61, bem acima da faixa deste guia",
		["{area:1099} in the east is the Horde town."] = "{area:1099}, no leste, é a cidade da Horda.",
		["{area:1113} and {area:1111} are level 60 areas, far above this guide. Skip this step for now and come back near that level: exploring the whole map needs them."] = "{area:1113} e {area:1111} são áreas de nível 60, muito acima deste guia. Pule este passo por enquanto e volte perto desse nível: explorar o mapa todo exige elas.",
		["{area:1116} on {area:1120} is the Alliance town (boat from the {area:1108})."] = "{area:1116}, em {area:1120}, é a cidade da Aliança (barco a partir de {area:1108}).",
		["{area:2079} is a level 61 area, far above this guide. Skip this step for now and come back near that level: exploring the whole map needs it."] = "{area:2079} é uma área de nível 61, muito acima deste guia. Pule este passo por enquanto e volte perto desse nível: explorar o mapa todo exige ela.",
		["{zone:1444}: level 60+ areas"] = "{zone:1444}: áreas de nível 60+",
		["{zone:1445} is east of the southern {zone:1413}; {area:496} in the north-west is the Horde town."] = "{zone:1445} fica a leste do sul de {zone:1413}; {area:496}, no noroeste, é a cidade da Horda.",
		["{zone:1445}: level 61+ area"] = "{zone:1445}: área de nível 61+",
		["{zone:2652}, the ruins between {zone:1443} and {zone:1412}, is entered from southern {zone:1443} through the {area:2657}."] = "{zone:2652}, as ruínas entre {zone:1443} e {zone:1412}, tem a entrada no sul de {zone:1443}, por {area:2657}.",
} end)()
t.guides["forever/exploration/kalimdor-45-60"] = (function() return {
		["1 area to discover here, level 15."] = "1 área a descobrir aqui, nível 15.",
		["12 areas to discover here, levels 47-54."] = "12 áreas a descobrir aqui, níveis 47-54.",
		["13 areas to discover here, levels 55-60."] = "13 áreas a descobrir aqui, níveis 55-60.",
