		["Flight path here: {area:2255} (Maethrya)."] = "Rota de voo aqui: {area:2255} (Maethrya).",
		["Flight path here: {area:2255} (Yugrek)."] = "Rota de voo aqui: {area:2255} (Yugrek).",
		["Flight path here: {area:3137} (Jarrodenus)."] = "Rota de voo aqui: {area:3137} (Jarrodenes).",
		["Flight path here: {area:3425} ({npc:15177})."] = "Rota de voo aqui: {area:3425} ({npc:15177}).",
		["Flight path here: {area:3425} ({npc:15178})."] = "Rota de voo aqui: {area:3425} ({npc:15178}).",
		["Flight path here: {area:541} (Gryfe)."] = "Rota de voo aqui: {area:541} (Gryfe).",
		["Flight path here: {area:976} ({npc:7823})."] = "Rota de voo aqui: {area:976} ({npc:7823}).",
		["Flight path here: {area:976} ({npc:7824})."] = "Rota de voo aqui: {area:976} ({npc:7824}).",
		["Flight path here: {zone:1450} (Faustron)."] = "Rota de voo aqui: {zone:1450} (Faustron).",
		["Flight path here: {zone:1450} (Sindrayl)."] = "Rota de voo aqui: {zone:1450} (Sindrayl).",
		["Fly to {area:1237} if you have it, otherwise to {area:431}, and walk east out of {zone:1440} into {zone:1447}."] = "Voe para {area:1237} se tiver a rota, senão para {area:431}, e caminhe para leste saindo de {zone:1440} até {zone:1447}.",
		["Fly to {area:3137} if you have it, otherwise to {area:415}, and walk east out of {zone:1440} into {zone:1447}."] = "Voe para {area:3137} se tiver a rota, senão para {area:415}, e caminhe para leste saindo de {zone:1440} até {zone:1447}.",
		["From western {zone:1446} take the path down into {zone:1449}. {area:541} in the north is a neutral camp."] = "Do oeste de {zone:1446} pegue a trilha que desce até {zone:1449}. {area:541}, no norte, é um acampamento neutro.",
		["Horde town: Alliance characters only need to touch its edge (guards)"] = "Cidade da Horda: personagens da Aliança só precisam tocar a borda dela (guardas)",
		["Starts in {zone:1446}, south of {zone:1445}. The last area of this guide completes the {zone:1414} map. 20 areas to discover here, levels 40-50."] = "Começa em {zone:1446}, ao sul de {zone:1445}. A última área deste guia completa o mapa de {zone:1414}. 20 áreas a descobrir aqui, níveis 40-50.",
		["Take the {area:1769} tunnel in northern {zone:1448} through to {zone:1450} (druids: {spell:18960}). {area:2361} is neutral."] = "Pegue o túnel de {area:1769}, no norte de {zone:1448}, até {zone:1450} (druidas: {spell:18960}). {area:2361} é neutra.",
		["The other exit of the {area:1769} tunnel leads into {zone:1452}. {area:2255} is a neutral goblin town with flight masters for both factions."] = "A outra saída do túnel de {area:1769} leva a {zone:1452}. {area:2255} é uma cidade goblin neutra com mestres de voo das duas facções.",
		["any one of these names counts"] = "qualquer um destes nomes conta",
		["{zone:1446} is south of {zone:1445} and {zone:1441}. {area:976} is a neutral goblin town."] = "{zone:1446} fica ao sul de {zone:1445} e de {zone:1441}. {area:976} é uma cidade goblin neutra.",
		["{zone:1448} is north of {zone:1440}."] = "{zone:1448} fica ao norte de {zone:1440}.",
		["{zone:1451} is west of {zone:1449}, through the pass in its north-west. {area:3425} is neutral."] = "{zone:1451} fica a oeste de {zone:1449}, pela passagem no noroeste dela. {area:3425} é neutra.",
		["{zone:2482} is reached from {zone:1452} through {area:2256} in the south. It is Forever's endgame leveling zone."] = "{zone:2482} é alcançado a partir de {zone:1452} por {area:2256}, no sul. É a zona de evolução de fim de jogo do Forever.",
} end)()
t.guides["forever/exploration/zephras-isle"] = (function() return {
		["Exploration: {zone:2521}"] = "Exploração: {zone:2521}",
		["Skyborne start here. Everyone else takes a skyboat, about every five minutes; either faction may take either one."] = "Os Celonatos começam aqui. Todos os outros pegam um barco celeste, mais ou menos a cada cinco minutos; qualquer facção pode pegar qualquer um deles.",
		["The skyboat leaves the cliffs south of {area:17045}, north of {zone:1456} (another flies from {area:279})."] = "O barco celeste parte dos penhascos ao sul de {area:17045}, ao norte de {zone:1456} (outro voa de {area:279}).",
		["The skyboat leaves the north side of {area:279} in the {zone:1416} (another flies from north of {zone:1456})."] = "O barco celeste parte do lado norte de {area:279}, nas {zone:1416} (outro voa do norte de {zone:1456}).",
		["any one of these names counts"] = "qualquer um destes nomes conta",
		["{zone:2521} is the Skyborne starting island, a world of its own in {area:17221}; anyone may visit. 20 areas to discover here, levels 3-12."] = "{zone:2521} é a ilha inicial dos Celonatos, um mundo à parte em {area:17221}; qualquer um pode visitar. 20 áreas para descobrir aqui, níveis 3-12.",
} end)()
t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "Ajude {npc:261366}: fique ao lado dele quando {npc:261367} e os fuzileiros de {area:21} subirem a serra",
		["At the {area:2362}"] = "Em {area:2362}",
		["At the {object:147538}: summons {quest:882}"] = "Em {object:147538}: invoca {quest:882}",
		["Back down to {npc:11857}."] = "De volta a {npc:11857}.",
		["Back east over the bridge and up the trail to {npc:5900}'s shrine, as at 10. {npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "Volte para leste pela ponte e suba a trilha até o santuário de {npc:5900}, como no nível 10. {npc:5900} faz {item:6636} com o piche e o bornal. Use junto ao braseiro ao lado dele para revelar {npc:5893}, mate-a para pegar {item:6655} e depois ponha a brasa no braseiro.",
		["Back north into the Bristleback camps. Any Bristleback can drop a tusk for {npc:3432}, so collect them while you kill these for {npc:3430}. Keep one {item:5075}."] = "De volta ao norte, para os acampamentos Costagulha. Qualquer Costagulha pode deixar cair uma presa para {npc:3432}, então junte enquanto mata estes para {npc:3430}. Guarde um {item:5075}.",
		["Back north into {area:378} on the way to the Crossroads: {npc:3387} takes the thunderhawk wings. Warriors: {npc:6394} first, before the antennae fade."] = "De volta ao norte, em {area:378}, a caminho da Encruzilhada: {npc:3387} recebe as asas de falcotrom. Guerreiros: {npc:6394} primeiro, antes que as antenas sumam.",
		["Back to the Crossroads"] = "De volta à Encruzilhada",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them."] = "De volta ao acampamento Crinavalha. Geomantes e Defensores ocupam a metade leste; {npc:3438} anda entre eles.",
		["Bristleback camps"] = "Acampamentos Costagulha",
		["Burning Blade Cultists hold {area:1898} in northern {zone:1411}; they drop the {item:6652}. The {item:5026} comes from the Razormane on your next visit to their camp."] = "Sectários da Lâmina Ardente ocupam {area:1898}, no norte de {zone:1411}; eles deixam cair o {item:6652}. O {item:5026} vem dos Crinavalha na sua próxima visita ao acampamento deles.",
		["Cast {spell:18960}"] = "Use {spell:18960}",
		["Cast {spell:18960}. {npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "Use {spell:18960}. {npc:11802} fica no andar de cima do prédio dele em {area:2361}: suba por dentro, a seta não diferencia os andares.",
		["Crossroads flight master"] = "Mestre de voo da Encruzilhada",
		["Dogran is chained up in the quilboar camp west of the road."] = "Dogran está acorrentado no acampamento de javatuscos a oeste da estrada.",
		["Down the {area:458} to {area:378} again."] = "Desça {area:458} até {area:378} de novo.",
		["East along the road to {npc:4049} and {npc:11857}'s camp, on the way back out of Stonetalon."] = "A leste pela estrada até o acampamento de {npc:4049} e {npc:11857}, na volta de Torres de Pedra.",
		["East from {npc:261366} toward the {area:382}: {npc:9316} stands at the camp on the road north of the Crossroads."] = "Para o leste a partir de {npc:261366}, rumo a {area:382}: {npc:9316} fica no acampamento da estrada ao norte da Encruzilhada.",
		["East of Ziz, the Venture Company is clear-cutting {area:461}; one of the Operators carries the blueprints."] = "A leste de Zé Fízzica, a Empreendimentos S.A. está desmatando {area:461}; um dos Operadores leva as plantas.",
		["East to the beach, at the south end of the pirate camp: the crate of boots and the fragile crate with the lens sit there, a short walk north of {area:385}."] = "Para leste, até a praia, na ponta sul do acampamento dos piratas: a caixa de botas e a caixa frágil com a lente ficam lá, a uma curta caminhada ao norte de {area:385}.",
		["Fill the {item:7766} at the quilboar watering hole"] = "Encha o {item:7766} no bebedouro dos javaligs",
		["Finish the Plainstrider Beaks"] = "Complete os Bicos de Pinote",
		["Finish the Raptor Heads"] = "Complete as Cabeças de Raptor",
		["Fly back to the Crossroads; the road west to Stonetalon starts at {npc:3389}'s bunkers."] = "Voe de volta para a Encruzilhada; a estrada para o oeste, rumo a Torres de Pedra, começa nos bunkers de {npc:3389}.",
		["Fly from the Crossroads to {area:1638} and train your level 20 ranks: {npc:3033} is on {area:1639}."] = "Voe da Encruzilhada para {area:1638} e treine as habilidades de nível 20: {npc:3033} fica em {area:1639}.",
		["Fly from the Crossroads to {area:1638}: {npc:3033} trains you on {area:1639}."] = "Voe da Encruzilhada para {area:1638}: {npc:3033} treina você em {area:1639}.",
		["Fly from {zone:1456} on to {area:392}."] = "Siga voando de {zone:1456} para {area:392}.",
		["Fly from {zone:1456} straight on to {area:392}."] = "Voe de {zone:1456} direto para {area:392}.",
		["Fly on to {area:392} from Doras on the tower in the {object:172982}."] = "Siga voando para {area:392} com Doras, na torre de {object:172982}.",
		["Fly to Crossroads"] = "Voe para a Encruzilhada",
		["Fly to {area:1637}"] = "Voe para {area:1637}",
		["Fly to {area:1638} to train: {npc:3033} is on {area:1639}."] = "Voe para {area:1638} para treinar: {npc:3033} fica em {area:1639}.",
		["Fly to {area:392}"] = "Voe para {area:392}",
		["Follow the road east to the outpost above the {area:814}."] = "Siga a estrada para leste até o posto acima de {area:814}.",
		["Follow the road on west from {npc:4049} into Stonetalon. The troll village of {area:2539} sits at the entrance of the canyon."] = "Siga a estrada para oeste a partir de {npc:4049}, rumo a Torres de Pedra. A vila troll de {area:2539} fica na entrada do desfiladeiro.",
		["Follow the road south-east to {area:392} on the coast."] = "Siga a estrada para sudeste até {area:392}, no litoral.",
		["Follow the {area:458} south to {area:378}."] = "Siga {area:458} para o sul até {area:378}.",
		["Grimtotem camp"] = "Acampamento Temível Totem",
		["He gives you the {item:15826}"] = "Ele dá a você {item:15826}",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "Em seguida ele oferece {quest:1838} (1838, nível 30): ela exige {area:1717} e manda você por toda Kalimdor e pelos Reinos do Leste. O guia da classe Guerreiro {quest:1838} cobre essa missão.",
		["Head north from the Crossroads to {area:384} and fill the {item:15842} at the {object:19464}, then back to {npc:3448} in the Crossroads. No {skill:182}? {npc:3490} beside him sells {item:2449}, three at a time until he restocks."] = "Siga para o norte da Encruzilhada até {area:384} e encha o {item:15842} em {object:19464}, depois volte a {npc:3448} na Encruzilhada. Sem {skill:182}? {npc:3490}, ao lado dele, vende {item:2449}, três por vez até repor o estoque.",
		["In from the north gate: {npc:3464} first, {npc:3338} by the inn, {npc:3448} at the south gate, then up to {npc:3449} and {npc:3429} on the tower platform, where the flight master stands."] = "Entrando pelo portão norte: {npc:3464} primeiro, {npc:3338} junto à estalagem, {npc:3448} no portão sul; depois suba até {npc:3449} e {npc:3429}, na plataforma da torre, onde fica o mestre de voo.",
		["In the camp, Water Seekers and Thornweavers hold the western half, Hunters the middle; the supply crates sit at its eastern end.\nPlainstriders here count toward the beaks."] = "No acampamento, os Rabdomantes e os Tecespinhos ficam na metade oeste e os Caçadores Crinavalha no meio; as caixas de suprimentos ficam na ponta leste.\nOs Pinotes daqui também contam para os bicos.",
		["Inside"] = "Lá dentro",
		["Keep it: the {object:107045} is beside {area:272}, on the {area:287} guide"] = "Guarde: {object:107045} fica ao lado de {area:272}, no guia de {area:287}",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "Guarde-a: {npc:12696} em {zone:1440}, próximo guia",
		["Keep it: {npc:5875} in {zone:1454}, on the next guide's {zone:1454} stop"] = "Guarde: {npc:5875} em {zone:1454}, na parada em {zone:1454} do próximo guia",
		["Keep it: {quest:3923} is in {zone:1454}'s {object:172958}, on the {zone:1454} trip at 20"] = "Guarde: {quest:3923} fica em {object:172958}, em {zone:1454}, na ida a {zone:1454} no nível 20",
		["Kolkar camp"] = "Acampamento Kolkar",
		["Leave {zone:1454} by the main gate and follow the road south through {zone:1411}, then west over the {area:814} bridge: {area:379} sits just above it on the {zone:1413} side. {npc:3337} and {npc:5810} stand together."] = "Saia de {zone:1454} pelo portão principal e siga a estrada para o sul por {zone:1411}, depois para oeste pela ponte de {area:814}: {area:379} fica logo acima dela, do lado de {zone:1413}. {npc:3337} e {npc:5810} ficam juntos.",
		["Lost Barrens Kodos roam the plains around the Kolkar camp north-west of {npc:3389}; herbalists pick {item:2449} there too."] = "Os Kodos Perdidos dos Sertões andam pelas planícies em volta do acampamento Kolkar, a noroeste de {npc:3389}; os herbalistas também colhem {item:2449} ali.",
		["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "Para o norte, até {area:383}. {npc:3682} acampa abaixo das colinas; {npc:261366}, o eremita na serra atrás dele, só tem trabalho para você depois que {npc:3682} mandar você subir.",
		["North up the road from {area:2539}: {npc:11858} and his Grimtotem Brutes hold the bend in the road, and the Deepmoss Creepers and Venomspitters lurk in the webs on both sides of the path all the way up."] = "Subindo a estrada a partir de {area:2539}: {npc:11858} e os Brutos Temível Totem dele dominam a curva da estrada, e os Rastejantes e Cospeçonhas de Fundolimo espreitam nas teias dos dois lados da trilha, até lá em cima.",
		["North up the {area:458} to the Crossroads: {npc:3432} stands by the inn, {npc:3428} west of the north gate."] = "Suba pela {area:458} até a Encruzilhada: {npc:3432} fica perto da estalagem, {npc:3428} a oeste do portão norte.",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate. Keep the {item:5075}: {npc:3430} takes it on the next stop in {area:378}."] = "Suba pela {area:458} até a Encruzilhada: {npc:3448} no portão sul, {npc:3432} perto da estalagem, {npc:3428} a oeste do portão norte. Guarde o {item:5075}: {npc:3430} o recebe na próxima parada em {area:378}.",
		["North-west to the {area:383}: the Witchwing Slayers hold their western end; they wear the rings.\nCareful: Some stealthed harpy ambushers wait in the area and stay hidden until you get close. A level 19 elite harpy also patrols there."] = "Para o noroeste, até {area:383}: as Asabruxas Matadoras ocupam a ponta oeste; elas carregam os anéis.\nCuidado: algumas harpias emboscadoras furtivas esperam na área e ficam escondidas até você chegar perto. Uma harpia elite de nível 19 também patrulha por lá.",
		["On the top floor"] = "No último andar",
		["On the way back down the {area:1076}, {npc:11856} is held in {npc:11858}'s hut at the bend in the road. Once you take her quest she walks straight off south-east to {area:2538}, the burned village, without waiting: stay close, or the quest fails.\nCareful: Three Grimtotems ambush her at the burned village and go for her, not you: pull them off her and kill their caster quickly."] = "Na descida de volta por {area:1076}, {npc:11856} está presa na cabana de {npc:11858}, na curva da estrada. Assim que você aceitar a missão dela, ela segue direto para sudeste até {area:2538}, a aldeia queimada, sem esperar: fique perto, ou a missão falha.\nCuidado: três Temível Totem a emboscam na aldeia queimada e vão para cima dela, não de você: tire-os de cima dela e mate o conjurador deles rápido.",
		["On the way back down the {area:458} to {area:378}: the Razormane Raiders among the Bristleback camps, either side of the road north of the camp, carry {item:277277}. Hand them to {npc:3432} on your last Crossroads stop."] = "Na volta por {area:458} até {area:378}: os Saqueadores Crinavalha entre os acampamentos Costagulha, dos dois lados da estrada ao norte do acampamento, carregam {item:277277}. Entregue-os a {npc:3432} na última parada na Encruzilhada.",
		["On the way east to {quest:881}: Sunscale Scytheclaws prowl the plains east of the {area:383}; any of them can drop an {item:5055} for {npc:3446} in {area:392}."] = "No caminho para o leste, rumo a {quest:881}: Garrafoices Helióscamo rondam as planícies a leste de {area:383}; qualquer um pode deixar cair um {item:5055} para {npc:3446} em {area:392}.",
		["Over the {area:814} bridge below {area:379} and south along the {zone:1411} bank to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "Atravesse a ponte de {area:814} abaixo de {area:379} e siga para o sul pela margem de {zone:1411} até onde uma trilha estreita sobe a montanha: {npc:5900} cuida do santuário no topo. Cuidado com as beiradas na subida e desça pela mesma trilha.",
		["Plainstrider Beaks as you go"] = "Bicos de Pinote pelo caminho",
		["Plainstriders roam the plains all over the {zone:1413}, and about one in four drops a beak: kill the ones you pass on the way."] = "Pinotes vagam por todas as planícies de {zone:1413}, e cerca de um em cada quatro solta um bico: vá matando os que encontrar pelo caminho.",
		["Raptor Heads as you go"] = "Cabeças de Raptor pelo caminho",
		["Raptor nests"] = "Ninhos de raptor",
		["Razormane camp"] = "Acampamento Crinavalha",
		["Razormane camp: {npc:3429}'s quilboar"] = "Acampamento Crinavalha: os javatuscos de {npc:3429}",
		["Savannah Patriarchs roam the plains east of the hills, and the Sprung Traps lie among them. {quest:876} leads the Witchwing harpies in the hills to the west.\nCareful: The route in passes stealthed Harpy Ambushers and an elite harpy that patrols."] = "Patriarcas da Savana vagam pelas planícies a leste das colinas, e as Armadilhas Disparadas estão no meio deles. {quest:876} lidera as harpias Asabruxa nas colinas a oeste.\nCuidado: o caminho até lá passa por harpias emboscadoras furtivas e por uma harpia elite que patrulha.",
		["South down the road to the Crossroads: {npc:3449} stands on the tower platform, {npc:3448} at the south gate."] = "Desça a estrada para o sul até a Encruzilhada: {npc:3449} fica na plataforma da torre e {npc:3448}, no portão sul.",
		["South of Camp Taurajo, the Silithid Mounds dot the {area:390}; the eggs lie in them, and Silithid Swarmers come out to defend them.\nCareful: Silithid Swarmers in the area release many tiny adds that interrupt spells; damage shields such as Thorns kill them in one hit."] = "Ao sul do Acampamento Taurajo, os Montes de Terra Silitídeos se espalham por {area:390}; os ovos ficam neles, e Enxameadores Silitídeos saem para defendê-los.\nCuidado: os Enxameadores Silitídeos da região soltam muitos bichinhos que interrompem feitiços; escudos de dano como Espinhos matam cada um com um golpe.",
		["South-east of the Crossroads. Test the seeds at the bubbling fissure on the oasis' east bank; {npc:3448} takes the result on the next Crossroads stop, so carry on north-west to the {area:383} from here."] = "A sudeste da Encruzilhada. Teste as sementes na fenda borbulhante da margem leste do oásis; {npc:3448} recebe o resultado na próxima parada na Encruzilhada, então siga daqui para o noroeste até {area:383}.",
		["South-east on the way back to the Crossroads: {quest:881}, a white lion, prowls the plains north of the Razormane camp.\nCareful: Savannah Huntresses roam around the lair. They respawn quickly and often join the fight alongside {quest:881}, so clear them out before you blow the horn.\nSunscale raptors here count toward the heads."] = "Ao sudeste, na volta para a Encruzilhada: {quest:881}, um leão branco, ronda as planícies ao norte do acampamento Crinavalha.\nCuidado: as Caçadoras da Savana andam em volta do covil. Elas reaparecem rápido e muitas vezes entram na luta junto com {quest:881}, então limpe a área antes de soprar a trombeta.\nOs raptores Helióscamo daqui também contam para as cabeças.",
		["South-west from {area:392} across the plains to the {area:1697}: the three nests sit together south-west of the oasis, and Sunscale Scytheclaws guard them. Each nest needs a {item:5165}: kill Sunscale raptors (most drop one) until you have three, then use a feather at each nest."] = "Para o sudoeste a partir de {area:392}, atravessando as planícies até {area:1697}: os três ninhos ficam juntos a sudoeste do oásis, e Garrafoices Helióscamo os guardam. Cada ninho precisa de uma {item:5165}: mate raptores Helióscamo (a maioria solta uma) até ter três, depois use uma pena em cada ninho.",
		["Speak to {npc:3389} again to start the attack: the Kolkar charge the bunkers just west of him in waves. Fight beside the grunts until {npc:9456} (elite, 20) arrives with two bodyguards, usually from the south, then click the banner over his body."] = "Fale de novo com {npc:3389} para começar o ataque: os Kolkar atacam os bunkers logo a oeste dele em ondas. Lute ao lado dos soldados até {npc:9456} (elite, 20) chegar com dois guarda-costas, geralmente pelo sul; depois clique no estandarte sobre o corpo dele.",
		["Still short of seven? Plainstriders are thickest on the plains north of the Crossroads, along the road north."] = "Ainda não chegou a sete? Os Pinotes são mais numerosos nas planícies ao norte da Encruzilhada, ao longo da estrada para o norte.",
		["Still short of twelve? Sunscale Lashtails and Screechers roam the plains north-east of the Crossroads, on the way back south from {quest:881}'s lair."] = "Ainda não chegou a doze? Batecaudas e Uivadores Helióscamo andam pelas planícies a nordeste da Encruzilhada, na volta para o sul, vindo da toca de {quest:881}.",
		["Sunscale Scytheclaws hunt the plains around the {area:1697}; they drop the horns. {npc:3446} takes them when the escort brings you back to {area:392}.\nSouth-east toward the coast: the stolen silver lies in a raptor nest north-west of {area:385}."] = "Garrafoices Helióscamo caçam nas planícies em volta de {area:1697}; eles deixam cair os chifres. {npc:3446} os recebe quando a escolta traz você de volta a {area:392}.\nPara o sudeste, rumo à costa: a prata roubada está num ninho de raptores a noroeste de {area:385}.",
		["Sunscale raptors here count toward the heads."] = "Os raptores Helióscamo daqui também contam para as cabeças.",
		["Sunscale raptors roam the plains north and east of the Crossroads, and about three in four drop a head: kill the ones you pass on the way. Careful: Sunscale Screechers call nearby allies within 30 yd once below 30% health."] = "Os raptores Helióscamo andam pelas planícies ao norte e a leste da Encruzilhada, e uns três em cada quatro soltam uma cabeça: vá matando os que encontrar pelo caminho. Cuidado: os Uivadores Helióscamo chamam aliados num raio de 30 metros quando caem abaixo de 30% de vida.",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue."] = "Taurens: {npc:11957} espera na colina ao sul, acima da ponte. Celonatos: {npc:272054} fica ao sul das pontes gêmeas. Depois, as tocas a leste do lago: saia da forma, clique na estátua da entrada para ganhar cinco minutos de furtividade, evite os espíritos lá dentro e pegue uma de cada relíquia; {item:280680} fica ao pé da estátua do gato branco.",
		["The Bristleback quilboar camps spread over the plains north of {area:378}, either side of the {area:458}. {npc:3432}'s wife lies at their north edge, on your way south. Leave the quilboar for now: {npc:3430} in {area:378} wants the same camps cleared. {quest:883}, a grey kodo, sometimes wanders here: his hoof starts a quest."] = "Os acampamentos dos javatuscos Costagulha se espalham pelas planícies ao norte de {area:378}, dos dois lados de {area:458}. A esposa de {npc:3432} está caída na borda norte deles, no seu caminho para o sul. Deixe os javatuscos para depois: {npc:3430}, em {area:378}, quer esses mesmos acampamentos limpos. {quest:883}, um kodo cinza, às vezes passeia por aqui: o casco dele inicia uma missão.",
		["The Grimtotem camp is just north of {npc:11857}, a short walk off the road: Ruffians and Mercenaries stand among the tents."] = "O acampamento Temível Totem fica logo ao norte de {npc:11857}, a uma curta caminhada fora da estrada: Rufiões e Mercenários ficam no meio das tendas.",
		["The Razormane camp lies east of the Crossroads. Warriors: the {object:58369} stands in the camp. Shamans: the quilboar drop the {item:5026}.\nCareful: The chest stands next to a broken wagon, guarded by a pair of Razormanes, including hunters that can pull more quilboar into the fight."] = "O acampamento Crinavalha fica a leste da Encruzilhada. Guerreiros: o {object:58369} fica no acampamento. Xamãs: os javatuscos soltam o {item:5026}.\nCuidado: o baú fica ao lado de uma carroça quebrada, guardado por dois Crinavalhas, incluindo caçadores que podem puxar mais javatuscos para a luta.",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "Os Feitores e Seguranças da Empreendimentos S.A. na mina do canto nordeste da zona deixam cair {item:5097}.",
		["The antennae vanish fifteen minutes after they drop: kill the Silithid Swarmers and Creepers at the {area:390}' mounds, just south of {npc:3387}'s thunderhawks, until you have five, then take them straight to {npc:6394} in {area:378}.\nCareful: Silithid Swarmers (level 21-22) cast {npc:4196} both in and out of combat, which brings several small adds. Silithid Creepers (level 20-21) periodically cast {npc:5781} in combat, which spawns extra adds."] = "As antenas somem quinze minutos depois de caírem: mate os Enxameadores e Rastejantes Silitídeos nos montes de {area:390}, logo ao sul dos falcotrons de {npc:3387}, até ter cinco, depois leve-as direto a {npc:6394} em {area:378}.\nCuidado: Enxameadores Silitídeos (nível 21-22) soltam {npc:4196} dentro e fora de combate, o que traz vários bichinhos. Rastejantes Silitídeos (nível 20-21) soltam {npc:5781} de tempos em tempos em combate, o que gera bichinhos extras.",
		["The next guide goes north-east across the {zone:1413} to the {area:1703} and {zone:1440}."] = "O próximo guia segue para nordeste por {zone:1413} até {area:1703} e {zone:1440}.",
		["The pirates camp on the beach south of {area:392}: the piles of complicated parts lie in the sand among them, and {npc:3467} stands at the camp's southern end."] = "Os piratas acampam na praia ao sul de {area:392}: as pilhas de peças complicadas ficam na areia entre eles, e {npc:3467} fica na ponta sul do acampamento.",
		["The pools lie just north of {npc:3389}. Walk into the water to explore them; the Laden Mushrooms for Helbrim grow around them. Kill every Kolkar you pass for bracers. {npc:3394} stands in the Kolkar camp west of the pools."] = "As poças ficam logo ao norte de {npc:3389}. Entre na água para explorá-las; os Cogumelos Carregados para Hermógenes crescem em volta delas. Mate todo Kolkar que encontrar, por causa das braçadeiras. {npc:3394} fica no acampamento Kolkar a oeste das poças.",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "A estrada sobe para o norte como {area:1076}. {quest:1483} tem uma cabana onde a estrada se divide para leste rumo a {area:461}.",
		["The tool buckets with the slugs lie around the Venture Co. drill site in the {area:382}."] = "Os baldes de ferramentas com as lesmas ficam em volta da perfuração da Empreendimentos S.A. em {area:382}.",
		["The {area:2363}"] = "Os {area:2363}",
		["The {object:172960} is the canyon under the {object:172982}."] = "O {object:172960} é o cânion sob o {object:172982}.",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177792} fica na borda norte de {area:382}, junto à torre da Empreendimentos S.A. Contém {item:15883} para {quest:30}.",
		["The {object:4141} stands at the Venture Co. research site west of the {area:382}. Close the three valves around the drill, use the console again, then take the {item:5089} from {npc:3471} beside it.\nCareful: Several guards stand within aggro range of the valves, respawn in under about 3 minutes, and run at low health to bring back help; nearby mobs also join if you use a valve while they are close."] = "{object:4141} fica no posto de pesquisa da Empreendimentos S.A. a oeste de {area:382}. Feche as três válvulas em volta da perfuratriz, use o painel de novo e pegue {item:5089} com {npc:3471}, ali do lado.\nCuidado: vários guardas ficam ao alcance das válvulas, renascem em menos de uns 3 minutos e fogem com pouca vida para chamar reforço; monstros por perto também entram na briga se você mexer numa válvula com eles ali.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:209797} (level 20 elite) needs a group of 2. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:209797} (elite nível 20) pede um grupo de 2. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["Thunder Lizards and Lightning Hides graze just across the bridge below {area:379}."] = "Lagartos Trovejantes e Pelegos de Relâmpago pastam logo depois da ponte, abaixo de {area:379}.",
		["Thunder lizards across the river"] = "Lagartos trovejantes do outro lado do rio",
		["Thunderhawk Cloudscrapers circle over the same plains south of the camp."] = "Falcotrons Raspa-nuvens voam em círculos sobre as mesmas planícies ao sul do acampamento.",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard, roams among them: his Tailspike starts a quest."] = "Cabeças-de-trovão pastam nas planícies logo ao sul de {area:378}. {quest:884}, um lagarto-trovão azul, vaga entre eles: a Ponta da Cauda dele inicia uma missão.",
		["Train your level 20 ranks in {area:1637} now: fly from {npc:3615} on the Crossroads' tower."] = "Treine agora as habilidades de nível 20 em {area:1637}: voe com {npc:3615}, na torre da Encruzilhada.",
		["Twitching Antennae"] = "Antenas Agitadas",
		["Twitching Antennae from the silithid"] = "Antenas Agitadas dos silitídeos",
		["Underwater"] = "Debaixo d'água",
		["Upstairs"] = "No andar de cima",
		["Venture Co. Loggers, all over the clear-cut"] = "Madeireiros da Empreendimentos S.A., por toda a área desmatada",
		["Warriors: take {quest:1824} from {npc:6394} now, not earlier: it runs for 30 minutes from the accept. The thunderhawks and the eggs come first, the antennae last, then straight back to {npc:6394}."] = "Guerreiros: pegue {quest:1824} com {npc:6394} agora, não antes: são 30 minutos de prazo a partir da aceitação. Os falcotrons e os ovos vêm primeiro, as antenas por último, depois direto de volta a {npc:6394}.",
		["West from the burned village to {area:2539}: {npc:12816} stands just outside it, before the village."] = "A oeste da aldeia queimada até {area:2539}: {npc:12816} fica logo fora dela, antes da vila.",
		["West from the mine to {npc:9316}'s camp, then south down the road to the Crossroads."] = "A oeste da mina até o acampamento de {npc:9316}; depois desça a estrada para o sul até a Encruzilhada.",
		["West to the {area:383}. The Witchwing harpies nest all over them; any of them can drop a talon. {quest:819} lies in their hills. Savannah Prowlers hunt the plains between {npc:3389} and the hills: take their claws on the way.\nCareful: There are 2 Witchwing Ambushers (level 17-18). They stay stealthed with Sneak while out of combat."] = "Para o oeste, até {area:383}. As harpias Asabruxa fazem ninho por toda parte; qualquer uma pode deixar cair uma garra. {quest:819} fica nas colinas delas. Predadores da Savana caçam nas planícies entre {npc:3389} e as colinas: pegue as garras deles pelo caminho.\nCuidado: há 2 Asabruxas Emboscadoras (nível 17-18). Elas ficam em Furtividade enquanto estão fora de combate.",
		["West to {npc:3389}'s watch post on the Kolkar border."] = "A oeste, até o posto de vigia de {npc:3389}, na fronteira com os Kolkar.",
		["While you are in the camp: {npc:3429}'s Water Seekers and Thornweavers in its western half, the Hunters in the middle, the supply crates at its eastern end."] = "Já que está no acampamento: os Rabdomantes e os Tecespinhos de {npc:3429} ficam na metade oeste, os Caçadores Crinavalha no meio e as caixas de suprimentos na ponta leste.",
		["Wizzlecrank drives his shredder out of the camp: stay with him and kill whatever attacks him. {npc:3442} takes it in {area:392}.\nCareful: The route leads west and climbs a ramp. Once you reach the top, two Venture Company mobs ambush you."] = "Manivela tira o retalhador do acampamento: fique com ele e mate o que atacar. Quem recebe é {npc:3442}, em {area:392}.\nCuidado: o caminho vai para oeste e sobe uma rampa. Lá em cima, dois capangas da Empreendimentos S.A. emboscam você.",
		["You arrive from {area:379}. {npc:3489} and {npc:3338} stand by the inn, Helbrim and {npc:3464} by the north gate; {npc:3615}, {npc:3429} and {npc:3449} on the tower platform."] = "Você chega vindo de {area:379}. {npc:3489} e {npc:3338} ficam perto da estalagem, Helbrim e {npc:3464} no portão norte; {npc:3615}, {npc:3429} e {npc:3449} na plataforma da torre.",
		["Zhevra Runners graze along the road east toward {area:392}: take their hooves on the way out."] = "Zevras Corredoras pastam ao longo da estrada a leste, rumo a {area:392}: pegue os cascos delas na saída.",
		["the Crossroads"] = "a Encruzilhada",
		["{area:1076}: kill these as you meet them"] = "{area:1076}: vá matando estes pelo caminho",
		["{area:1697}: kill these as you meet them"] = "{area:1697}: vá matando estes pelo caminho",
		["{area:1898} cultists"] = "Sectários de {area:1898}",
		["{area:380} is your base for this guide. Everyone you need stands within a few steps of the inn: {npc:3338} by the inn, Helbrim and {npc:3464} by the north gate, then up the tower to {npc:3615}, the wind rider master, {npc:3429} and {npc:3449}, and {npc:3448} at the south gate on the way out."] = "{area:380} é a sua base neste guia. Todo mundo de que você precisa fica a poucos passos da estalagem: {npc:3338} junto à estalagem, Helbrim e {npc:3464} no portão norte, depois a torre, para {npc:3615}, o mestre de mantícoras, {npc:3429} e {npc:3449}, e {npc:3448} no portão sul, na saída.",
		["{area:385}, on the coast just south of the pirate camp. The Theramore Marines and Preservers (15-16) drop the medals; {npc:3393} (20) and the two cannoneers (19) stand in the keep and on its walls, and they are why the hold waits until now.\nCareful: Each named target is linked to a healer and guards, and Fairmount has three extra marines with her. Killing the healer first makes the fight easier."] = "{area:385}, na costa, logo ao sul do acampamento dos piratas. Os Fuzileiros e as Preservadoras de Theramore (15-16) deixam cair as medalhas; {npc:3393} (20) e os dois canhoneiros (19) ficam na fortaleza e nas muralhas, e é por isso que a fortaleza espera até agora.\nCuidado: cada alvo nomeado está ligado a um curandeiro e a guardas, e Fairmount tem três fuzileiros extras com ela. Matar o curandeiro primeiro deixa a luta mais fácil.",
		["{area:385}: kill these as you meet them"] = "{area:385}: vá matando estes pelo caminho",
		["{area:392} flight master"] = "Mestre de voo de {area:392}",
		["{item:10338}, from any zhevra; Zhevra Chargers graze around the tree"] = "{item:10338}, de qualquer zevra; Corcéis Zevra pastam em volta da árvore",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, de um {object:177785} no lago",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "{item:2449} de {npc:3490}; herbalistas colhem nas planícies",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798}, em {area:2361}, leva druidas voando até lá",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}, no {area:2362}",
		["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart."] = "{npc:11802} fica no andar de cima do prédio dele em {area:2361}: suba por dentro, a seta não diferencia os andares.",
		["{npc:11802} stands upstairs in his building in {area:2361}: go up inside, the arrow cannot tell the floors apart. The Shrine Baubles lie on the bed of {area:656} and fade within minutes: swim one straight to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}. {quest:28} runs on a timer: no teleport or Hearthstone until {npc:11799} has it."] = "{npc:11802} fica no andar de cima do prédio dele em {area:2361}: suba por dentro, a seta não distingue os andares. Os Adornos de Altar ficam no fundo de {area:656} e somem em poucos minutos: nade com um direto até {area:2362}, na margem noroeste, use-o lá e fale com {npc:11799}. {quest:28} tem cronômetro: nada de teleporte nem de Pedra de Regresso até {npc:11799} ficar com ele.",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}: as boas-vindas de {npc:3033}",
		["{npc:11856}, inside {npc:11858}'s hut"] = "{npc:11856}, dentro da cabana de {npc:11858}",
		["{npc:11857}: keep it, {npc:11864} at {area:460} in the {zone:1413} & Stonetalon guide"] = "{npc:11857}: guarde, {npc:11864} em {area:460}, no guia de {zone:1413} e Torres de Pedra",
		["{npc:11858} waits up the {area:1076}"] = "{npc:11858} espera no alto de {area:1076}",
		["{npc:12296}: use the {item:15826} on them; they roam the plains all around the Crossroads"] = "{npc:12296}: use o {item:15826} neles; eles andam pelas planícies em volta da Encruzilhada",
		["{npc:12816}: the spiders along the {area:1076}"] = "{npc:12816}: as aranhas ao longo de {area:1076}",
		["{npc:246344} teaches Paladins in {area:1638}. You have no flight path there yet: fly to {area:378}, head west through {zone:1412} and up a lift, and take the flight path from {npc:2995} on the central rise."] = "{npc:246344} ensina Paladinos em {area:1638}. Você ainda não tem a rota de voo de lá: voe para {area:378}, siga para oeste por {zone:1412}, suba um elevador e pegue a rota de voo com {npc:2995} no platô central.",
		["{npc:262119} and his marines hold the wrecked caravan south of {npc:261366}. The marines are linked: pulling one calls the rest. Pull from the edge and run; they leash short, so you can thin the camp one at a time before tackling the Corporal."] = "{npc:262119} e os fuzileiros dele ocupam a caravana destruída ao sul de {npc:261366}. Os fuzileiros andam juntos: puxou um, vêm todos. Puxe pela borda e corra; eles desistem logo, então dá para ir esvaziando o acampamento um por um antes de encarar o Cabo.",
		["{npc:3338} by the inn first, then the innkeeper, Helbrim by the north gate, {npc:3429} and {npc:3449} on the tower platform, {npc:3432} by the inn, and {npc:3448} at the south gate on the way out."] = "{npc:3338} junto à estalagem primeiro, depois o estalajadeiro, Hermógenes junto ao portão norte, {npc:3429} e {npc:3449} na plataforma da torre, {npc:3432} junto à estalagem e {npc:3448} no portão sul, na saída.",
		["{npc:3338}: the raptor nests south of the Crossroads"] = "{npc:3338}: os ninhos de raptores ao sul da Encruzilhada",
		["{npc:3354} is in the {object:172958}, {npc:5892} in the {object:172957}."] = "{npc:3354} fica em {object:172958}, {npc:5892} em {object:172957}.",
		["{npc:3389}: {npc:3395} walks with the Kolkar at the {area:388}, later"] = "{npc:3389}: {npc:3395} anda com os Kolkar em {area:388}, mais tarde",
		["{npc:3390}: {quest:1358}, from Zinge"] = "{npc:3390}: {quest:1358}, com Zilda",
		["{npc:3391} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "{npc:3391} fica no andar de cima do prédio dele: suba por dentro, a seta não diferencia os andares.",
		["{npc:3391}, upstairs"] = "{npc:3391}, no andar de cima",
		["{npc:3391}: the crates lie at the south end of the beach camp, on the walk to {area:385} at 18"] = "{npc:3391}: as caixas ficam na ponta sul do acampamento da praia, no caminho para {area:385}, no nível 18",
		["{npc:3395} walks among the Kolkar at the {area:388} south-east of the Crossroads. Oasis Snapjaws crawl in the water around it: their shells are for {npc:3448}."] = "{npc:3395} anda entre os Kolkar em {area:388}, a sudeste da Encruzilhada. Mordeliscas do Oásis rastejam na água em volta dele: as carapaças delas são para {npc:3448}.",
		["{npc:3396} leads the Kolkar on the west shore of {area:387}, south of {npc:3389}. He walks that shore, from about 46,36 in the north to 46,42 in the south: if he isn't at the arrow, follow the shore until you meet him. Hand his head to {npc:3389} on your last Crossroads stop."] = "{npc:3396} lidera os Kolkar na margem oeste de {area:387}, ao sul de {npc:3389}. Ele anda por essa margem, de cerca de 46,36 no norte a 46,42 no sul: se ele não estiver na seta, siga a margem até encontrá-lo. Entregue a cabeça dele a {npc:3389} na sua última parada na Encruzilhada.",
		["{npc:3428}: the eggs are in the {area:390}, south of {area:378}, after the {zone:1454} trip"] = "{npc:3428}: os ovos ficam em {area:390}, ao sul de {area:378}, depois da ida a {zone:1454}",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, no alto da torre",
		["{npc:3429}, on the tower, from level 17. Keep it: Kadrak at the {area:1703}, next guide"] = "{npc:3429}, na torre, a partir do nível 17. Guarde: Kadrak em {area:1703}, no próximo guia",
		["{npc:3430}, in the cage"] = "{npc:3430}, na jaula",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "{npc:3432} oferece {quest:95774} depois que {quest:4921} for entregue",
		["{npc:3432}: his wife lies at the north edge of the Bristleback camps, later"] = "{npc:3432}: a esposa dele fica na borda norte dos acampamentos Costagulha, mais adiante",
		["{npc:3439} stands inside the Venture Co. camp in the {area:382}; {npc:3445} carries the key."] = "{npc:3439} fica dentro do acampamento da Empreendimentos S.A. em {area:382}; {npc:3445} carrega a chave.",
		["{npc:3442} in {area:392}: on the next {area:392} stop"] = "{npc:3442} em {area:392}: na próxima parada em {area:392}",
		["{npc:3442}: keep it, {quest:1483} is on the {area:1076} in Stonetalon, at the end of this guide"] = "{npc:3442}: guarde, {quest:1483} fica em {area:1076}, em Torres de Pedra, no fim deste guia",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}: o console fica em {area:382}, depois",
		["{npc:3442}: {npc:9316} stands on the road north of the Crossroads, on the way to the {area:382}"] = "{npc:3442}: {npc:9316} fica na estrada ao norte da Encruzilhada, a caminho de {area:382}",
		["{npc:3446}, beside the {object:3972} poster"] = "{npc:3446}, ao lado do cartaz {object:3972}",
		["{npc:3446}, beside the {object:3972} poster: take it now if he did not offer it on the first {area:392} stop"] = "{npc:3446}, junto ao cartaz {object:3972}: pegue agora, se ele não a ofereceu na primeira parada em {area:392}",
		["{npc:3448}: the Oasis Snapjaws at the {area:388}, with {npc:3395}"] = "{npc:3448}: as Mordeliscas do Oásis em {area:388}, com {npc:3395}",
		["{npc:3449}, on the tower: {quest:876} leads the harpies in the {area:383}"] = "{npc:3449}, na torre: {quest:876} lidera as harpias em {area:383}",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}: as harpias vêm depois, em {area:383}",
		["{npc:3464}, by the Crossroads' north gate"] = "{npc:3464}, junto ao portão norte da Encruzilhada",
		["{npc:3464}: the {quest:3281}, in a raptor nest north-west of {area:385}"] = "{npc:3464}: {quest:3281}, num ninho de raptores a noroeste de {area:385}",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465} está acorrentado dentro do forte. Fale com ele para iniciar a escolta e fique perto: soldados de Theramore atacam na saída. Ele leva você de volta a {area:392}.",
		["{npc:3615}, on the tower"] = "{npc:3615}, na torre",
		["{npc:4049} and {npc:11857} share the camp on the road west to Stonetalon."] = "{npc:4049} e {npc:11857} dividem o acampamento na estrada que vai para o oeste, rumo a Torres de Pedra.",
		["{npc:4049}: the Venture loggers at {area:461}"] = "{npc:4049}: os madeireiros da Empreendimentos S.A. em {area:461}",
		["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "{npc:4197} vive em {area:2539}, a aldeia troll logo na entrada da Cordilheira das Torres de Pedra, no fim da estrada a oeste de {npc:3389}.",
		["{npc:4201}, inside"] = "{npc:4201}, lá dentro",
		["{npc:4201}: for {npc:3442}, beside {area:392}'s flight master at the end of the {zone:1413} & Stonetalon guide"] = "{npc:4201}: para {npc:3442}, ao lado do mestre de voo de {area:392}, no fim do guia de {zone:1413} e Torres de Pedra",
		["{npc:4276}'s defence is hard alone at this level: grouping up is encouraged, look for people to do it with. Skip it if you are alone.\n{npc:4276} mines at the bottom of the {area:2160} on the east side of the crag, past its kobolds (levels 19-23). Talk to him, then keep him alive for five minutes while he mines: a dozen or more kobolds come at him in waves, melee fighters first, then casters, and the mine's own kobolds respawn into the fight. If he dies, the quest fails."] = "A defesa de {npc:4276} é difícil sozinho neste nível: recomenda-se formar grupo, procure gente para fazer com você. Pule se estiver sozinho.\n{npc:4276} minera no fundo de {area:2160}, no lado leste do penhasco, depois dos kobolds de lá (níveis 19-23). Fale com ele e depois mantenha-o vivo por cinco minutos enquanto ele minera: uma dúzia ou mais de kobolds vem para cima dele em ondas, primeiro os combatentes corpo a corpo, depois os conjuradores, e os kobolds da própria mina renascem no meio da luta. Se ele morrer, a missão falha.",
		["{npc:4276}, below ground"] = "{npc:4276}, no subterrâneo",
		["{npc:5878} camps beside the road east of the Crossroads."] = "{npc:5878} acampa ao lado da estrada a leste da Encruzilhada.",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878} acampa ao lado da estrada para o leste, rumo a {area:392}.",
		["{npc:5878} camps beside the road from the Crossroads to {area:392}. The {object:58369} sits in the south of the Razormane camp just north of him."] = "{npc:5878} acampa junto à estrada da Encruzilhada para {area:392}. O {object:58369} fica no sul do acampamento Crinavalha, logo ao norte dele.",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}: fill the {item:7766} at the watering hole below it."] = "A cabana de {npc:5899} fica na crista acima do bebedouro dos javatuscos, ao sul de {area:378}: encha o {item:7766} no bebedouro abaixo dela.",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900} faz {item:6636} com o piche e o bornal. Use-o junto ao braseiro ao lado dele para revelar o {npc:5893}, mate-o pela {item:6655} e depois coloque a brasa no braseiro.",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901} espera na colina ao sul de {area:392}, no caminho para o norte.",
		["{npc:5907} stands on the ridge north of the Razormane camp."] = "{npc:5907} fica na serra ao norte do acampamento Crinavalha.",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}: {npc:2523}, seu {item:5176} e o {item:263412}",
		["{npc:5909}, a few steps away"] = "{npc:5909}, a poucos passos",
		["{npc:6018} stands in the {object:172961} on the city's west side."] = "{npc:6018} fica no {object:172961}, no lado oeste da cidade.",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018} fica em {object:172961}, no lado oeste da cidade.",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018}: {npc:4606} em {zone:1458}, daqui a dois guias",
		["{npc:6394}, inside"] = "{npc:6394}, lá dentro",
		["{object:3972} poster"] = "cartaz {object:3972}",
		["{quest:1483}, inside"] = "{quest:1483}, lá dentro",
		["{quest:1492}, on the dock"] = "{quest:1492}, no cais",
		["{quest:1492}: the emerald comes from the {area:381}, later"] = "{quest:1492}: a esmeralda vem de {area:381}, mais tarde",
		["{quest:2458}: {npc:7233}, by the {area:382} on the next guide's walk north"] = "{quest:2458}: {npc:7233}, junto a {area:382}, na caminhada para o norte do próximo guia",
		["{quest:30}, carried: one half pendant in the {area:382} in this guide, the other underwater off Silverpine on the way to {area:287} at 21; the pendant is handed in after {area:287}"] = "{quest:30}, com você: uma metade do pingente no {area:382} deste guia, a outra debaixo d'água, na costa de Pinhaprata, a caminho de {area:287} no nível 21; o pingente é entregue depois de {area:287}",
		["{quest:3923} stands by the {object:172958}'s water, east of the Drag."] = "{quest:3923} fica junto à água de {object:172958}, a leste do Drag.",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127}: {area:384}, próximo guia",
		["{quest:865}, if still open: Sunscale Scytheclaws prowl among the lions"] = "{quest:865}, se ainda estiver aberta: Garrafoices Helióscamo rondam no meio dos leões",
		["{quest:882}, a big Sunscale raptor, only comes to a fresh kill: loot a {item:10338} from a zhevra, then use it at the {object:147538} north-west of {area:392}, north of the road to the Crossroads, and be ready when he arrives."] = "{quest:882}, um grande raptor Helióscamo, só aparece para uma caça fresca: saqueie uma {item:10338} de uma zevra, use-a em {object:147538}, a noroeste de {area:392}, ao norte da estrada para a Encruzilhada, e fique pronto para quando ele chegar.",
		["{zone:1413}: kill these as you meet them"] = "{zone:1413}: vá matando estes pelo caminho",
		["{zone:1454} class quests"] = "Missões de classe em {zone:1454}",
		["{zone:1454} flight master"] = "Mestre de voo de {zone:1454}",
		["{zone:1456} flight master"] = "Mestre de voo de {zone:1456}",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["Back down the road past the zeppelin towers and east to {npc:1495}'s camp: {npc:267009} stands beside her."] = "De volta pela estrada, passando as torres do zepelim, e a leste até o acampamento de {npc:1495}: {npc:267009} fica ao lado dela.",
		["Back north-west up the road to the {area:228}."] = "De volta ao noroeste pela estrada, até {area:228}.",
		["Class trainer"] = "Instrutor de classe",
		["Follow the lake shore south from the murlocs: the {object:1593} lies at the ferry landing, on the way to {area:233}."] = "Siga a margem do lago para o sul, saindo dos murlocs: {object:1593} fica no embarcadouro da balsa, a caminho de {area:233}.",
		["Follow the lake shore south-east from the Yoricks' house: the Vile Fin Shredders and Tidehunters along it drop the murloc eyes."] = "Siga a margem do lago para o sudeste a partir da casa dos Yorick: os Retalhadores Pinavil e os Caçamarés que andam por ela soltam os olhos de murloc.",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "Siga a estrada para nordeste até a casa dos Yorick no {area:238}.",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood."] = "Siga a estrada para o sul. O {object:1627} fica ao lado dela, ao norte de Lenhardente.",
		["Inside"] = "Lá dentro",
		["Keep south along the shore from the ferry to {area:233}. Protectors guard the outskirts and Mages the town; both drop pendants. Stay out of the middle, where {npc:2120} stands."] = "Continue ao sul pela margem, saindo da balsa, até {area:233}. Protetoras guardam a periferia e Magos a cidade; ambos deixam cair pingentes. Fique longe do meio, onde fica {npc:2120}.",
		["Mottled Worgs"] = "Worgs Mosqueados",
		["Mottled Worgs prowl the hills around the house."] = "Worgs Mosqueados rondam as colinas em volta da casa.",
		["North again to the Yoricks' house."] = "De novo ao norte até a casa dos Yorick.",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field."] = "Ao norte do {area:228}. {npc:1983} assombra o {area:240}: mate-o e depois atravesse o campo.",
		["On the road north, the farmhouse at {area:227}: go upstairs, the {object:1571} lie on the floor in the back room. Looting them brings a {npc:1770}."] = "Na estrada para o norte, a casa da fazenda em {area:227}: suba, os {object:1571} estão no chão do quarto dos fundos. Saquear os livros traz um {npc:1770}.",
		["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "Fale com {npc:10181}, no {object:36126}: {quest:93739}",
		["Speak with {npc:10540}, in Grommash Hold"] = "Fale com {npc:10540}, na Fortaleza Grommash",
		["Speak with {npc:3230}, in Grommash Hold"] = "Fale com {npc:3230}, na Fortaleza Grommash",
		["Take the road north toward {zone:1420}: the Yoricks' house at {area:238} is on the way. {quest:425} lurks a short walk west of it."] = "Pegue a estrada para o norte rumo a {zone:1420}: a casa dos Yorick, em {area:238}, fica no caminho. {quest:425} espreita a uma curta caminhada a oeste dela.",
		["Talk to {npc:10181}"] = "Fale com {npc:10181}",
		["Talk to {npc:10540}"] = "Fale com {npc:10540}",
		["Talk to {npc:3230}"] = "Fale com {npc:3230}",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "As taboas e o capim-lança crescem junto à água no {object:172958}, a leste do Drag.",
		["The cultists camp a short walk south-east of {npc:267009}. Dark Neophytes and Dark Enforcers drop the Necrotic Crystal Fragments; more fragments, black crystals, lie on the ground among the tents."] = "Os sectários acampam a uma caminhada curta a sudeste de {npc:267009}. Os Neófitos Sombrios e os Impositores Sombrios deixam cair os Fragmentos de Cristal Necrótico; há mais fragmentos, cristais negros, no chão entre as tendas.",
		["The {object:172960} is the canyon under the {object:172982}; {quest:829} stands at its far end."] = "O {object:172960} é o cânion sob o {object:172982}; {quest:829} fica no fundo dele.",
		["Train while you are in the city: Druids and Paladins have no trainer here."] = "Treine enquanto estiver na cidade: Druidas e Paladinos não têm instrutor aqui.",
		["Vile Fin murlocs"] = "Murlocs Pinavil",
		["Walk in by the main gate. {npc:3310}, the wind rider master, stands on the tower in the {object:172982}; {npc:268701} by the bank below it."] = "Entre pelo portão principal. {npc:3310}, o mestre de mantícoras, fica na torre em {object:172982}; {npc:268701} junto ao banco, logo abaixo.",
		["Walk in through the main gate. {npc:268701} stands in the {object:172982}."] = "Entre pelo portão principal. {npc:268701} fica em {object:172982}.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Já que está aqui: aprenda Cajados com {npc:2704} ({object:172958}, 10 pratas); a arma corpo a corpo do Caçador vale pelos atributos, e as de duas mãos são as que mais trazem.",
		["While you're here: learn Staves from {npc:2704} ({object:172958}, 10 silver); a staff carries more spell stats than a one-hander while you level."] = "Já que está aqui: aprenda Cajados com {npc:2704} ({object:172958}, 10 pratas); enquanto você sobe de nível, um cajado traz mais atributos de feitiço que uma arma de uma mão.",
		["While you're here: learn {spell:197} from {npc:11868} ({object:172958}, 10 silver); two-handers level a Paladin fastest."] = "Já que está aqui: aprenda {spell:197} com {npc:11868} ({object:172958}, 10 pratas); arma de duas mãos é o jeito mais rápido de upar Paladino.",
		["While you're here: learn {spell:197} from {npc:11868} ({object:172958}, 10 silver); two-handers level a Warrior fastest."] = "Já que está aqui: aprenda {spell:197} com {npc:11868} ({object:172958}, 10 pratas); arma de duas mãos é o jeito mais rápido de upar Guerreiro.",
		["Zeppelin to {zone:1454}"] = "Zepelim para {zone:1454}",
		["Zeppelin to {zone:1458}"] = "Zepelim para {zone:1458}",
		["{area:159} is a short walk north up the road from the zeppelin towers: {npc:1738} stands by the road into town, {npc:1518} in the apothecary's house on the west side of the square."] = "{area:159} fica a uma caminhada curta ao norte pela estrada, saindo das torres do zepelim: {npc:1738} fica junto à estrada de entrada da cidade e {npc:1518}, na casa do boticário, no lado oeste da praça.",
		["{area:159} is a short walk north up the road from the zeppelin towers; {npc:1499} is in the town hall."] = "{area:159} fica a uma curta caminhada para o norte pela estrada, saindo das torres do zepelim; {npc:1499} está na prefeitura.",
		["{area:227} farmhouse"] = "Casa da fazenda de {area:227}",
		["{area:228} is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; {npc:2226}, the bat handler, is just east of it."] = "{area:228} é a cidade-cripta dos Renegados no meio da floresta. Todos de quem você precisa ficam em volta da entrada da cripta; {npc:2226}, o adestrador de morcegos, fica logo a leste dela.",
		["{area:233} comes later, down the lake shore"] = "{area:233} vem depois, descendo pela margem do lago",
		["{npc:10181} holds court in the {object:36126}."] = "{npc:10181} despacha em {object:36126}.",
		["{npc:11044}, in the Apothecarium"] = "{npc:11044}, no Apothecarium",
		["{npc:11046}, the alchemy trainer, stands next door to {npc:3348}."] = "{npc:11046}, o instrutor de alquimia, fica ao lado de {npc:3348}.",
		["{npc:11046}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11046}: Acampamento 101, da fogueira de Brakk em {zone:1411}",
		["{npc:11066}, the enchanting trainer, works in the Drag."] = "{npc:11066}, o instrutor de encantamento, trabalha no Drag.",
		["{npc:11066}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11066}: Acampamento 101, da fogueira de Brakk em {zone:1411}",
		["{npc:1499} in {area:159}, on the way to the zeppelin at the end"] = "{npc:1499} em {area:159}, a caminho do zepelim no fim",
		["{npc:1518}, inside"] = "{npc:1518}, lá dentro",
		["{npc:1937}: Zinge in the {zone:1458}, on the way to the zeppelin at the end"] = "{npc:1937}: Zilda em {zone:1458}, no caminho para o zepelim, no fim",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937}: para o Quintino, na estrada ao norte, no final",
		["{npc:1938}, just north of Allister"] = "{npc:1938}, logo ao norte de Allister",
		["{npc:1938}: his books lie in the {area:227} farmhouse, on the walk north"] = "{npc:1938}: os livros dele ficam na casa da fazenda de {area:227}, na caminhada para o norte",
		["{npc:1951}, inside"] = "{npc:1951}, lá dentro",
		["{npc:1952}, below ground"] = "{npc:1952}, no subterrâneo",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978} espera a nordeste da casa. Escolte-o de volta até {npc:1950}; worgs atacam no caminho.",
		["{npc:1978}, inside"] = "{npc:1978}, lá dentro",
		["{npc:2226}: {npc:4556} in the {zone:1458}, at the end of this guide; no need to buy the flight"] = "{npc:2226}: {npc:4556} em {zone:1458}, no fim deste guia; não precisa comprar o voo",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} treina Paladinos em {area:159}, a uma curta caminhada para o norte pela estrada a partir das torres de zepelim. Volte pela mesma estrada para Pinhaprata.",
		["{npc:260093}, the {area:1497}'s paladin trainer"] = "{npc:260093}, o treinador de paladinos da {area:1497}",
		["{npc:268684} and {npc:268682} sit behind Grommash Hold in the {object:172957}; the Smooth Boulders lie around them."] = "{npc:268684} e {npc:268682} ficam atrás da Fortaleza Grommash, em {object:172957}; os Pedregulhos Lisos estão em volta deles.",
		["{npc:268684} and {npc:268682} sit behind Grommash Hold in the {object:172957}; the Smooth Boulders lie around them. Train while you are in the city (Druids and Paladins have no trainer here). The next guide walks from here to {area:379} and the Crossroads."] = "{npc:268684} e {npc:268682} ficam atrás da Fortaleza Grommash, em {object:172957}; os Pedregulhos Lisos estão em volta deles. Treine enquanto estiver na cidade (Druidas e Paladinos não têm instrutor aqui). O próximo guia vai daqui até {area:379} e a Encruzilhada.",
		["{npc:2855}, the tailoring trainer, is in the {object:172958}."] = "{npc:2855}, o instrutor de alfaiataria, fica em {object:172958}.",
		["{npc:2855}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:2855}: Acampamento 101, da fogueira de Brakk em {zone:1411}",
		["{npc:3230}, in Grommash Hold"] = "{npc:3230}, na Fortaleza Grommash",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348} e {npc:3347} cuidam da loja de alquimia no Drag; {npc:11046} fica ao lado.",
		["{npc:3365}, the leatherworking trainer, works in the {object:172958}."] = "{npc:3365}, o instrutor de couraria, trabalha em {object:172958}.",
		["{npc:3365}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3365}: Acampamento 101, da fogueira de Brakk em {zone:1411}",
		["{npc:3404}, the herbalism trainer, keeps her shop in the Drag."] = "{npc:3404}, a instrutora de herborismo, mantém sua loja no Drag.",
		["{npc:3404}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3404}: Acampamento 101, da fogueira de Brakk em {zone:1411}",
		["{npc:4047}: {npc:4049}, on the road into Stonetalon in the next guide"] = "{npc:4047}: {npc:4049}, na estrada que entra em Torres de Pedra, no próximo guia",
		["{npc:4551}, the bat handler"] = "{npc:4551}, o adestrador de morcegos",
		["{npc:4551}: keep {item:16210}, Podrig takes it on the next stop at the {area:228}, at 22"] = "{npc:4551}: guarde {item:16210}, Podrig fica com ela na próxima parada em {area:228}, no nível 22",
		["{npc:4556}, the weapon merchant beside the bat handler"] = "{npc:4556}, o mercador de armas ao lado do adestrador de morcegos",
		["{npc:4586}, the engineering trainer, works in the {zone:1458}."] = "{npc:4586}, o instrutor de engenharia, trabalha em {zone:1458}.",
		["{npc:4586}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4586}: Acampamento 101, da fogueira de {npc:265812} em Tirisfal",
		["{npc:4598}, the mining trainer, works in the {zone:1458}."] = "{npc:4598}, o instrutor de mineração, trabalha em {zone:1458}.",
		["{npc:4598}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4598}: Acampamento 101, da fogueira de {npc:265812} em Tirisfal",
		["{npc:4605}, the blacksmithing trainer, works in the {zone:1458}."] = "{npc:4605}, o instrutor de ferraria, trabalha em {zone:1458}.",
		["{npc:4605}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4605}: Acampamento 101, da fogueira de {npc:265812} em Tirisfal",
		["{npc:4949} stands in Grommash Hold. He offers {quest:98024} and {quest:93739} once {quest:95350} is handed in."] = "{npc:4949} fica na Fortaleza Grommash. Ele oferece {quest:98024} e {quest:93739} depois que você entregar {quest:95350}.",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}, dentro da Fortaleza Grommash",
		["{npc:4949}: keep it, Thork at the Crossroads in the {zone:1413} guide"] = "{npc:4949}: guarde, Thork na Encruzilhada, no guia de {zone:1413}",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}: {quest:93739}, um passeio pelos líderes da Horda",
		["{npc:5204}, in the Apothecarium"] = "{npc:5204}, no Apothecarium",
		["{npc:5204}: Helbrim at the Crossroads, in the next guide"] = "{npc:5204}: Hermógenes na Encruzilhada, no próximo guia",
		["{npc:7088}, the skinning trainer, stands in the {object:172958}."] = "{npc:7088}, o instrutor de esfolamento, fica em {object:172958}.",
		["{npc:7088}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:7088}: Acampamento 101, da fogueira de Brakk em {zone:1411}",
		["{object:1571}; upstairs"] = "{object:1571}; no andar de cima",
		["{object:1661} lies under the {area:153}, beside the zeppelin towers. {npc:2050} stands at the inn by the way down; {npc:7683} on the way down to the Apothecarium, where {npc:11044} and {npc:5204} stand beside {npc:2055}."] = "{object:1661} fica sob {area:153}, ao lado das torres dos zepelins. {npc:2050} fica na estalagem, junto à descida; {npc:7683} na descida para o Apothecarium, onde {npc:11044} e {npc:5204} ficam ao lado de {npc:2055}.",
		["{object:173016} is a few steps north."] = "{object:173016} fica a poucos passos ao norte.",
		["{quest:264} is handed in at {object:24776}, a grave a few steps south of the crypt entrance, not to a person."] = "{quest:264} é entregue em {object:24776}, um túmulo a poucos passos ao sul da entrada da cripta, e não a uma pessoa.",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["A few steps east of {npc:14242}'s tree, a small camp: two Encroaching Soldiers and the {npc:268623} for Logmar. The {npc:268623} is elite: grouping up is advised."] = "A poucos passos a leste da árvore de {npc:14242}, um acampamento pequeno: dois Soldados Invasores e o {npc:268623} de Logmar. O {npc:268623} é elite: recomenda-se formar grupo.",
		["Bael'dun fortress"] = "Fortaleza de Bael'dun",
		["Crossroads flight master"] = "Mestre de voo da Encruzilhada",
		["East along the road from {area:2539} to {npc:4049}'s camp, on the way to {area:378}."] = "Para o leste pela estrada, de {area:2539} até o acampamento de {npc:4049}, no caminho para {area:378}.",
		["Fly to Crossroads"] = "Voe para a Encruzilhada",
		["Fly to the Crossroads from the wind rider master: {npc:2995} on {zone:1456}'s central rise."] = "Voe para a Encruzilhada com o mestre de mantícoras: {npc:2995}, no platô central de {zone:1456}.",
		["Fly to {area:1638}"] = "Voe para {area:1638}",
		["Fly to {area:1638} first: two of its elders give quests worked on this guide's and the next guide's walks."] = "Voe primeiro para {area:1638}: dois de seus anciãos dão missões feitas no percurso deste guia e do próximo.",
		["Fly to {area:378}"] = "Voe para {area:378}",
		["Fly to {area:392}"] = "Voe para {area:392}",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "Siga a estrada para o norte rumo a {area:467}. Ginetes Galhados pastam pelo caminho; as Feras de Seiva, os Corredores do Crepúsculo e os Dragões Encantados vagam pela mata abaixo do pico, e os druidas cenarianos ocupam o bosque de lá.",
		["Follow the road west past Regthar's bunkers and {npc:4049}'s camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "Siga a estrada para oeste, passando pelos bunkers de Regthar e pelo acampamento de {npc:4049}, até Torres de Pedra: {npc:3995} espera no subterrâneo em {area:2539}, ao pé de {area:1076}.",
		["Follow the road west past Regthar's bunkers: {npc:4049} camps beside it at the edge of Stonetalon."] = "Siga a estrada para o oeste, passando pelos bunkers de Regthar: {npc:4049} acampa ao lado dela, na entrada da Cordilheira das Torres de Pedra.",
		["From {area:2539} follow the road east to {npc:4049}'s camp, then south-east across the plains to {area:378}."] = "De {area:2539}, siga a estrada para leste até o acampamento de {npc:4049}, depois para sudeste pelas planícies até {area:378}.",
		["From {area:378} follow the road west through the gate into {zone:1412}, then north past {area:222} to {zone:1456}; a lift at the foot of the bluffs takes you up."] = "De {area:378}, siga a estrada para o oeste pelo portão até {zone:1412}, depois para o norte passando por {area:222} até {zone:1456}; um elevador ao pé dos penhascos leva você para cima.",
		["Gaea Dirt Mounds"] = "Montes de Terra de Gaia",
		["Gaea Seeds"] = "Sementes de Gaia",
		["Head back down the {area:1076} to {area:2539}."] = "Desça de volta por {area:1076} até {area:2539}.",
		["On the way back east to {npc:3341}: Hecklefang Stalkers and {npc:3238} lizards roam the plain between the ridge and his camp."] = "No caminho de volta para o leste, até {npc:3341}: Espreitadores Presavaia e lagartos {npc:3238} andam pela planície entre a serra e o acampamento dele.",
		["South of Gann, the Bael'dun dwarves dig at {area:359}. Excavators and Foremen work the pit; {npc:3392} (26) carries the journal: pull him alone.\nCareful: Excavators (level 21-22) and Foremen (level 22-23) run off for help once they fall to 15% health, so more dwarves can join the fight."] = "Ao sul de Gann, os anões de Bael'dun escavam em {area:359}. Escavadores e Encarregados trabalham no buraco; {npc:3392} (26) está com o diário: puxe-o sozinho.\nCuidado: Escavadores (nível 21-22) e Encarregados (nível 22-23) saem correndo atrás de ajuda quando caem para 15% de vida, então mais anões podem entrar na briga.",
		["South-west of Bael Modan, {npc:12576} waits at the top of the {area:1718}."] = "A sudoeste de Bael Modan, {npc:12576} espera no alto de {area:1718}.",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "A sudoeste da Rocha do Sol fica o {area:465}, queimado. Plante as Sementes de Gaia nos montes de terra no fundo do vale; os elementais de fogo deixam cair {item:16312}. Harpias e Emboscadoras Furissangue fazem ninho no lado norte, Matadoras e Plumerrantes ao sul.",
		["The Bael'dun Soldiers, Riflemen and Officers guard the fortress on the east side of the dig; all three items drop from them.\nCareful: Riflemen (level 24-25) Shoot from 5-30 yd, so nearby ones can join a fight from range."] = "Os Soldados, Carabineiros e Oficiais de Bael'dun guardam a fortaleza no lado leste da escavação; os três itens caem deles.\nCuidado: os Carabineiros (nível 24-25) atiram de 5 a 30 metros, então os que estiverem perto podem entrar na briga à distância.",
		["The Gaea Seeds lie in the grass around the southern shore of {area:464}, north of Sun Rock.\nCareful: Pridewings around the lake can aggro as a linked group."] = "As Sementes de Gaia ficam na grama em volta da margem sul de {area:464}, ao norte de Rocha do Sol.\nCuidado: as Asaltivas em volta do lago podem vir em bando.",
		["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "A máquina voadora dos anões fica na plataforma dentro do sítio de escavação. Use nela {item:5021} que {npc:3341} deu a você.",
		["The flying machine"] = "A máquina voadora",
		["The road west past {npc:4049}'s camp"] = "A estrada para o oeste, passando pelo acampamento de {npc:4049}",
		["The {area:1718}"] = "{area:1718}",
		["The {object:667362} grows on the bottom of {area:464}, off the same southern shore: dive to the plants and the Dried Mirkweed Piles; both give pods. Watch your breath."] = "{object:667362} cresce no fundo de {area:464}, ao largo da mesma margem sul: mergulhe até as plantas e as Pilhas de Lodoerva Seca; ambas dão vagens. Cuidado com o fôlego.",
		["To {zone:1456}"] = "Para {zone:1456}",
		["Up the {area:1076} past {npc:4201} and west to {area:460}; coming from {npc:4073}, back west past Ziz's hut."] = "Suba {area:1076}, passando por {npc:4201}, e vá para oeste até {area:460}; vindo de {npc:4073}, volte para o oeste passando pela cabana de Ziz.",
		["Up the {area:1076} to {npc:4201}' hut, then east along the road toward {area:461}: {npc:4074} patrols the road just east of the fork, {npc:4073} the slopes further north-east below the crag. Both are lone shredder robots; they roam, so follow the road until you meet them."] = "Suba {area:1076} até a cabana de {npc:4201}, depois siga a estrada para o leste rumo a {area:461}: {npc:4074} patrulha a estrada logo a leste da bifurcação, {npc:4073} as encostas mais a nordeste, abaixo do penhasco. Os dois são robôs retalhadores solitários; eles vagam, então siga a estrada até encontrá-los.",
		["West of Gann, the Razormane hold {area:1701}. {npc:3436} is on the east side, {npc:3434} to the south, {npc:3435} at the west end. Lok (25) and the Warfrenzies (24-25) are a few levels above you; {npc:5859}, a rare elite, sometimes walks the ridge: leave him. Pathfinders and Stalkers drop the Backstabber, Seers the Wand, Warfrenzies the War Shield. {quest:885}, a rare red wind serpent, flies over the ridge: its feather starts a quest.\nCareful: Razormane Stalkers move around in stealth and hit with {spell:1752}, so they can join a fight without warning."] = "A oeste de Gann, os Crinavalha ocupam {area:1701}. {npc:3436} fica no lado leste, {npc:3434} ao sul, {npc:3435} na ponta oeste. Lok (25) e os Belicosos (24-25) estão alguns níveis acima de você; {npc:5859}, um elite raro, às vezes anda pela serra: deixe-o em paz. Desbravadores e Espreitadores deixam cair o Punhal, Videntes a Varinha, Belicosos o Escudo de Guerra. {quest:885}, uma serpente alada vermelha rara, sobrevoa a serra: a pena dela inicia uma missão.\nCuidado: os Espreitadores Crinavalha se movem furtivos e atacam com {spell:1752}, então podem entrar na briga sem aviso.",
		["{area:378} flight master"] = "Mestre de voo de {area:378}",
		["{area:465}: kill these as you meet them"] = "{area:465}: vá matando estes pelo caminho",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}, de qualquer harpia Furissangue",
		["{npc:10079} stands at the top of the {area:1718}, beside {npc:12576}."] = "{npc:10079} fica no alto de {area:1718}, ao lado de {npc:12576}.",
		["{npc:10079}, at the top of the lift"] = "{npc:10079}, no alto do elevador",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}: Pedras Solares Lampejantes das harpias Furissangue",
		["{npc:11860}: {npc:12576} is at the {area:1718}, later in this guide"] = "{npc:11860}: {npc:12576} fica em {area:1718}, mais adiante neste guia",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}, ao lado de {npc:11862}",
		["{npc:11862}, up on the ledge"] = "{npc:11862}, lá em cima na saliência",
		["{npc:11862}: {npc:12736} at Zoram'gar, next guide"] = "{npc:11862}: {npc:12736} em Zoram'gar, no próximo guia",
		["{npc:11864} stands by the bonfire inside Sun Rock: Makaba's news that Kaya is alive is for her."] = "{npc:11864} fica junto à fogueira dentro da Rocha do Sol: a notícia de Makaba de que Kaya está viva é para ela.",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}, no alto da árvore logo a leste de {npc:3341}",
		["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:3024} and {npc:4721} stand a short walk east of him."] = "{npc:2995}, o mestre de mantícoras, fica no platô central: pegue a rota de voo dele se ainda não tiver. {npc:3024} e {npc:4721} ficam a uma curta caminhada a leste dele.",
		["{npc:3024}: the {object:667362} grows in {area:464}, by Sun Rock"] = "{npc:3024}: {object:667362} cresce em {area:464}, perto da Rocha do Sol",
		["{npc:3341} walks around {area:1701}: look inside the circle on the map"] = "{npc:3341} anda por {area:1701}: procure dentro do círculo no mapa",
		["{npc:3341} walks the road south toward {area:359}, between about 46,75 and 46,81: if he isn't at the arrow, follow the road until you meet him. {npc:14242} sits up in the tree just east of the road at 47.9,77.5."] = "{npc:3341} anda pela estrada para o sul, rumo a {area:359}, entre cerca de 46,75 e 46,81: se ele não estiver na seta, siga a estrada até encontrá-lo. {npc:14242} fica empoleirado na árvore logo a leste da estrada, em 47.9,77.5.",
		["{npc:3375} walks around {area:359}: look inside the circle on the map"] = "{npc:3375} anda por {area:359}: procure dentro do círculo no mapa",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}, no alto da torre",
		["{npc:3430}, in the cage"] = "{npc:3430}, na jaula",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}, na borda norte do acampamento",
		["{npc:3442} stands beside the flight master you land at."] = "{npc:3442} fica ao lado do mestre de voo onde você pousa.",
		["{npc:3442}: {quest:1094}, from {npc:4201}"] = "{npc:3442}: {quest:1094}, de {npc:4201}",
		["{npc:3995}, below ground"] = "{npc:3995}, no subterrâneo",
		["{npc:4049}: {npc:4074} and {npc:4073} roam east of {npc:4201}, on the way up"] = "{npc:4049}: {npc:4074} e {npc:4073} vagam a leste de {npc:4201}, no caminho para cima",
		["{npc:4128} walks around {area:1156}: look inside the circle on the map"] = "{npc:4128} anda por {area:1156}: procure dentro do círculo no mapa",
		["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "A próxima missão de {npc:4198}, Ornanos, fica no lado da Aliança de {zone:1440}. Pule-a.",
		["{npc:4198}, outside the gate"] = "{npc:4198}, do lado de fora do portão",
		["{npc:4721}: the phial comes from {zone:1440}, next guide"] = "{npc:4721}: o frasco vem de {zone:1440}, no próximo guia",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "A cabana de {npc:5899} fica na crista acima do bebedouro dos javaligs, ao sul de {area:378}, no caminho até {area:359}.",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}: o odre azul é enchido em {zone:1440}, no próximo guia",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}: o odre vermelho de {area:272}",
		["{npc:5911} stands by the flight master. His {npc:268623} (23) is elite: grouping up is advised; the two Encroaching Soldiers are not."] = "{npc:5911} fica ao lado do mestre de voo. O {npc:268623} dele (23) é elite: recomenda-se formar grupo; os dois Soldados Invasores não.",
		["{npc:5911}, beside the flight master"] = "{npc:5911}, ao lado do mestre de voo",
		["{npc:5911}: the soldiers and the pillager camp just east of {npc:3341}, on the way south"] = "{npc:5911}: os soldados e o pilhador acampam logo a leste de {npc:3341}, no caminho para o sul",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}, um grande manguadonte, nada nas águas rasas da {area:391}, a leste de {npc:3388}.",
		["{quest:874} camps on the shore just north of {area:392}'s flight master."] = "{quest:874} acampa na praia logo ao norte do mestre de voo de {area:392}.",
		["{zone:1442}: kill these as you meet them"] = "{zone:1442}: vá matando estes pelo caminho",
		["{zone:1454} flight master"] = "Mestre de voo de {zone:1454}",
		["{zone:1456} first: two of its elders give quests worked on this guide's and the next guide's walks. Fly to {area:378}; from there it is a walk west into {zone:1412} and north to the bluffs."] = "Primeiro {zone:1456}: dois de seus anciãos dão missões feitas no percurso deste guia e do próximo. Voe para {area:378}; de lá, é uma caminhada para o oeste até {zone:1412} e para o norte até os penhascos.",
		["{zone:1456}'s central rise"] = "Platô central de {zone:1456}",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back north up the road to the {area:431} flight master and fly to {area:1637}."] = "De volta ao norte, subindo a estrada até o mestre de voo de {area:431}, e voe para {area:1637}.",
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "De volta à estrada para o sul. Onde ela vira para leste rumo a {area:287}, {npc:2214} espera em {area:285}.",
		["Back to the outpost before heading east to Thistlefur."] = "De volta ao assentamento antes de seguir para o leste, rumo aos Pelocardo.",
		["Back west to Zoram'gar. {npc:12757} offers King of the Foulweald now; leave it for the next {zone:1440} visit at 26, when the walk east passes the Foulweald."] = "De volta a oeste, até Zoram'gar. {npc:12757} oferece O rei dos Torpeflora agora; deixe para a próxima visita a {zone:1440}, no nível 26, quando a caminhada para leste passa pelos Torpeflora.",
		["Below ground"] = "No subterrâneo",
		["Down the road through Silverpine to the {area:228}: from the zeppelin towers, south through Tirisfal; from the {object:177790}, south-east from the coast to the road. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "Desça a estrada por Pinhaprata até {area:228}: das torres dos zepelins, para o sul por Tirisfal; de {object:177790}, para sudeste, da costa até a estrada. {npc:2121} e {npc:1937} ficam na entrada da cripta.",
		["Druid trainer"] = "Instrutor de druida",
		["East of Zoram'gar, the Thistlefur furbolgs fill the village and the hills around their hold.\nCareful: A Shaman at 15% health or lower runs off to find help, which can pull extra furbolgs."] = "A leste de Zoram'gar, os furbolgs Pelocardo lotam a aldeia e as colinas em volta do covil deles.\nCuidado: um Xamã com 15% de vida ou menos sai correndo atrás de ajuda, o que pode trazer mais furbolgs.",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "Toda naga Iracauda ao longo da praia ao norte do posto deixa cair cabeças.",
		["Fly to {area:1637}"] = "Voe para {area:1637}",
		["Fly to {area:431}: {npc:12837} waits in the inn for news of Ruul."] = "Voe para {area:431}: {npc:12837} espera na estalagem por notícias de Ruul.",
		["From Seereth's camp head north-east across the {zone:1413} to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}."] = "Do acampamento de Seereth, siga para nordeste por {zone:1413} até a estrada ao norte da Encruzilhada; Ladinos vindos da torre de Arruela seguem para oeste até ela. {npc:8582} fica na torre de vigia de {area:1703}, onde a estrada entra em {zone:1440}.",
		["From the zeppelin towers, run south into Silverpine and west past the {area:240} to the coast: the {object:177790} lies at the bottom of very deep water there, beside an air fissure where you can breathe. Watch your breath on the way down. It holds the {item:15882} for Trial of the Sea Lion. Then on to the {area:228}."] = "Das torres do zepelim, corra para o sul, entrando em Pinhaprata, e a oeste, passando por {area:240}, até a costa: {object:177790} fica no fundo de águas muito profundas ali, ao lado de uma fissura de ar onde você consegue respirar. Fique de olho no fôlego na descida. Ele guarda a {item:15882} para a Missão do leão marinho. Depois siga para {area:228}.",
		["Head west along the main road across {zone:1440}, past {area:415} (Alliance: keep to the road), to the coast. {area:2897} is on the {area:414} in the north-west: {npc:12719}, {npc:12721} and {npc:12757} stand around it, the {npc:12863} beside the flight master. Its other quests are for the next visit, at 26."] = "Siga para oeste pela estrada principal por {zone:1440}, passando por {area:415} (Aliança: fique na estrada), até a costa. {area:2897} fica em {area:414}, no noroeste: {npc:12719}, {npc:12721} e {npc:12757} ficam em volta, e {npc:12863} junto ao mestre de voo. As outras missões de lá ficam para a próxima visita, no nível 26.",
		["If you did {quest:2478} with a group, {npc:3401} in the {object:172960} takes it now."] = "Se você fez {quest:2478} em grupo, {npc:3401}, em {object:172960}, recebe a entrega agora.",
		["Inside the hold, Troll Chests lie along the tunnels. {npc:12818} is held deep inside: free him and protect him all the way out, then he runs home to {area:428}.\nCareful: Two scripted ambushes occur, each made up of three Thistlefurs (a Shaman, a Pathfinder and an Avenger, Ursa or Den Watcher): the first when you come back to the tunnel's fork inside the cave, the second just beyond the gate where {npc:3987} roams."] = "Dentro do covil, Baús dos Trolls ficam ao longo dos túneis. {npc:12818} está preso lá no fundo: liberte-o e proteja até a saída; depois ele corre para casa, em {area:428}.\nCuidado: há duas emboscadas certas, cada uma com três Pelocardos (um Xamã, um Desbravador e um Vingador, Ursino ou Vigia do Covil): a primeira quando você volta à bifurcação do túnel dentro da caverna, a segunda logo depois do portão por onde {npc:3987} anda.",
		["Naga brazier"] = "Braseiro naga",
		["Naga heads"] = "Cabeças de naga",
		["On the way north from Seereth's camp, keep east of the road to the Venture Co. tower north of the {area:382}. Before you go near Fizzule, use {item:8051} to fire two flares, then target him and /salute: he attacks anyone who comes in without signalling first."] = "No caminho para o norte a partir do acampamento de Seereth, mantenha-se a leste da estrada até a torre da Empreendimentos S.A. ao norte de {area:382}. Antes de chegar perto de Arruela, use {item:8051} para disparar dois sinalizadores, depois selecione-o e use /saudar: ele ataca quem chega sem sinalizar antes.",
		["On the way west, {npc:267214} is stuck in a ravine south of the main road, south-east of {area:415}. Shadowhorn Stags and Ashenvale Bears roam the woods all around it."] = "No caminho para oeste, {npc:267214} está preso numa ravina ao sul da estrada principal, a sudeste de {area:415}. Cervos Galhassombra e Ursos do Vale Gris andam pela mata em toda a volta.",
		["Out of the inn and south down the road to the lumber camp: {npc:12867} stands there. The night elf Outrunners (23-24) stalk the woods south-east of it; they stealth, so watch for them."] = "Saindo da estalagem e descendo a estrada para o sul até o acampamento madeireiro: {npc:12867} fica lá. Os Vanguardeiros elfos noturnos (23-24) rondam a mata a sudeste dele; eles ficam furtivos, então fique atento.",
		["South down the road past Pyrewood: Dalaran Watchers and Wizards patrol the roads around {area:233}, and south-west of the town the Ravenclaw Drudgers and Guardians haunt the ruins of {quest:516} in the south-east of the forest."] = "Ao sul pela estrada, passando por Lenhardente: Vigias e Teurgos de Dalaran patrulham as estradas em volta de {area:233}, e a sudoeste da cidade os Mourejantes e Guardiões Corvinalle assombram as ruínas de {quest:516}, no sudeste da floresta.",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "Conduza o {npc:271181} de {npc:267214} para fora da ravina até a estrada principal em até quatro minutos; se a canalização quebrar, peça a {npc:267214} de novo.",
		["The Ravenclaw undead haunt the ruins of {quest:516}, east of the road in the south-east of the forest; a {npc:1973} drops the {item:271343} that leads to the {object:645153}.\nAn elite spirit (20) often stands beside the {object:645153}: pull the Ravenclaws away from the stone before you fight them."] = "Os mortos-vivos Corvinalle assombram as ruínas de {quest:516}, a leste da estrada, no sudeste da floresta; um {npc:1973} deixa cair o {item:271343} que leva a {object:645153}.\nUm espírito elite (20) costuma ficar ao lado de {object:645153}: afaste os Corvinalle da pedra antes de lutar com eles.",
		["The quest hands you a {item:210713}: use it beside the {object:645153} to offer your blood, then kill the elite spirit that answers.\n{quest:95883} is elite: grouping up is advised."] = "A missão dá a você um {item:210713}: use-o ao lado de {object:645153} para oferecer seu sangue, depois mate o espírito elite que responder.\n{quest:95883} é elite: é recomendado formar grupo.",
		["Thistlefur Hold"] = "Toca dos Pelocardo",
		["Zeppelin to {zone:1458}"] = "Zepelim para {zone:1458}",
		["the {object:645153} offers {quest:95883} once the {item:271343} is in; below ground"] = "{object:645153} oferece {quest:95883} depois que o {item:271343} é colocado; no subterrâneo",
		["{area:431} flight master"] = "Mestre de voo de {area:431}",
		["{area:431} is just north up the road. Coming in from the south, the flight master and {npc:12696}'s hunt board at {area:428} come first, then the vendors. {npc:12867} at the lumber camp offers {quest:6503}: leave it for the way back, at 22."] = "{area:431} fica logo ao norte, subindo a estrada. Vindo do sul, o mestre de voo e o quadro de caça de {npc:12696} em {area:428} vêm primeiro, depois os vendedores. {npc:12867}, no acampamento madeireiro, oferece {quest:6503}: deixe para a volta, no nível 22.",
		["{item:15882}, from the {object:177790}"] = "{item:15882}, do {object:177790}",
		["{item:210713}, beside the {object:645153}: summons the elite spirit"] = "{item:210713}, ao lado de {object:645153}: invoca o espírito elite",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}, de um {npc:1973}",
		["{item:271350}, from the Tortured Souls among the ruins; below ground"] = "{item:271350}, das Almas Torturadas no meio das ruínas; no subterrâneo",
		["{npc:12696}'s hunt targets (Ursangous, Shadumbra, Sharptalon) are for the next {zone:1440} visit, at 26."] = "Os alvos de caça de {npc:12696} (Ursangous, Shadumbra, Garraguda) são para a próxima visita a {zone:1440}, no nível 26.",
		["{npc:12717} walks north up the strand to a naga brazier. Put the brazier out, then guard him through the naga waves until Vorsha is dead; the Wrathtail naga drop the heads {npc:12719} wants."] = "{npc:12717} anda para o norte pela praia até um braseiro naga. Apague o braseiro e depois proteja-o das ondas de nagas até Vorsha morrer; os nagas Cauda da Ira soltam as cabeças que {npc:12719} quer.",
		["{npc:12717}: take it last, his escort starts at once"] = "{npc:12717}: pegue por último, a escolta dele começa na hora",
		["{npc:12721}: the troll charms are in Thistlefur Hold, east of the outpost"] = "{npc:12721}: os amuletos troll ficam no Covil dos Pelocardo, a leste do assentamento",
		["{npc:12818}, below ground"] = "{npc:12818}, no subterrâneo",
		["{npc:12837}, inside the inn"] = "{npc:12837}, dentro da estalagem",
		["{npc:1937}: Lydon in {area:272}, next guide"] = "{npc:1937}: Lydon em {area:272}, no próximo guia",
		["{npc:2121}: {quest:516}, south-east of {area:233}"] = "{npc:2121}: {quest:516}, a sudeste de {area:233}",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}: Darthalia em {area:272}",
		["{npc:2391} in {area:272} teaches Poisons: keep it"] = "{npc:2391}, em {area:272}, ensina Venenos: guarde-a",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152} treina Paladinos em {area:159}, a uma curta caminhada para o norte pela estrada a partir das torres de zepelim. Volte pela mesma estrada para Pinhaprata.",
		["{npc:271181}, on the road"] = "{npc:271181}, na estrada",
		["{npc:3034} in {zone:1412}; {zone:1454} has no druid trainer"] = "{npc:3034} em {zone:1412}; {zone:1454} não tem instrutor de druida",
		["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875} fica em {object:172960}. Use {item:6626} no círculo de invocação ali e derrote a súcubo para vinculá-la.",
		["{npc:6389} stands just west of the crypt entrance: hand him {item:16210} from the {zone:1458}."] = "{npc:6389} fica logo a oeste da entrada da cripta: entregue a ele {item:16210}, de {zone:1458}.",
		["{quest:2478} is for level 23 or more: the tower's drones are 25 and Gallywix a 23 elite. Do it when you can, with a group, from the Class guide Poisons (Horde)."] = "{quest:2478} é para nível 23 ou mais: os zangões da torre são 25 e Gallywix é um elite 23. Faça quando puder, com um grupo, a partir dos Venenos do guia de classe (Horda).",
		["{zone:1421}: kill these as you meet them"] = "{zone:1421}: vá matando estes pelo caminho",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["After returning Mission: Possible But Not Probable to Shenthul, bring {quest:2479} to {npc:2391} in {area:272}. Stay beside him until the brewing objective completes, then hand in the follow-up to learn Poisons. Finish it even if the Zanzil poison has already been removed; removing the debuff alone does not teach the skill."] = "Depois de entregar Missão: possível, mas não provável a Shenthul, leve {quest:2479} a {npc:2391}, em {area:272}. Fique ao lado dele até o objetivo da poção terminar e entregue a continuação para aprender Venenos. Termine mesmo que o veneno de Zanzil já tenha saído; só tirar a penalidade não ensina a perícia.",
		["Back down to Masoj on the hillside above {area:290}."] = "De volta a Masoj, na encosta acima de {area:290}.",
		["Back to the Crossroads"] = "De volta à Encruzilhada",
		["Back to {area:272}"] = "De volta a {area:272}",
		["Bears, creepers and lions"] = "Ursos, rastejantes e leões",
		["Careful: When one lion is attacked, nearby lions come to its aid, and the Vicious Black Bears sharing those fields can also join the fight."] = "Cuidado: quando um leão é atacado, os leões por perto vêm ajudar, e os ursos negros que dividem esses campos também podem entrar na briga.",
		["Cast {spell:18960}. Join the two pendant halves at the {area:2362}, on the north-west shore of the lake, before you see {npc:11802} in {area:2361}. {npc:11802} stands upstairs in his building: go up inside, the arrow cannot tell the floors apart."] = "Use {spell:18960}. Junte as duas metades do pingente em {area:2362}, na margem noroeste do lago, antes de ver {npc:11802} em {area:2361}. {npc:11802} fica no andar de cima do prédio dele: suba por dentro, a seta não diferencia os andares.",
		["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings. Their locks need keys: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks.\nFrom {area:272} go south-east into the hills on the way to {area:275}. Rogues and Watchmen hold the camps along the way."] = "Drull e {npc:2238} estão acorrentados nas construções do pátio de {area:275}. Os cadeados precisam de chaves: {npc:2427} carrega a {item:3467} e {npc:2428}, a {item:3499}, ambos na fortaleza. Mate-os e depois abra os dois cadeados.\nDe {area:272}, siga para sudeste pelas colinas rumo a {area:275}. Ladinos e Vigias da Camarilha ocupam os acampamentos pelo caminho.",
		["Drull's ball and chain"] = "Bola e corrente de Drull",
		["East along the foothills, then down into {area:272}."] = "Para leste pelo sopé, depois desça até {area:272}.",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "Encha o {item:7768} no {object:107045} ao lado da estalagem",
		["Fly on from {npc:2226}, the bat handler just east of the crypt, to the {area:1497}."] = "Siga voando com {npc:2226}, o tratador de morcegos logo a leste da cripta, até a {area:1497}.",
		["Fly to the {area:1497}"] = "Voe para a {area:1497}",
		["From {area:287} town climb the mountain to the north, right up to its top on the Alterac border: the western vial goes there, not on the lower slope."] = "Da cidade de {area:287}, suba a montanha ao norte, até o topo, na divisa com Alterac: o frasco ocidental vai ali, não na encosta de baixo.",
		["Inside"] = "Lá dentro",
		["Just south of Masoj, the {item:3502} grow on the hillsides above the river."] = "Logo ao sul de Masoj, as {item:3502} crescem nas encostas acima do rio.",
		["Keep it: the {area:287} coast, later on the route"] = "Guarde: o litoral de {area:287}, mais adiante na rota",
		["Masoj hides on the hillside above {area:290}, south-west of Durnholde, on the way down to the blossoms."] = "Masoj se esconde na encosta acima de {area:290}, a sudoeste do Forte do Desterro, no caminho até as flores.",
		["Masoj wants an Apothecary Vial placed on three peaks. The southern one is the hilltop above {area:290}, south-east of the blossoms: use a vial at the top."] = "Masoj quer uma Ampola de Boticário colocada em três picos. O do sul é o topo do morro acima de {area:290}, a sudeste das flores: use uma ampola no alto.",
		["Poison chain unfinished? Resume your current stage in the Class guide Poisons (Horde); completed quests do not need restarting. Arrange a group for Gallywix, finish the Hinott follow-up, then return to this leveling guide."] = "Cadeia dos venenos pela metade? Retome a etapa em que parou no guia de classe Venenos (Horda); missões já concluídas não precisam ser refeitas. Junte um grupo para o Gallywix, termine a continuação do Hinoto e depois volte para este guia de evolução.",
		["Take {quest:31} from {npc:11802}, who stands upstairs in his building. Then {npc:11798} in {area:2361} flies druids to {area:1638}: {npc:3033} is on {area:1639}."] = "Pegue {quest:31} com {npc:11802}, que fica no andar de cima do prédio dele. Depois {npc:11798}, em {area:2361}, leva druidas de voo até {area:1638}: {npc:3033} fica em {area:1639}.",
		["The Peasants work the fields south of the farmhouses. Every {area:287} human drops skulls; the Peasants drop them most often.\nCareful: A fleeing peasant that reaches the town hall can bring back many adds, including {area:287} footmen; snares, roots or similar effects keep them from escaping."] = "Os Camponeses trabalham nos campos ao sul das casas da fazenda. Todo humano de {area:287} deixa cair crânios; os Camponeses são os que mais deixam.\nCuidado: um camponês fugido que chega à prefeitura pode voltar com um monte de reforço, incluindo soldados de {area:287}; lentidão, enraizar e efeitos parecidos impedem a fuga.",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms."] = "As fazendas a leste da cidade de {area:287}. {npc:232} trabalha no campo perto da casa da fazenda ao norte, {npc:2403} no que fica mais a sudeste; Lavradores e Fazendeiros estão por toda parte. {npc:2451} cuida do campo ao sul das fazendas.",
		["The northern peak"] = "O pico norte",
		["The northern peak rises south-east of {area:272}, on the way down towards Durnholde."] = "O pico norte fica a sudeste de {area:272}, no caminho para o Forte do Desterro.",
		["The smithy"] = "A ferraria",
		["The smithy stands in the middle of {area:287} town. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the street north of it."] = "A ferraria fica no meio da cidade de {area:287}. {npc:2404} e seus aprendizes trabalham na forja; o {object:1736} está empilhado ao lado. {npc:2449} anda pela rua ao norte dela.",
		["The southern peak"] = "O pico sul",
		["The western peak"] = "O pico oeste",
		["The {object:556670} poster by the inn"] = "O cartaz {object:556670} perto da estalagem",
		["The {quest:567} poster: Kalaba with the peasants, Wilkes at the smithy; the clerk and the miner on the visit at about 30; inside"] = "O cartaz {quest:567}: Kalaba com os camponeses, Urbano na ferraria; o escrivão e o mineiro na visita por volta do nível 30; lá dentro",
		["Train before you fly on: the next guide flies from here to the Crossroads."] = "Treine antes de seguir voo: o próximo guia voa daqui até a Encruzilhada.",
		["Train with {npc:3033}. Before you fly on, {npc:3024} and {npc:4721}, a short walk east of the wind rider master, give two quests worked on the next guides' walks; then fly on to the Crossroads, where the next guide starts."] = "Treine com {npc:3033}. Antes de seguir voo, {npc:3024} e {npc:4721}, a uma curta caminhada a leste do mestre de mantícoras, dão duas missões feitas pelo caminho dos próximos guias; depois voe para a Encruzilhada, onde começa o próximo guia.",
		["Walk back up to {area:272} and fly to the {area:228}: {npc:2121} stands by the crypt entrance."] = "Volte a pé até {area:272} e voe para {area:228}: {npc:2121} fica na entrada da cripta.",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "A oeste da Serraria Tarren, Ursos Cinzentos, Rastejantes do Musgo da Floresta e Leões da Montanha Esfomeados vagam pelas colinas no caminho até as fazendas. Os rastejantes raramente derrubam {item:3477}; você só precisa de um.",
		["While you're here: learn Polearms from {npc:11870} ({object:36070}, 1 gold); a Hunter's melee weapon is mostly its stats, and two-handers carry the most."] = "Já que está aqui: aprenda Armas de Haste com {npc:11870} ({object:36070}, 1 ouro); a arma corpo a corpo do Caçador vale pelos atributos, e as de duas mãos são as que mais trazem.",
		["While you're here: learn Polearms from {npc:11870} ({object:36070}, 1 gold); two-handers level a Warrior fastest."] = "Já que está aqui: aprenda Armas de Haste com {npc:11870} ({object:36070}, 1 ouro); arma de duas mãos é o jeito mais rápido de upar Guerreiro.",
		["While you're here: learn Swords from {npc:11870} ({object:36070}, 10 silver); a sword in the main hand levels a Rogue steadily."] = "Já que está aqui: aprenda Espadas com {npc:11870} ({object:36070}, 10 pratas); espada na mão principal faz o Ladino subir de nível sem tropeço.",
		["While you're here: learn {spell:202} from {npc:11870} ({object:36070}, 10 silver); two-handers level a Paladin fastest."] = "Já que está aqui: aprenda {spell:202} com {npc:11870} ({object:36070}, 10 pratas); arma de duas mãos é o jeito mais rápido de upar Paladino.",
		["While you're here: learn {spell:202} from {npc:11870} ({object:36070}, 10 silver); two-handers level a Warrior fastest."] = "Já que está aqui: aprenda {spell:202} com {npc:11870} ({object:36070}, 10 pratas); arma de duas mãos é o jeito mais rápido de upar Guerreiro.",
		["Zeppelin to {zone:1454}"] = "Zepelim para {zone:1454}",
		["{area:272} flight master"] = "Mestre de voo de {area:272}",
		["{area:272} is your base for this guide: the hearth brings you back here twice. Everyone stands around the town square."] = "{area:272} é sua base neste guia: a pedra de regresso traz você de volta aqui duas vezes. Todos ficam em volta da praça da cidade.",
		["{area:275}: kill these as you meet them"] = "{area:275}: vá matando estes pelo caminho",
		["{area:286}: kill these as you meet them"] = "{area:286}: vá matando estes pelo caminho",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}: use uma metade em {area:2362}",
		["{item:3692}: the Peasants in the fields"] = "{item:3692}: os Camponeses de Eira dos Montes nos campos",
		["{npc:11798} in {area:2361} flies druids there"] = "{npc:11798}, em {area:2361}, leva druidas voando até lá",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}, no Apothecarium",
		["{npc:2055}, in the {zone:1458}"] = "{npc:2055}, em {zone:1458}",
		["{npc:2215}: orders for {npc:270438}, on the way to Durnholde"] = "{npc:2215}: ordens para {npc:270438}, a caminho do Forte do Desterro",
		["{npc:2216}, inside"] = "{npc:2216}, lá dentro",
		["{npc:2216}, inside: the {item:3502} grow south-west of Durnholde, on the walk there"] = "{npc:2216}, lá dentro: os {item:3502} crescem a sudoeste do Forte do Desterro, no caminho até lá",
		["{npc:2229}, inside"] = "{npc:2229}, lá dentro",
		["{npc:2230}, next to Lydon; inside"] = "{npc:2230}, ao lado de Lindolfo; lá dentro",
		["{npc:2238}'s ball and chain"] = "Bola e corrente de {npc:2238}",
		["{npc:2261} walks around here: look inside the circle on the map"] = "{npc:2261} anda por aqui: procure dentro do círculo no mapa",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274} é o cachorro de {npc:232}, na casa da fazenda ao norte, em {area:286}.",
		["{npc:2391}: Poisons"] = "{npc:2391}: Venenos",
		["{npc:2451} walks around {area:286}: look inside the circle on the map"] = "{npc:2451} anda por {area:286}: procure dentro do círculo no mapa",
		["{npc:270438}, once {quest:98094} is in"] = "{npc:270438}, depois que {quest:98094} estiver entregue",
		["{npc:3024}: {quest:97538}, the Mirkweed in {area:464} by Sun Rock"] = "{npc:3024}: {quest:97538}, a Erva-do-pântano em {area:464}, perto da Rocha do Sol",
		["{npc:4606} stands in the {object:36070}."] = "{npc:4606} fica no {object:36070}.",
		["{npc:4721}: {quest:1195}, the phial from {zone:1440}'s Laughing Sisters"] = "{npc:4721}: {quest:1195}, o frasco das Irmãs Risonhas de {zone:1440}",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["A short walk north of the Galak camps, the cave of {area:1557} leads down to its deepest chamber, where the {object:20807} burns. Use the {item:5868} on it, then loot the {item:5869} at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to {npc:2986}'s mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame."] = "A uma curta caminhada ao norte dos acampamentos Galath, a caverna de {area:1557} desce até a câmara mais funda, onde arde o {object:20807}. Use o {item:5868} nele e saqueie o {item:5869} na hora: a chama só fica apagada por pouco tempo e, se reacender, o frasco já era. Depois siga a leste até a meseta de {npc:2986}.\nCuidado: dois Guardas da Chama Galath (30) ficam junto ao braseiro e um guarda centauro anda pela caverna: puxe-os um de cada vez antes de apagar a chama.",
		["Back east to {area:484}: it lies on the way from {area:487} to {npc:2986}'s mesa."] = "De volta a leste, até {area:484}: fica no caminho de {area:487} até a mesa de {npc:2986}.",
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "De volta ao sul até o acampamento, depois suba até {zone:1456} para o voo até o {area:378}.",
		["Back south-west to {area:421}. {npc:12759}, a corrupted water elemental, drifts around the lake's island and under the water. She drops the {item:16408} only once you have {quest:25} from {npc:12737}; it starts a quest for Splintertree."] = "De volta a sudoeste até o {area:421}. {npc:12759}, uma elemental da água corrompida, flutua em volta da ilha do lago e debaixo d'água. Ela só deixa cair o {item:16408} depois que você pegar {quest:25} com {npc:12737}; o item inicia uma missão para o Posto Machadada.",
		["Back to Zoram'gar from the ruins before heading east for good."] = "De volta ao Assentamento Zoram'gar, saindo das ruínas, antes de seguir para o leste de vez.",
		["Back to {area:484}. The {area:2240}'s quests come with the next visit to the {area:439}, at 33."] = "De volta a {area:484}. As missões de {area:2240} vêm na próxima visita a {area:439}, no nível 33.",
		["Befouled Water Elementals drift around the lake's shores; the gazebo stands on the island, overlooking the Alliance outpost."] = "Elementais da Água Contaminados flutuam pelas margens do lago; o gazebo fica na ilha, com vista para o posto avançado da Aliança.",
		["Class trainer"] = "Instrutor de classe",
		["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "Suba a trilha até o alto do {area:2097}. {npc:10646} está presa ao lado de {npc:10896} (29): elimine os guardas e {npc:10896} primeiro, depois liberte-a e proteja-a na descida; emboscadores Temível Totem atacam você no caminho.",
		["Felmusk satyrs"] = "Sátiros Malmíscar",
		["Fly to {area:1638}"] = "Voe para {area:1638}",
		["Fly to {area:1638} from Zoram'gar. If you don't know its flight path, fly to {area:378} and walk north through {zone:1412} instead."] = "Voe para {area:1638} a partir de Zoram'gar. Se você não tem a rota de voo de lá, voe para o {area:378} e siga a pé para o norte por {zone:1412}.",
		["Fly to {area:2897}"] = "Voe para {area:2897}",
		["Fly to {area:378}"] = "Voar para o {area:378}",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "Siga a estrada principal para leste passando {area:415} (Aliança: fique na estrada). {npc:12678}, um urso-pardo grande, vaga pelas {area:418} ao sul da estrada, a oeste do {area:421}. A pata dele inicia a próxima missão de caça.",
		["Galak centaurs"] = "Centauros Galath",
		["Gazebo"] = "Gazebo",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "Amostras de Toxina de Penumbrascente, dos Cadáveres Roídos ({npc:264096})",
		["Grimtotem camps below {area:2097}"] = "Acampamentos Temível Totem abaixo de {area:2097}",
		["If you skipped {quest:5151} and are still short of 29.49, kill harpies here first: {area:487} is your next stop anyway. Past it, this step skips itself. Or, with a group, run the {area:2797} dungeon or the {area:796} dungeon (Graveyard) instead."] = "Se você pulou {quest:5151} e ainda não chegou a 29.49, mate harpias aqui primeiro: {area:487} é a sua próxima parada de qualquer jeito. Se já passou disso, esta etapa se pula sozinha. Ou, em grupo, faça a masmorra {area:2797} ou a masmorra {area:796} (Cemitério).",
		["Into {area:1638} by a lift: {npc:2995}, the wind rider master, stands on the central rise. Take his flight path if you don't know it yet."] = "Entre em {area:1638} por um elevador: {npc:2995}, o mestre de mantícoras, fica no platô central. Pegue a rota de voo dele se ainda não a tem.",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "Continue para leste pela estrada. {npc:12858} espera a sudoeste do Acampamento de Lenhadores Brado Guerreiro. Ele e seus peões invadem o {area:2360}: deixe que eles atraiam a ameaça e fique com {npc:12858} até {npc:12860} morrer.",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "Mate o {npc:10720} que vem atrás de {npc:10638}",
		["Laughing Sisters"] = "Irmãs Risonhas",
		["Level 28.9"] = "Nível 28.9",
		["Level 29.49"] = "Nível 29.49",
		["North of Thunder Bluff"] = "Ao norte de Penhasco do Trovão",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "Ao norte do acampamento, aranhas infestam o cemitério em {area:17044}. Use o {item:273015} de {npc:264074} nos Cadáveres Roídos; as Tecelãs deixam cair a {item:273181}. {npc:264082} fica no extremo norte: o {item:273658} dela inicia {quest:96294}.",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "A noroeste do Posto Machadada, os sátiros Malmíscar acampam na mata. Todo sátiro pode deixar cair chifres.",
		["On the road south to the {area:485}, turn east into the {area:359} dig. {npc:3421} hides at its south edge. {object:3646} stands on the bottom floor of the dwarves' fortress, beside {npc:3414} (30) and his Officers (26): pull them to you one at a time."] = "Na estrada para o sul até {area:485}, vire para leste na escavação de {area:359}. {npc:3421} se esconde na borda sul dela. {object:3646} fica no andar de baixo da fortaleza dos anões, ao lado de {npc:3414} (30) e seus Oficiais (26): puxe-os até você um de cada vez.",
		["On the way back north-east to Splintertree: {npc:12676} prowls the woods south-east of the Warsong lumber camp."] = "No caminho de volta a nordeste, rumo ao Posto Machadada: {npc:12676} ronda a mata a sudeste do Acampamento de Lenhadores Brado Guerreiro.",
		["Only if the {npc:10617} dropped his plot for you: {npc:10638} stands at {area:2237}."] = "Só se {npc:10617} tiver soltado o plano dele para você: {npc:10638} fica em {area:2237}.",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "Desça de elevador e siga a estrada para leste pelos cânions até {area:484}, uma aldeia tauren no alto das mesetas. O elevador dela fica no lado norte.",
		["Sapphires of Aku'Mai"] = "Safiras de Aku'Mai",
		["Short of 28.9? The Grimtotem around these camps (25-28) are the right level: kill a few more before the climb to {npc:10646}. Past it, this step skips itself. Or, with a group, run the {area:2797} dungeon or the {area:1717} dungeon instead."] = "Abaixo de 28.9? Os Temível Totem destes acampamentos (25-28) são do nível certo: mate mais alguns antes de subir até {npc:10646}. Se já passou disso, esta etapa se pula sozinha. Ou, em grupo, faça a masmorra {area:2797} ou a masmorra {area:1717}.",
		["South from Raynewood, the moonwell sits in a hollow west of the river, hard to see from the road; {area:421} is west of it. Use the {item:5867} at the moonwell to fill it."] = "Ao sul de Raynewood, o poço lunar fica numa depressão a oeste do rio, difícil de ver da estrada; o {area:421} fica a oeste dele. Use o {item:5867} no poço lunar para enchê-lo.",
		["South of Darkcloud, the harpies of {area:487}. {npc:4490} (31) walks among them: thin out the harpies around her before you pull her. The Screeching Harpies, Roguefeathers and Windcallers there are {npc:4877}'s; her {quest:98069} lie on the ground along the foot of the cliff and in the cave up on top."] = "Ao sul do Pináculo da Nuvem Negra, as harpias de {area:487}. {npc:4490} (31) anda entre elas: reduza as harpias em volta dela antes de puxá-la. As Harpias Guinchadoras, Plumerrantes e Arautos do Vento de lá são de {npc:4877}; as {quest:98069} dela ficam no chão ao longo do pé do penhasco e na caverna no alto.",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "Fale com {npc:3057}, em {area:1638}: {quest:93739}",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "Desça de elevador. O ovo está num ninho no fundo do cânion em um de três lugares: a sudeste das mesetas (52.3,55.2), a leste (56.4,50.4) ou a sudoeste (37.6,56.1).",
		["Talk to {npc:3057}"] = "Fale com {npc:3057}",
		["The Earthen Ring"] = "A Harmonia Telúrica",
		["The Earthen Ring camp and its three quests stand up on {area:17045}, north of {zone:1456}. Fly to {zone:1456} if you know its flight path and take a lift down, else fly to {area:378} and walk north through {zone:1412}; the arrow then leads round to the plateau's north end and up onto it."] = "O acampamento da Harmonia Telúrica e suas três missões ficam no alto de {area:17045}, ao norte de {zone:1456}. Voe para {zone:1456} se você já tem a rota de voo de lá e desça por um elevador; senão, voe para {area:378} e siga a pé para o norte por {zone:1412}; a seta então leva você em volta até o extremo norte do planalto e para cima dele.",
		["The Earthen Ring camp stands north of the bluffs: {npc:264074}, {npc:264072} and {npc:259118}. From {zone:1456}, take a lift down; coming on foot from {area:378}, keep north past the bluffs."] = "O acampamento da Harmonia Telúrica fica ao norte dos penhascos: {npc:264074}, {npc:264072} e {npc:259118}. Saindo de {zone:1456}, desça por um elevador; vindo a pé de {area:378}, siga ao norte, passando pelos penhascos.",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "Os furbolgs Torpeflora ocupam a mata a leste do {area:421}, ao sul da estrada. Coloque o {item:16972} no {object:178206} e proteja-o: os furbolgs vêm derrubá-lo. {npc:12918} vem por último; o totem dele cai no cesto.",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks between the camps: kill him when you meet him, his note starts a quest for {area:2237}."] = "Os acampamentos Galath enchem o cânion ao norte da Aldeia Vento Livre; Batedores, Cavalgantes e Ventilhãs dividem todos os acampamentos. Um {npc:10617} solitário anda entre os acampamentos: mate-o quando o encontrar, o bilhete dele inicia uma missão para o {area:2237}.",
		["The Laughing Sisters, dryads, wander {area:426} around {npc:12677}'s woods; one of them drops {npc:4721}'s {item:5867}, which can take several kills."] = "As Irmãs Risonhas, dríades, vagam pelo {area:426} em volta da mata de {npc:12677}; uma delas deixa cair o {item:5867} de {npc:4721}, o que pode exigir várias mortes.",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "As Safiras são cristais azuis nas paredes dos túneis que levam ao portal das {area:2797}, no subsolo e fora da instância: nade para baixo a partir do fosso, por baixo da parede, até a caverna. Os sátiros e nagas dos túneis são elite: é recomendado formar grupo. Os cristais reaparecem rápido, então não é preciso ir fundo.",
		["The Wanted poster beside {npc:10537}"] = "O cartaz de procura-se ao lado do {npc:10537} do Rochedo",
		["The fountain stands in the middle of the {area:418}, where {npc:12678} roams: use the {item:7767} there."] = "A fonte fica no meio das {area:418}, onde {npc:12678} anda: use o {item:7767} lá.",
		["The next guide flies on from here to the Crossroads and {zone:1454}."] = "O próximo guia voa daqui para a Encruzilhada e para {zone:1454}.",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "O caminho até as Safiras passa pelas ruínas submersas no extremo norte da praia: desça as escadas até o fosso.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:10992} is a level 30 elite: most classes solo it at level 32, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:10992} é elite de nível 30: a maioria das classes encara sozinha no nível 32, mas talvez você precise de ajuda. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["Underwater"] = "Debaixo d'água",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "A oeste da Aldeia Vento Livre, os acampamentos Temível Totem abaixo do {area:2097}. Os Bilhetes Secretos estão em Baús de Documentos nos acampamentos sudeste, sudoeste e noroeste.",
		["West of Mystral Lake, {npc:12678}, a big grizzly, roams the {area:418}: his paw now drops for you."] = "A oeste do Lago Mystral, {npc:12678}, um urso-pardo grande, vaga pelas {area:418}: agora a pata dele cai para você.",
		["West of Whitereach the wyverns nest on the {area:482} cliffs; the eggs lie in the nests. {npc:10427} waits on the east side of the nesting grounds: free him and keep him alive on the walk back to {area:2237}.\nCareful: Wyverns at level 28-29 fly overhead and can be pulled without warning. A group of three wyverns can ambush you once you pass the first pillar at the bottom."] = "A oeste do Posto Confinalvo, as mantícoras fazem ninho nos penhascos de {area:482}; os ovos ficam nos ninhos. {npc:10427} espera no lado leste da área dos ninhos: liberte-o e mantenha-o vivo na volta até {area:2237}.\nCuidado: mantícoras de nível 28-29 voam por cima e podem ser puxadas sem aviso. Um bando de três mantícoras pode emboscar você depois que passar a primeira coluna lá embaixo.",
		["While you're here: learn {spell:199} from {npc:11869} (10 silver); two-handers level a Warrior fastest."] = "Já que está aqui: aprenda {spell:199} com {npc:11869} (10 pratas); arma de duas mãos é o jeito mais rápido de upar Guerreiro.",
		["for {npc:5901}, south of {area:392}: next guide"] = "para {npc:5901}, ao sul de {area:392}: próximo guia",
		["grind on {npc:10759}"] = "mate {npc:10759} até subir",
		["grind on {npc:4101}"] = "mate {npc:4101} até subir",
		["{area:17044}: kill these as you meet them"] = "{area:17044}: vá matando estes pelo caminho",
		["{area:2797} ruins"] = "Ruínas das {area:2797}",
		["{area:2897} flight master"] = "Mestre de voo de {area:2897}",
		["{area:392} flight master"] = "Mestre de voo de {area:392}",
		["{area:418} fountain"] = "Fonte das {area:418}",
		["{area:483}: kill these as you meet them"] = "{area:483}: vá matando estes pelo caminho",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}, das Tecelãs de Penumbrascente ({npc:264081})",
		["{item:273658}, from {npc:264082}: it does not drop for everyone"] = "{item:273658}, de {npc:264082}: não cai para todo mundo",
		["{item:5867}, at the {object:20806}"] = "{item:5867}, no {object:20806}",
		["{item:5867}, from a {npc:4054}"] = "{item:5867}, de uma {npc:4054}",
		["{item:5868}, at the {object:20807}"] = "{item:5868}, no {object:20807}",
		["{item:5869}, from the {object:20807}"] = "{item:5869}, do {object:20807}",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}, perto do mestre de mantícoras",
		["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "A próxima missão de {npc:10428}, Fogo sagrado, termina em {zone:1456}, fora desta rota. Pule-a.",
		["{npc:10617}'s {quest:4881}, if you meet him"] = "{quest:4881} de {npc:10617}, se você o encontrar",
		["{npc:10645}, inside"] = "{npc:10645}, lá dentro",
		["{npc:11116}, beside {npc:4877}"] = "{npc:11116}, ao lado de {npc:4877}",
		["{npc:12196}, beside her"] = "{npc:12196}, ao lado dela",
		["{npc:12676}, a big nightsaber, prowls the woods south-east of the Warsong lumber camp, on the way north to Splintertree. Her claw starts the next hunt quest."] = "{npc:12676}, uma grande sabre-da-noite, ronda a mata a sudeste do Acampamento de Lenhadores Brado Guerreiro, no caminho para o norte, rumo ao Posto Machadada. A garra dela inicia a próxima missão de caça.",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}, uma pantera das sombras, ronda a mata em volta do {area:426}, a oeste do acampamento Malmíscar. A cabeça dela inicia a próxima missão de caça.",
		["{npc:12696} keeps the hunt board at {area:428}, by the flight master: take {quest:6383} and hand it straight back. {npc:12678}, {npc:12676} and {npc:12677} drop their trophies only after it."] = "{npc:12696} cuida do quadro de caçadas em {area:428}, perto do mestre de voo: pegue {quest:6383} e entregue-a na hora. {npc:12678}, {npc:12676} e {npc:12677} só deixam cair os troféus depois disso.",
		["{npc:12696}, once all three hunts are in"] = "{npc:12696}, depois que as três caçadas forem entregues",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}: só se você tiver as páginas do manual",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736} oferece em seguida uma missão das {area:2797}; deixe-a de lado a menos que tenha um grupo.",
		["{npc:12736} stands in the outpost."] = "{npc:12736} fica no assentamento.",
		["{npc:210995} walks around the {area:1276}: the map marks where to look"] = "{npc:210995} anda por {area:1276}: o mapa marca onde procurar",
		["{npc:210995}, a Forever addition, stands on the west shore of {area:421} with three quick Dragonslayer quests."] = "{npc:210995}, uma novidade do Forever, fica na margem oeste do {area:421} com três missões rápidas de Matadragões.",
		["{npc:259118} offers {quest:96261} only once {quest:96259} is handed in."] = "{npc:259118} só oferece {quest:96261} depois que {quest:96259} for entregue.",
		["{npc:259118}: {quest:96261} comes once this is handed in"] = "{npc:259118}: {quest:96261} vem depois que esta for entregue",
		["{npc:264082} sits at the north end of {area:17044}; her {item:273658} starts {quest:96294}. {npc:264082} is elite: grouping up is advised."] = "{npc:264082} fica na ponta norte de {area:17044}; o {item:273658} dela inicia {quest:96294}. {npc:264082} é elite: é recomendado formar grupo.",
		["{npc:2986} offers {quest:1151} once {quest:1150} is in"] = "{npc:2986} oferece {quest:1151} depois que {quest:1150} for entregue",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986} fica no alto de uma meseta a leste dos acampamentos Galath. Para o {quest:1149}, ande até o fim das tábuas ao lado dele: você cai em segurança.",
		["{npc:2986}'s mesa is north-east of Freewind."] = "A mesa de {npc:2986} fica a nordeste de Vento Livre.",
		["{npc:2986}, below ground"] = "{npc:2986}, no subterrâneo",
		["{npc:3024} stands beside {npc:4721}, east of {npc:2995}."] = "{npc:3024} fica ao lado de {npc:4721}, a leste de {npc:2995}.",
		["{npc:4499}, a hard-hitting rock elemental, walks the cliffs of {area:482}, back west past {area:2237}. {npc:4499} is elite: grouping up is advised."] = "{npc:4499}, um elemental de rocha que bate forte, anda pelos penhascos do {area:482}, de volta a oeste, passando por {area:2237}. {npc:4499} é elite: é recomendado formar grupo.",
		["{npc:4721} stands a short walk east of {npc:2995}."] = "{npc:4721} fica a uma curta caminhada a leste de {npc:2995}.",
		["{npc:4721}: {npc:4722} at {area:484}, later in this guide"] = "{npc:4721}: {npc:4722} em {area:484}, mais adiante neste guia",
		["{npc:4722} stands in {area:484}: {npc:4721}'s filled phial is for him."] = "{npc:4722} fica em {area:484}: o frasco cheio de {npc:4721} é para ele.",
		["{npc:4722}: the {object:20807} in {area:1557}, among the Galak camps"] = "{npc:4722}: o {object:20807} em {area:1557}, entre os acampamentos Galath",
		["{npc:4877}, inside"] = "{npc:4877}, lá dentro",
		["{npc:4877}, the trade supplies vendor: the Screeching harpies of {area:487}; inside the inn"] = "{npc:4877}, a mercadora de suprimentos de profissão: as harpias Guinchadoras do {area:487}; dentro da estalagem",
		["{npc:4877}: her stolen supplies lie in the same harpy den"] = "{npc:4877}: os suprimentos roubados dela estão no mesmo covil de harpias",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole south of {area:378}, on the road to the {area:485}."] = "A cabana de {npc:5899} fica na crista acima do bebedouro dos javatuscos, ao sul de {area:378}, na estrada para {area:485}.",
		["{object:176344}, north-west camp"] = "{object:176344}, acampamento noroeste",
		["{object:176344}, south-east camp"] = "{object:176344}, acampamento sudeste",
		["{object:176344}, south-west camp"] = "{object:176344}, acampamento sudoeste",
		["{object:3646}; below ground"] = "{object:3646}; no subterrâneo",
		["{quest:98069}, on the ground around the den"] = "{quest:98069}, no chão em volta do covil",
		["{zone:1456} flight master"] = "Mestre de voo de {zone:1456}",
		["{zone:1456}'s central rise"] = "Platô central de {zone:1456}",
} end)()
t.guides["forever/horde/30-40/01-hillsbrad-foothills"] = (function() return {
		["Back east to {area:272}."] = "Volte para leste até {area:272}.",
		["Back into the yeti caves west of {area:272} with the {item:3710}. The path splits just inside: the {object:1768} burns on the upper level to the right, the {object:1769} on the lower level to the left, past more yetis."] = "De volta às cavernas dos yetis a oeste de {area:272} com o {item:3710}. O caminho se divide logo na entrada: {object:1768} queima no nível de cima, à direita, e {object:1769} no nível de baixo, à esquerda, depois de mais yetis.",
		["Back north to {area:321}."] = "Volte ao norte até {area:321}.",
		["Back to {area:272}"] = "De volta a {area:272}",
		["Below ground"] = "No subterrâneo",
		["Boulderfist camp"] = "Acampamento Punho de Pedra",
		["Clear {area:290} from the gate in; the dwarves run for help at 30% health."] = "Limpe {area:290} do portão para dentro; os anões correm para pedir ajuda com 30% de vida.",
		["Crossroads flight master"] = "Mestre de voo da Encruzilhada",
		["Daggerspine naga"] = "Nagas Espinhadaga",
		["Daggerspine shore"] = "Margem dos Espinhadaga",
		["Darthalia's last battle is at {area:290}, the dwarven keep south-east of {area:271}: every dwarf there is elite (28-32), {npc:2304} too. Great XP if you have a group for it."] = "A última batalha de Darthalia é em {area:290}, a fortaleza anã a sudeste de {area:271}: todo anão de lá é elite (28-32), {npc:2304} também. Ótima XP se você tiver um grupo.",
		["Fly from {area:484} to {area:1638} and train with {npc:3033} on {area:1639}; fly on to the Crossroads from there."] = "Voe de {area:484} para {area:1638} e treine com {npc:3033} em {area:1639}; de lá, siga voando até a Encruzilhada.",
		["Fly from {area:484} to {area:392}. {npc:5901} camps on the coast a short walk south of the town; fly on to the Crossroads from {area:392}."] = "Voe de {area:484} para {area:392}. {npc:5901} acampa na costa, a uma curta caminhada ao sul da cidade; de {area:392}, siga voando até a Encruzilhada.",
		["Fly to the Crossroads"] = "Voe para a Encruzilhada",
		["Fly to the {area:228}. The {object:113791} stands on the hill just south-west of it: beat the Corrupt Manifestation of Water beside it, place its bracers in the brazier, speak to the {npc:5895} and keep the {item:7813} for {npc:5901}. Fly on to {area:272} from the {area:228}."] = "Voe para {area:228}. {object:113791} fica no morro logo a sudoeste dela: derrote a Manifestação Corrompida da Água ao lado, coloque as braçadeiras dela no braseiro, fale com {npc:5895} e guarde o {item:7813} para {npc:5901}. Siga voando para {area:272} a partir de {area:228}.",
		["Fly to {area:1497}"] = "Voe para {area:1497}",
		["Fly to {area:1637}"] = "Voe para {area:1637}",
		["Fly to {area:272}"] = "Voe para {area:272}",
		["Head back north to {area:272}, east of {area:271}."] = "Volte ao norte até {area:272}, a leste de {area:271}.",
		["Head back north to {area:272}."] = "Volte para o norte até {area:272}.",
		["Head east out of {area:272} through {area:1057} and follow the road east. The Boulderfist Ogres and Enforcers (32-34) camp south of the road, south of {area:313}; the Enforcers stay in the cave there."] = "Saia de {area:272} para leste, passando por {area:1057}, e siga a estrada para leste. Os Ogros e Impositores Punho de Pedra (32-34) acampam ao sul da estrada, ao sul de {area:313}; os Impositores ficam na caverna de lá.",
		["Head east to {area:271}'s graveyard, on the north-east edge of the town: Helcular's grave lies among the others. Come at it from the north and keep away from the town's guards."] = "Siga para leste até o cemitério de {area:271}, na ponta nordeste da vila: o túmulo de Helcular fica entre os outros. Chegue pelo norte e fique longe dos guardas da vila.",
		["Head south past {area:287} town to the {area:288}. Miners work the tunnels; {npc:2305} (30) and {npc:2450} (29) are deep inside."] = "Siga ao sul, passando pela vila de {area:287}, até {area:288}. Mineiros trabalham nos túneis; {npc:2305} (30) e {npc:2450} (29) estão bem lá no fundo.",
		["Head west along the foot of the mountains to the violet dome of {area:279}. {npc:2411}, {npc:2412} and {npc:2413} (33-34) stand together inside the crater's eastern rim, {npc:2414} (35) a little west of them; each carries one Bloodstone piece. The Shield Guards and Theurgists (31-33) around them drop the Worn Stone Tokens. Careful: Many guards stand in linked pairs and others patrol alone around the camp."] = "Siga para oeste pelo pé das montanhas até a cúpula violeta de {area:279}. {npc:2411}, {npc:2412} e {npc:2413} (33-34) ficam juntos na borda leste da cratera, {npc:2414} (35) um pouco a oeste deles; cada um carrega uma peça de Pedra-sangrenta. Os Escudeiros e Teurgos (31-33) em volta deles deixam cair as Fichas de Pedra Gastas. Cuidado: muitos guardas andam em duplas ligadas, e outros patrulham sozinhos em volta do acampamento.",
		["Highland raptors and Plains Creepers"] = "Raptores do Planalto e Rastejantes das Planícies",
		["Inside"] = "Lá dentro",
		["Inside {area:288}"] = "Dentro de {area:288}",
		["Level 30"] = "Nível 30",
		["Level 31"] = "Nível 31",
		["Lydon's next errand is a keg of Shindigger Stout from the cellar of {area:290}, the elite dwarven keep south-east of {area:271}: take it only if you go there with a group."] = "A próxima tarefa de Lindolfo é um barril de Stout do Festeiro da adega de {area:290}, a fortaleza anã de elite a sudeste de {area:271}: só pegue se for lá em grupo.",
		["On the way back north, Highland Striders roam the hills all around {area:321} and drop the eyes, and south of it the Plains Creepers (32-33) spin their webs in the grass; they carry the spidersilk."] = "No caminho de volta ao norte, Andarilhos do Planalto vagam pelas colinas em volta de {area:321} e deixam cair os olhos, e ao sul dela os Rastejantes das Planícies (32-33) tecem suas teias no capim; eles carregam a seda de aranha.",
		["On to {area:287} town, south-west of the yeti caves. The town hall is on the town's west side: {npc:2335} (30) and {npc:2448} are inside with the Town Registry; the Proclamation is pinned up beside it. Councilmen walk the town."] = "Siga para a vila de {area:287}, a sudoeste das cavernas dos yetis. A prefeitura fica no lado oeste da vila: {npc:2335} (30) e {npc:2448} estão lá dentro com o Cartório; a Proclamação está afixada ao lado. Conselheiros andam pela vila.",
		["Place the {object:1729} on the {object:1728} beside the inn; upstairs"] = "Coloque {object:1729} em {object:1728} ao lado da estalagem; no andar de cima",
		["Shindigger keg"] = "Barril do Festeiro",
		["South of Hammerfall, the Witherbark trolls hold the village in the hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village. Careful: All three troll types flee for help at 15% health, which can pull more trolls from the nearby camps."] = "Ao sul de Ruína do Martelo, os trolls Cascasseca ocupam a aldeia nas colinas. Arremessadores de Machado guardam as cabanas de fora; os Mandingueiros e Caçadores de Cabeças ficam no coração da aldeia. Cuidado: os três tipos de troll fogem atrás de ajuda com 15% de vida, o que pode trazer mais trolls dos acampamentos vizinhos.",
		["South-west, the Cave and Ferocious Yetis (30-32) fill the {area:277} in the hills west of {area:272}; about one in sixteen carries the rod."] = "A sudoeste, os Yetis das Cavernas e Yetis Ferozes (30-32) enchem {area:277}, nas colinas a oeste de {area:272}; cerca de um em cada dezesseis carrega o bastão.",
		["Syndicate missives"] = "Missivas da Camarilha",
		["The Daggerspine naga line the shore south-east of the town."] = "As nagas Espinhadaga se enfileiram pela costa a sudeste da cidade.",
		["The Kegs of Shindigger Stout stand in the cellar of {area:290}, the dwarven keep south-east of {area:271}, beside {npc:2304} (32); every dwarf there is elite (28-32)."] = "Os Barris de Stout do Festeiro ficam na adega de {area:290}, a fortaleza anã a sudeste de {area:271}, ao lado de {npc:2304} (32); todo anão de lá é elite (28-32).",
		["The Torn Fin murlocs camp on the beaches south-west of {area:271}'s bay, below the mine."] = "Os murlocs Rancapina acampam nas praias a sudoeste da baía de {area:271}, abaixo da mina.",
		["The orc stronghold at the eastern end of the road. {npc:2851}, the wind rider master, stands by the gate.\n{npc:15126} offers the {quest:8263} only once you are Friendly with the Defilers ({zone:1461}): skip it if he doesn't offer it."] = "A fortaleza orc na ponta leste da estrada. {npc:2851}, o mestre de mantícoras, fica junto ao portão.\n{npc:15126} só oferece {quest:8263} quando você está Amigável com os Profanadores ({zone:1461}): pule se ele não oferecer.",
		["The third flame burns in the smaller cave up in the hills north of the caverns."] = "A terceira chama queima na caverna menor, no alto das colinas ao norte das cavernas.",
		["The {area:279} crater"] = "A cratera de {area:279}",
		["The {area:279} crater's eastern rim"] = "A borda leste da cratera de {area:279}",
		["Torn Fin beach"] = "Praia dos Rancapina",
		["Torn Fin murlocs"] = "Murlocs Rancapina",
		["Town hall"] = "Prefeitura",
		["Train"] = "Treinar",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Treine enquanto estiver em {zone:1458}: os instrutores ficam no {object:36070}, no {object:36073} e no {object:36082} (paladinos: {npc:260093}).",
		["Train your new spells."] = "Treine seus novos feitiços.",
		["Zeppelin to {zone:1458}"] = "Zepelim para {zone:1458}",
		["for {npc:2425} in the {zone:1458}, at the end of this guide"] = "para {npc:2425}, em {zone:1458}, no fim deste guia",
		["for {npc:4483} in the {area:439}, next guide"] = "para {npc:4483} em {area:439}, no próximo guia",
		["for {npc:5901}, next guide"] = "para {npc:5901}, próximo guia",
		["grind on {npc:2248}"] = "mate {npc:2248} até subir",
		["grind on {npc:2562}"] = "mate {npc:2562} até subir",
		["{area:228} flight master"] = "Mestre de voo de {area:228}",
		["{area:272}'s {quest:544}, {quest:556} and {quest:676} are offered from level 30. Below it? Keep killing the yetis in these caves until level 30. Or, with a group, run the {area:796} dungeon (Graveyard) or the {area:2797} dungeon instead."] = "As missões {quest:544}, {quest:556} e {quest:676} de {area:272} são oferecidas a partir do nível 30. Abaixo disso? Continue matando os yetis nestas cavernas até o nível 30. Ou, em grupo, faça a masmorra {area:796} (Cemitério) ou a masmorra {area:2797}.",
		["{area:321} flight master"] = "Mestre de voo de {area:321}",
		["{area:321}'s quests are 32-36. Below 31? Keep killing the Boulderfist Ogres and Enforcers at this camp until level 31. Or, with a group, run the {area:796} dungeon (Graveyard) or the {area:2797} dungeon instead."] = "As missões de {area:321} são de nível 32-36. Abaixo de 31? Continue matando os Ogros e Impositores Punho de Pedra neste acampamento até o nível 31. Ou, em grupo, faça a masmorra {area:796} (Cemitério) ou a masmorra {area:2797}.",
		["{area:392} flight master"] = "Mestre de voo de {area:392}",
		["{area:484} flight master"] = "Mestre de voo de {area:484}",
		["{item:278225}, from Plains Creepers"] = "{item:278225}, dos Rastejantes das Planícies",
		["{item:279469}: an object to loot, by the traitors"] = "{item:279469}: um objeto para saquear, perto dos traidores",
		["{item:3388}: auction house or an alchemist, for {quest:515}."] = "{item:3388}: casa de leilões ou um alquimista, para {quest:515}.",
		["{item:3703}, for {npc:2333}"] = "{item:3703}, para {npc:2333}",
		["{item:6637}: drink it by the standing stone to see the elemental"] = "{item:6637}: beba junto à pedra erguida para ver o elemental",
		["{npc:12920}, at the south gate"] = "{npc:12920}, no portão sul",
		["{npc:2216}, inside"] = "{npc:2216}, lá dentro",
		["{npc:2229} now offers {npc:2316} (level 36): leave it for the 38-39 visit."] = "{npc:2229} agora oferece {npc:2316} (nível 36): deixe para a visita dos níveis 38-39.",
		["{npc:2229}, inside"] = "{npc:2229}, lá dentro",
		["{npc:2410}, inside"] = "{npc:2410}, lá dentro",
		["{npc:2410}, inside: offered from level 30"] = "{npc:2410}, lá dentro: oferecida a partir do nível 30",
		["{npc:2410}: for the 38-39 visit to Alterac"] = "{npc:2410}: para a visita aos níveis 38-39 em Alterac",
		["{npc:2410}: he offers {quest:545} after it"] = "{npc:2410}: ele oferece {quest:545} depois disso",
		["{npc:2410}: {quest:93680}, the {item:279469} is by the traitors"] = "{npc:2410}: {quest:93680}; {item:279469} fica perto dos traidores",
		["{npc:2419}'s sword drops from the same {area:290} dwarves (about one in twelve)."] = "A espada de {npc:2419} cai dos mesmos anões de {area:290} (cerca de um em doze).",
		["{npc:2425} stands beside Sylvanas in the {object:36126}."] = "{npc:2425} fica ao lado de Sylvana em {object:36126}.",
		["{npc:2425}: Darthalia's commendation"] = "{npc:2425}: a recomendação de Darthalia",
		["{npc:2437}, inside"] = "{npc:2437}, lá dentro",
		["{npc:2437}, inside: offered from level 30"] = "{npc:2437}, lá dentro: oferecida a partir do nível 30",
		["{npc:2437}: for the 38-39 visit to Alterac"] = "{npc:2437}: para a visita aos níveis 38-39 em Alterac",
		["{npc:260093} trains Paladins in the {zone:1458}."] = "{npc:260093} treina Paladinos em {zone:1458}.",
		["{npc:2706}'s Guile of the Raptor, {npc:2771}'s next {quest:677} and the doctor's Ward Restocking wait for the 38-39 visit."] = "A astúcia dos raptores de {npc:2706}, a próxima {quest:677} de {npc:2771} e o Reabastecimento de Proteção do doutor ficam para a visita dos níveis 38-39.",
		["{npc:2706}: its Syndicate are by the road in from {area:272}, on the 38-39 visit"] = "{npc:2706}: a Camarilha de lá fica junto à estrada que vem de {area:272}, na visita dos níveis 38-39",
		["{npc:2770}: for {npc:2771} in {area:321}, later in this guide (from level 30)"] = "{npc:2770}: para {npc:2771} em {area:321}, mais adiante neste guia (a partir do nível 30)",
		["{npc:2792}, by the gate"] = "{npc:2792}, junto ao portão",
		["{npc:3428} stands beside the Crossroads flight master."] = "{npc:3428} fica ao lado do mestre de voo da Encruzilhada.",
		["{npc:3428}: for {npc:4485} in {zone:1454}"] = "{npc:3428}: para {npc:4485} em {zone:1454}",
		["{npc:4485} stands in the {object:172958}, on the way out to the main gate."] = "{npc:4485} fica em {object:172958}, no caminho para o portão principal.",
		["{npc:4949} waits in Grommash Hold, in the {object:172957}."] = "{npc:4949} espera na Fortaleza Grommash, em {object:172957}.",
		["{npc:4949}, Grommash Hold, if you carry it"] = "{npc:4949}, Fortaleza Grommash, se você a tiver",
		["{npc:5901}: your {item:6637}, for the brazier"] = "{npc:5901}: {item:6637}, para o braseiro",
		["{object:1761}, inside"] = "{object:1761}, lá dentro",
		["{quest:515} needs a {item:3388}, an {skill:171} item: buy one at the auction house if you can (or ask an alchemist). The quest text says Strong, but it takes a {item:3388}. No elixir: skip the Elixir steps in {area:287}."] = "{quest:515} precisa de um {item:3388}, um item de {skill:171}: compre um na casa de leilões se puder (ou peça a um alquimista). O texto da missão diz Forte, mas ela pede um {item:3388}. Sem elixir: pule as etapas de Elixir em {area:287}.",
		["{quest:515} with a group"] = "{quest:515} com um grupo",
		["{quest:539} with a group"] = "{quest:539} com um grupo",
		["{quest:547} with a group"] = "{quest:547} com um grupo",
		["{zone:1456} flight master"] = "Mestre de voo de {zone:1456}",
		["{zone:1458} flight master"] = "Mestre de voo de {zone:1458}",
		["{zone:1458} trainers"] = "Instrutores de {zone:1458}",
} end)()
t.guides["forever/horde/30-40/02-thousand-needles"] = (function() return {
		["Back south to {npc:11863}'s tower."] = "De volta ao sul, até a torre de {npc:11863}.",
		["Back west to {npc:11863}."] = "De volta ao oeste, até {npc:11863}.",
		["Clam beds"] = "Leitos de mariscos",
		["East onto the flats. The Saltstone Basilisks (30-31) sun themselves north-west of it; the Sparkleshell tortoises crowd round a half-buried ship in the north-east, and the Salt Flats Scavengers and Vultures circle the eastern flats. Every vulture drops a bone, about one tortoise in three a shell.\nCareful: Scavengers and Vultures use Execute when your health is low; the Snappers (34-35) hit hardest of the tortoises."] = "A leste, rumo às planícies. Os Basiliscos Sal-gema (30-31) tomam sol a noroeste delas; as tartarugas Quelobrilho se aglomeram em volta de um navio meio enterrado no nordeste, e os Catadores da Planície Salgada e os Abutres rodeiam as planícies do leste. Todo abutre solta um osso, e cerca de uma tartaruga em três solta uma casca.\nCuidado: Catadores e Abutres usam Executar quando a sua vida está baixa; as Tartaliscas (34-35) são as que batem mais forte entre as tartarugas.",
		["Fly from {zone:1454} to {area:1638} and train with {npc:3033} on {area:1639}; fly on to {area:484} from there."] = "Voe de {zone:1454} para {area:1638} e treine com {npc:3033} em {area:1639}; de lá, siga voando até {area:484}.",
		["Fly from {zone:1454} to {area:392}. {npc:5901} camps on the coast a short walk south of the town; fly on to {area:484} from {area:392}."] = "Voe de {zone:1454} para {area:392}. {npc:5901} acampa na costa, a uma curta caminhada ao sul da cidade; de {area:392}, siga voando até {area:484}.",
		["Fly to {area:460}"] = "Voar para o {area:460}",
		["Fly to {area:484}"] = "Voe para {area:484}",
		["Giant Softshell Clams, on the sea floor"] = "Mariscos de Casca Mole Gigantes, no fundo do mar",
		["Head east past {area:599} and along the northern hills to the satyrs' ruins of {area:603}. Kill every kind you meet for {npc:268705}; the Shadowstalkers walk unseen.\nCareful: Hatefury Rogues use Hide when they spawn, so they are stealthed until you find them."] = "Siga para leste, passando por {area:599} e pelas colinas do norte, até as ruínas dos sátiros de {area:603}. Mate todos os tipos que encontrar para {npc:268705}; os Assombrantes andam sem serem vistos.\nCuidado: os Errantes Furiódio usam Esconder ao surgir, então ficam furtivos até você encontrá-los.",
		["Head east to {area:599}. Beat a Burning Blade cultist down, then use the {item:6436} on it before it dies to fill one {item:6435}. The {npc:13019} stands on the fortress's top floor with the Sceptre. The cultists also drop a {item:20310} now and then (1-5%); if one drops, read it. {quest:5381}: clear the middle of the largest building, then use the {item:14523} on the red {object:176581} there. A {npc:11876} (37) comes out: kill it for the {item:13542}."] = "Siga para leste até {area:599}. Derrube um sectário da Lâmina Ardente e use {item:6436} nele antes que morra, para obter {item:6435}. {npc:13019} fica no último andar da fortaleza com o Cetro. Os sectários também deixam cair {item:20310} de vez em quando (1-5%); quando cair, leia. {quest:5381}: limpe o meio do maior prédio e use {item:14523} no {object:176581} vermelho de lá. Um {npc:11876} (37) aparece: mate-o para pegar {item:13542}.",
		["Head north along the coast, then inland to the ruined tower of {area:2405}: {npc:11863} waits inside. The coast's clams and naga come after {area:599}, on one walk north to {area:2406}."] = "Siga para o norte pela costa e depois para o interior, até a torre em ruínas de {area:2405}: {npc:11863} espera lá dentro. Os mariscos e as nagas da costa ficam para depois de {area:599}, numa só caminhada para o norte até {area:2406}.",
		["Head south out of Stonetalon into {zone:1443} and follow the road south to {npc:11596}'s camp."] = "Siga para o sul, saindo de Torres de Pedra, até {zone:1443}, e continue pela estrada para o sul até o acampamento de {npc:11596}.",
		["Head west to the troll village on the coast, keeping clear of the {area:606} on the way. {npc:268705} stands on the path just north of the village.\n{npc:268705} may not be here on Forever: if {npc:268705} doesn't offer {quest:97265}, skip it."] = "Siga para oeste até a vila troll na costa, mantendo distância de {area:606} no caminho. {npc:268705} fica na trilha logo ao norte da vila.\n{npc:268705} pode não estar aqui no Forever: se {npc:268705} não oferecer {quest:97265}, pule.",
		["Keep killing silithid at the dig site for the heart, the talons and the carapaces."] = "Continue matando silitídeos no sítio de escavação, pelo coração, pelas garras e pelas carapaças.",
		["Keep north to {area:598}. The Slitherblade Myrmidons, Naga and Sorceresses hold the beach; pull them one at a time. Any Slitherblade can drop {item:15881}."] = "Continue ao norte até {area:598}. Os Mirmidões, Nagas e Feiticeiras Sibilâmina ocupam a praia; puxe-os um de cada vez. Qualquer Sibilâmina pode soltar {item:15881}.",
		["Level 32.5"] = "Nível 32.5",
		["Level 33"] = "Nível 33",
		["North from the dig to {npc:4483}'s camp on the western edge of the flats."] = "Ao norte da escavação, até o acampamento de {npc:4483}, na borda oeste das planícies.",
		["On the top floor"] = "No último andar",
		["Run {area:133} with a group when it suits you: {npc:7800} at the end drops his Safe Combination; open his safe behind the northern bomb pillar for the {item:9153}."] = "Faça {area:133} em grupo quando for conveniente: {npc:7800}, no fim, deixa cair a Combinação do Cofre dele; abra o cofre dele atrás do pilar de bomba do norte para pegar o {item:9153}.",
		["Scorpashi Lashers"] = "Escorpachis Açoitadores",
		["Shadowprey's {quest:5381} and the coast's naga want 33. Below that? The Scorpashi Lashers on the slopes north of {npc:11596}'s camp are on your way west: kill them until level 33. Or, with a group, run the {area:796} dungeon (Library) instead."] = "{quest:5381}, de Pescassombra, e as nagas da costa pedem nível 33. Abaixo disso? Os Escorpachis Açoitadores nas encostas ao norte do acampamento de {npc:11596} ficam no seu caminho para oeste: mate-os até o nível 33. Ou, em grupo, faça a masmorra {area:796} (Biblioteca).",
		["South of the raceway, the Saltstone Crystalhides (32-33) and Gazers (34-35) roam the far end of the flats."] = "Ao sul do circuito, os Cristaldermes Sal-gema (32-33) e os Observadores (34-35) vagam pela outra ponta das planícies.",
		["South to {area:609}. {quest:1365} (35) walks among the tents on the east side with a Battle Lord or two (32-33): clear around him, then pull him alone at full health.\nCareful: Kolkar Battle Lords call nearby allies within 30 yd once they fall to 20% health."] = "Ao sul, até {area:609}. {quest:1365} (35) anda entre as tendas do lado leste com um ou dois Senhores de Batalha (32-33): limpe em volta dele, depois puxe-o sozinho, com vida cheia.\nCuidado: os Senhores de Batalha Kolkar chamam aliados num raio de 30 metros quando caem a 20% de vida.",
		["South-west back to the raceway."] = "De volta ao sudoeste, até o circuito.",
		["South-west down the road to the post."] = "Desça a estrada para o sudoeste até o posto.",
		["Sparkleshell Snappers"] = "Tartaliscas Quelobrilho",
		["Swim out to {area:2406} off the far northern tip and use the {item:15766} on the {object:177673}: {npc:12369} (38) rises; kill him for the {quest:6027}. He is well above you: rest to full first. {object:177786} stands on the shore beside the statue: open it with both keys."] = "Nade até {area:2406}, no extremo norte, e use {item:15766} no {object:177673}: surge {npc:12369} (38); mate-o para pegar {quest:6027}. Ele está bem acima do seu nível: descanse até ficar com vida cheia antes. {object:177786} fica na margem ao lado da estátua: abra-o com as duas chaves.",
		["Take the lift down and follow the canyon east. {npc:4483} camps on the north-western edge of the salt flats."] = "Desça de elevador e siga o cânion para o leste. {npc:4483} acampa na borda noroeste das planícies de sal.",
		["The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Os goblins e gnomos de {area:2240} são neutros e dão missões às duas facções.",
		["The southern flats"] = "As planícies do sul",
		["The zeppelin lands at the tower outside {zone:1454}'s main gate. {npc:5639} walks the Drag: if he isn't at the arrow, look along its streets to the south-west. {npc:5640} stands in the {object:172961} on the west side of the city."] = "O zepelim pousa na torre fora do portão principal de {zone:1454}. {npc:5639} anda pelo Drag: se ele não estiver na seta, procure pelas ruas do Drag a sudoeste. {npc:5640} fica em {object:172961}, no lado oeste da cidade.",
		["The {quest:6027}"] = "O {quest:6027}",
		["Train while you are in the city."] = "Treine enquanto estiver na cidade.",
		["Underwater"] = "Debaixo d'água",
		["Use {npc:11596}'s {item:13892} on an Aged, Dying or {npc:4702} in the graveyard and walk the tamed kodo back to {npc:11596}. At his camp, talk to the kodo: that counts it and lets you tame the next. Five kodos, one at a time."] = "Use o {item:13892} de {npc:11596} num Kodo Idoso, Moribundo ou {npc:4702} no cemitério e leve o kodo domado de volta a {npc:11596}. No acampamento dele, fale com o kodo: isso o conta e deixa você domar o próximo. Cinco kodos, um de cada vez.",
		["West back to {area:484}. {npc:10537} stands in the middle of the post, on the way to the flight master."] = "De volta a oeste, até {area:484}. {npc:10537} fica no meio do posto, no caminho para o mestre de voo.",
		["West of them the silithid swarm the dig site. Searchers and Hive Drones walk among the mounds; the Invaders (34-35) stay inside the hive cave. The first silithid you kill drops a {item:5877}: open it.\nCareful: Hive Drones call for help when they fall to 20% health."] = "A oeste deles, os silitídeos enxameiam o sítio de escavação. Buscadores e Zangões da Colmeia andam entre os montes; os Invasores (34-35) ficam dentro da caverna da colmeia. O primeiro silitídeo que você matar solta uma {item:5877}: abra-a.\nCuidado: os Zangões da Colmeia chamam ajuda quando caem para 20% de vida.",
		["West to Shadowprey: your hearthstone is bound there."] = "A oeste, até Pescassombra: sua Pedra de Regresso está vinculada lá.",
		["West to the shore. Giant Softshell Clams lie in the shallows and the Enraged Reef Crawlers walk the beach: each clam you open on the sea floor, and some crawlers, give a {item:15874}. Open each one in your bags for its meat.\nThe Drysnap Crawlers and Pincers on the same beach carry {item:15878}, about one in seven."] = "A oeste, até a praia. Mariscos de Casca Mole Gigantes ficam nas águas rasas e os Tiscorais Enfurecidos andam pela praia: cada marisco que você abrir no fundo do mar, e alguns tiscorais, dão {item:15874}. Abra cada um nas bolsas para pegar a carne.\nOs Rastejadores e as Pinças Estalasseca da mesma praia carregam {item:15878}, cerca de um em cada sete.",
		["Zeppelin to {zone:1454}"] = "Zepelim para {zone:1454}",
		["for the second {zone:1443} visit, in forever/horde/30-40/04-dustwallow-marsh"] = "para a segunda visita a {zone:1443}, em forever/horde/30-40/04-dustwallow-marsh",
		["for {npc:5641} in {zone:1443}, later in this guide"] = "para {npc:5641}, em {zone:1443}, mais adiante neste guia",
		["grind on {npc:4143}"] = "mate {npc:4143} até subir",
		["grind on {npc:4697}"] = "mate {npc:4697} até subir",
		["{area:392} flight master"] = "Mestre de voo de {area:392}",
		["{area:439}: kill these as you meet them"] = "{area:439}: vá matando estes pelo caminho",
		["{area:484} flight master"] = "Mestre de voo de {area:484}",
		["{item:14523}, on the {object:176581}"] = "{item:14523}, no {object:176581}",
		["{item:15766}, on the {object:177673}"] = "{item:15766}, no {object:177673}",
		["{item:15874}: open it in your bags"] = "{item:15874}: abra nas bolsas",
		["{item:15878}, from the Drysnap crabs"] = "{item:15878}, dos caranguejos Secoestalo",
		["{item:15881}, from the Slitherblade naga"] = "{item:15881}, das nagas Sibilâmina",
		["{npc:10537}: for {npc:11259} in {zone:1443}, next"] = "{npc:10537}: para {npc:11259}, em {zone:1443}, em seguida",
		["{npc:11259}, up on the rise"] = "{npc:11259}, no alto da elevação",
		["{npc:11624}'s Portals of the Legion and {zone:1443}'s other 38-40 quests wait for the second visit, at 38: the next guides fly to {zone:1454} and take the zeppelin to {zone:1434}."] = "Os Portais para a Legião de {npc:11624} e as outras missões de {zone:1443} dos níveis 38-40 ficam para a segunda visita, no nível 38: os próximos guias voam para {zone:1454} e pegam o zepelim para {zone:1434}.",
		["{npc:11877}: for {quest:5762} in Stranglethorn, next guide"] = "{npc:11877}: para {quest:5762}, na Selva do Espinhaço, no próximo guia",
		["{npc:268705}, on the path just north of the village"] = "{npc:268705}, na trilha logo ao norte da aldeia",
		["{npc:268705}: the Hatefury satyrs of {area:603}, later in this guide"] = "{npc:268705}: os sátiros Furiódio de {area:603}, mais adiante neste guia",
		["{npc:3412}'s workshop is in the {object:172958}. {quest:2841} is {area:133}'s last boss: great XP if you run it with a group. Run it whenever your group is ready; hand it in on a later {zone:1454} stop."] = "A oficina de {npc:3412} fica em {object:172958}. {quest:2841} é o último chefe de {area:133}: ótima XP se você for com um grupo. Faça quando o seu grupo estiver pronto; entregue em uma parada posterior em {zone:1454}.",
		["{npc:4452}'s crate for {quest:5762} in Stranglethorn, later on the route"] = "A caixa de {npc:4452} para {quest:5762}, na Selva do Espinhaço, mais adiante na rota",
		["{npc:4452}: his parts order goes to {quest:1111} in {area:392}, later on the route"] = "{npc:4452}: o pedido de peças dele vai para {quest:1111} em {area:392}, mais adiante na rota",
		["{npc:4454}: his letter goes to Martek in the {zone:1418}, at 39"] = "{npc:4454}: a carta dele vai para Martek, em {zone:1418}, no nível 39",
		["{npc:4630}: for Gazlowe in {area:392}, later on the route"] = "{npc:4630}: para Gazlowe em {area:392}, mais adiante na rota",
		["{npc:4671}, on the way south"] = "{npc:4671}, no caminho para o sul",
		["{npc:5395} stands in the post, {npc:11259} up on its rise; {npc:5641} and {npc:4498} wait on the rise west of it, above the {area:596}."] = "{npc:5395} fica no posto, {npc:11259} no alto da elevação; {npc:5641} e {npc:4498} esperam na elevação a oeste dela, acima de {area:596}.",
		["{npc:5639}: offered from level 30"] = "{npc:5639}: oferecida a partir do nível 30",
		["{npc:5641}'s next errand sends you after a demon lord with an elite guard: skip it."] = "A próxima tarefa de {npc:5641} manda você atrás de um senhor demoníaco com uma guarda de elite: pule-a.",
		["{npc:5641}: for {npc:5640} in {zone:1454}, next guide"] = "{npc:5641}: para {npc:5640}, em {zone:1454}, no próximo guia",
		["{npc:5892} stands in the {object:172957}."] = "{npc:5892} fica no {object:172957}.",
		["{npc:5892}: for {npc:5905} by {area:484}, later in this guide"] = "{npc:5892}: para {npc:5905} perto de {area:484}, mais adiante neste guia",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}: {npc:3527} e seu {item:5177}",
		["{npc:5905} also starts Elemental Aid ({area:1717}), the 33-40 chain to The Tempest's Weapons: forever/class/shaman/call-of-air-horde."] = "{npc:5905} também inicia Elemental Aid ({area:1717}), a série 33-40 até The Tempest's Weapons: forever/class/shaman/call-of-air-horde.",
		["{npc:5905} hides in a small cave in the canyon wall north-east of the post, on the way east."] = "{npc:5905} se esconde numa pequena caverna na parede do cânion a nordeste do posto, no caminho para o leste.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}: seu {item:5178}",
		["{npc:6726}, at the village's south-west end"] = "{npc:6726}, na ponta sudoeste da aldeia",
		["{object:177787} lies on the ground just south-west of {npc:11863}'s tower, on the way down to the shore: read it. Its two keys drop only while you have the quest."] = "{object:177787} fica no chão logo a sudoeste da torre de {npc:11863}, no caminho para a praia: leia-o. As duas chaves só caem enquanto você tiver a missão.",
		["{object:19868}, all over the northern flats"] = "{object:19868}, por todas as planícies do norte",
		["{quest:1104}, from the Scorpid Reavers of the north half"] = "{quest:1104}, dos Aniquiladores Escorpídeos da metade norte",
		["{zone:1443}'s quests are 33-38. Still below 32.5 after the raceway's hand-ins? Keep killing the Sparkleshell Snappers on the flats just north of the raceway until level 32.5. Or, with a group, run the {area:796} dungeon (Graveyard or Library) instead."] = "As missões de {zone:1443} são de nível 33-38. Ainda abaixo de 32.5 depois das entregas do circuito? Continue matando as Tartaliscas Quelobrilho nas planícies logo ao norte do circuito até o nível 32.5. Ou, em grupo, faça a masmorra {area:796} (Cemitério ou Biblioteca).",
		["{zone:1454} flight master"] = "Mestre de voo de {zone:1454}",
		["{zone:1454} trainers"] = "Instrutores de {zone:1454}",
		["{zone:1456} flight master"] = "Mestre de voo de {zone:1456}",
} end)()
t.guides["forever/horde/30-40/03-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "De volta ao norte, até o acampamento.",
		["Back to {area:1637}"] = "De volta a {area:1637}",
		["Back to {object:3202}."] = "De volta a {object:3202}.",
		["Boat to {area:35}"] = "Barco para {area:35}",
		["Dizzywig's parts go back to Kravel in the {area:439}, off the route: leave them."] = "As peças de Dizzywig voltam para Kravel em {area:439}, fora da rota: deixe-as.",
		["Dustwallow's quests are 35-38. Still below 36 after {object:3202}'s hand-ins? The Mosh'Ogg Brutes and Witch Doctors camp in the hills just east of the camp: kill them until level 36, pulling one at a time, then walk back to the zeppelin tower. Or, with a group, run the {area:796} dungeon (Armory) or the {area:1316} dungeon instead."] = "As missões de Pântano Vadeoso são de nível 35-38. Ainda abaixo de 36 depois das entregas de {object:3202}? Os Brutamontes e Mandingueiros Mosh'Ogg acampam nas colinas logo a leste do acampamento: mate-os até o nível 36, puxando um de cada vez, e depois volte a pé até a torre do zepelim. Ou, em grupo, faça a masmorra {area:796} (Armaria) ou a masmorra {area:1316}.",
		["East of the Mosh'Ogg hills, Shadowmaw Panthers (37-38) stalk the jungle towards the lake; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}. Careful: Shadowmaw Panthers (level 37-38) and Elder Shadowmaw Panthers (level 42-43) use Sneak while out of combat, so they remain hidden until you get near them."] = "A leste das colinas de Mosh'Ogg, as Panteras Umbragorja (37-38) espreitam a selva rumo ao lago; as Tigresas-do-espinhaço andam pela mesma área e de vez em quando deixam cair uma presa imaculada. Crocoliscos Arapuca tomam o rio logo a oeste da selva; guarde as peles para {npc:2495}. Cuidado: as Panteras Umbragorja (nível 37-38) e as Panteras Umbragorja Anciãs (nível 42-43) ficam furtivas fora de combate, então só aparecem quando você chega perto.",
		["Elder Stranglethorn Tigers"] = "Tigres-do-espinhaço Anciões",
		["Fly from {area:2408} to {area:1638} and train with {npc:3033} on {area:1639}; fly on to {zone:1454} from there."] = "Voe de {area:2408} para {area:1638} e treine com {npc:3033} em {area:1639}; de lá, siga voando até {zone:1454}.",
		["Fly to {area:1637}"] = "Voe para {area:1637}",
		["Fly to {area:35}"] = "Voe até {area:35}",
		["Fly to {area:392}"] = "Voe até {area:392}",
		["Fly to {object:3202}"] = "Voe até {object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. {npc:773} wants it investigated: walk among its tents. From here on, keep every page of {quest:338} you loot: {npc:716} takes them on your next Stranglethorn visit."] = "Siga a estrada para o norte saindo de {object:3202}; o acampamento de caça de Rosarães Guima fica na colina a nordeste do rio. {npc:773} quer que ele seja investigado: ande entre as tendas. Daqui em diante, guarde toda página de {quest:338} que saquear: {npc:716} as recebe na sua próxima visita à Selva do Espinhaço.",
		["Green Hills pages"] = "Páginas de Grande Espinhaço: Veredas",
		["Lashtail Raptors"] = "Raptores Batecauda",
		["Leave {area:35} through the tunnel and follow the road north to {object:3202}, the orc camp on the west side of the vale. Stay on the road: the jungle beside it is above your level."] = "Saia de {area:35} pelo túnel e siga a estrada para o norte até {object:3202}, o acampamento orc no lado oeste do vale. Fique na estrada: a selva ao lado está acima do seu nível.",
		["Level 35"] = "Nível 35",
		["Level 36"] = "Nível 36",
		["Mosh'Ogg camp"] = "Acampamento Mosh'Ogg",
		["Nesingwary's camp"] = "Acampamento de Rosarães Guima",
		["North-west of Grom'gol the {area:104} lies under the water off the coast. The {item:4094} rests on the sea floor by the sunken ruins; watch your breath and the murlocs."] = "A noroeste do Acampamento Grom'gol, {area:104} fica sob a água, perto do litoral. O {item:4094} está no fundo do mar, junto às ruínas submersas; cuidado com o fôlego e com os murlocs.",
		["On your way back south to {object:3202}, the Lashtail Raptors (35-36) hunt the jungle between the camp and {object:3202}: they count for Hemet and for {npc:2464}."] = "Na volta para o sul, até {object:3202}, os Raptores Batecauda (35-36) caçam na selva entre o acampamento e {object:3202}: eles contam para Rosarães e para {npc:2464}.",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. {npc:716} takes the chapters on your next Stranglethorn visit, at about 40."] = "As páginas de {item:2755} caem com cerca de 1% cada dos trolls Sanguescalpo e Rachacrânio; guarde toda página que saquear e procure o resto na casa de leilões. {npc:716} recebe os capítulos na sua próxima visita à Selva do Espinhaço, por volta do nível 40.",
		["River Crocolisks lie along the river below the camp. Young Stranglethorn Tigers prowl west of the camp, Young Panthers east of it. Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it. Careful: The troll camps have many patrolling mobs, so other trolls often join a fight."] = "Crocoliscos do Rio ficam ao longo do rio, abaixo do acampamento. Tigres-do-espinhaço Jovens rondam a oeste do acampamento, Panteras Jovens a leste dele. Siga para oeste, passando pelo acampamento. Raptores-do-espinhaço (33-34) caçam nas clareiras, e os trolls Sanguescalpo ocupam as ruínas da costa: qualquer Sanguescalpo pode deixar cair uma presa. {item:4614} cai muito raramente deles: se cair, leia. Cuidado: os acampamentos troll têm muita patrulha, então outros trolls costumam entrar na briga.",
		["Stranglethorn Tigers (32) roam the hills around the camp and south of it, Panthers (32) the clearings west and south-west of it. The Venture Co. Geologists, who carry the Tumbled Crystals, work the camps by {area:37}, south-east of the camp."] = "Tigres-do-espinhaço (32) vagam pelas colinas em volta do acampamento e ao sul dele, Panteras (32) pelas clareiras a oeste e sudoeste. Os Geólogos da Empreendimentos S.A., que carregam os Cristais Rolados, trabalham nos acampamentos perto de {area:37}, a sudeste do acampamento.",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads.\nThe Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of {quest:338}."] = "Os Caçadores de Cabeças Sanguescalpo (36-37) da aldeia da costa carregam as cabeças encolhidas.\nOs trolls Sanguescalpo ocupam as ruínas costa acima, ao norte do recife, e a aldeia mais adiante; qualquer um pode deixar cair um {item:3915}. Continue saqueando as páginas de {quest:338}.",
		["The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp. Careful: Troll camps are close to the tiger area, and trolls can join a fight if you pull carelessly."] = "Os Tigres-do-espinhaço Anciões (34-35) vagam pelas colinas a sudoeste do acampamento. Cuidado: acampamentos de trolls ficam perto da área dos tigres, e os trolls podem entrar na briga se você puxar sem cuidado.",
		["The Mosh'Ogg ogres camp in the hills just east of {object:3202}, on your way back. Kill 10 Brutes and 5 Witch Doctors (36-37); pull them one at a time."] = "Os ogros Mosh'Ogg acampam nas colinas logo a leste de {object:3202}, no seu caminho de volta. Mate 10 Brutamontes e 5 Mandingueiros (36-37); puxe um de cada vez.",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "As Panteras Umbragorja vêm bem mais tarde, perto de {object:3202}",
		["The next guide takes the zeppelin to {zone:1454} from the tower on the west side of the camp."] = "O próximo guia pega o zepelim para {zone:1454} na torre do lado oeste do acampamento.",
		["Train while you are in the city."] = "Treine enquanto estiver na cidade.",
		["Underwater"] = "Debaixo d'água",
		["West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear.\n{npc:729}, a level 37 tiger, prowls the hilltop south-west of the camp.\nCareful: The raptor nest has young raptors that join the fight when you attack the adults."] = "A oeste do acampamento, Basiliscos da Serra dos Cristais (34-35) ficam nas pedras; qualquer Sanguescalpo da aldeia mais adiante pode deixar cair uma orelha.\n{npc:729}, um tigre de nível 37, ronda o alto do morro a sudoeste do acampamento.\nCuidado: o ninho de raptores tem filhotes que entram na briga quando você ataca os adultos.",
		["from {npc:4723}"] = "de {npc:4723}",
		["grind on {npc:1142}"] = "mate {npc:1142} até subir",
		["grind on {npc:686}"] = "mate {npc:686} até subir",
		["{area:100}: kill these as you meet them"] = "{area:100}: vá matando estes pelo caminho",
		["{area:102}: kill these as you meet them"] = "{area:102}: vá matando estes pelo caminho",
		["{area:2408} flight master"] = "Mestre de voo da {area:2408}",
		["{area:301}: kill these as you meet them"] = "{area:301}: vá matando estes pelo caminho",
		["{area:35} first: the goblins' boat sails there from {area:392}, and every {area:35} quest is for the north of the vale, which you then walk up into."] = "Primeiro {area:35}: o barco dos goblins sai de {area:392} para lá, e todas as missões de {area:35} são para o norte do vale, até onde você depois segue a pé.",
		["{area:35} flight master"] = "Mestre de voo de {area:35}",
		["{area:35}'s and {object:3202}'s next quests are 35-38. Still below 35 after Aggro'gosh's hand-in? The Lashtail Raptors (35) hunt the jungle just north of {object:3202}: kill them until level 35. Or, with a group, run the {area:796} dungeon (Library or Armory) instead."] = "As próximas missões de {area:35} e {object:3202} são de nível 35-38. Ainda abaixo de 35 depois da entrega a Aggro'gosh? Os Raptores Batecauda (35) caçam na selva logo ao norte de {object:3202}: mate-os até o nível 35. Ou, em grupo, faça a masmorra {area:796} (Biblioteca ou Armaria).",
		["{item:5852}, in {object:20691}"] = "{item:5852}, em {object:20691}",
		["{npc:2464} stands in the middle of {object:3202}, {npc:2497} near the zeppelin tower, {npc:2465} beside the flight master."] = "{npc:2464} fica no meio de {object:3202}, {npc:2497} perto da torre do zepelim, e {npc:2465}, ao lado do mestre de voo.",
		["{npc:2465}: for forever/horde/40-50/01-stranglethorn-vale"] = "{npc:2465}: para forever/horde/40-50/01-stranglethorn-vale",
		["{npc:2465}: the Shadowmaw claws and the tigress fang come at the end of this guide"] = "{npc:2465}: as garras das panteras Umbragorja e a presa da tigresa ficam para o fim deste guia",
		["{npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs beside the flight master."] = "A loja de {npc:2495} fica no prédio a leste da estalagem; {npc:2498} está no andar de baixo da estalagem, e {npc:2496}, {npc:737} e {npc:773}, no andar de cima, ao lado do mestre de voo.",
		["{npc:2495}, inside"] = "{npc:2495}, lá dentro",
		["{npc:2496}, upstairs"] = "{npc:2496}, no andar de cima",
		["{npc:2496}: Cozzle's footlocker is at {area:37}, later in this guide"] = "{npc:2496}: o baú de Cozzle fica em {area:37}, mais adiante neste guia",
		["{npc:2496}: for Pozzik at the {area:2240}, on the way to {zone:1446} around level 43"] = "{npc:2496}: para Pozzik em {area:2240}, a caminho de {zone:1446} por volta do nível 43",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}: para o Planalto Arathi, mais adiante na rota",
		["{npc:2497}: for forever/horde/40-50/01-stranglethorn-vale"] = "{npc:2497}: para forever/horde/40-50/01-stranglethorn-vale",
		["{npc:2498}, inside"] = "{npc:2498}, lá dentro",
		["{npc:2498}, inside, on the bottom floor"] = "{npc:2498}, lá dentro, no andar de baixo",
		["{npc:3391} waits upstairs in the house by the flight master; {quest:1111} stands on the docks, beside the boat."] = "{npc:3391} espera no andar de cima da casa ao lado do mestre de voo; {quest:1111} fica nas docas, ao lado do barco.",
		["{npc:3391}, upstairs"] = "{npc:3391}, no andar de cima",
		["{npc:3391}: for {npc:4631} in {area:35}, where the boat goes"] = "{npc:3391}: para {npc:4631} em {area:35}, para onde o barco vai",
		["{npc:4631} stands on the pier where the boat docks. {npc:2495}'s shop is in the building east of the inn; {npc:2498} is on the inn's bottom floor, {npc:2496}, {npc:737} and {npc:773} upstairs, {npc:2858} the flight master on the upper deck."] = "{npc:4631} fica no píer onde o barco atraca. A loja de {npc:2495} fica no prédio a leste da estalagem; {npc:2498} está no andar de baixo da estalagem, {npc:2496}, {npc:737} e {npc:773} no andar de cima, e {npc:2858}, o mestre de voo, no deque superior.",
		["{npc:4631}, on the pier"] = "{npc:4631}, no píer",
		["{npc:4723} (38) is inside the Venture Co. house on {area:37}'s west shore, among the geologists: his key opens {object:20691} in the same house, which holds the blueprints for {npc:2496}."] = "{npc:4723} (38) está dentro da casa da Empreendimentos S.A. na margem oeste de {area:37}, entre os geólogos: a chave dele abre {object:20691} na mesma casa, que guarda as plantas para {npc:2496}.",
		["{npc:5640} stands in the {object:172961} on the west side of the city."] = "{npc:5640} fica em {object:172961}, no lado oeste da cidade.",
		["{npc:737}, upstairs"] = "{npc:737}, no andar de cima",
		["{npc:773}, upstairs"] = "{npc:773}, no andar de cima",
		["{object:3202} flight master"] = "Mestre de voo de {object:3202}",
		["{quest:1111}, on the docks"] = "{quest:1111}, nas docas",
		["{zone:1434}: kill these as you meet them"] = "{zone:1434}: vá matando estes pelo caminho",
		["{zone:1454} flight master"] = "Mestre de voo de {zone:1454}",
		["{zone:1454} trainers"] = "Instrutores de {zone:1454}",
		["{zone:1456} flight master"] = "Mestre de voo de {zone:1456}",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Back to {area:1637}"] = "De volta a {area:1637}",
		["Crossroads flight master"] = "Mestre de voo da Encruzilhada",
		["Darkmist cavern"] = "Caverna Névoa Negra",
		["Fly from {area:2408} to {area:1638} and train with {npc:3033} on {area:1639}; fly on to {zone:1454} from there."] = "Voe de {area:2408} para {area:1638} e treine com {npc:3033} em {area:1639}; de lá, siga voando até {zone:1454}.",
		["Fly to the Crossroads"] = "Voe para a Encruzilhada",
		["Fly to {area:1637}"] = "Voe para {area:1637}",
		["Fly to {area:2408}"] = "Voe para {area:2408}",
		["Fly to {area:378}"] = "Voar para o {area:378}",
		["Fly to {area:392}"] = "Voe para {area:392}",
		["For {npc:2519} at {object:3202}, in forever/horde/40-50/01-stranglethorn-vale"] = "Para {npc:2519} em {object:3202}, em forever/horde/40-50/01-stranglethorn-vale",
		["Head back west to Brackenwall with the head: {npc:4503} stands at the south edge of the village where the road comes in, {npc:4791} in the village."] = "Volte para o oeste, até a Aldeia Muralha Verde, com a cabeça: {npc:4503} fica na borda sul da aldeia, onde a estrada chega, e {npc:4791}, na aldeia.",
		["Head east back to the {area:497}."] = "Volte para leste até {area:497}.",
		["Head east from {area:378} along the road into the marsh. The burned-out {area:403} stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "Siga para leste de {area:378} pela estrada que entra no pântano. {area:403}, toda queimada, fica ao lado da estrada logo depois da divisa; o escudo, o distintivo e as pegadas de casco estão dentro e em volta da ruína.",
		["Head east to {area:602}. With the {quest:5381} from {npc:11624} in your bags, open a demon portal's ring: a {npc:11937} (38-39) comes out; kill it to close that portal. Six portals. Careful: Infernals, Doomguards and Burning Blade Summoners walk close by many portals and may join in; kill nearby mobs first or drag the guardian away, for example toward the coven's central lake."] = "Siga para leste até {area:602}. Com {quest:5381}, de {npc:11624}, nas bolsas, abra o anel de um portal demoníaco: sai um {npc:11937} (38-39); mate-o para fechar esse portal. São seis portais. Cuidado: Infernais, Demonarcas e Evocadores da Lâmina Ardente andam perto de muitos portais e podem entrar na briga; mate os mobs próximos primeiro ou arraste o guardião para longe, por exemplo em direção ao lago central do covil.",
		["Head north to {area:502}. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "Siga para o norte até {area:502}. O Cascão fica no pé do morro; escolte-o enquanto ele colhe as folhas logo ao sul dali.",
		["Head south along the coast from {area:392} to {area:720}. {npc:6236} stands by the arena: step on the grate to start the fight; the challengers come one at a time, then {npc:6238} (33)."] = "Siga para o sul pela costa de {area:392} até {area:720}. {npc:6236} fica junto à arena: pise na grade para começar a luta; os desafiantes vêm um de cada vez e, por fim, {npc:6238} (33).",
		["Head south-east to the bone fields of the {area:2657}, where Undead Ravagers roam. At the far south-east, use the {item:15848} to draw the Magrami Spectres: they drop the ghost-o-plasm."] = "Siga para sudeste até os campos de ossos de {area:2657}, onde Assoladores Mortos-vivos vagam. No extremo sudeste, use {item:15848} para atrair os Espectros Magrami: eles deixam cair o fantasmoplasma.",
		["Head west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely.\nThe Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes.\nCareful: Darkfang Lurkers (level 36-37) use Sneak to stealth while out of combat and cast Poison once fighting.\nCareful: Stealthed spiders in the same area will attack you on sight.\nCareful: Darkmist Lurkers move about stealthed and use poison once in combat. The spiders stand close together, so adds are common; pulling single targets from the outer edge cuts down on them."] = "Atravesse o pântano de volta para oeste. As Cospeçonhas Presanegra nas cristas ao norte da Muralha Verde deixam cair as bolsas de veneno. Infiltradores de Theramore (35-36) se esgueiram pela mesma mata: estão furtivos, então olhe com atenção.\nAs aranhas Névoa Negra infestam a entrada da caverna a noroeste da Muralha Verde; todo tipo deixa cair olhos.\nCuidado: as Tocaieiras Presanegra (nível 36-37) ficam furtivas fora de combate e soltam Veneno quando a luta começa.\nCuidado: aranhas furtivas da mesma área atacam assim que veem você.\nCuidado: as Tocaieiras Névoa Negra andam furtivas e usam veneno no combate. As aranhas ficam bem juntas, então é comum vir monstro a mais; puxar um alvo de cada vez pela borda ajuda.",
		["Jarl lives in the {area:497} south-east of {area:502}."] = "Zé mora no {area:497} a sudeste do {area:502}.",
		["Level 37.5"] = "Nível 37.5",
		["Mirefin murlocs"] = "Murlocs Lamapina",
		["North to the goblin camp on the west side of the {area:596}."] = "Ao norte, até o acampamento goblin no lado oeste de {area:596}.",
		["North to the post; {npc:5412} stands beside {npc:5395}."] = "Ao norte, até o posto; {npc:5412} fica ao lado de {npc:5395}.",
		["Shadowprey"] = "Pescassombra",
		["South-east from the manor to {area:513}: the {object:20925} lies on the sea floor off the docks on the isle's east side. Swim in and out and keep off the piers and the town: Theramore's guards are level 53-57."] = "Para o sudeste do solar até {area:513}: o {object:20925} está no fundo do mar diante das docas, no lado leste da ilha. Entre e saia nadando e fique longe dos píeres e da cidade: os guardas de Theramore são de nível 53-57.",
		["Stinky Ignatz"] = "Inácio \"Cascão\"",
		["Swamp Eye Jarl"] = "Zé \"Olho de Lama\"",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "Pegue a estrada para o norte na bifurcação até a aldeia ogra de Muralha Verde.",
		["The Mirefin murlocs crowd the coast east and north-east of {area:502}; every kind drops heads."] = "Os murlocs Lamapina lotam a costa a leste e a nordeste do {area:502}; todo tipo deixa cair cabeças.",
		["The next guide takes the {zone:1458} zeppelin from the tower outside the main gate."] = "O próximo guia pega o zepelim de {zone:1458} na torre fora do portão principal.",
		["The {area:2657}"] = "{area:2657}",
		["Train while you are in the city; everyone else trains in the {zone:1458}, next."] = "Treine enquanto estiver na cidade; todos os outros treinam em {zone:1458}, em seguida.",
		["Underwater"] = "Debaixo d'água",
		["West of the post, the Maraudine centaurs hold the {area:607}. Every Maraudine can drop a {item:254432} and an ear for {npc:5395}'s {quest:1366}."] = "A oeste do posto, os centauros Maraudinos ocupam {area:607}. Todo Maraudino pode deixar cair {item:254432} e uma orelha para {quest:1366}, de {npc:5395}.",
		["West to Shadowprey."] = "A oeste, até Pescassombra.",
		["Zeppelin to {zone:1454}"] = "Zepelim para {zone:1454}",
		["for {npc:4485} in {zone:1454}, at the end of this guide"] = "para {npc:4485}, em {zone:1454}, no fim deste guia",
		["grind on {npc:4377}"] = "mate {npc:4377} até subir",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "só se você tiver uma {item:3853} ({skill:164} ou a Casa de Leilões)",
		["{area:2408} flight master"] = "Mestre de voo da {area:2408}",
		["{area:392} flight master"] = "Mestre de voo de {area:392}",
		["{area:496} flight master"] = "Mestre de voo de {area:496}",
		["{area:496}: kill these as you meet them"] = "{area:496}: vá matando estes pelo caminho",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, para Zé \"Olho de Lama\"",
		["{npc:11624} stands in the village."] = "{npc:11624} fica na aldeia.",
		["{npc:12277} is held in the Maraudine camp at the valley's western end; free her and escort her out east of the valley.\nCareful: The scripted groups are linked and only appear during the escort, so you cannot clear them in advance or pull them one at a time. Clearing the normal centaurs on the path before you start does help."] = "{npc:12277} está presa no acampamento Maraudino, na ponta oeste do vale; liberte-a e escolte-a para fora, a leste do vale.\nCuidado: os grupos da escolta vêm juntos e só aparecem durante ela, então não dá para limpar antes nem puxar um de cada vez. Limpar os centauros comuns do caminho antes de começar ajuda.",
		["{npc:3354}, {object:172958}: for {area:720}, later in this guide (offered from level 30)"] = "{npc:3354}, {object:172958}: para {area:720}, mais adiante neste guia (oferecida a partir do nível 30)",
		["{npc:3412}'s workshop is in the {object:172958} beside {npc:4485}: hand in {quest:2841} if you ran {area:133}."] = "A oficina de {npc:3412} fica em {object:172958}, ao lado de {npc:4485}: entregue {quest:2841} se você fez {area:133}.",
		["{npc:3428} stands beside the Crossroads flight master."] = "{npc:3428} fica ao lado do mestre de voo da Encruzilhada.",
		["{npc:3446} stands below Gazlowe's house by the flight master, towards the docks."] = "{npc:3446} fica no andar de baixo da casa de Gazlowe, junto ao mestre de voo, rumo às docas.",
		["{npc:4485} stands in the {object:172958}."] = "{npc:4485} fica em {object:172958}.",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}, na borda sul da aldeia, onde chega a estrada",
		["{npc:4983} waits in the {area:2302} east of the village. Follow him to Reethe and keep him alive through the fight that breaks out."] = "{npc:4983} espera no {area:2302} a leste da aldeia. Siga-o até Reethe e mantenha-o vivo na luta que começa.",
		["{npc:6019} waits at the goblin camp on the west side of the {area:596}."] = "{npc:6019} espera no acampamento goblin no lado oeste do {area:596}.",
		["{object:20985}, beside the manor"] = "{object:20985}, ao lado do solar",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}, agora que {npc:4791} leu o relatório",
		["{quest:1218}, if you did not buy them in {zone:1454}"] = "{quest:1218}, se você não comprou em {zone:1454}",
		["{zone:1443}'s last quests and Alterac are 38-41. Still below 37.5 after Brackenwall's hand-ins? The Darkmist spiders and Lurkers (35-38) by the cavern north-west of the village are the closest: kill them until level 37.5. Or, with a group, run the {area:1316} dungeon or the {area:796} dungeon (Armory) instead."] = "As últimas missões de {zone:1443} e Alterac são de nível 38-41. Ainda abaixo de 37.5 depois das entregas de Muralha Verde? As aranhas e Tocaieiras Névoa Negra (35-38) perto da caverna a noroeste da aldeia são as mais próximas: mate-as até o nível 37.5. Ou, em grupo, faça a masmorra {area:1316} ou a masmorra {area:796} (Armaria).",
		["{zone:1454} flight master"] = "Mestre de voo de {zone:1454}",
		["{zone:1454} trainers"] = "Instrutores de {zone:1454}",
		["{zone:1456} flight master"] = "Mestre de voo de {zone:1456}",
} end)()
t.guides["forever/horde/30-40/05-arathi-highlands"] = (function() return {
		["Back north-east to {area:321}."] = "Volte para o nordeste até {area:321}.",
		["Back to {area:321}"] = "De volta a {area:321}",
		["Below ground"] = "No subterrâneo",
		["Boulderfist quests for a group"] = "Missões Punho de Pedra para um grupo",
		["Each {object:180105} is a ring of standing stones; the key sits on the stone at its heart. The eastern circle is on the hills north-west of {area:321}.\nCareful: Each center stone is guarded by around three elementals near level 39 that attack together if you click the stone without clearing them: Burning Exiles at West, Thundering Exiles at Outer, Cresting Exiles at East."] = "Cada {object:180105} é um anel de monólitos; a chave fica na pedra do centro. O círculo do leste fica nas colinas a noroeste de {area:321}.\nCuidado: cada pedra central é guardada por uns três elementais perto do nível 39, que atacam juntos se você clicar na pedra sem limpá-los antes: Exilados em Chamas no Oeste, Exilados Trovejantes no Externo, Exilados Vagalhantes no Leste.",
		["Escort the professor up the hill to the cave above the cove and guard him while he works. Two level 40 water elementals ambush him there, and they are immune to frost. Hold them at the cave mouth, away from him: if the fight happens inside the cave, he joins in instead of working and more elementals keep coming."] = "Escolte o professor colina acima até a caverna sobre a enseada e proteja-o enquanto ele trabalha. Dois elementais da água de nível 40 o emboscam ali, e são imunes a gelo. Segure-os na boca da caverna, longe dele: se a luta acontecer dentro da caverna, ele entra na briga em vez de trabalhar, e continuam vindo mais elementais.",
		["Find where {quest:503} is held, on the top floor"] = "Descubra onde {quest:503} está preso, no último andar",
		["Fleshstalker raptors"] = "Raptores Fareja-carne",
		["Fly to {area:272}"] = "Voe para {area:272}",
		["Follow the road east. The violet shards glow just off the road a short way west of {area:321}."] = "Siga a estrada para leste. Os cacos violeta brilham um pouco fora da estrada, a uma curta distância a oeste de {area:321}.",
		["Go'shek Farm"] = "Fazenda Go'Shek",
		["Head back east to {area:272}."] = "Volte para leste até {area:272}.",
		["Head east out of {area:272} through {area:1057}. The Syndicate hold the walled manor and its farm north of the road; their Highwaymen, Mercenaries and Pathstalkers carry the Bloodstone Amulets.\nCareful: Highwaymen (level 30-31) can be in Sneak, so they may be hidden when you approach."] = "Saia de {area:272} para leste, passando por {area:1057}. A Camarilha ocupa a mansão murada e sua fazenda ao norte da estrada; seus Bandoleiros, Mercenários e Tocaiantes carregam os Amuletos de Pedra-sangrenta.\nCuidado: os Bandoleiros (nível 30-31) podem estar em Furtividade, então podem estar escondidos quando você chegar perto.",
		["Head north past Valik's camp to {area:280}, the Syndicate-held village (35-37). {npc:2431} carries the {item:3704}; {quest:503} sits in a cage in the house on the north side.\nCareful: Stealthed Syndicate spies roam {area:280}, and the buildings hold many Syndicate mobs, mages among them."] = "Siga ao norte, passando pelo acampamento de Vito, até {area:280}, a vila dominada pela Camarilha (35-37). {npc:2431} carrega {item:3704}; {quest:503} está numa jaula na casa do lado norte.\nCuidado: espiões furtivos da Camarilha rondam {area:280}, e os prédios têm muitos monstros da Camarilha, entre eles magos.",
		["Head north-west through the mountains to the Perenolde manor on the northern shore of {area:1339}. {quest:507} (41) waits in a room upstairs: he shields himself, puts you to sleep and heals below half health. {npc:2317} stands beside him."] = "Siga para noroeste pelas montanhas até a mansão Perenolde, na margem norte de {area:1339}. {quest:507} (41) espera num quarto no andar de cima: ele se protege com escudo, faz você dormir e se cura abaixo da metade da vida. {npc:2317} fica ao lado dele.",
		["Head south to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "Siga para o sul até a enseada dos goblins, na costa sul. {npc:2766} vigia do penhasco acima dela.",
		["Head west; the outer circle stands in the middle of the highlands."] = "Siga para o oeste; o círculo externo fica no meio do planalto.",
		["Highland Fleshstalkers (36-37) hunt the southern highlands, a pack north of {area:316} and another on the plain to its west. Pull them one at a time."] = "Farejas-carne do Planalto (36-37) caçam no planalto sul, um bando ao norte de {area:316} e outro na planície a oeste. Puxe um de cada vez.",
		["Inside"] = "Lá dentro",
		["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael.\nCareful: Every kobold type runs off for help when low on health (Kobolds at 30%, Surveyors and Diggers at 15%), which can pull more of them."] = "A nordeste da Ruína do Martelo, os kobolds Bigodesseco mineram o desfiladeiro; os Kobolds da entrada e os Escavadores e Topógrafos lá do fundo deixam cair as Partículas de Myzrael.\nCuidado: todo tipo de kobold sai correndo atrás de ajuda com pouca vida (Kobolds com 30%, Topógrafos e Escavadores com 15%), o que pode trazer mais deles.",
		["Only if you ran Stromgarde with a group: back to {area:321} for its hand-ins, then on to the {area:880}."] = "Só se você fez Stromgarde em grupo: volte a {area:321} para as entregas e siga para {area:880}.",
		["Perenolde manor"] = "Mansão Perenolde",
		["South along the lake shore to the ruins around the {area:279} crater. The Dalaran Summoners lead Elemental Slaves; the bracers drop from the slaves."] = "Ao sul pela margem do lago, até as ruínas em volta da cratera de {area:279}. Os Evocadores de Dalaran comandam Escravos Elementais; as braçadeiras caem dos escravos.",
		["Stromgarde"] = "Stromgarde",
		["Stromgarde quests for a group"] = "Missões de Stromgarde para um grupo",
		["The Boulderfist Brutes camp outside the ogres' hall, far south-west of {area:321}; the Magus stand among them. Pull them one at a time."] = "Os Brutamontes Punho de Pedra acampam fora do salão dos ogros, bem a sudoeste de {area:321}; os Magus Punho de Pedra ficam entre eles. Puxe um de cada vez.",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "O círculo interno fica ao sul do círculo oeste, a leste de Stromgarde.",
		["The magus offers a dungeon errand next: leave it."] = "O mago oferece em seguida um serviço de masmorra: deixe de lado.",
		["The next guide crosses the {area:880} into the {zone:1437} and heads for the {zone:1418}."] = "O próximo guia atravessa {area:880} para {zone:1437} e segue rumo a {zone:1418}.",
		["The stone's next task needs Fozruk, a level 42 elite who roams west of {area:321}: leave it."] = "A próxima tarefa da pedra exige Fozruk, um elite de nível 42 que vaga a oeste de {area:321}: deixe de lado.",
		["The western circle is near {area:1057}, north-west of the outer one."] = "O círculo oeste fica perto de {area:1057}, a noroeste do círculo externo.",
		["The {object:138492}"] = "{object:138492}",
		["The {object:1763} poster by the inn"] = "O cartaz {object:1763} perto da estalagem",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "Os {object:2701} ficam no fundo do desfiladeiro.",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "Treine enquanto estiver em {zone:1458}: os instrutores ficam no {object:36070}, no {object:36073} e no {object:36082} (paladinos: {npc:260093}).",
		["Underwater"] = "Debaixo d'água",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "A oeste da enseada, os Saqueadores e Feiticeiras Espinhadaga (38-40) ocupam a praia: puxe um de cada vez. Os dois naufrágios ficam nas águas rasas em frente, com as cartas e os diários dentro; as gemas ficam no fundo do mar em volta dos naufrágios.",
		["West of the inner circle, Stromgarde's ruins: the Syndicate hold the east half (the Sigil drops from their Conjurors, Prowlers and Magi; {npc:2783} is among them), the Boulderfist the west half by the {area:325} ({npc:2773} waits in one of the roofless houses beside it)."] = "A oeste do círculo interno, as ruínas de Stromgarde: a Camarilha ocupa a metade leste (o Sigilo cai dos Conjuradores, Predadores e Magus deles; {npc:2783} está entre eles), os Punho de Pedra a metade oeste, junto a {area:325} ({npc:2773} espera numa das casas sem teto ao lado dela).",
		["Zeppelin to {zone:1458}"] = "Zepelim para {zone:1458}",
		["for {npc:2487} in {area:35}, around level 41"] = "para {npc:2487} em {area:35}, por volta do nível 41",
		["{area:17707}: kill these as you meet them"] = "{area:17707}: vá matando estes pelo caminho",
		["{area:328}: kill these as you meet them"] = "{area:328}: vá matando estes pelo caminho",
		["{npc:12920}, at the south gate"] = "{npc:12920}, no portão sul",
		["{npc:2229} waits inside the inn at {area:272}, back south down the road."] = "{npc:2229} espera dentro da estalagem de {area:272}, descendo a estrada de volta ao sul.",
		["{npc:2229}, inside"] = "{npc:2229}, lá dentro",
		["{npc:2229}, inside the inn"] = "{npc:2229}, dentro da estalagem",
		["{npc:2306} (40) carries the head. He turns up in one spot at a time: the cellar of {area:280}'s inn, or one of the Syndicate tent camps in the uplands north and north-west of the village, which lie on your way to the Perenolde manor. If you already met him while freeing {quest:503}, this step is done."] = "{npc:2306} (40) leva a cabeça. Ele aparece em um lugar de cada vez: a adega da estalagem de {area:280}, ou um dos acampamentos de tendas da Camarilha nas terras altas ao norte e noroeste da vila, que ficam no seu caminho para a mansão Perenolde. Se você já o encontrou ao libertar {quest:503}, esta etapa está feita.",
		["{npc:2410}, inside"] = "{npc:2410}, lá dentro",
		["{npc:2437}, inside"] = "{npc:2437}, lá dentro",
		["{npc:2703}'s {quest:639} drops from the elite Syndicate (35-38) in Stromgarde's ruins, the west of the highlands. Great XP if you have a group for it: the route passes Stromgarde on its way to the inner circle."] = "O {quest:639} de {npc:2703} cai dos elites da Camarilha (35-38) nas ruínas de Stromgarde, no oeste do planalto. Ótima XP se você tiver um grupo: a rota passa por Stromgarde a caminho do círculo interno.",
		["{npc:2706}'s next {quest:671} is {npc:2783}, a level 40 elite warlock in Stromgarde's Syndicate quarter."] = "A próxima {quest:671} de {npc:2706} é {npc:2783}, um bruxo elite de nível 40 no bairro da Camarilha de Stromgarde.",
		["{npc:2733}'s lab shack stands at Go'shek Farm, north-east of the raptors' plain on the way back to {area:321}; the case of {item:278462} is inside."] = "O barraco de laboratório de {npc:2733} fica na Fazenda Go'shek, a nordeste da planície dos raptores, na volta para {area:321}; a caixa de {item:278462} está lá dentro.",
		["{npc:2771}'s next {quest:678} and {npc:2772}'s {quest:680} are the elite ogres (38-40) in Stromgarde's ogre quarter, on the same group trip as the Sigil."] = "A próxima {quest:678} de {npc:2771} e a {quest:680} de {npc:2772} são os ogros elite (38-40) do bairro dos ogros de Stromgarde, na mesma viagem em grupo do Signo.",
		["{npc:2772}, beside him"] = "{npc:2772}, ao lado dele",
		["{npc:2792}, by the gate"] = "{npc:2792}, junto ao portão",
		["{quest:503}, on the top floor"] = "{quest:503}, no último andar",
		["{quest:671} with a group"] = "{quest:671} com um grupo",
		["{zone:1458} flight master"] = "Mestre de voo de {zone:1458}",
		["{zone:1458} trainers"] = "Instrutores de {zone:1458}",
} end)()
t.guides["forever/horde/30-40/06-badlands"] = (function() return {
		["Below ground"] = "No subterrâneo",
		["Head back south down the road, past the {area:1877}."] = "Volte para o sul pela estrada, passando por {area:1877}.",
		["Head for the {object:2673}, the great bridge at Arathi's southern edge, cross it and follow the road south through the {zone:1437} to the {object:1668} tunnel into {zone:1432}. {area:144}, the dwarf town on the road in the middle of {zone:1432}, has guards who attack the Horde: leave the road before it and pass the town on the hills to its west. The road leaves {zone:1432} to the south into the {zone:1418}; follow it to the goblin camp in the {area:1877}."] = "Vá até {object:2673}, a grande ponte no limite sul de Arathi, atravesse-a e siga a estrada para o sul por {zone:1437} até o túnel de {object:1668} para {zone:1432}. {area:144}, a cidade anã na estrada, no meio de {zone:1432}, tem guardas que atacam a Horda: saia da estrada antes dela e passe pela cidade pelas colinas a oeste. A estrada sai de {zone:1432} para o sul, rumo a {zone:1418}; siga-a até o acampamento goblin em {area:1877}.",
		["Head west along the road towards {area:340}; {npc:2921}'s camp sits in the {area:1878} halfway there."] = "Siga para oeste pela estrada rumo a {area:340}; o acampamento de {npc:2921} fica em {area:1878}, no meio do caminho.",
		["Head west back to {area:340}. {npc:5394} stands on {area:340}'s upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart."] = "Siga a oeste, de volta a {area:340}. {npc:5394} fica no andar de cima de {area:340}, bem acima do mestre de voo: suba pelas rampas, a seta não distingue os andares.",
		["Into the {zone:1418}"] = "Rumo a {zone:1418}",
		["Keep north on the road; the chest lies in the {area:1517} dig site, at the foot of the ruins north-west of the road."] = "Continue para o norte pela estrada; o baú fica no sítio de escavação de {area:1517}, ao pé das ruínas a noroeste da estrada.",
		["Lesser Rock Elementals"] = "Elementais Inferiores da Rocha",
		["North-west across the basin to {npc:2921}'s camp. Short of Jarkal's shards? The Lesser Rock Elementals (37) on the flats west of the camp drop them about one kill in five."] = "A noroeste, atravessando a bacia, até o acampamento de {npc:2921}. Faltam estilhaços para Jarkal? Os Elementais Inferiores da Rocha (37) nas planícies a oeste do acampamento os deixam cair em cerca de uma morte a cada cinco.",
		["Rock Elementals"] = "Elementais da Rocha",
		["South-east across the basin, the bigger Rock Elementals (39) stand on the slopes west of {area:345}; each one drops a slab. Every rock elemental can drop {npc:6868}'s Rock Elemental Shards."] = "A sudeste, atravessando a bacia, os Elementais da Rocha maiores (39) ficam nas encostas a oeste de {area:345}; cada um deixa cair uma laje. Todo elemental da rocha pode deixar cair os Estilhaços de Elemental da Rocha de {npc:6868}.",
		["Stonevault troggs"] = "Troggs da Abóbada de Pedra",
		["The Elder Crag Coyotes and Giant Buzzards roam the basin south of the {area:1878}. Coyotes drop both the jawbones and the fangs; the Giant Buzzards drop the gizzards."] = "Os Coiotes Anciões do Rochedo e os Urubus Gigantes andam pela bacia ao sul de {area:1878}. Os coiotes deixam cair tanto as mandíbulas quanto as presas; os Urubus Gigantes deixam cair as moelas.",
		["The Stonevault troggs dig around the cave mouths south of the {area:1877}, on the way north from {area:345}; the Bonesnappers and Shamans drop the flakes. The Buzzards for {npc:2817}'s wings circle the hills between the {area:1877} and {area:345}."] = "Os troggs da Abóbada de Pedra cavam em volta das bocas das cavernas ao sul de {area:1877}, no caminho para o norte, saindo de {area:345}; os Quebraossos e Xamãs deixam cair as lascas. Os Urubus para as asas de {npc:2817} sobrevoam as colinas entre {area:1877} e {area:345}.",
		["The next guide flies from {area:340} to {object:3202}."] = "O próximo guia voa de {area:340} para {object:3202}.",
		["The road north to {area:1517} runs through the {area:1877}: {npc:2817} and {npc:4618} take the wings and the flakes on the way."] = "A estrada ao norte para {area:1517} atravessa {area:1877}: {npc:2817} e {npc:4618} recebem as asas e as lascas no caminho.",
		["The small elementals drift across the flats between {area:340} and {npc:2921}'s camp, on the road back east. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards."] = "Os elementais pequenos vagam pelas planícies entre {area:340} e o acampamento de {npc:2921}, na estrada de volta ao leste. Todo elemental de rocha da zona pode deixar cair os Estilhaços de Elemental da Rocha de {npc:6868}.",
		["Theldurin sits among the dwarven ruins at {area:345}, just east of the elementals."] = "Theldurin fica entre as ruínas anãs em {area:345}, logo a leste dos elementais.",
		["for Fizzle at the {area:2240}, on the way from {area:484} to {zone:1446} around level 43"] = "para Xabu em {area:2240}, no caminho de {area:484} para {zone:1446}, por volta do nível 43",
		["for Helgrum in {area:75}, around level 42"] = "para Helgrum, em {area:75}, por volta do nível 42",
		["{area:340} is the Horde fortress built into the cliffs at the zone's western edge. {npc:5394} stands on {area:340}'s upper level, high above the flight master: take the ramps up, the arrow cannot tell the levels apart."] = "{area:340} é a fortaleza da Horda construída nos penhascos, na ponta oeste da zona. {npc:5394} fica no andar de cima de {area:340}, bem acima do mestre de voo: suba pelas rampas, a seta não distingue os andares.",
		["{npc:2921}'s next study wants bracers from the Greater Rock Elementals (42-44) in the south-western gulches, well above you: leave it."] = "O próximo estudo de {npc:2921} pede braçadeiras dos Elementais Maiores da Rocha (42-44) nas ravinas do sudoeste, bem acima do seu nível: deixe para lá.",
		["{npc:6868}, inside"] = "{npc:6868}, lá dentro",
		["{quest:1106}: Fizzle's letter from the {area:439}"] = "{quest:1106}: a carta de Bulho, de {area:439}",
		["{zone:1418}: kill these as you meet them"] = "{zone:1418}: vá matando estes pelo caminho",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Sea Wolf\" MacKinley, on the top floor"] = "MacKinley \"Lobo do Mar\", no último andar",
		["Below ground"] = "No subterrâneo",
		["Draenethyst crystals"] = "Cristais de draenetista",
		["Fly to {area:35}"] = "Voe até {area:35}",
		["Fly to {object:3202}"] = "Voe para {object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "Siga a costa para o sul. As nagas exploradoras andam pela água ao longo da costa e levam os feixes de junco; {object:759} borbulha nas colinas logo a leste delas.",
		["Follow the road east from {zone:1431} through {zone:1430} into the swamp. {npc:1776} waits at the {area:657}, the draenei camp just off the road where it comes in from {zone:1430}."] = "Siga a estrada para leste a partir de {zone:1431}, por {zone:1430}, até o pântano. {npc:1776} espera em {area:657}, o acampamento dos draeneis logo fora da estrada, onde ela chega de {zone:1430}.",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals.\nCareful: Stealthed Shadowmaw Panthers and Stranglethorn Tigresses roam the area around the camp."] = "Mais ao norte, os goblins da Empreendimentos S.A. cavam na mina a leste da estrada; mineradores, encarregados, topógrafos e engenhoqueiros deixam cair os cristais.\nCuidado: Panteras Umbragorja furtivas e Tigresas-do-espinhaço andam em volta do acampamento.",
		["Gringer, the flight master, waits on {area:35}'s upper deck. The quest givers stand on the boardwalks around the harbour and in the inn."] = "Gringer, o mestre de voo, espera no convés superior de {area:35}. As pessoas que dão missões ficam nos passadiços ao redor do porto e na estalagem.",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "Entregue as presas a Unbagwa e fique perto dele: ele chama três ondas de gorilas, depois {npc:1514}. Enfrente-os um de cada vez.",
		["Head east to {area:75}, in the reeds south of the road. Bind here."] = "Siga para o leste até {area:75}, nos juncos ao sul da estrada. Fixe sua Pedra de Regresso aqui.",
		["Head north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. {npc:1059} guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all."] = "Siga para o norte até as ruínas dos Rachacrânio, a leste da mina da Empreendimentos S.A.; puxe os caçadores de cabeças e os berserkers um de cada vez. {npc:1059} guarda as ruínas do sudoeste, e uma pilha de crânios-troféu fica no lado norte das ruínas. Qualquer Rachacrânio pode deixar cair uma presa ou um colar: os colares são a parte demorada, então continue matando no acampamento dos guerreiros ao norte das ruínas até completar.",
		["Head north up the road to the hunters' camp."] = "Siga a estrada para o norte até o acampamento dos caçadores.",
		["Head north up the road; the hunters camp on the hill above the river."] = "Siga a estrada para o norte; os caçadores acampam no morro acima do rio.",
		["Head south to {area:35}. Shaky Phillipe waits on the docks."] = "Siga para o sul até {area:35}. Shaky Phillipe espera no cais.",
		["Head west to {object:3202}."] = "Siga para oeste até {object:3202}.",
		["His strongbox waits at his old camp north of {area:75}, on the way back west."] = "O cofre dele espera no antigo acampamento dele, ao norte de {area:75}, no caminho de volta a oeste.",
		["If you skipped {quest:192} or {quest:195}, grind here to level 42.68 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "Se você pulou {quest:192} ou {quest:195}, mate monstros aqui até o nível 42.68 para seguir o plano da rota. Ou, em grupo, faça a masmorra {area:1517}.",
		["If you skipped {quest:208}, grind here to level 42.74 to stay on the route's plan. Or, with a group, run the {area:1517} dungeon instead."] = "Se você pulou {quest:208}, mate monstros aqui até o nível 42.74 para seguir o plano da rota. Ou, em grupo, faça a masmorra {area:1517}.",
		["Inside"] = "Lá dentro",
		["Inside {area:1742}"] = "Dentro de {area:1742}",
		["Into the {zone:1435}"] = "Rumo a {zone:1435}",
		["Ironjaw Basilisks"] = "Basiliscos Ferroqueixo",
		["Jungle Stalkers"] = "Espreitadores da Selva",
		["Jungle stalkers"] = "Espreitadores da selva",
		["Leave town by the tunnel; the note lies in the pirates' cove just north of {area:35}."] = "Saia da cidade pelo túnel; o bilhete fica na enseada dos piratas, logo ao norte de {area:35}.",
		["Level 42.68"] = "Nível 42.68",
		["Level 42.74"] = "Nível 42.74",
		["MacKinley, on the top floor: for Stoley in {zone:1446}"] = "MacKinley, no último andar: para Esmirno, em {zone:1446}",
		["Mistvale gorillas"] = "Gorilas do Vale da Névoa",
		["Nesingwary's camp"] = "Acampamento de Rosarães Guima",
		["Noboru wanders the clearing south-west of the {area:76}; his cudgel starts a quest."] = "Noboru vaga pela clareira a sudoeste de {area:76}; a clava dele inicia uma missão.",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "A nordeste do Vale da Névoa, os seguidores de Zanzil acampam na selva; todos eles podem levar o preparado.",
		["Optional, and tough at 41: the scroll, {quest:624}, lies on the decks of the three ships off the {area:43}, crewed by pirates of 42-45 who come in pairs. Take it only if you can pull the crew to the rail one at a time, or with a friend; its chain runs on through the {zone:1435}, {zone:1445} and the {zone:1425}."] = "Opcional, e difícil no nível 41: o pergaminho, {quest:624}, fica nos conveses dos três navios ao largo de {area:43}, tripulados por piratas de nível 42-45 que vêm em pares. Pegue só se conseguir puxar a tripulação até a amurada um de cada vez, ou com um amigo; a cadeia dele segue por {zone:1435}, {zone:1445} e {zone:1425}.",
		["Pirate ghosts"] = "Fantasmas piratas",
		["Ride north out of {area:35} along the road; the basilisks bask on the rocks east of it in the middle of the jungle, on the way back to {object:3202}. Their shards drop often."] = "Siga a cavalo para o norte, saindo de {area:35}, pela estrada; os basiliscos tomam sol nas rochas a leste dela, no meio da selva, no caminho de volta a {object:3202}. Os estilhaços deles caem com frequência.",
		["Ride north-east to the {area:76}. The crystals stand along the way up to {npc:5391}'s cage."] = "Cavalgue para nordeste até {area:76}. Os cristais ficam ao longo da subida até a jaula de {npc:5391}.",
		["Ride on north to {object:3202}."] = "Siga a cavalo para o norte até {object:3202}.",
		["Ride west along the road to the draenei camp at the {area:657}, near the way in from {zone:1430}. {quest:698} goes to {npc:5592} at {area:1978} on the next swamp visit: keep the flanks."] = "Cavalgue para oeste pela estrada até o acampamento dos draeneis em {area:657}, perto da entrada vinda de {zone:1430}. {quest:698} vai para {npc:5592} em {area:1978} na próxima visita ao pântano: guarde os flancos.",
		["Sawtooth crocolisks"] = "Crocoliscos Dentesserra",
		["Skullsplitter warriors"] = "Guerreiros Rachacrânio",
		["South of Booty Bay the Bloodsail swashbucklers camp on the {area:43}; the charts and the orders lie in their tents. Any Bloodsail can carry snuff and {npc:2493}'s eye, so keep killing until you have both."] = "Ao sul de Angra do Butim, os Espadachins da Vela Sangrenta acampam em {area:43}; os mapas e as ordens ficam nas barracas deles. Qualquer pirata da Vela Sangrenta pode levar rapé e o olho do {npc:2493}, então continue matando até ter os dois.",
		["Take the road north out of {area:35}; Unbagwa sits on a hill in {area:1737}, east of the road."] = "Pegue a estrada para o norte saindo de {area:35}; Unbagwa fica numa colina em {area:1737}, a leste da estrada.",
		["The Bloodsail ships"] = "Os navios da Vela Sangrenta",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights."] = "Os Espreitadores da Selva (40-41) caçam no litoral ao sul de {object:3202}. Eles estão bem acima de você: puxe um de cada vez e descanse entre as lutas.",
		["The crocolisks wallow in the pools around {npc:5391}'s camp and south towards {area:75}; about one in four drops a flank."] = "Os crocoliscos chafurdam nas poças em volta do acampamento de {npc:5391} e ao sul rumo a {area:75}; cerca de um em quatro deixa cair uma anca.",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "Os gorilas vagam pelo vale em volta de Unbagwa. Os anciões deixam cair os miúdos; qualquer um deles pode deixar cair uma presa.",
		["The next trophy skulls stand in the small ruins just north of the warriors' camp.\nThe last skulls are in the ruins a short walk west, on the way back to {object:3202}."] = "Os próximos crânios-troféu ficam nas ruínas pequenas logo ao norte do acampamento dos guerreiros.\nOs últimos crânios ficam nas ruínas a uma curta caminhada a oeste, no caminho de volta a {object:3202}.",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "Os raptores espreitadores caçam na selva ao sul de {object:3202}, rumo à costa oeste.",
		["The three ghostly pirates haunt the jungle north of {area:35}, near Zanzil's camps: {npc:2535} and {npc:2536} stand together, {npc:2537} further east."] = "Os três piratas fantasmagóricos assombram a selva ao norte de {area:35}, perto dos acampamentos de Zanzil: {npc:2535} e {npc:2536} ficam juntos, {npc:2537} mais a leste.",
		["The {area:43}"] = "{area:43}",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:728} is a level 40 elite: most classes solo it at level 42, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:728} é elite de nível 40: a maioria das classes encara sozinha no nível 42, mas talvez você precise de ajuda. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:730} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:730} é elite de nível 43: a maioria das classes encara sozinha no nível 45, mas talvez você precise de ajuda. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:731} is a level 43 elite: most classes solo it at level 45, but you may need help. Skip it if you are alone: the route has you grind the XP back.\nCareful: Tigers and stealthed shadowmaw panthers roam close to him. Clear them before you pull him. When he is pulled, {npc:731} calls for help from creatures within 20 yd."] = "São monstros elite: vale a pena formar grupo, procure gente para ir junto. {npc:731} é elite de nível 43: a maioria das classes encara sozinha no nível 45, mas talvez você precise de ajuda. Se estiver sozinho, pule: a rota faz você recuperar a XP matando monstros.\nCuidado: tigres e panteras umbragorja furtivas andam perto dele. Limpe tudo antes de puxá-lo. Quando é puxado, {npc:731} chama ajuda de qualquer bicho num raio de 20 metros.",
		["Venture Co. mine"] = "Mina da Empreendimentos S.A.",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them. Stay on the Bloodscalps here until level 41: {quest:586}, at the cauldron next, sends you to Skullsplitters of 41-43. Or, with a group, run the {area:1517} dungeon instead.\nOn the coast between Zul'Kunda and {object:3202} an {npc:2635} (level 38 elite) shares the spawns of the ordinary crocolisks: kill it if it is up and take its skin for {npc:2495}."] = "A oeste da expedição, os chefes Sanguescalpo {npc:1061} e {npc:1062} ficam juntos nas ruínas de Zul'Kanda. Limpe os guardas primeiro, depois puxe-os. Continue com os Sanguescalpo aqui até o nível 41: {quest:586}, no caldeirão logo adiante, manda você aos Rachacrânio de nível 41-43. Ou, em grupo, faça a masmorra {area:1517}.\nNa costa entre Zul'Kanda e {object:3202}, um {npc:2635} (elite de nível 38) compartilha os pontos de surgimento dos crocoliscos comuns: mate-o se ele estiver lá e pegue a pele dele para {npc:2495}.",
		["Zanzil's camps"] = "Acampamentos de Zanzil",
		["Zul'Kunda"] = "Ruínas de Zul'Kanda",
		["Zul'Mamwe"] = "Ruínas de Zul'Mamwe",
		["for a later stop in the {zone:1435}"] = "para uma parada posterior em {zone:1435}",
		["from the {object:52}, in the ruins"] = "de {object:52}, nas ruínas",
		["grind on the Bloodscalps here: {quest:586}, at the cauldron next, sends you to Skullsplitters of 41-43"] = "mate os Sanguescalpos daqui até subir: {quest:586}, no caldeirão logo adiante, manda você para os Rachacrânios de nível 41-43",
		["grind on {npc:667}"] = "mate {npc:667} até subir",
		["the Drowned City's entrance, underwater"] = "a entrada da Cidade Submersa, debaixo d'água",
		["the {object:2076}"] = "o {object:2076}",
		["the {object:2076} again: Yenniku's fate"] = "{object:2076} de novo: o destino de Yennikan",
		["the {object:2076}, beside {npc:2497}"] = "o {object:2076}, ao lado de {npc:2497}",
		["{area:127}: kill these as you meet them"] = "{area:127}: vá matando estes pelo caminho",
		["{area:1577}: kill these as you meet them"] = "{area:1577}: vá matando estes pelo caminho",
		["{area:340} flight master"] = "Mestre de voo de {area:340}",
		["{npc:1442}, upstairs"] = "{npc:1442}, no andar de cima",
		["{npc:1443}, on the top floor"] = "{npc:1443}, no último andar",
		["{npc:2488}, on the top floor"] = "{npc:2488}, no último andar",
		["{npc:2491}, in the inn: his bottles wash up on the {zone:1425} coast, around level 48"] = "{npc:2491}, na estalagem: as garrafas dele dão na costa de {zone:1425}, por volta do nível 48",
		["{npc:2495}, inside: the {item:4105}"] = "{npc:2495}, lá dentro: a {item:4105}",
		["{npc:2495}: the Snapjaw skins gathered earlier; inside"] = "{npc:2495}: as peles de Crocolisco Arapuca que você juntou antes; lá dentro",
		["{npc:2495}: the {npc:2635} suns on the coast between Zul'Kunda and {object:3202}, later on this loop"] = "{npc:2495}: o {npc:2635} toma sol na costa entre Zul'Kanda e {object:3202}, mais adiante neste circuito",
		["{npc:2496}, on the balcony beside MacKinley"] = "{npc:2496}, na sacada ao lado de MacKinley",
		["{npc:2497}: for the {zone:1425}, around level 48"] = "{npc:2497}: para {zone:1425}, por volta do nível 48",
		["{npc:2498}, inside"] = "{npc:2498}, lá dentro",
		["{npc:2519}: the basilisks graze beside the road back from {area:35}"] = "{npc:2519}: os basiliscos pastam ao lado da estrada na volta de {area:35}",
		["{npc:2519}: the cavern entrance under the {area:104}, west of the camp"] = "{npc:2519}: a entrada da caverna sob {area:104}, a oeste do acampamento",
		["{npc:2519}: the legend lies in Zul'Kunda, where this guide goes for {npc:1061}"] = "{npc:2519}: a lenda está em Zul'Kanda, onde este guia vai atrás de {npc:1061}",
		["{npc:2519}: the trophy skulls stand in the Skullsplitter ruins, later on this loop"] = "{npc:2519}: os crânios troféu ficam nas ruínas dos Rachacrânio, mais adiante neste circuito",
		["{npc:4631}, on the docks: Gazlowe's letter, if you carry it"] = "{npc:4631}, no cais: a carta de Gazlowe, se você estiver com ela",
		["{npc:5391} is held in the {area:76} in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "{npc:5391} está preso em {area:76}, no nordeste do pântano. Liberte-o e siga-o para fora, enfrentando as criaturas do pântano que o perseguem.",
		["{npc:5591}, inside"] = "{npc:5591}, lá dentro",
		["{npc:669} walks around here: look inside the circle on the map"] = "{npc:669} anda por aqui: procure dentro do círculo no mapa",
		["{npc:6807}, upstairs"] = "{npc:6807}, no andar de cima",
		["{npc:6930}, upstairs"] = "{npc:6930}, no andar de cima",
		["{npc:737}, upstairs"] = "{npc:737}, no andar de cima",
		["{npc:737}, upstairs: the tusks come from the Skullsplitters, later on this loop"] = "{npc:737}, no andar de cima: as presas vêm dos Rachacrânio, mais adiante neste circuito",
		["{npc:773}, upstairs: for {quest:2864} in {area:976}"] = "{npc:773}, no andar de cima: para {quest:2864} em {area:976}",
		["{object:3202} flight master"] = "Mestre de voo de {object:3202}",
		["{quest:95770}: west of {object:3202}, swim out over the {area:104} and dive to the cavern entrance in the reef; the quest completes as you find it. Leave the cavern for now: the jungle stalkers are south along the coast."] = "{quest:95770}: a oeste de {object:3202}, nade sobre {area:104} e mergulhe até a entrada da caverna no recife; a missão é concluída quando você a encontra. Deixe a caverna para depois: os espreitadores da selva estão ao sul, ao longo da costa.",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Fly from {zone:1454} to {area:392}; {npc:6251} stands on the hill above the docks."] = "Voe de {zone:1454} para {area:392}; {npc:6251} fica na colina acima das docas.",
		["Fly to {area:1637}"] = "Voe para {area:1637}",
		["Fly to {area:1638}"] = "Voe para {area:1638}",
		["Fly to {area:484}"] = "Voe para {area:484}",
		["Fly to {object:3202}"] = "Voe para {object:3202}",
		["Fly to {zone:1454}. From the flight master: the {object:172960}, then the Drag, then the {object:172958}."] = "Voe para {zone:1454}. A partir do mestre de voo: o {object:172960}, depois o Drag, depois o {object:172958}.",
		["Grimtotem camp"] = "Acampamento Temível Totem",
		["Kodos: {npc:3685}, beside {npc:3690} in {area:222}."] = "Kodos: {npc:3685}, ao lado de {npc:3690} em {area:222}.",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "Ao norte dos gnolls, os ogros ocupam um posto no alto de uma colina; puxe os Ogros-magos até você. O cobalto está nos montes de terra em volta do posto, e o pergaminho fica no chão lá dentro.",
		["North-west of the ruins, the yetis den in {area:1105}; every yeti there can drop a thick hide."] = "A noroeste das ruínas, os yetis têm a toca em {area:1105}; todo yeti de lá pode deixar cair um couro grosso.",
		["Only with the distress beacon: any beast, gnoll or ogre in {zone:1444} can drop it, about one kill in a hundred; use it to start the quest. The robot sits in a small cave on the north side of {area:1105}, just north-west of the ruins. Escort it to the dock on the {area:1108}; yetis and gorillas ambush you on the way. Its reward waits in {area:35} for a later visit.\nCareful: Three ambushes spawn during the escort, and the robot warns you before each one. The first is 3 yetis, just after the robot leaves the cave and climbs toward the road. The second is 3 gorillas, on the path that runs along the cliff. The third is about 4 gnolls, one of them a caster, where the route turns off toward the dock."] = "Só com o transmissor de emergência: qualquer fera, gnoll ou ogro em {zone:1444} pode deixá-lo cair, cerca de uma morte em cem; use-o para iniciar a missão. O robô fica numa pequena caverna no lado norte de {area:1105}, logo a noroeste das ruínas. Escolte-o até o cais em {area:1108}; yetis e gorilas emboscam vocês no caminho. A recompensa dele espera em {area:35}, para uma visita posterior.\nCuidado: três emboscadas surgem durante a escolta, e o robô avisa antes de cada uma. A primeira é de 3 yetis, logo depois que o robô sai da caverna e sobe rumo à estrada. A segunda é de 3 gorilas, na trilha que corre ao longo do penhasco. A terceira é de cerca de 4 gnolls, um deles lançador de feitiços, onde a rota desvia rumo ao cais.",
		["Raptors: Zjolnir, beside {npc:7953} in {area:367}."] = "Raptores: Zjolnir, ao lado de {npc:7953} em {area:367}.",
		["Ride north-east back to the port: {npc:7881}, the {npc:15165} and the Security Chief take what {area:1336} gave you. {area:976} is west of it."] = "Siga a cavalo para nordeste de volta ao porto: {npc:7881}, a {npc:15165} e o Chefe de Segurança recebem o que {area:1336} deu a você. {area:976} fica a oeste dele.",
		["Ride north-east to the goblin harbour on the coast."] = "Siga para o nordeste até o porto goblin na costa.",
		["Ride west from the hive to the ogre ruins below {area:1105}. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb."] = "Siga para o oeste, saindo da colmeia, até as ruínas dos ogros abaixo de {area:1105}. Xamãs, Bruxos e Espancadores as ocupam; os Lordes-magos na ponta sul carregam o orbe.",
		["Riding and Galestriders: {npc:265756}, at the {area:17684} in {area:16638} on Zephras Isle."] = "Montaria e Vagaventos: {npc:265756}, em {area:17684}, {area:16638}, na Ilha de Zefras.",
		["Riding at 40"] = "Montaria no 40",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:3690} in {area:222}, with {npc:3685}'s kodos (20 gold each) beside him. Ride back up to {zone:1456}'s flight master afterwards."] = "Equitação exige nível 40 e custa 100 ouros; aprendê-la dá a você uma montaria. Cada raça aprende com o instrutor da própria raça: o seu é {npc:3690} em {area:222}, com os kodos de {npc:3685} (20 ouros cada) ao lado dele. Depois, suba a cavalo de volta ao mestre de voo de {zone:1456}.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Each race learns it from its own race's trainer: yours is {npc:7953} in {area:367}, a short ride south of {zone:1454} down the {zone:1411} road, with Zjolnir's raptors (20 gold each) beside him. Ride back to {zone:1454}'s flight master afterwards."] = "Equitação exige nível 40 e custa 100 ouros; aprendê-la dá a você uma montaria. Cada raça aprende com o instrutor da própria raça: o seu é {npc:7953} em {area:367}, a uma curta cavalgada ao sul de {zone:1454}, pela estrada de {zone:1411}, com os raptores de Zjolnir (20 ouros cada) ao lado dele. Depois, volte a cavalo até o mestre de voo de {zone:1454}.",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel. Skyborne learn it from {npc:265756} at the {area:17684} in {area:16638} on Zephras Isle, with a Galestrider: the skyboat to the isle leaves the cliffs south of {area:17045}, north of {zone:1456}, about every five minutes. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "Equitação exige nível 40 e custa 100 ouros; aprendê-la dá a você uma montaria. {npc:4752} ensina os Orcs em {object:172958}, junto ao canil de {npc:3362}. Celonatos aprendem com {npc:265756} em {area:17684}, em {area:16638}, na Ilha de Zefras, com um Vagavento: o barco celeste para a ilha sai dos penhascos ao sul de {area:17045}, ao norte de {zone:1456}, mais ou menos a cada cinco minutos. As outras montarias da sua raça custam 20 ouros cada: Colecionáveis, Montarias · Nível 40 tem um guia para cada uma.",
		["South along the coast, the Southsea pirates hold the cove. {npc:7883} and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often.\nCareful: Two or three pirates stand with {npc:7883}, and many more pirates from the town join the fight once it starts."] = "Ao sul pela costa, os piratas dos Mares do Sul ocupam a enseada. {npc:7883} e a carga roubada ficam no cais, lá no fundo. Qualquer pirata pode deixar cair um chapéu, os sequestradores mais que todos.\nCuidado: dois ou três piratas ficam com {npc:7883}, e muitos outros piratas da vila entram na briga assim que ela começa.",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "Os taurens Temível Totem acampam ao lado do bosque dos Dardejantes; Saqueadores, Naturalistas e Xamãs carregam chifres.",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane.\nCareful: Every Woodpaw gnoll except the Alpha runs off for help at 15% health, which can pull more gnolls into the fight."] = "Os gnolls Patábua acampam nas colinas logo a noroeste de Mojache; qualquer um pode deixar cair uma juba.\nCuidado: todo gnoll Patábua, menos o Macho Alfa, sai correndo atrás de ajuda com 15% de vida, o que pode trazer mais gnolls para a briga.",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "A colmeia Zukk'ash se entoca nas colinas a sudeste do acampamento; {quest:7731} espera na câmara mais funda.",
		["The bandits and thieves camp in the dunes east of {area:976}. Every Wastewander can carry a water pouch: keep ten, five for each of Luglunket's bounties.\nCareful: Wastewander Rogues (level 43-44) move stealthed, so they can approach unseen."] = "Os bandidos e ladrões acampam nas dunas a leste de {area:976}. Qualquer Errante pode carregar um cantil: guarde dez, cinco para cada recompensa do Rastamala.\nCuidado: os Ladinos Errantes (nível 43-44) andam furtivos, então podem chegar sem ser vistos.",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "O mapa de batalha fica no acampamento Patábua ao sul de Mojache.",
		["The road from {area:484} to {zone:1446} runs past the {area:2240} on the {area:439}: {npc:4454} is in the gnomes' camp beside the track, {npc:4630} and {npc:4709} by the goblins' camp. {npc:4630} first, then {npc:4709}, who runs off to keep Rizzle busy; then take Rizzle's plans from the gnomes' camp and bring them back to {npc:4630}."] = "A estrada de {area:484} a {zone:1446} passa por {area:2240}, nas {area:439}: {npc:4454} fica no acampamento dos gnomos ao lado da trilha, {npc:4630} e {npc:4709} perto do acampamento dos goblins. {npc:4630} primeiro, depois {npc:4709}, que sai correndo para manter Rizzle ocupado; depois pegue os planos de Rizzle no acampamento dos gnomos e leve-os de volta a {npc:4630}.",
		["The shadow mages, rogues and assassins camp south-east of {area:976}.\nSouth-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp.\nCareful: Wastewander Rogues keep Sneak up while out of combat, so hidden rogues can join a fight you start at a camp.\nCareful: Two stealthed Wastewander Rogues travel with him wherever he goes. At his spawn camp, two shadowmages and their minions are close enough to join a fight with him. Out by the towers you can fight him without them."] = "Os magos das sombras, ladinos e assassinos acampam a sudeste de {area:976}.\nA sudeste de Geringontzan, os bandidos Errantes acampam nas dunas; {npc:7847} fica no acampamento do leste.\nCuidado: os Ladinos Errantes ficam furtivos fora de combate, então ladinos escondidos podem entrar numa briga que você começar num acampamento.\nCuidado: dois Ladinos Errantes furtivos acompanham o Califa aonde ele for. No acampamento onde ele surge, dois magos das sombras e seus lacaios estão perto o bastante para entrar na luta. Lá perto das torres dá para enfrentá-lo sem eles.",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour.\nCareful: Most Alphas sit in small tent camps with 2-4 other gnolls that join the fight, and other gnolls patrol between the camps."] = "Os dardejantes esvoaçam sobre o bosque logo a oeste de Mojache; quase todos deixam cair uma asa. Os Machos Alfa Patábua lideram os acampamentos a sudoeste dele: mate-os dentro de uma hora.\nCuidado: a maioria dos Machos Alfa fica em acampamentos pequenos de tenda com mais 2 a 4 gnolls que entram na briga, e outros gnolls patrulham entre os acampamentos.",
		["To {area:976}"] = "Para {area:976}",
		["Upstairs"] = "No andar de cima",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "Lobos: {npc:3362}, ao lado de {npc:4752}.",
		["Woodpaw battle map"] = "Mapa de batalha Patábua",
		["Woodpaw north camp"] = "Acampamento Patábua do norte",
		["Your trainer is in {zone:1456}: {npc:3033} (Druids) on {area:1639}, {npc:246344} (Paladins)."] = "Seu instrutor fica em {zone:1456}: {npc:3033} (Druidas) em {area:1639}, {npc:246344} (Paladinos).",
		["Zeppelin to {zone:1454}"] = "Zepelim para {zone:1454}",
		["for the {zone:1425}, around level 48"] = "para {zone:1425}, por volta do nível 48",
		["for {area:35}, around level 50"] = "para {area:35}, por volta do nível 50",
		["for {zone:1454}, around level 45"] = "para {zone:1454}, por volta do nível 45",
		["the Rage Scar yetis, on the next visit to {zone:1444}"] = "os yetis Cortifúria, na próxima visita a {zone:1444}",
		["water pouches in your bags"] = "bolsas de água nas bolsas",
		["{area:1099} flight master"] = "Mestre de voo de {area:1099}",
		["{area:1105} yetis"] = "Yetis de {area:1105}",
		["{area:1336}: kill these as you meet them"] = "{area:1336}: vá matando estes pelo caminho",
		["{area:1937}: kill these as you meet them"] = "{area:1937}: vá matando estes pelo caminho",
		["{area:2522}: kill these as you meet them"] = "{area:2522}: vá matando estes pelo caminho",
		["{area:392} flight master"] = "Mestre de voo de {area:392}",
		["{area:392} for the Felsteed"] = "{area:392} para o Corcel Vil",
		["{area:75} flight master"] = "Mestre de voo de {area:75}",
		["{area:976} flight master"] = "Mestre de voo de {area:976}",
		["{area:976} is the walled goblin town just past the {zone:1446} border."] = "{area:976} é a cidade goblin murada logo depois da fronteira de {zone:1446}.",
		["{area:985}: kill these as you meet them"] = "{area:985}: vá matando estes pelo caminho",
		["{npc:3690}, riding trainer"] = "{npc:3690}, instrutor de montaria",
		["{npc:4454}: {quest:1137}, from Martek in the {zone:1418}"] = "{npc:4454}: {quest:1137}, de Martek em {zone:1418}",
		["{npc:4630}: the {item:5852} from {npc:2496}, if you carry them"] = "{npc:4630}: os {item:5852} de {npc:2496}, se estiver com eles",
		["{npc:4706}, beside {npc:4630}"] = "{npc:4706}, ao lado de {npc:4630}",
		["{npc:4752}, riding trainer"] = "{npc:4752}, instrutor de montaria",
		["{npc:5234} walks around {area:2522}: look inside the circle on the map"] = "{npc:5234} anda por {area:2522}: procure dentro do círculo no mapa",
		["{npc:6986}, the Drag"] = "{npc:6986}, no Drag",
		["{npc:7010}, the Drag"] = "{npc:7010}, no Drag",
		["{npc:7777} walks around {area:1099}: look inside the circle on the map"] = "{npc:7777} anda por {area:1099}: procure dentro do círculo no mapa",
		["{npc:7854}, inside"] = "{npc:7854}, lá dentro",
		["{npc:7875}: for {npc:7010} in {zone:1454}"] = "{npc:7875}: para {npc:7010}, em {zone:1454}",
		["{npc:7881}, inside"] = "{npc:7881}, lá dentro",
		["{npc:7882}, inside"] = "{npc:7882}, lá dentro",
		["{npc:7953}, riding trainer"] = "{npc:7953}, instrutor de montaria",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}: para {zone:1454}, por volta do nível 45",
		["{npc:8579}: the screechers live in {zone:1444}, on the next {zone:1444} visit"] = "{npc:8579}: os guinchadores vivem em {zone:1444}, na próxima visita a {zone:1444}",
		["{quest:2863}: one hour from now"] = "{quest:2863}: daqui a uma hora",
